L["Intro Text"] = "어떤 이야기는 한 통의 편지, 떠도는 소문, 실종된 여행자, 혹은 마을 어귀에서 나지막이 오간 이름 하나로 시작됩니다.\n\nStory Mode는 그런 이야기들을 모아 장별로 펼쳐 보여 줍니다. 어디서 시작해야 하는지, 무엇이 아직 기다리고 있는지, 이미 무엇을 보았는지 한눈에 확인할 수 있습니다.\n\n완료한 장은 일지에 남아, 만났던 사람들과 맞섰던 위험, 기억할 만한 이름들을 조용히 기록합니다.\n\n지나온 모험을 다시 떠올려 보세요."
L["Intro Text Complete"] = "표시된 모든 이야기를 완료했습니다. 편지와 경고, 잊힌 이름, 숨은 후원자, 던전의 문, 집안의 빚, 기이한 보물이 이제 일지 속에 나란히 자리합니다.\n\n결코 작은 업적이 아닙니다. 모든 단서를 쫓고, 모든 부름에 응하고, 모든 장을 끝까지 마친 끝에, 흩어져 있던 소문들은 직접 이룬 업적의 기록이 되었습니다.\n\n이 일지가 그 증거입니다. 이야기들은 그저 발견된 것이 아닙니다. 끝까지 완수되고, 기억되어, 모험의 일부가 되었습니다."

