L["Scarlet Whisper 25"] = "또 하나의 붉은 휘장. 생각보다 손이 먼저 움직였다."
L["Scarlet Whisper 50"] = "점점 쉬워진다. 그 사실이 지금보다 훨씬 더 마음에 걸려야 마땅하다."
L["Scarlet Whisper 75"] = "지금 되어 가는 그것을 부르는 말이 있다. 그 말만은 떠올리지 않으려 애써 왔다."
L["Scarlet Voss Banner Header"] = "깊어지는 장부"
