L["Scarlet Share Hint"] = "Shift-클릭으로 장부 공유"
L["Scarlet Link Compare Format"] = "상대의 장부: |cffe62929%d|r. 나의 장부: |cffffd200%d|r."
L["Scarlet Ledger Korgal"] = "메븐 코갈은 죽음의 종소리 마을에서 죽은 이들의 소식을 전했다. 그의 죽음을 전해 줄 이는 아무도 없다."
L["Scarlet Ledger Perrine"] = "대장 페린은 브릴이 내려다보이는 곳에서 병사들을 훈련시켰다. 이제 훈련은 멈췄다."
L["Scarlet Ledger Vachon"] = "대장 바콘의 야영지는 아직 그대로 서 있다. 그 안에 서 있는 것은 아무것도 없다."
L["Scarlet Ledger Melrache"] = "대장 멜라케는 빛이 병사들을 지켜 주리라 약속했다. 빛은 그저 지켜보기만 했다."
L["Scarlet Ledger Balnazzar"] = "대성전사란 걸치는 옷에 불과했다. 그 옷을 입고 있던 것의 정체도 이미 보았다. 그런데도 설교는 여전히 메아리친다."
L["Scarlet Ledger Radley"] = "사냥꾼 래들리는 이 들판에서 움직이는 모든 것을 추적했다. 그런 그도 끝내 이쪽의 기척은 듣지 못했다."
L["Scarlet Ledger Durgen"] = "기병 드루겐은 하스글렌의 깃발을 앞세우고 출정했다. 그의 말은 주인 없이 돌아왔다."
L["Scarlet Ledger Abbendis"] = "고위사령관 아벤디스는 높은 성벽 뒤에서 티르의 손 수도원을 지휘했다. 성벽에도 끝은 있다."
L["Scarlet Ledger BenedictusVoss"] = "대사제 베네딕투스 보스는 딸을 교리에 바쳤다. 그 빚을 받아 낼 사람은 따로 있다."
L["Scarlet Ledger Thalnos"] = "혈법사 탈노스는 교단의 가장 오래된 비밀을 지켰다. 무덤은 그의 비밀을 하나도 지켜 주지 않았다."
L["Scarlet Ledger Vishas"] = "심문관 비샤스는 더는 아무것도 묻지 않는다. 그래도 보렐의 목소리는 아직 귓가에 맴돈다."
L["Scarlet Ledger Loksey"] = "사냥개조련사 록시는 사냥개들 곁에서 죽었다. 십자군은 결코 그 개들만큼 그를 애도하지 않을 것이다."
L["Scarlet Ledger Doan"] = "신비술사 도안은 아무도 읽어서는 안 되는 책들을 지켰다. 이제 도서관은 한층 고요해졌다."
L["Scarlet Ledger Herod"] = "붉은십자군 용사 헤로드. 신병들은 그의 이름을 연호했다. 이제는 아무도 환호하지 않는다."
L["Scarlet Ledger Mograine"] = "르노 모그레인은 자신의 제단 앞에서 쓰러졌다. 무엇을 속죄하려 했든, 그것으로는 부족했다."
L["Scarlet Ledger Fairbanks"] = "종교재판관 페어뱅크스는 가짜 돌벽 뒤에 갇혀 있었다. 십자군은 진실을 두 번 묻는다."
L["Scarlet Ledger Whitemane"] = "그녀가 빛을 부르자 빛이 응답했다. 이제는 그 이유를 묻지 않는다."
L["Scarlet Ledger Courier"] = "진홍십자군 급사의 편지는 이제 어디에도 닿지 않는다."
L["Scarlet Ledger Demetria"] = "붉은십자군 예언자는 많은 것을 내다보았다. 하지만 그 길도, 그 길 끝에 선 자도 보지 못했다."
L["Scarlet Section 100"] = "홀로 벌이는 전쟁"
L["Scarlet Section 250"] = "리듬"
L["Scarlet Section 500"] = "거울"
L["Scarlet Section 1000"] = "사제의 딸"
L["Scarlet Tab Body 250"] = "이제 전쟁에는 리듬이 생겼다. 광신자의 기도가 중간에 끊길 때 어떤 소리가 나는지 안다. 그들이 어느 길을 순찰하는지, 어느 농가를 이미 비워 버렸는지도 안다. 티리스팔 어딘가에서 노파의 등불이 꺼졌다. 등불이 타오르던 창턱을 지나쳤지만, 걸음을 멈추지 않았다.\n\n이 셈에 아직 의미가 있다고 스스로 되뇐다. 하지만 더는 합계를 확인하지 않는다."
L["Scarlet Tab Body 500"] = "더는 얼굴을 기억하지 않는다. 붉은 휘장, 은빛 불꽃, 끊어진 기도. 세세한 것들은 이미 정리된 채로 떠오른다. 불안한 것은 숫자가 아니다. 살육이 너무나 깔끔해졌다는 사실이다. 분노도 슬픔도 더는 없다. 셈을 맞춰 달라고 재촉하는 장부만 남았을 뿐이다.\n\n화이트메인의 광신자들은 확신이 곧 정의라고 믿는다. 가장 힘든 밤이면, 그 둘의 차이를 말로 꺼내기도 전에 잠이 든다."
L["Scarlet Tab Body 1000"] = "십자군은 병사를 모으기만 하는 것이 아니다. 길러 내기도 한다. 쓸어버린 야영지와 챙기지 않은 편지들 속에서 한 이름이 떠오르기 시작했다. 수도원 성벽 안에서 망자를 주저 없이 불태우도록 길러진 사제의 딸, 릴리안. 그녀의 아버지 대사제 베네딕투스 보스는 남들이 십일조를 바치듯 자식을 교리에 바쳤다. 그녀는 기도하듯 두 손을 모은 채로 사람을 죽일 수 있다고 한다. 단 한 번도 이유를 묻지 않았다고 한다.\n\n언젠가 십자군은 그녀를 보며, 쓸모를 다한 모든 이에게서 보던 것을 보게 될 것이다. 바로 감염을. 그날 무슨 일이 벌어지든 직접 손쓴 일은 아닐 것이다. 하지만 살아 있는 그 누구보다 그 일을 깊이 이해하게 될 것이다.\n\n보스라는 이름을 기억하라. 장부는 아직 그 이름과 끝나지 않았다. 그 이름과의 인연도 아직 끝나지 않았다."
L["Scarlet Tab Body"] = "처음부터 그들의 적이 되려던 것은 아니었다.\n\n시작은 조용했다. 티리스팔에서 우연히 지나친, 불타 버린 농가 한 채. 아들을 위해 밝혀 둔 등불 앞에서 울던 노파. 아들이 붉은 휘장을 두른 뒤로 편지에 답장을 하지 않는다고 그녀는 말했다. 십자군은 그에게 새로운 기도를 가르쳤고, 그 기도 속에 어머니의 이름이 들어설 자리는 없었다.\n\n그다음은 남녘해안 외곽의 갈대숲에 숨어 있던 소년이었다. 머리카락에는 예배당의 재가 묻어 있었다. 그다음은 정의로운 검에 베여 피를 흘리던 길 위의 상인이었다. 그다음은 자기 집 문 앞의 농부였다. 우연일 뿐이라고 스스로 되뇌었다. 그러나 붉은 깃발이 눈에 들어올 때마다 생각보다 손이 먼저 움직였다. 붉은십자군을 하나씩 쓰러뜨릴수록 그것은 전쟁이라기보다 셈에 가까워졌다. 은빛으로 치장한 거짓에 맞서 하나하나 헤아려 가는 빚이었다.\n\n이 일은 어느 편지에도 적지 않았다. 어느 지휘관도 맡긴 적이 없다. 명령도, 헌장도, 맹세도 없다. 침묵 속에서 기록되며 늘어 가는 숫자가 있을 뿐이다.\n\n붉은 성전사. 그 말의 오래된 의미 그대로다. 그들의 일원이 아니라, 그들에 맞서는 단 한 사람. 쓰러뜨린 붉은 휘장 하나하나가 다른 누구도 읽을 수 없는 장부에 또 하나의 이름으로 더해진다."

