L["A \"Humble\" Request"] = "간단한 부탁"
L["A Beastly Expedition"] = "무덤 탐험"
L["A Better Future"] = "더 나은 미래"
L["A Big Score"] = "빼돌리기"
L["A Bit of Chaos"] = "약간의 혼란"
L["A Bit of Espionage"] = "약간의 첩보"
L["A Bitter Reunion"] = "씁쓸한 재회"
L["A Body of Evidence"] = "증거의 실체"
L["A Brewing Situation"] = "축하주 돌리기"
L["A Burden Shared"] = "함께 짊어지는 짐"
L["A Burning Distraction"] = "시선을 끄는 데는 불이 최고!"
L["A Challenge From Our Enemies"] = "적의 도전"
L["A Change of Seasons"] = "계절의 변화"
L["A Chilling Summons"] = "섬뜩한 부름"
L["A Cold Front Approaches"] = "다가오는 한랭 전선"
L["A Conjuror's Duty"] = "창조술사의 의무"
L["A contagion strikes the Broken Shore. Cure the plague, recruit Aelthalyste, and seek the High Priest's Seeker mount."] = "부서진 해변에 전염병이 번집니다. 역병을 치료하고 애살리스테를 영입한 뒤, 대사제의 구도자 탈것을 찾으세요."
L["A courier brought word of Thas'dorah — the ancestral bow of the Windrunner family, carried by Alleria into the Twisting Nether and lost for decades. You followed the trail through ancient elven ruins, fighting off demons who sought to claim its power. The bow sang in your hands when you drew it, as if it had been waiting for a worthy archer all along."] = "한 전령이 탈도라에 관한 소식을 전해 왔다. 윈드러너 가문에 대대로 내려온 활로, 알레리아가 뒤틀린 황천으로 가져간 뒤 수십 년 동안 행방을 알 수 없던 무기였다. 고대 엘프 유적을 따라 흔적을 쫓으며, 그 힘을 차지하려는 악마들을 물리쳤다. 시위를 당기자 활이 손안에서 노래했다. 마치 오래전부터 자격 있는 궁수를 기다려 온 것처럼."
L["A Courteous Guest"] = "예의 바른 손님"
L["A Covert Operation"] = "은밀한 작전"
L["A cryptic summons led you into the sewers beneath Dalaran, where Lord Jorach Ravenholdt revealed The Uncrowned — a secret order of assassins operating outside the law. You proved your worth in the shadows and claimed a blade befitting the order's newest operative."] = "의문의 소환장을 따라 달라란 아래 하수도로 내려가자, 조라크 라벤홀트 경이 무관의 자의 존재를 밝혔다. 법의 테두리 밖에서 움직이는 비밀 암살자 결사였다. 그림자 속에서 실력을 증명한 끝에, 결사의 새 요원에게 걸맞은 칼날을 손에 넣었다."
L["A Culling of Souls"] = "영혼 수집"
L["A Curious Contagion"] = "기이한 감염"
L["A curious contagion swept the Broken Shore — a plague that twisted both body and spirit. Aelthalyste, a banshee who had rediscovered her faith, helped you trace the disease to its source, craft a cure, and administer it to the fallen. With the contagion contained and Aelthalyste as your newest champion, you answered a final call to the Sunken Vault, where a creature of pure Light awaited — the High Priest's Seeker, a mount that would carry you above the battlefield."] = "기이한 감염이 부서진 해변을 휩쓸었다. 몸과 영혼을 모두 뒤틀어 버리는 역병이었다. 신앙을 되찾은 밴시 애살리스테의 도움으로 병의 근원을 추적하고, 치료제를 만들어 쓰러진 이들에게 투여했다. 감염을 막아 내고 애살리스테를 새로운 용사로 맞이한 뒤, 마지막 부름에 응해 가라앉은 금고로 향했다. 그곳에서는 순수한 빛의 존재가 기다리고 있었다. 전장 위로 날아오르게 해 줄 탈것, 대사제의 구도자였다."
L["A Cycle of Hatred"] = "증오의 굴레"
L["A damaged Titan Keeper has been protecting the swamp's darkest secret — a proto-god of blood and shadow sealed beneath the earth."] = "망가진 티탄 관리자가 늪의 가장 어두운 비밀을 지켜 왔습니다. 바로 땅속 깊이 봉인된 피와 어둠의 원시 신입니다."
L["A Dance With Dragons"] = "용과의 춤"
L["A Daring Rescue"] = "대담한 구출"
L["A dark curse has fallen over Drustvar. Lord Waycrest has vanished, his lady has withdrawn behind manor walls, and old stories about witches have begun walking through the woods again.\n\nJoin Lucille Waycrest and the Order of Embers as they follow the coven's trail through cursed villages, haunted fens, and a land where buried grudges have a way of clawing back to the surface."] = "드러스트바에 어두운 저주가 내렸습니다. 군주 웨이크레스트는 자취를 감췄고, 그의 부인은 저택 담장 안에 틀어박혔으며, 마녀에 관한 옛이야기가 다시 숲을 거닐기 시작했습니다.\n\n루실 웨이크레스트와 잿불단과 함께 저주받은 마을과 유령이 출몰하는 늪지를 지나며 마녀단의 흔적을 쫓으세요. 이 땅에서는 묻어 둔 원한이 언제든 땅을 헤집고 다시 기어 나옵니다."
L["A Daughter's Embrace"] = "딸의 한"
L["A Deadly New Ally"] = "죽음을 부르는 새로운 아군"
L["A Defias plot has surfaced inside Stormwind's own walls, and Master Shaw needs someone he can trust to follow it to the source. The old grievances that shaped the Deadmines have not vanished just because the kingdom moved on.\n\nTrace the conspiracy through Stormwind's streets and forgotten debts, and decide what kind of human history is worth honoring when the past asks to be heard again."] = "스톰윈드 성벽 안에서 데피아즈단의 음모가 드러났고, 마티아스 쇼는 그 근원을 추적할 믿을 만한 사람이 필요합니다. 죽음의 폐광을 낳은 오랜 원한은 왕국이 앞으로 나아갔다고 해서 사라지지 않았습니다.\n\n스톰윈드의 거리와 잊힌 빚을 따라 음모를 추적하고, 과거가 다시 목소리를 낼 때 인간의 역사 중 무엇을 기릴 가치가 있는지 결정하세요."
L["A Desecrated Temple"] = "더럽혀진 사원"
L["A Display of Power"] = "힘의 과시"
L["A dying sprite's plea reveals mogu rituals at the Terrace of Ten Thunders and the spirits trapped beneath them."] = "죽어 가는 정령의 애원을 통해, 열 천둥의 정원에서 벌어지는 모구의 의식과 그 아래 갇힌 영혼들의 존재가 드러납니다."
L["A Final Offer"] = "마지막 제의"
L["A Fitting Reward"] = "합당한 보상"
L["A Forlorn Hope"] = "허무한 희망"
L["A Friend of the Frogs"] = "개구리의 친구"
L["A Friendly Accord"] = "우호적인 합의"
L["A Gathering of Champions"] = "영웅들의 회동"
L["A girl is singing by herself at an empty homestead. She asks you to find her stuffed animals for a tea party. As you collect each one, she recites little rhymes about what happened to the people who used to live here. The rhymes are not comforting."] = "텅 빈 농장에서 한 소녀가 홀로 노래를 부르고 있습니다. 소녀는 다과회를 열고 싶다며 봉제 인형들을 찾아 달라고 부탁합니다. 인형을 하나씩 찾을 때마다, 소녀는 이곳에 살던 사람들에게 무슨 일이 있었는지 짧은 동요로 읊어 줍니다. 그 동요는 전혀 위안이 되지 않습니다."
L["A Glade Defense"] = "숲 방어"
L["A Glimpse of Terror"] = "공포의 일면"
L["A Glorious Reunion"] = "영광스러운 재회"
L["A goblin named Patch and a crew of demolitions experts blast a way through the blood troll defenses."] = "패치라는 고블린과 폭파 전문가들이 피의 트롤 방어선을 날려 버리며 길을 뚫습니다."
L["A Godly Invitation"] = "신의 초대"
L["A Golden Ticket"] = "금빛 표"
L["A Grim Portent"] = "음산한 징조"
L["A Growing Crisis"] = "커져가는 위기"
L["A Hero Remains"] = "영웅은 남고..."
L["A Hero's Weapon"] = "영웅의 무기"
L["A hooded figure is paying coin inside the Scarlet Halls — silver for Scarlet blood. She wants their membership records. She calls herself the Hooded Crusader, and she is very thorough."] = "두건을 쓴 인물이 붉은십자군 전당 안에서 돈을 치르고 있습니다. 붉은십자군의 피에 은화를 내건 것입니다. 그녀가 원하는 것은 그들의 단원 명부입니다. 스스로를 두건 쓴 성전사라 부르는 그녀는 무척이나 철저합니다."
L["A hooded priestess summons you to Netherlight Temple, where Alonsus Faol — the founder of the priesthood — reveals himself."] = "두건을 쓴 여사제의 부름을 받고 황천빛 사원으로 향하자, 사제단의 창시자 알론서스 파올이 모습을 드러냅니다."
L["A Humble Offering"] = "소박한 제물"
L["A Hungry Heritage"] = "굶주린 유산"
L["A Legend You Can Hold"] = "손에 거머쥔 전설"
L["A Lesson in Humility"] = "겸손을 배우라"
L["A Lesson in Witch Hunting"] = "마녀 사냥학 개론"
L["A Light in the Darkness"] = "어둠 속의 빛"
L["A Line in the Sand"] = "모래 한 줌 빼낸들 사막이 없어지리"
L["A little girl stands alone at Glenbrook Homestead, singing a nursery rhyme about her empty village. The chimneys are still warm, the tables are still set, and the silence feels much too fresh.\n\nShe only wants help preparing a tea party: a few toys, a missing cat, and one more guest. In Drustvar, even the smallest errands can carry a shadow longer than the road ahead."] = "작은 소녀가 글렌브룩 농장에 홀로 서서, 텅 빈 마을에 관한 동요를 부르고 있습니다. 굴뚝은 아직 따뜻하고, 식탁은 아직 차려져 있으며, 정적은 너무도 생생합니다.\n\n소녀가 바라는 것은 다과회 준비를 도와줄 사람뿐입니다. 장난감 몇 개, 사라진 고양이, 그리고 손님 한 명만 더. 드러스트바에서는 아무리 사소한 심부름이라도 앞길보다 긴 그림자를 드리울 수 있습니다."
L["A Local Guide"] = "지역의 조력자"
L["A Long Walk"] = "기나긴 길"
L["A Mage's Weapon"] = "마법사의 무기"
L["A Magical Glow"] = "반딧불이의 정수"
L["A Mark For A Protector"] = "수호자의 징표"
L["A Matter of Finesse"] = "수완이 중요해"
L["A Message From Ly'leth"] = "라일레스의 전갈"
L["A Message From Our Enemies"] = "우리 적의 전갈"
L["A Message of Blood and Fire"] = "피와 불의 메시지"
L["A Mile in My Shoes"] = "시작은 내 얘기로"
L["A More Wretched Hive of Scum and Villainy"] = "불한당과 악당들이 모인 북새통"
L["A mysterious courier delivers an urgent summons to the sewers beneath Dalaran, where a secret order of assassins watches from the shadows."] = "의문의 전령이 달라란 아래 하수도로 서둘러 오라는 소환장을 전합니다. 그곳에서는 비밀 암살자 결사가 그림자 속에서 지켜보고 있습니다."
L["A mysterious paladin appeared with word of the Silver Hand — the holy mace wielded by the first paladins of Lordaeron. You followed the trail through ancient crypts and sacred sites, facing trials that tested your faith as much as your strength. The Silver Hand pulsed with warmth when you finally held it, and the spirits of the original knights seemed to nod in approval."] = "의문의 성기사가 은빛 손에 관한 소식을 가지고 나타났다. 로데론의 초대 성기사들이 휘둘렀던 성스러운 철퇴였다. 고대 묘실과 성지를 따라 흔적을 쫓으며, 힘만큼이나 신앙을 시험하는 시련에 맞섰다. 마침내 손에 쥐자 은빛 손은 따스하게 고동쳤고, 초대 기사들의 영혼이 고개를 끄덕이며 인정하는 듯했다."
L["A mysterious priestess led you through a portal to Netherlight Temple, a sanctuary floating in the Twisting Nether between the forces of Light and Void. There, Alonsus Faol — the man who had founded the original priesthood of Lordaeron — revealed he had survived as an undead, guiding the faith from the shadows for centuries. Prophet Velen stood beside him, and together they asked you to lead a new Conclave. Calia Menethil and High Priestess Ishanah pledged as your first champions."] = "의문의 여사제를 따라 차원문을 지나 황천빛 사원에 이르렀다. 빛과 공허의 세력 사이, 뒤틀린 황천에 떠 있는 성소였다. 그곳에서 로데론 최초의 사제단을 세운 알론서스 파올이 자신이 언데드로 살아남아 수 세기 동안 그림자 속에서 신앙을 이끌어 왔음을 밝혔다. 예언자 벨렌이 그의 곁에 섰고, 두 사람은 새로운 비밀 집회를 이끌어 달라고 청했다. 칼리아 메네실과 대여사제 이샤나가 첫 용사로서 충성을 맹세했다."
L["A Nation Divided"] = "분열된 국가"
L["A Nation United"] = "하나된 국가"
L["A New Beginning"] = "새로운 시작"
L["A New Order"] = "새로운 잿불단의 탄생"
L["A New Tradition"] = "새로운 전통"
L["A New Vision"] = "새로운 예언"
L["A Pact of Necessity"] = "뜻밖의 아군"
L["A Pact With Death"] = "죽음과의 계약"
L["A Particularly Potent Potion"] = "아주 특별하고 강력한 물약"
L["A People in Need of Healing"] = "치유가 필요한 사람들"
L["A People Shattered"] = "조각난 민족"
L["A Perfect Match"] = "완벽한 짝"
L["A Personal Request"] = "개인적인 부탁"
L["A pirate legend speaks of cursed cutlasses buried with their last captain. Fleet Admiral Tethys knows the way."] = "해적 전설에 따르면 저주받은 해적검들이 마지막 선장과 함께 묻혔다고 합니다. 함대 사령관 테시스가 그곳으로 가는 길을 알고 있습니다."
L["A Plea to Revendreth"] = "레벤드레스에 보내는 요청"
L["A Plea to the Harvesters"] = "수확자에게로의 부탁"
L["A Promise of Earth"] = "바위 어머니의 약속"
L["A Proper Disguise"] = "적절한 변장"
L["A Proper Weapon"] = "적당한 무기"
L["A Pungent Solution"] = "매운 해결책"
L["A Re-Warding Effort"] = "수호물 재가동"
L["A Reflection of Truth"] = "진실의 거울"
L["A Revealing Missive"] = "진실을 폭로하는 명령서"
L["A Ring Reforged"] = "다시 만든 고리"
L["A Ring Unbroken"] = "부서지지 않은 고리"
L["A Royal Escort"] = "왕 호위"
L["A Royal Key"] = "고귀한 열쇠"
L["A Scarlet Letter"] = "단홍빛 편지"
L["A Second Weapon"] = "두 번째 무기"
L["A secret order of rogues operates from the shadows beneath Dalaran. The Uncrowned do not rule kingdoms, but they know where every kingdom keeps its secrets.\n\nAs the order's newest blade in the dark, gather legendary tools, follow a conspiracy through trusted halls, and learn who can still be trusted when everyone is trained to lie."] = "달라란 아래 그림자 속에서 도적들의 비밀 결사가 활동하고 있습니다. 무관의 자는 왕국을 다스리지 않지만, 모든 왕국이 비밀을 어디에 숨겨 두는지 알고 있습니다.\n\n결사의 가장 새로운 어둠 속 칼날로서 전설적인 도구를 모으고, 믿었던 이들의 전당을 꿰뚫는 음모를 추적하며, 모두가 거짓말하도록 훈련받은 곳에서 아직 누구를 믿을 수 있는지 알아내세요."
L["A secret society of rogue mages is hoarding dangerous knowledge. Infiltrate their ranks with Ravandwyr and Esara Verrinde."] = "변절한 마법사들의 비밀 결사가 위험한 지식을 쌓아 두고 있습니다. 라반드위르, 이사라 베린드와 함께 그들의 조직에 잠입하세요."
