L["A val'kyr claims you worthy of Odyn's attention. You ascend to Skyhold, the warrior paradise above the clouds, and take up a weapon of legend."] = "한 발키르가 오딘의 관심을 받을 자격이 있다고 선언합니다. 구름 위에 자리한 전사들의 낙원, 하늘보루로 올라가 전설의 무기를 손에 넣으세요."
