L["A'dal"] = "아달"
L["Abby has vanished. You find a village register — nearly every name crossed out. Three people may still be alive: the Hayeses and Samuel Hawthorne. They are not. Then Abby reappears, lights the candles, pours the tea, and introduces the last guest."] = "애비가 사라졌습니다. 마을 명부를 찾아내지만, 거의 모든 이름에 줄이 그어져 있습니다. 아직 살아 있을지도 모르는 사람은 셋, 헤이즈 부부와 사무엘 호손입니다. 하지만 그들도 살아 있지 않습니다. 그때 애비가 다시 나타나 촛불을 켜고, 차를 따르고, 마지막 손님을 소개합니다."
L["Abby Lewis"] = "애비 루이스"
L["Abby Lewis stood alone at Glenbrook Homestead, singing softly to herself. The houses were abandoned. The village was silent. She said she just wanted friends for a tea party — three stuffed animals: Mr. Munchykins, Trunksy, and Mayor Striggs. You found them, each one near a place where something had clearly gone very wrong. Abby appeared each time to recite a cheerful little rhyme. The rhymes were about the dead."] = "애비 루이스는 글렌브룩 농장에 홀로 서서 나지막이 노래를 부르고 있었다. 집들은 버려졌고 마을은 고요했다. 소녀는 그저 다과회에 함께할 친구들이 필요할 뿐이라고 했다. 봉제 인형 셋, 먼치킨스 씨와 트렁크시, 그리고 스트릭스 시장이었다. 인형들은 저마다 무언가 끔찍하게 잘못된 것이 분명한 장소 근처에 있었다. 그때마다 애비가 나타나 명랑한 짧은 동요를 읊었다. 그 동요는 죽은 이들에 관한 것이었다."
L["Above the ice, at the roof of the world, the Frozen Throne waits. The Ashen Verdict — Argent Crusade and Ebon Blade, bound by a single purpose — stands at the citadel's door. Highlord Tirion Fordring lifts the Ashbringer. Every victory in Northrend, every fallen soldier, every mile of ground bought in blood has led here. One way or another, the reign of Arthas Menethil ends at the summit."] = "얼음 위, 세상의 지붕에서 얼어붙은 왕좌가 기다린다. 은빛십자군과 칠흑의 기사단이 하나의 목적 아래 뭉친 잿빛 선고단이 성채의 문 앞에 서 있다. 대영주 티리온 폴드링이 파멸의 인도자를 치켜든다. 노스렌드에서 거둔 모든 승리, 쓰러진 모든 병사, 피로 얻어 낸 모든 땅이 이곳으로 이어졌다. 어떤 식으로든 아서스 메네실의 통치는 정상에서 끝난다."
L["Absalan the Pious"] = "신앙심 깊은 압살란"
L["Absolon"] = "압솔론"
L["Ace Pilot Stormcog"] = "최우수 조종사 스톰코그"
