L["Aerylia"] = "에이릴리아"
L["Aethas Sunreaver"] = "에이타스 선리버"
L["After Baine's rescue, the Horde fractured completely. Some followed Saurfang to Razor Hill, others remained loyal to Sylvanas in Orgrimmar. The stage was set for the final confrontation — not between Alliance and Horde, but within the Horde itself."] = "바인을 구출한 뒤 호드는 완전히 분열되었다. 일부는 사울팽을 따라 칼바위 언덕으로 향했고, 나머지는 오그리마에 남아 실바나스에게 충성을 지켰다. 마지막 대결의 무대가 마련되었다. 얼라이언스와 호드 사이가 아니라, 호드 내부의 대결이었다."
L["After the fall of Lordaeron, Saurfang had surrendered to the Alliance rather than flee with Sylvanas. Now Nathanos was dispatched to retrieve him — or ensure he stayed quiet. You tracked the old orc through layers of Alliance intelligence, pieced together where he was held, and extracted him. Saurfang walked out of Stormwind on his own two feet, not as anyone's prisoner. He thanked Nathanos without warmth. Whatever he was planning, it wasn't a return to Sylvanas's service."] = "로데론이 함락된 뒤, 사울팽은 실바나스와 함께 달아나는 대신 얼라이언스에 항복했다. 이제 나타노스가 그를 데려오라는, 혹은 영원히 입을 다물게 하라는 명을 받고 파견되었다. 얼라이언스 정보망을 한 겹씩 헤치며 늙은 오크의 행방을 쫓았고, 그가 갇힌 곳을 알아내 그를 빼냈다. 사울팽은 누구의 포로도 아닌 채 제 발로 스톰윈드를 걸어 나왔다. 그는 나타노스에게 감사를 표했지만, 그 말에 온기는 없었다. 무엇을 계획하고 있든, 실바나스의 곁으로 돌아가는 것은 아니었다."
L["Against Magatha's Will"] = "마가타에게 반기 들기"
L["Against the Giants"] = "거인에 맞서라!"
L["Agent Render"] = "요원 렌더"
L["Aggra"] = "아그라"
L["Agmar's Hammer"] = "아그마르의 망치"
L["Agony Abounds"] = "만발하는 고통"
L["Aka'magosh"] = "아카마고쉬"
L["Alchemist Korlya"] = "연금술사 콜리아"
L["Aldrachi Warblades"] = "알드라치 전투검"
L["Alexstrasza the Life-Binder"] = "생명의 어머니 알렉스트라자"
L["All Aboard!"] = "모두 승선!"
L["All Along the Waterways"] = "물길 따라"
L["All Hail Roanauk!"] = "로아나우크를 맞이하라!"
L["All In"] = "최후의 수단"
L["All the threads came together when the Legion launched a full assault on Dalaran itself, breaching the Violet Hold with demonic forces. Halduron Brightwing helped you forge new weapons and prepare defenses, while Shandris Feathermoon rallied reinforcements. You led the Unseen Path into the Violet Hold and faced Hakkar the Houndmaster in a battle that shook the city. When the demon fell, Emmarel Shadewarden bestowed upon you the title of Huntmaster — the highest honor the Unseen Path could give."] = "모든 실마리가 하나로 이어진 것은 불타는 군단이 달라란에 총공세를 퍼부어 악마 군세로 보랏빛 요새를 뚫었을 때였다. 할두런 브라이트윙은 새 무기를 벼리고 방어를 준비하도록 도왔고, 샨드리스 페더문은 지원군을 규합했다. 보이지 않는 길을 이끌고 보랏빛 요새로 들어가, 도시를 뒤흔든 전투에서 사냥개조련사 학카르와 맞섰다. 악마가 쓰러지자, 에마렐 셰이드워든은 보이지 않는 길이 내릴 수 있는 최고의 영예인 사냥의 대가 칭호를 수여했다."
L["All We Can Spare"] = "이게 전부라고요"
L["Allari the Souleater"] = "영혼착취자 알라리"
L["Allegiance of Flame"] = "충성의 불길"
L["Alliance"] = "얼라이언스 연합"
L["Alliance city call-up"] = "얼라이언스 도시 소집"
L["Allies of the Light"] = "빛의 아군"
L["Alonsus Faol"] = "알론서스 파올"
L["Alonsus Faol sensed whispers in the Void — disturbances emanating from Azsuna that threatened the balance of Netherlight Temple itself. Prophet Velen sent his best: Zabra Hexx, a shadow priest of the Darkspear, and Yalia Sagewhisper, a Pandaren healer of quiet wisdom. Together you investigated the source, dealing with murloc mind control and disrupted ley lines. Both proved their worth and joined your Conclave as champions."] = "알론서스 파올은 공허에서 속삭임을 감지했다. 아즈스나에서 흘러나온 불길한 기운이 황천빛 사원의 균형마저 위협하고 있었다. 예언자 벨렌은 최고의 인재들을 보냈다. 검은창 부족의 암흑 사제 자브라 헥스와, 조용한 지혜를 지닌 판다렌 치유사 야리아 세이지위스퍼였다. 함께 근원을 조사하며 멀록의 정신 지배와 어지러워진 지맥에 맞섰다. 두 사람 모두 실력을 증명하고 용사로서 비밀 집회에 합류했다."
L["Alonsus Faol spoke of Natalie Seline — a brilliant priest who had studied the Void so deeply that it had consumed her. She was trapped in a shadow realm between worlds, and only you could reach her. With Micah Belford guiding you through the darkness, you entered the Void itself and found Seline — transformed, but not lost. She returned to the Conclave carrying shadows that whispered secrets even the Light could not reveal."] = "알론서스 파올은 나탈리 세린에 관해 이야기했다. 공허를 너무 깊이 파고든 나머지 공허에 삼켜져 버린 뛰어난 사제였다. 그녀는 세계와 세계 사이의 어둠의 영역에 갇혀 있었고, 그녀에게 닿을 수 있는 사람은 단 한 명뿐이었다. 미카 벨포드의 안내를 받아 어둠을 헤치고 공허 그 자체로 들어가, 변해 버렸지만 길을 잃지는 않은 세린을 찾아냈다. 그녀는 빛조차 드러낼 수 없는 비밀을 속삭이는 어둠을 품은 채 비밀 집회로 돌아왔다."
L["Alonsus Faol spoke of T'uure — a crystal of pure Light created by the naaru themselves, said to be a beacon that could pierce any darkness. You followed a vindicator's plea to its resting place and fought through the shadows to claim it. When T'uure's light filled the room, every wound healed, every doubt faded, and the darkness recoiled."] = "알론서스 파올은 투우레에 관해 이야기했다. 나루가 직접 만들어 낸 순수한 빛의 수정으로, 어떤 어둠도 꿰뚫는 등불이라 전해졌다. 한 구원자의 간청을 따라 그것이 잠든 곳으로 향했고, 어둠을 헤치며 싸워 그것을 손에 넣었다. 투우레의 빛이 방 안을 가득 채우자, 모든 상처가 아물고 모든 의심이 사라졌으며, 어둠은 움찔하며 물러났다."
L["Alpha Bat"] = "박쥐 우두머리"
L["Already Among Us"] = "우리 중에 첩자가 있는 것 같아"
L["Altar Keeper Biehn"] = "제단 감시자 비엔"
L["Aluneth, Greatstaff of the Magna"] = "알루네스 - 마그나의 대지팡이"
L["Amal'thazad"] = "아말타자드"
L["Amal'thazad's Message"] = "아말타자드의 전갈"
