L["Ammunition Acquisition"] = "탄약 확보"
L["Among Us"] = "우리 사이에"
L["Amped for Revolt!"] = "화끈한 게 좋아!"
L["An Air of Worry"] = "걱정스러운 내음"
L["An Airtight Alibi"] = "모든 증거가 무죄를 증명한다"
L["An Ample Supply"] = "보급품 사수 작전"
L["An Ancient Legend"] = "고대의 전설"
L["An ancient vrykul artifact holds the key to unmasking the enemy. The search leads through the haunted halls of Black Rook Hold."] = "고대 브리쿨 유물에 적의 정체를 밝힐 열쇠가 숨겨져 있습니다. 수색은 유령이 출몰하는 검은 떼까마귀 요새의 전당으로 이어집니다."
L["An Artificer's Appeal"] = "기술병의 호소"
L["An eagle leads you to Trueshot Lodge, where the Unseen Path — an ancient order of hunters — calls you to serve as champion."] = "독수리 한 마리가 정조준 오두막으로 길을 안내합니다. 그곳에서 고대 사냥꾼 결사인 보이지 않는 길이 용사가 되어 달라고 요청합니다."
