L["An Unexpected Advantage"] = "예상치 못한 선물"
L["An Unexpected Message"] = "뜻밖의 전언"
L["An unexpected message revealed the location of Felo'melorn — the legendary sword of the Sunstrider dynasty, lost when Kael'thas fell. You traced it to the frozen depths of Icecrown, where it had lain since Arthas shattered it in single combat. You reforged the blade in phoenix fire and carried it from the ice, its flames burning hotter than ever — as if centuries of cold had only made it angrier."] = "뜻밖의 전언을 통해 펠로멜로른의 행방이 드러났다. 캘타스가 몰락하며 잃어버린 선스트라이더 왕조의 전설적인 검이었다. 흔적을 따라 얼음왕관의 얼어붙은 심연에 이르렀다. 아서스가 일대일 결투에서 산산조각 낸 이래로 검은 그곳에 잠들어 있었다. 불사조의 불꽃으로 검을 다시 벼려 얼음 속에서 꺼내자, 그 불꽃은 그 어느 때보다 뜨겁게 타올랐다. 마치 수 세기에 걸친 추위가 분노만 더 키운 것처럼."
L["An Unexpected Visitor"] = "뜻밖의 손님"
L["An unexpected visitor brought troubling news — a secret society called the Empyrean Society was gathering forbidden knowledge across the Broken Isles. Ravandwyr, apprentice to the missing Archmage Vargoth, led you on a covert infiltration of their ranks. With Esara Verrinde's help, you discovered the Society had been experimenting with powers far beyond their control. You shut them down from the inside, but the trail left behind raised a darker question — where was Archmage Vargoth?"] = "뜻밖의 손님이 불길한 소식을 가져왔다. 최고천 협회라는 비밀 결사가 부서진 섬 곳곳에서 금지된 지식을 모으고 있다는 것이었다. 실종된 대마법사 바르고스의 제자 라반드위르의 안내로 그들의 조직에 은밀히 잠입했다. 이사라 베린드의 도움으로, 협회가 감당할 수 없는 힘을 실험해 왔다는 사실을 밝혀냈다. 안에서부터 그들을 무너뜨렸지만, 남겨진 흔적은 더 어두운 의문을 남겼다. 대마법사 바르고스는 어디에 있는가?"
L["An Unlikely Ally"] = "예상치 못한 아군"
L["An Unlikely Informant"] = "뜻밖의 정보원"
L["An Urgent Gathering"] = "비상소집"
L["An Urgent Matter"] = "긴박한 문제"
L["An Urgent Plea"] = "다급한 애원"
L["An Urgent Situation"] = "긴급 상황"
L["An Windfur"] = "안 윈드퍼"
L["Ancestors and Enemies"] = "선조와 적의 관계"
L["Ancient Armor, Ancient Mystery"] = "고대의 방어구와 수수께끼"
L["Ancient Curses"] = "고대의 저주"
L["Ancient Magic"] = "고대 마법"
L["Ancient Mana"] = "고대 마나"
L["Ancient Power"] = "고대의 힘"
L["Ancient Statue"] = "고대 석상"
L["Ancient Tablet"] = "고대 석판"
L["And a Heavy Fist"] = "무거운 주먹"
L["And Justice For All"] = "정의가 실현됐다"
L["And They Will Tremble"] = "그리고 그들은 전율하리라"
L["Anduin Wrynn"] = "안두인 린"
L["Anduin's Decision"] = "안두인의 결정"
L["Angrathar. The black gate beyond which the Lich King's frozen fortress waits. Bolvar Fordragon has gathered every shield the Alliance can spare. Dragons circle above. Somewhere to the east, the Horde marches its own road to the same gate. Ahead, the Scourge stands in ranks that do not end. This is the road to the Lich King's door."] = "앙그라타르. 그 검은 문 너머에서 리치 왕의 얼어붙은 요새가 기다린다. 볼바르 폴드라곤은 얼라이언스가 내줄 수 있는 모든 방패를 끌어모았다. 하늘에는 용들이 선회한다. 동쪽 어딘가에서는 호드가 같은 문을 향해 저들만의 길을 행군하고 있다. 앞에는 끝없이 늘어선 스컬지의 대열이 버티고 있다. 이것이 리치 왕의 문으로 향하는 길이다."
L["Angrathar. The Wrathgate. The final road to the Lich King's own door. Saurfang the Younger takes point, every Orc behind him blood-mad and ready for the reckoning. Somewhere to the west, the Alliance marches under a brittle truce toward the same gate. Above, dragons circle on wings of red flame. Whatever happens at this gate, the world will remember it."] = "앙그라타르. 분노의 관문. 리치 왕의 문으로 향하는 마지막 길. 사울팽의 아들이 선두에 서고, 그 뒤를 따르는 모든 오크가 피에 굶주린 채 심판의 순간을 기다린다. 서쪽 어딘가에서는 얼라이언스가 위태로운 휴전 아래 같은 문을 향해 행군하고 있다. 하늘에는 붉은 불꽃의 날개를 펼친 용들이 선회한다. 이 문에서 무슨 일이 일어나든, 세상은 그것을 기억할 것이다."
L["Angus Ballaster"] = "앵거스 발라스터"
L["Angus Ironfist"] = "앵거스 아이언피스트"
L["Anima Attrition"] = "령 소모전"
L["Annie Warren"] = "애니 워런"
L["Another Arcan'dor Closes..."] = "또 다른 아르칸도르..."
L["Answer Baine Bloodhoof's call as the spirit realm and the living world begin to drift dangerously out of alignment. Across Mulgore and Thunder Bluff, the elders still remember an age before the Horde, and the ancestors have not gone silent.\n\nWalk with the spiritwalkers, restore rites interrupted by years of war, and listen for the balance between the living, the dead, and the land beneath your hooves."] = "영혼의 세계와 산 자의 세계가 위태롭게 어긋나기 시작한 지금, 바인 블러드후프의 부름에 응하세요. 멀고어와 썬더 블러프 곳곳의 원로들은 아직 호드 이전의 시대를 기억하며, 조상들도 침묵하지 않았습니다.\n\n영혼술사들과 함께 걸으며 오랜 전쟁으로 끊겼던 의식을 되살리고, 산 자와 죽은 자, 그리고 발굽 아래 대지 사이의 균형에 귀 기울이세요."
L["Answer Tess Greymane's call when the Nightbane begin to reappear in Duskwood and near the borders of the Emerald Dream. The Gilneans are a kingdom in exile, and the curse that gave them a second face has not stopped reshaping them.\n\nHunt through fog and shadow, confront the pull of the worgen curse, and uphold the discipline that has kept Gilnean tradition alive since Greymane Wall fell."] = "그늘숲과 에메랄드의 꿈 접경지 근처에 밤의 파멸단이 다시 나타나기 시작한 지금, 테스 그레이메인의 부름에 응하세요. 길니아스인은 망명 중인 왕국의 백성이며, 그들에게 또 하나의 얼굴을 안긴 저주는 지금도 그들을 바꾸어 놓고 있습니다.\n\n안개와 그림자 속에서 사냥하며 늑대인간 저주의 이끌림에 맞서고, 그레이메인 성벽이 무너진 이후로 길니아스의 전통을 지켜 온 규율을 지키세요."
L["Answer the Call"] = "부름에 응하라"
L["Answer the Clarion Call from Maiev Shadowsong, who has heard rumors of demonic activity older than the Burning Legion's last invasion. The trail leads into Felwood and the Emerald Dream's borderlands, where corruption has roots ten thousand years deep.\n\nFollow the Wardens into old shadows, face threats tied to ancient Kaldorei memory, and stand with a people still carrying loss beneath the light of Elune."] = "마이에브 섀도송의 소집 명령에 응하세요. 그녀는 불타는 군단의 지난 침공보다 더 오래된 악마의 활동에 관한 소문을 들었습니다. 흔적은 악령숲과 에메랄드의 꿈 접경지로 이어지고, 그곳의 타락은 만 년 깊이까지 뿌리를 내리고 있습니다.\n\n감시자들을 따라 오래된 그림자 속으로 들어가, 고대 칼도레이의 기억에 얽힌 위협에 맞서고, 엘룬의 빛 아래 여전히 상실을 짊어진 이들과 함께하세요."
L["Answering Aggression"] = "폭력에 대한 응답"
L["Answers Unknown"] = "알려지지 않은 답"
L["Anvil-Thane Thurgaden"] = "엔빌테인 터르가덴"
L["Apata Highmountain told the tale of Talonclaw — an eagle spear wielded by the greatest hunters of Highmountain since the age of the titans. You climbed into the highest peaks and proved yourself in trials of survival, tracking, and combat. When you claimed Talonclaw from its ancient resting place, the spirits of past hunters looked on with approval."] = "아파타 하이마운틴은 탈론클로에 관한 이야기를 들려주었다. 티탄의 시대부터 높은산의 가장 위대한 사냥꾼들이 휘둘러 온 독수리 창이었다. 가장 높은 봉우리에 올라 생존과 추적, 전투의 시험에서 실력을 증명했다. 오랜 안식처에서 탈론클로를 손에 넣자, 옛 사냥꾼들의 영혼이 흡족한 듯 지켜보았다."
L["Apocalypse"] = "대재앙"
L["Aponi Brightmane"] = "아포니 브라이트메인"
L["Aponi Brightmane studied the Codex of Command but needed a demon's mind to crack its encryption. The answer came from an unlikely source — a demon prisoner in the Violet Hold. Delas Moonfang, a night elf priestess drawn to the paladin's path, helped translate the demonic text. What you found inside chilled your blood: the Legion had captured Aponi Brightmane and was holding her on Niskara. The invasion plans were clear — and so was your next move."] = "아포니 브라이트메인은 지휘의 고문서를 연구했지만, 그 암호를 풀려면 악마의 정신이 필요했다. 해답은 뜻밖의 곳에서 나왔다. 보랏빛 요새에 갇힌 악마 포로였다. 성기사의 길에 이끌린 나이트 엘프 여사제 델라스 문팽이 악마의 문자를 번역하는 일을 도왔다. 그 안에서 찾아낸 내용에 피가 얼어붙었다. 불타는 군단이 아포니 브라이트메인을 사로잡아 니스카라에 가두고 있었던 것이다. 침공 계획은 명확했고, 다음에 할 일도 분명했다."
L["Aponi's Trail"] = "아포니의 흔적"
L["Apostate Liberation"] = "변절자 해방"
L["Apothecary Keever"] = "연금술사 키버"
L["Apprentice Beruun"] = "수습생 베룬"
L["Apprentice Nelphi"] = "수습생 넬피"
L["Arcan'dor, Gift of the Ancient Magi"] = "아르칸도르, 고대 마법사의 선물"
L["Arcane Communion"] = "비전의 교감"
L["Arcane Thirst"] = "비전 갈증"
L["Arcanist Kel'danath"] = "비전술사 켈다나스"
L["Arcanist Valtrois"] = "비전술사 발트와"
L["Archdruid Hamuul Runetotem"] = "대드루이드 하뮬 룬토템"
L["Archdruid Hamuul Runetotem's summons led you to Moonglade, where Malfurion Stormrage revealed the Emerald Dreamway — ancient paths woven through the Dream itself. Keeper Remulos guided you through to the Dreamgrove, a sanctuary hidden in Val'sharah. There, Rensar Greathoof asked you to claim an artifact weapon and plant the Seed of Ages, binding your fate to the land. You ascended the Cenarion Circle as its newest Archdruid."] = "대드루이드 하뮬 룬토템의 부름을 따라 달의 숲에 이르자, 말퓨리온 스톰레이지가 에메랄드의 꿈길을 보여 주었다. 꿈 그 자체를 꿰뚫고 이어진 고대의 길이었다. 수호자 레물로스의 인도로 발샤라에 숨겨진 성소인 꿈의 숲에 다다랐다. 그곳에서 렌사르 그레이트후프는 유물 무기를 손에 넣고 세월의 씨앗을 심어 운명을 대지와 엮어 달라고 청했다. 그렇게 세나리온 의회의 가장 새로운 대드루이드가 되었다."
L["Archdruid's Campaign"] = "대드루이드의 대장정"
L["Archimonde, The Defiler"] = "파멸자 아키몬드"
L["Archmage Kalec"] = "대마법사 칼렉"
L["Archmage Khadgar"] = "대마법사 카드가"
L["Archmage Melis"] = "대마법사 멜리스"
L["Archmage Modera"] = "대마법사 모데라"
L["Archmage Omniara"] = "대마법사 옴니아라"
L["Archmage Vargoth"] = "대마법사 바르고스"
L["Archmage Vargoth has vanished. Khadgar leads the search through his retreat, but a darker threat lurks behind his disappearance."] = "대마법사 바르고스가 사라졌습니다. 카드가가 그의 은신처를 뒤지며 수색을 이끌지만, 그의 실종 뒤에는 더 어두운 위협이 도사리고 있습니다."
L["Archmage Vargoth's Retreat"] = "대마법사 바르고스의 은거지"
L["Archmage's Campaign"] = "대마법사의 대장정"
L["Argent Aid"] = "은빛십자군의 도움"
L["Argent Vanguard"] = "은빛십자군 선봉기지"
L["Arko'narin Starshade"] = "아르코나린 스타셰이드"
L["Arluin"] = "알루인"
L["Arluin's Request"] = "알루인의 부탁"
L["Armies of Legionfall"] = "군단척결군"
L["Arming Dalaran"] = "달라란 무장시키기"
L["Arming the Army"] = "보급품 보충하기"
L["Arming the Rebels"] = "반군 무장"
L["Armor Fit For A Deathlord"] = "죽음군주에게 걸맞은 방어구"
L["Armor Stand"] = "갑옷 거치대"
L["Army of the Damned"] = "저주받은 자들의 군대"
L["Arom's Stand became the Order's new headquarters. Inquisitor Sterntide — one of the few who still remembered the old ways — gave you a crash course in witch hunting: silver weapons for the cursed, fire for the wicker, and sharp thinking for the witches themselves. You rooted out hidden dealings in the camp, exposed infiltrators wearing friendly faces, and trained new guards to replace the corrupted ones. When Lucille raised the Order's banner over Arom's Stand, the message was clear — the witches had hunted long enough. Now they were the prey."] = "아롬의 격전지는 잿불단의 새 본부가 되었다. 옛 방식을 아직 기억하는 몇 안 되는 이 중 하나인 심문관 스턴타이드가 마녀 사냥을 속성으로 가르쳐 주었다. 저주받은 자에게는 은 무기를, 고리버들 괴물에게는 불을, 마녀들에게는 날카로운 판단력을. 야영지에 숨은 뒷거래를 뿌리 뽑고, 친근한 얼굴을 한 첩자들을 폭로하고, 타락한 경비병을 대신할 새 경비병을 훈련시켰다. 루실이 아롬의 격전지 위로 잿불단의 깃발을 올리자 메시지는 분명해졌다. 마녀들의 사냥은 이제 끝났다. 이제 사냥감은 그들이었다."
L["Arthas died at the Frozen Throne. The moment he fell, the power of the Lich King's realm rippled outward — and Sylvanas, like every Forsaken sustained by that dark energy, briefly stopped. She died on her feet, alone at the pinnacle of Icecrown. A Val'kyr named Annhylde gave her life to pull her back. Sylvanas opened her eyes to wind and ice and herself, inexplicably, still breathing. She looked out at nothing for a long time. Then she went back to work. She never explained what she had seen. But the Val'kyr — the ones who would spend their own lives to keep her alive — suddenly became very important to her. Now she knew why."] = "아서스는 얼어붙은 왕좌에서 죽었다. 그가 쓰러진 순간, 리치 왕 영역의 힘이 물결처럼 퍼져 나갔다. 그리고 그 어둠의 힘으로 존재를 이어 가던 모든 포세이큰처럼, 실바나스도 잠시 멈추었다. 그녀는 얼음왕관의 정상에서 홀로 선 채 죽었다. 안힐드라는 발키르가 자신의 목숨을 바쳐 그녀를 되돌려 놓았다. 실바나스가 눈을 떴을 때 그곳에는 바람과 얼음, 그리고 영문도 모른 채 여전히 숨 쉬고 있는 자신이 있었다. 그녀는 한참 동안 허공을 바라보았다. 그리고 다시 할 일로 돌아갔다. 무엇을 보았는지 그녀는 끝내 말하지 않았다. 하지만 발키르, 자신의 목숨을 바쳐서라도 그녀를 살려 둘 존재들이 갑자기 그녀에게 무척 중요해졌다. 이제 그녀는 그 이유를 알았다."
L["Arthas Menethil"] = "아서스 메네실"
L["Arzaal"] = "아르자알"
L["As Strong As Our Will"] = "우리의 의지만큼 강하게"
L["Ascendant of Flames"] = "불의 계승자"
L["Ascending The Circle"] = "다시 마법진으로"
L["Ask and You Shall Receive"] = "물어라, 그러면 얻을 것이다"
L["Asking a Favor"] = "동력원을 부탁해"
L["Assassin Entrapment"] = "암살자 암살"
L["Assault by Air"] = "공중 공격"
L["Assault by Ground"] = "지상 공격"
L["Assault on the Airstrip"] = "비행장 급습"
L["Assault on Violet Hold: The Fel Lexicon"] = "보랏빛 요새 침공: 지옥 사전"
L["Assault the Scarlet Monastery to raise the third Horseman — High Inquisitor Whitemane, your oldest enemy turned servant."] = "붉은십자군 수도원을 습격해 세 번째 기수를 일으키세요. 오랜 숙적에서 이제 종이 될 자, 종교재판관 화이트메인입니다."
L["Assemble the Forsaken"] = "포세이큰 집결"
L["Assessing the Enemy"] = "적군 분석"
L["Asset Security"] = "자산 사수"
L["Assisting the Archmage"] = "대마법사 돕기"
L["At Arom's Stand, recruit and train the first new Inquisitors. Learn the old ways of witch hunting — silver, fire, and sharp thinking."] = "아롬의 격전지에서 첫 신입 심문관들을 모집하고 훈련시키세요. 은, 불, 그리고 날카로운 판단력. 마녀 사냥의 옛 방식을 익히세요."
L["At Odyn's command, you rallied the finest warriors the world had to offer. Finna Bjornsdottir and Ragnvald Drakeborn pledged their blades to your cause. Under Skyseer Ghrent's guidance, you recruited troops, dispatched them to the Broken Isles, and established Skyhold as a true war machine — Einar the Runecaster fortifying your forces with ancient vrykul magic."] = "오딘의 명에 따라 세상에서 가장 뛰어난 전사들을 규합했다. 핀나 비요른스도티르와 라그느발드 드레이크본이 대의를 위해 검을 바치기로 맹세했다. 하늘현자 그렌트의 안내 아래 병력을 모집해 부서진 섬으로 파견하고, 하늘보루를 진정한 전쟁 기계로 탈바꿈시켰다. 룬마술사 이나르는 고대 브리쿨 마법으로 군대를 강화했다."
L["At the Bottom of the Sea"] = "바다 밑바닥에서"
L["At the Maelstrom's edge, the Earthen Ring struggles to keep Azeroth from tearing apart. The elements are restless, wounded, and not always willing to answer.\n\nAs Farseer, seek the elemental lords, restore balance where the world is breaking, and hold the center while the Legion tries to pull everything apart."] = "혼돈의 소용돌이 가장자리에서, 대지 고리회는 아제로스가 찢어지지 않도록 힘겹게 버티고 있습니다. 정령들은 불안하고, 상처 입었으며, 언제나 부름에 응하지도 않습니다.\n\n선견자로서 정령 군주들을 찾아 나서고, 세상이 무너지는 곳에 균형을 되찾으며, 불타는 군단이 모든 것을 갈라놓으려 하는 동안 중심을 지키세요."
L["At the northern edge of the forest, a wounded sprite led you into an older, stranger grief. The mogu had bound spirits into vessels, rituals, and stone. Pei-Zhi needed those cycles broken before the dead were consumed by someone else's ambition. You shattered simulacrums, gathered ritual artifacts, released wayward spirits, returned beasts to nature, and offered the humility the terrace demanded. To bridge earth and sky, you had to answer the past without trying to own it."] = "숲의 북쪽 끝에서, 상처 입은 정령이 더 오래되고 기이한 슬픔으로 이끌었다. 모구는 영혼들을 그릇과 의식, 그리고 돌에 묶어 두었다. 페이즈는 망자들이 다른 누군가의 야망에 삼켜지기 전에 그 순환을 끊어야 했다. 허상을 부수고, 의식 유물을 모으고, 떠도는 영혼들을 풀어 주고, 짐승들을 자연으로 돌려보내고, 정원이 요구하는 겸손을 바쳤다. 험한 세상과 하늘에 다리가 되어 주려면, 과거를 소유하려 하지 말고 과거에 답해야 했다."
L["At the Source"] = "근원에서"
L["At Tian Monastery, training means discipline, hospitality, a proper weapon, and learning not to solve every problem as a soldier."] = "티엔 수도원에서의 수련이란 규율과 환대, 제대로 된 무기, 그리고 모든 문제를 군인처럼 해결하지 않는 법을 배우는 것입니다."
