L["Baine Bloodhoof"] = "바인 블러드후프"
L["Baine Bloodhoof has decided Derek Proudmoore cannot be used as a weapon against his own family and asks for your help freeing him. The plan runs through Plunder Harbor under false colors, with Thomas Zelling — the very tidesage Lilian helped raise — guiding the escape from the inside. When Baine and Zelling are punished for their defiance, Lilian says nothing to Sylvanas. She tells Zelling's family he died a hero. Then the War Campaign rolls on regardless — Warfang Hold needs securing, and Nathanos is already planning the next move."] = "바인 블러드후프는 데릭 프라우드무어를 그의 가족을 겨누는 무기로 쓰게 둘 수 없다고 결심하고, 그를 풀어 주는 데 도움을 청합니다. 계획은 위장한 깃발을 달고 약탈의 항구를 거쳐 진행되며, 릴리안이 되살리는 일을 도왔던 바로 그 파도현자 토마스 젤링이 안에서 탈출을 이끕니다. 바인과 젤링이 반항의 대가로 처벌받자, 릴리안은 실바나스에게 아무 말도 하지 않습니다. 대신 젤링의 가족에게 그가 영웅으로 죽었다고 전합니다. 그럼에도 전쟁 캠페인은 계속됩니다. 전쟁송곳니 주둔지를 확보해야 하고, 나타노스는 이미 다음 수를 계획하고 있습니다."
L["Baine Bloodhoof is to be executed. Lor'themar has gathered allies to defy the Warchief and save the Tauren chieftain."] = "바인 블러드후프가 처형될 위기에 처했습니다. 로르테마르가 대족장에 맞서 타우렌 족장을 구하기 위해 동맹을 모았습니다."
L["Baine Bloodhoof looked at Derek Proudmoore — raised, hollowed out, aimed at his own kin — and decided he would not be part of it. He asked for your help. Thomas Zelling, the tidesage whose raising Lilian had stood witness to in Stormsong, helped guide Derek out from the inside. They freed him.\n\nSylvanas had Baine arrested and Zelling killed. Lilian said nothing aloud. Later, quietly, she went to Zelling's family and told them he had died a hero. It was not defiance. It was a choice. Small enough that no one noticed. Large enough that she did.\n\nAnd then the war moved on. Warfang Hold needed to be secured for a leadership summit. Boss Mida handled the SI:7 spies and the gate-crashers. Nathanos arrived to make a display of the Horde's strength. The machine kept turning, indifferent to what had just been lost."] = "바인 블러드후프는 데릭 프라우드무어를 바라보았다. 되살아나 텅 빈 껍데기가 된 채, 자신의 혈육을 겨누게 된 그를. 그리고 이 일에 가담하지 않기로 결심했다. 그는 도움을 청했다. 스톰송에서 릴리안이 그 부활을 지켜보았던 파도현자 토마스 젤링이 안에서 데릭의 탈출을 도왔다. 그들은 데릭을 풀어 주었다.\n\n실바나스는 바인을 체포하고 젤링을 처형했다. 릴리안은 아무 말도 하지 않았다. 훗날 그녀는 조용히 젤링의 가족을 찾아가 그가 영웅으로 죽었다고 전했다. 반항은 아니었다. 선택이었다. 아무도 알아차리지 못할 만큼 작지만, 그녀 자신은 알아차릴 만큼 큰 선택이었다.\n\n그리고 전쟁은 계속되었다. 지도자 회담을 위해 전쟁송곳니 주둔지를 확보해야 했다. 두목 미다는 SI:7 첩자들과 불청객들을 처리했다. 나타노스는 호드의 힘을 과시하러 나타났다. 방금 무엇을 잃었는지에는 아랑곳없이, 기계는 계속 돌아갔다."
