L["Belath's intelligence pointed to a Legion commander hiding in Stormheim. Malace Shade tracked the demon through vrykul lands while you disrupted their rune networks. The trail led to Niskara — a demon world that could only be reached by jumping the Fel Hammer through a portal. You forged deadlier warglaives, fueled the ship's engines with demonic power, and launched the invasion. On Niskara, you cut through the Legion's defenses, destroyed their command structure, and earned the title of Slayer — the demon hunters' highest honor."] = "벨라스의 정보는 스톰하임에 숨은 군단 지휘관을 가리켰다. 말리스 셰이드가 브리쿨의 땅을 가로질러 악마를 추적하는 동안, 그들의 룬 연결망을 교란했다. 흔적은 니스카라로 이어졌다. 지옥 망치호를 차원문으로 도약시켜야만 닿을 수 있는 악마의 세계였다. 더 치명적인 전투검을 벼리고, 악마의 힘으로 함선의 엔진에 동력을 채운 뒤 침공을 개시했다. 니스카라에서 군단의 방어를 뚫고 지휘 체계를 무너뜨려, 악마사냥꾼 최고의 영예인 학살자 칭호를 얻었다."
L["Belmont's Report"] = "벨몬트의 보고서"
L["Beneath Dalaran lies the Hall of the Guardian, seat of the ancient Tirisgarde: mages sworn to protect Azeroth from magical threats that ordinary armies cannot understand.\n\nAs the order's newest Archmage, investigate hidden enemies, recover lost allies, and defend the Kirin Tor from dangers that wear familiar faces."] = "달라란 아래에는 고대 티리스가드의 본거지인 수호자의 전당이 있습니다. 티리스가드는 평범한 군대로는 이해할 수 없는 마법의 위협으로부터 아제로스를 지키기로 맹세한 마법사들입니다.\n\n결사의 가장 새로운 대마법사로서 숨은 적을 조사하고, 잃어버린 동료들을 되찾고, 익숙한 얼굴을 한 위험으로부터 키린 토를 지키세요."
L["Beneath Light's Hope Chapel lies the Sanctum of Light, where the Knights of the Silver Hand reform under your command. The Legion threatens every oath the order was built to keep.\n\nAs Highlord, unite paladins of many traditions, investigate demonic plans, and bring the Light into battles where hope has started to thin."] = "희망의 빛 예배당 아래에는 빛의 성소가 있으며, 그곳에서 은빛 손 기사단이 대영주의 지휘 아래 다시 결성됩니다. 불타는 군단은 기사단이 지키기로 한 모든 맹세를 위협하고 있습니다.\n\n대영주로서 여러 전통의 성기사들을 하나로 모으고, 악마의 계획을 조사하며, 희망이 희미해지기 시작한 전장에 빛을 가져가세요."
