L["Bo Bo"] = "보 보"
L["Boarding the Skybreaker is the moment Icecrown changes scale. High Captain Justin Bartlett runs the deck. Sky-Commander Keller handles the flight line. Absalan the Pious blesses every salvo. The first sortie drops into Ymirheim, where the Scourge mines its saronite. The second swings west to the Broken Front, where a Scourge vanguard once mauled the 7th Legion's first landing. After that comes the grind: Poke and Prod, Against the Giants, Coprous the Defiled, the tinker Kibli Killohertz and his lightning-based sarcasm. Farther west, past the Valley of Lost Hope, Thassarian cracks open the Desolation Gate with borrowed Scourge ordnance and a half-broken jumpbot. By the time the Skybreaker swings east again, the Guardians of Corp'rethar are already in the crosshairs."] = "하늘파괴자호에 오르는 순간, 얼음왕관의 규모가 달라진다. 수석 선장 저스틴 바틀릿이 갑판을 지휘한다. 하늘사령관 켈러가 비행 대열을 맡는다. 신앙심 깊은 압살란은 모든 일제 사격을 축복한다. 첫 출격은 스컬지가 사로나이트를 채굴하는 이미르하임으로 향한다. 두 번째 출격은 서쪽의 부서진 전선으로 향한다. 일찍이 스컬지 선봉대가 제7군단의 첫 상륙 부대를 짓밟은 곳이다. 그 뒤로는 고된 싸움이 이어진다. 적을 알아내는 법, 거인에 맞서라!, 타락자 코프루스, 그리고 번개 같은 독설을 퍼붓는 땜장이 키블리 킬로헤르츠까지. 더 서쪽, 잃어버린 희망의 골짜기 너머에서는 타사리안이 빌려 온 스컬지 병기와 반쯤 망가진 점프봇으로 황폐의 관문을 열어젖힌다. 하늘파괴자호가 다시 동쪽으로 선회할 무렵, 코르프레타르의 수호자들은 이미 조준선 안에 들어와 있다."
L["Bodies are turning up across the Broken Isles, and the trail leads to a chilling conspiracy deep within SI:7 itself."] = "부서진 섬 곳곳에서 시신이 발견되고, 그 흔적은 SI:7 내부 깊숙이 뻗은 섬뜩한 음모로 이어집니다."
L["Bodies started appearing across the Broken Isles — agents killed with surgical precision. The trail led you through a web of betrayal reaching into SI:7 itself. Working with Fleet Admiral Tethys and Marin Noggenfogger, you gathered evidence and allies while throwing SI:7 off your scent, uncovering a conspiracy far deeper than anyone suspected."] = "부서진 섬 곳곳에서 시신들이 나타나기 시작했다. 외과 수술처럼 정밀하게 살해된 요원들이었다. 흔적을 따라가자 SI:7 내부까지 뻗은 배신의 거미줄이 드러났다. 함대 사령관 테시스, 마린 노겐포저와 함께 SI:7의 추적을 따돌리며 증거와 동료를 모았고, 누구도 짐작하지 못한 깊은 음모를 밝혀냈다."
