L["Brewmaster Blanche"] = "양조사 블랜치"
L["Brewmaster Blanche fell to a Legion poison on the Broken Shore, her spirit lingering to guide you. You brewed a cure from fel ingredients, saved who you could, and secured the Shore for the monks. Then came word of Ban-Lu — a celestial tiger who had served every Grandmaster since the order's founding. Master Bu led you across Pandaria following the tiger's trail through history: his shadow in the Jade Forest, his river in the Valley, his trial at the peak. When Ban-Lu finally appeared, he spoke — and declared you worthy. The Grandmaster had found a companion."] = "양조사 블랜치는 부서진 해변에서 군단의 독에 쓰러졌고, 그녀의 영혼은 이승에 남아 길을 안내했다. 지옥 재료로 치료제를 빚어 구할 수 있는 이들을 구하고, 수도사들을 위해 해변을 확보했다. 그때 반루에 관한 소식이 전해졌다. 교단이 세워진 이래 모든 대가를 섬겨 온 천신 호랑이였다. 사부 부의 안내로 판다리아를 가로지르며 역사 속 호랑이의 자취를 따라갔다. 비취 숲에 드리운 그림자, 골짜기의 강, 봉우리 위의 시험. 마침내 모습을 드러낸 반루는 입을 열어 자격이 있다고 선언했다. 대가가 동반자를 얻은 것이다."
L["Brick By Brick"] = "눈에는 눈, 주먹에는 주먹"
