L["Build the Illidari's strength on the Fel Hammer. Recruit champions, train troops, and prove yourself leader of the demon hunters."] = "지옥 망치호에서 일리다리의 힘을 키우세요. 용사를 영입하고 병력을 훈련시켜 악마사냥꾼의 지도자임을 증명하세요."
L["Build the order hall's strength by recruiting legendary rogues as champions and establishing operations throughout the Broken Isles."] = "전설적인 도적들을 용사로 영입하고 부서진 섬 전역에 작전 거점을 세워 직업 전당의 힘을 키우세요."
L["Build, test, and defend the X-52 while goblin politics and greed explode all around you."] = "고블린의 정치와 탐욕이 사방에서 폭발하는 가운데 X-52를 만들고, 시험하고, 지켜 내세요."
L["Building Our Troops"] = "병력 편성"
L["Buried Power"] = "파묻힌 힘"
L["Burn Doctor Olakin Sainrith's plague lab, save Father Kamaros's people, and finish the Runesmiths' work."] = "의사 올라킨 세인리스의 역병 실험실을 불태우고, 신부 카마로스의 사람들을 구하고, 룬대장장이들의 과업을 마무리하세요."
L["Burning Down the House"] = "초가삼간 불태우기"
L["Burning Within"] = "깊은 곳의 화염"
L["Business, betrayal, and big explosions: a proper goblin story. You helped Hobart finish the X-52, survived every reckless test, crushed Gallywix's takeover, and earned the right to wear the pride of Kezan."] = "사업, 배신, 그리고 거대한 폭발. 그야말로 고블린다운 이야기였다. 호바트를 도와 X-52를 완성하고, 무모한 시험을 모두 견뎌 내고, 갤리윅스의 탈취 시도를 분쇄하여 케잔의 자부심을 걸칠 자격을 얻었다."
L["Buyers Wanted!"] = "구매자 모집 공고"
