L["Calydus"] = "칼리두스"
L["Calydus pointed you toward Ulthalesh — the Deadwind Harvester, a scythe of terrible power that had reaped souls for millennia. You followed the curse through Deadwind Pass, where the Dark Riders still haunted the roads. In their shadowed lair, you tore Ulthalesh from their grasp. The scythe's whispers joined the chorus in your mind — a weapon that was never truly silent."] = "칼리두스는 울타레쉬로 향하는 길을 알려 주었다. 수천 년 동안 영혼을 거둬 온 끔찍한 힘의 낫, 저승바람 수확자였다. 저주를 따라 저승바람 고개로 향했고, 그곳의 길에는 아직도 어둠의 기수들이 출몰했다. 그들의 그늘진 은신처에서 울타레쉬를 빼앗았다. 낫의 속삭임이 머릿속의 합창에 더해졌다. 결코 진정으로 침묵하지 않는 무기였다."
L["Calydus revealed the location of the Scepter of Sargeras — a weapon capable of tearing holes between dimensions, wielded by the Dark Titan's own lieutenants. You found it sealed in a vault warded against mortal hands. But a warlock's hands were never quite mortal. You broke the wards, claimed the Scepter, and felt the fabric of reality shudder around you. The power to break worlds was now in your grip."] = "칼리두스는 살게라스의 홀이 있는 곳을 밝혔다. 어둠의 티탄의 부관들이 휘두르던, 차원과 차원 사이에 구멍을 뚫을 수 있는 무기였다. 그것은 필멸자의 손이 닿지 못하도록 보호된 금고 안에 봉인되어 있었다. 하지만 흑마법사의 손은 결코 온전히 필멸자의 것이 아니었다. 보호막을 깨뜨리고 홀을 손에 넣자, 주변의 현실이 전율하는 것이 느껴졌다. 세계를 부수는 힘이 이제 손안에 있었다."
L["Calydus spoke of the Skull of the Man'ari — an eredar artifact of staggering summoning power. The ritual reagents alone were dangerous enough to kill a lesser warlock. You gathered them, performed the summoning, and wrested the Skull from the eredar lord who guarded it. The Skull's eyes glowed with malevolent intelligence, as if the demon trapped within was already planning its next move."] = "칼리두스는 만아리의 해골에 관해 이야기했다. 압도적인 소환의 힘을 지닌 에레다르 유물이었다. 의식에 쓰일 재료만으로도 미숙한 흑마법사는 목숨을 잃을 만큼 위험했다. 재료를 모아 소환 의식을 치르고, 해골을 지키던 에레다르 군주에게서 그것을 빼앗았다. 해골의 눈은 사악한 지성으로 빛났다. 마치 그 안에 갇힌 악마가 이미 다음 수를 꾸미고 있는 것처럼."
