L["Chief Plaguebringer Middleton has been busy in the Carrion Fields. He has something new to test — a blight meant to undo the Scourge where steel cannot reach. The formula wants a subject. Middleton smiles through gritted teeth and swears the first dose is always the worst. Whatever the Apothecaries are cooking under the Horde's banner, it may reshape this war."] = "고위 역병인도자 미들턴은 시체 들판에서 바쁘게 움직이고 있다. 그에게는 시험할 새로운 것이 있다. 강철이 닿지 않는 곳에서 스컬지를 무너뜨리기 위한 역병이다. 공식에는 실험 대상이 필요하다. 미들턴은 이를 악문 채 미소 지으며, 첫 투약이 언제나 가장 힘든 법이라고 장담한다. 호드의 깃발 아래 약제사들이 무엇을 만들고 있든, 그것은 이 전쟁의 판도를 바꿀지도 모른다."
L["Chief Telemancer Oculeth"] = "수석 이동술사 오큘레스"
L["Chieftain Hatuun"] = "족장 하투운"
L["Cho slows the Horde campaign long enough to teach the land's memory, then the hozen pull you back into motion."] = "초는 땅의 기억을 가르치기 위해 호드의 진군을 잠시 늦추지만, 이내 호젠들 때문에 다시 바삐 움직이게 됩니다."
L["Chon Po Stormstout"] = "촌 포 스톰스타우트"
L["Choppertunity"] = "사격 연습"
L["Chosen by Odyn himself, you ascend to Skyhold: the legendary warrior paradise above the clouds. The Valarjar measure worth in courage, scars, and the battles a champion is still willing to fight.\n\nAs Battlelord, recover ancient symbols of war, seek alliances with titan-forged powers, and lead warriors who believe glory is something earned in motion."] = "오딘이 직접 선택한 용사로서 구름 위 전설적인 전사들의 낙원, 하늘보루로 올라갑니다. 발라리아르는 용기와 흉터, 그리고 용사가 여전히 기꺼이 치르려는 전투로 가치를 가늠합니다.\n\n전투군주로서 고대 전쟁의 상징을 되찾고, 티탄이 벼려 낸 세력과 동맹을 맺으며, 영광은 멈추지 않고 나아가며 얻는 것이라 믿는 전사들을 이끄세요."
L["Chromie"] = "크로미"
L["Chromie of the Bronze Dragonflight sends you back to Stratholme, to a day history remembers in silence. The Infinite Dragonflight would rewrite this moment. Yours is the harder task: walk beside a young Prince Arthas Menethil and keep time honest, whatever price the past demands."] = "청동용군단의 크로미가 스트라솔름으로 돌려보낸다. 역사가 침묵으로 기억하는 바로 그날로. 무한용군단은 이 순간을 다시 쓰려 한다. 이쪽에 주어진 임무는 더 어렵다. 젊은 왕자 아서스 메네실의 곁을 걸으며, 과거가 어떤 대가를 요구하든 시간을 바르게 지켜야 한다."
L["Cities in Dust"] = "먼지가 된 도시"
L["Citizens' Army"] = "시민군"
L["Claim the Ashbringer, the legendary blade that burned with holy fire and shattered the Scourge."] = "성스러운 불꽃으로 타오르며 스컬지를 산산이 부순 전설의 검, 파멸의 인도자를 손에 넣으세요."
L["Claim the Fists of the Heavens, a pair of enchanted handwraps charged with the fury of storms."] = "폭풍의 분노가 깃든 마법의 손싸개 한 쌍, 천상의 주먹을 손에 넣으세요."
L["Claim Xal'atath, a dagger that whispers with the voice of the Void and remembers the Black Empire that ruled before the titans."] = "공허의 목소리로 속삭이며 티탄 이전에 세상을 지배한 검은 제국을 기억하는 단검, 잘아타스를 손에 넣으세요."
