L["Complete Armies of Legionfall on the Broken Shore, then return to the Hall of Shadows to begin the final class mount chapter."] = "부서진 해변에서 군단척결군을 완료한 뒤, 어둠의 전당으로 돌아가 마지막 직업 탈것 장을 시작하세요."
L["Complete the Forsaken Heritage questline as an Undead character. Requires having sided with Sylvanas during the war campaign."] = "언데드 캐릭터로 포세이큰 유산 퀘스트 라인을 완료하세요. 전쟁 캠페인에서 실바나스의 편에 섰어야 합니다."
L["Complete the Horde War Campaign introduction and travel to Zuldazar to unlock this chapter."] = "호드 전쟁 캠페인 도입부를 완료하고 줄다자르로 이동하면 이 장이 열립니다."
L["Complete the Horde War Campaign through Stormsong Valley to unlock this chapter."] = "호드 전쟁 캠페인을 스톰송 계곡까지 진행하면 이 장이 열립니다."
L["Complete the Kul Tiras intro and War Campaign chapters to unlock, then speak with Mathias Shaw in Proudmoore Keep."] = "쿨 티라스 도입부와 전쟁 캠페인 장을 완료해 잠금을 해제한 뒤, 프라우드무어 요새에서 마티아스 쇼와 대화하세요."
L["Complete the Silver Hand's reformation. Recruit Arator and Lothraxion, and accept the title of Highlord."] = "은빛 손 기사단의 재건을 완수하세요. 아라토르와 로스락시온을 영입하고 대영주 칭호를 받아들이세요."
L["Complete the Zereth Mortis campaign and defeat the Jailer in the Sepulcher of the First Ones raid."] = "제레스 모르티스 캠페인을 완료하고 태초의 존재의 매장터 공격대에서 간수를 처치하세요."
L["Confront Mueh'zala's influence, recover forgotten loa, and complete a Trial of the Loa worthy of the Darkspear."] = "무에잘라의 영향력에 맞서고, 잊힌 로아를 되찾고, 검은창 부족에 걸맞은 로아의 시련을 완수하세요."
L["Confrontation at the Black Temple"] = "검은 사원에서의 대면"
