L["Corlain was a nightmare — hexed citizens wandered the streets, ruinous rituals played out in every alley, and the coven's strongest witches guarded the approach to the manor. You cut through them all. Lucille led the final charge to the gates of Waycrest Manor itself, where her mother — Lady Waycrest, consumed by Gorak Tul's power — waited in the depths. In the dungeon beneath the manor, you faced the fallen mother and broke the Drust king's hold on her. The curse over Drustvar shattered like glass. Lucille knelt beside her mother's body, the heir of a house that would rebuild. The witchwood was silent at last."] = "콜레인은 악몽 그 자체였다. 저주에 걸린 주민들이 거리를 헤매고, 골목마다 파멸의 의식이 벌어졌으며, 마녀단의 가장 강력한 마녀들이 저택으로 향하는 길을 지키고 있었다. 그 모두를 베어 넘겼다. 루실은 웨이크레스트 저택의 정문을 향한 마지막 돌격을 이끌었다. 그 깊은 곳에서는 고라크 툴의 힘에 잠식된 그녀의 어머니, 부인 웨이크레스트가 기다리고 있었다. 저택 아래 던전에서 타락한 어머니와 맞서, 드러스트 왕이 그녀에게 건 속박을 끊어 냈다. 드러스트바를 뒤덮은 저주가 유리처럼 산산이 부서졌다. 루실은 다시 일어설 가문의 후계자로서 어머니의 시신 곁에 무릎을 꿇었다. 마침내 마녀림에 정적이 찾아왔다."
