L["Dahlia's Tears"] = "달리아의 눈물"
L["Dalaran"] = "달라란"
L["Dalaran / Broken Isles"] = "달라란 / 부서진 섬"
L["Danica the Reclaimer"] = "되찾는 자 다니카"
L["Danica the Reclaimer appeared to you in Dalaran bearing a message from Odyn himself — the All-Father had been watching, and he found you worthy. You ascended to Skyhold, the legendary warrior paradise suspended above the clouds, where Odyn named you champion of the Valarjar and bade you claim an artifact weapon fit for the battles ahead."] = "되찾는 자 다니카가 달라란에 나타나 오딘이 직접 보낸 전언을 전했다. 만물의 아버지가 줄곧 지켜보고 있었으며, 자격이 있다고 판단했다는 것이었다. 구름 위에 떠 있는 전설적인 전사들의 낙원, 하늘보루로 올라가자, 오딘은 발라리아르의 용사로 임명하고 앞으로의 전투에 걸맞은 유물 무기를 손에 넣으라 명했다."
L["Darion Mograine revealed the Lich King's plan — to raise the Four Horsemen, death knights of legendary power, to serve as the Ebon Blade's vanguard. The first was Nazgrim, the Horde general who fell defending the gates of Orgrimmar. You tore his spirit from the grave and bound it in service. Thassarian and Nazgrim pledged as your champions, and the order's forces began to take shape — troops recruited, missions dispatched, and a war machine built from bone and shadow."] = "다리온 모그레인이 리치 왕의 계획을 밝혔다. 전설적인 힘을 지닌 죽음의 기사인 네 기수를 일으켜 칠흑의 기사단의 선봉으로 삼는 것이었다. 첫 번째는 오그리마의 정문을 지키다 쓰러진 호드의 장군 나즈그림이었다. 무덤에서 그의 영혼을 끌어내 섬기도록 속박했다. 타사리안과 나즈그림이 용사로서 충성을 맹세했고, 기사단의 전력이 모습을 갖추기 시작했다. 병력을 모집하고, 임무를 보내며, 뼈와 그림자로 이루어진 전쟁 기계를 세웠다."
L["Darion Mograine spoke of Frostmourne — the Lich King's blade, shattered atop Icecrown Citadel. Its shards still radiated power, and the call of Icecrown pulled you north. In the frozen throne room, you gathered the remnants and reforged them into the Blades of the Fallen Prince — twin runeblades that carried echoes of Arthas, Ner'zhul, and every soul the original sword had devoured."] = "다리온 모그레인은 서리한에 관해 이야기했다. 얼음왕관 성채 꼭대기에서 산산조각 난 리치 왕의 검이었다. 그 파편들은 여전히 힘을 내뿜었고, 얼음왕관의 부름이 북쪽으로 이끌었다. 얼어붙은 왕좌의 방에서 잔해를 모아 타락한 왕자의 칼날로 다시 벼려 냈다. 아서스와 넬쥴, 그리고 원래의 검이 삼킨 모든 영혼의 메아리를 품은 한 쌍의 룬검이었다."
L["Dark Iron Machinations"] = "검은무쇠의 계략"
L["Dark Ranger Alina"] = "어둠 순찰자 앨리나"
L["Dark Ranger Velonara"] = "어둠 순찰자 벨로나라"
L["Dark Ranger Vorel"] = "어둠 순찰자 보렐"
L["Dark Secrets and Shady Deals"] = "추악한 비밀과 더러운 거래"
L["Darkhaven's crisis brought you into the shadow of Castle Nathria. Lord Chamberlain showed you the Stoneborn, Revendreth's gargoyle guardians, and carried your request to the Harvesters. Then you met Sire Denathrius: ancient, immaculate, and utterly certain of his own necessity. He promised aid, but only after you helped him discipline the rebellion tearing through his realm. His authority filled the court like perfume and poison. Revendreth's nobles bowed. The Stoneborn obeyed. And for the moment, you were expected to do the same."] = "어둠안식처의 위기는 나스리아 성채의 그림자 속으로 이끌었다. 시종장은 레벤드레스의 가고일 수호자인 돌숨결을 보여 주고, 수확자들에게 요청을 전했다. 그리고 대영주 데나트리우스를 만났다. 오래되고, 흠잡을 데 없으며, 자신이 꼭 필요한 존재임을 털끝만큼도 의심하지 않는 자였다. 그는 도움을 약속했지만, 그의 영역을 휩쓰는 반란을 다스리는 일을 먼저 도와야 한다고 했다. 그의 권위는 향수처럼, 그리고 독처럼 궁정을 가득 채웠다. 레벤드레스의 귀족들은 고개를 숙였다. 돌숨결은 복종했다. 그리고 당분간은 이쪽도 그렇게 하기를 요구받았다."
L["Darkheart Thicket"] = "어둠심장 숲"
L["Darkheart Thicket: Nightmare Oak"] = "어둠심장 숲: 악몽의 떡갈나무"
L["Darkheart Thicket: The Nightmare Lash"] = "어둠심장 숲: 악몽의 채찍"
L["Darkrider Arly"] = "어둠기수 알리"
L["Darkspeaker R'khem"] = "암흑예언자 르켐"
L["Daughter of the Sea"] = "바다의 딸"
L["Dawn's Blossom"] = "새벽의 꽃"
L["Dawn's Blossom slowed the campaign down long enough for you to see the people under it. Cho, Toya, and the villagers asked for something different than victory. An Windfur's missing cubs led to the Jade Witch and a curse hiding behind a grandmother's smile. The Goldendraft and Wanderbrew families needed courage more than soldiers, and the Arboretum needed ink, color, and permission before a marriage could heal an old feud. It was not a detour. It was the point: Pandaria was full of lives that had nothing to do with the Alliance or Horde until the war made everything their problem."] = "새벽의 꽃에서 캠페인의 속도가 늦춰진 덕분에, 그 아래에서 살아가는 사람들을 볼 수 있었다. 초와 토야, 그리고 마을 사람들은 승리와는 다른 것을 원했다. 안 윈드퍼의 사라진 새끼들을 찾다 보니 비취 마녀와 할머니의 미소 뒤에 숨은 저주에 이르렀다. 골든드래프트 가문과 원더브루 가문에게는 병사보다 용기가 필요했고, 수목원에서는 결혼으로 오랜 반목을 치유하기 전에 먹물과 색채, 그리고 허락이 필요했다. 이는 곁길이 아니었다. 바로 이것이 핵심이었다. 판다리아에는 전쟁이 모든 것을 그들의 문제로 만들기 전까지 얼라이언스나 호드와 아무 상관도 없던 삶들이 가득했다."
L["Dazar'alor"] = "다자알로"
L["De Darkspear Loa"] = "검은창의 로아"
L["De Loa of de Past"] = "과거의 로아"
L["De Old Loa"] = "오래된 로아"
L["De Power of Death"] = "죽음의 힘"
