L["Debt Collection!"] = "떼인 돈 받아드립니다!"
L["Debt Repaid"] = "빚 갚기"
L["Decipher the Legion's Codex of Command. The Violet Hold holds a demon who can translate it — but at what cost?"] = "군단의 지휘의 고문서를 해독하세요. 보랏빛 요새에는 그것을 번역할 수 있는 악마가 갇혀 있습니다. 하지만 그 대가는?"
L["Deciphering the Letter"] = "편지 해독"
L["Deep beneath the earth, a titan research facility holds the worst mistake the Pantheon ever made. G'huun has to die."] = "땅속 깊은 곳, 티탄 연구 시설에는 판테온이 저지른 최악의 실수가 잠들어 있습니다. 그훈은 반드시 죽어야 합니다."
L["Deep Dive"] = "심해 잠수"
L["Deep Doubts, Deep Wisdom"] = "깊은 의심과 깊은 지혜"
L["Deep in the Bowels of The Underhalls"] = "지하 전당 속 깊숙이"
L["Deep in the mountains of Highmountain lay a shield forged from a scale of Neltharion, the Earth-Warder — before madness claimed him and he became Deathwing. You braved the ancient caverns and faced the guardians left behind to protect it. The Scale of the Earth-Warder was heavier than any shield you had ever held, but it was unyielding — and so were you."] = "높은산의 깊은 산중에는 대지수호자 넬타리온이 광기에 사로잡혀 데스윙이 되기 전, 그의 비늘로 벼려 낸 방패가 잠들어 있었다. 고대 동굴을 헤치고 들어가 그것을 지키도록 남겨진 수호자들과 맞섰다. 대지수호자의 비늘은 지금껏 들어 본 그 어떤 방패보다 무거웠지만, 결코 굽히지 않았다. 그것을 든 자도 마찬가지였다."
L["Deep in the Swamp"] = "늪 깊은 곳에서"
L["Deep in the tunnels beneath Suramar, you found Arcanist Kel'danath on the edge of withering, his brilliant mind nearly consumed by mana starvation. You fought through packs of feral withered to reach him, recovering his scattered research notes and the remnants of his arcane experiments. His knowledge of ancient Nightborne magic proved invaluable to the growing rebellion."] = "수라마르 아래 터널 깊은 곳에서 찾아낸 비전술사 켈다나스는 메마른 자로 전락하기 직전이었다. 그의 뛰어난 정신은 마나 결핍으로 거의 잠식되어 있었다. 야생의 메마른 자 무리를 뚫고 그에게 다가가, 흩어진 연구 기록과 비전 실험의 잔해를 되찾았다. 고대 나이트본 마법에 대한 그의 지식은 커져 가는 반란에 더없이 귀중한 힘이 되었다."
L["Deeper into the Woods"] = "더 깊은 숲속으로"
L["Deepholm stirs with twilight corruption. Seek Therazane the Stonemother and purge the Twilight's Hammer from her domain."] = "심원의 영지가 황혼의 타락으로 들끓고 있습니다. 바위어머니 테라제인을 찾아가 그녀의 영역에서 황혼의 망치단을 몰아내세요."
L["Defenders of the Dream"] = "꿈의 수호자"
L["Defenders of the World"] = "세상의 수호자"
L["Defending the Isles"] = "부서진 섬 사수"
L["Defending The Vanguard"] = "십자군 방어"
L["Defense of Aviana"] = "아비아나 방어"
L["Defense of Quel'Danas"] = "쿠엘다나스 방어"
L["Defense of the Fel Hammer"] = "지옥 망치호 방어"
L["Defense of Tian Monastery"] = "티엔 수도원 방어"
L["Defiance"] = "저항"
L["Delas Moonfang"] = "델라스 문팽"
L["Delegation"] = "위임"
L["Deliverance from the Pit"] = "구덩이로부터의 해방"
L["Delivery for Kasea"] = "카시에게 배달"
L["Delve into a demonic vault to claim a pair of shadow-forged blades that hunger for souls."] = "악마의 금고 깊숙이 들어가, 영혼을 갈망하는 그림자로 벼려 낸 한 쌍의 칼날을 손에 넣으세요."
L["Delve into Ironforge's deepest archives with Brann Bronzebeard, who has kept the chronicles longer than most dwarves have been alive. An old relic of the Bronzebeard line has been broken and scattered across roads with long memories.\n\nWalk those roads again, recover what was lost, and return to the great anvils where dwarven legacy is measured in craft, stubbornness, and stone."] = "대부분의 드워프가 살아온 세월보다 더 오래 연대기를 지켜 온 브란 브론즈비어드와 함께 아이언포지의 가장 깊은 기록 보관소로 들어가세요. 브론즈비어드 가문의 오래된 유물이 부서져, 오랜 기억을 간직한 길 곳곳에 흩어졌습니다.\n\n그 길을 다시 걸으며 잃어버린 것을 되찾고, 솜씨와 고집, 그리고 돌로 드워프의 유산을 가늠하는 거대한 모루로 돌아가세요."
L["Demonic Improvements"] = "악마의 지식"
L["Demonic Runes"] = "악마의 룬석"
L["Demons Among Us"] = "몰래 숨어든 악마"
L["Denathrius sends you after the Accuser, a rebel Harvester whose sinstone may prove she is no righteous dissenter."] = "데나트리우스의 명에 따라 반역한 수확자인 고발자를 쫓습니다. 그녀의 죄악석이 그녀가 정의로운 반대자가 아님을 증명할지도 모릅니다."
L["Derek Proudmoore had barely been hauled out of the sea before Sylvanas found a use for him — not as a weapon yet, but as bait. The Kul Tiran fleet chased his ghost while you and Nathanos hit Stormsong Monastery. Thomas Zelling, the tidesage whose raising Lilian had stood witness to, guided you from inside. He was doing what he was told. So was she. The Horde got its scepter. Lilian got her champion tabard. No one asked if any of it was right."] = "데릭 프라우드무어가 바다에서 끌려 나오자마자 실바나스는 그의 쓰임새를 찾아냈다. 아직 무기로서가 아니라 미끼로서였다. 쿨 티란 함대가 그의 망령을 쫓는 사이, 나타노스와 함께 스톰송 수도원을 들이쳤다. 릴리안이 그 부활을 지켜보았던 파도현자 토마스 젤링이 안에서 길을 안내했다. 그는 시키는 대로 하고 있었다. 그녀도 마찬가지였다. 호드는 홀을 손에 넣었다. 릴리안은 용사의 휘장을 얻었다. 이 모든 것이 옳은지 묻는 이는 아무도 없었다."
L["Derek Proudmoore's body is put to use before Lilian ever gets her orders: the Horde deploys him as bait to draw Kul Tiran warships away from Boralus, then drives a strike force into Stormsong Monastery to seize the Abyssal Scepter. Thomas Zelling — raised against his will just weeks ago — now fights for the Horde from inside the monastery walls. Lilian watches what the war makes of people."] = "릴리안이 명령을 받기도 전에 데릭 프라우드무어의 시신이 쓰임새를 찾습니다. 호드는 그를 미끼로 삼아 쿨 티란 전함들을 보랄러스에서 멀리 끌어낸 뒤, 타격대를 스톰송 수도원으로 보내 심연의 홀을 탈취합니다. 불과 몇 주 전 본인의 뜻과 상관없이 되살아난 토마스 젤링은 이제 수도원 담장 안에서 호드를 위해 싸웁니다. 릴리안은 전쟁이 사람을 어떻게 바꾸어 놓는지 지켜봅니다."
L["Descend into the depths to recover Sharas'dal, a scepter that commands the tides themselves."] = "깊은 바다로 내려가, 파도 그 자체를 다스리는 홀 샤라스달을 되찾으세요."
L["Desperate Strike"] = "최후의 일격"
L["Destroying the Altars"] = "제단 파괴"
L["Destroying the Cult"] = "이교도 소탕 작전"
