L["Discover the nightfallen exiles hiding in the ruins of Shal'Aran and learn the desperate truth behind Suramar's shimmering barrier."] = "샬아란의 폐허에 숨은 나이트폴른 망명자들을 찾아내고, 수라마르의 일렁이는 보호막 뒤에 숨은 절박한 진실을 알아내세요."
L["Disguise yourself as a Nightborne noble and infiltrate Suramar City to gather intelligence for the rebellion."] = "나이트본 귀족으로 변장하고 수라마르 성에 잠입해 반란군을 위한 정보를 모으세요."
