L["Dreadtick Combustion"] = "공포거미 폭파 작전"
L["Dredhollow"] = "공포 골짜기"
L["Dress in Scarlet cloth, take the Vault for the Ebon Blade, and ride up to Malykriss to kill four riders."] = "붉은십자군의 옷을 차려입고 칠흑의 기사단을 위해 금고를 점령한 뒤, 말리크리스로 올라가 네 기수를 처치하세요."
L["Drust Do It."] = "드러스트바의 결말이 드러나다"
L["Drustfall"] = "드러스트의 최후"
L["Drustvar"] = "드러스트바"
L["Duke August Foehammer"] = "대공 어거스트 포해머"
L["Duke Lankral"] = "공작 란크랄"
L["Duke Lankral appeared in Dalaran with an urgent summons — the Knights of the Ebon Blade needed you at Acherus. The Ebon Hold floated above the Broken Isles like a fortress of iron and frost, and Highlord Darion Mograine spoke of a pact of necessity: the living would fight the Legion their way, and the dead would fight it theirs. You claimed an artifact weapon forged for death itself."] = "공작 란크랄이 긴급한 소환장을 들고 달라란에 나타났다. 칠흑의 기사단이 아케루스에서 기다린다는 것이었다. 칠흑의 요새는 강철과 서리로 된 성채처럼 부서진 섬 위에 떠 있었고, 대영주 다리온 모그레인은 필요에 의한 협약을 이야기했다. 산 자는 산 자의 방식으로, 죽은 자는 죽은 자의 방식으로 군단과 싸우리라는 것이었다. 죽음 그 자체를 위해 벼려진 유물 무기를 손에 넣었다."
L["Duke Lankral summons you to Acherus, where the Ebon Blade prepares for a war that only the dead can fight."] = "공작 란크랄이 아케루스로 부릅니다. 그곳에서 칠흑의 기사단은 오직 죽은 자만이 싸울 수 있는 전쟁을 준비하고 있습니다."
L["Duke Lankral told of the Maw of the Damned — a vampiric greataxe that drank the blood of its enemies and fed it to its wielder. The weapon had been lost in a Legion stronghold, guarded by demons who had learned to fear it. You stormed their fortress and tore the Maw from the hands of its demonic captor. The axe drank deep on the way out."] = "공작 란크랄은 저주받은 자의 아귀에 관해 이야기했다. 적의 피를 마시고 그 피를 사용자에게 먹이는 흡혈의 대형 도끼였다. 그 무기는 군단의 요새에서 행방이 묘연해졌고, 그것을 두려워하게 된 악마들이 지키고 있었다. 요새로 쳐들어가 악마 포획자의 손에서 아귀를 빼앗았다. 빠져나오는 길에 도끼는 실컷 피를 마셨다."
L["Durak"] = "듀락"
L["Dvalen Ironrune"] = "드바렌 아이언룬"
L["Dying Berserker"] = "죽어가는 광전사"
