L["Einar the Runecaster"] = "룬마술사 이나르"
L["Either With Us"] = "우리와 함께하거나"
L["Eitrigg"] = "아이트리그"
L["Elder Lusshan"] = "장로 루샨"
L["Elder Sage Rain-Zhu"] = "원로 현자 레인주"
L["Elder Sage Wind-Yi"] = "원로 현자 윈드이"
L["Eliminate the Competition"] = "경쟁자 처치"
L["Elisande seals Suramar's gates and tightens her grip. The resistance must find a way through the lockdown."] = "엘리산드가 수라마르의 성문을 봉쇄하고 통제를 강화합니다. 저항군은 봉쇄를 뚫을 방법을 찾아야 합니다."
L["Elisande struck back with the full power of the Nightwell, warping time itself to halt the rebellion's advance. You worked with Valtrois to investigate the temporal distortions, scouted breaches in the Nighthold's defenses, and uncovered how the Grand Magistrix channeled the Nightwell's energy through ancient seals. Breaking those seals would be the key to reaching her."] = "엘리산드는 밤샘의 모든 힘을 동원해 반격했다. 시간 그 자체를 비틀어 반란군의 진격을 멈춘 것이다. 발트루아와 함께 시간 왜곡을 조사하고, 밤의 요새 방어의 틈을 정찰하여, 대마법학자가 고대의 봉인을 통해 밤샘의 힘을 끌어 쓰는 방법을 밝혀냈다. 그 봉인을 깨뜨리는 것이 그녀에게 닿는 열쇠가 될 것이었다."
L["Elisande's forces captured and experimented on nightfallen prisoners, transforming them into felborne abominations. You stormed the Felsoul experiments alongside Kel'danath and Oculeth, freeing those who could still be saved and putting down those who could not. The horrors you witnessed only strengthened the resolve of every rebel who fought beside you."] = "엘리산드의 군대는 나이트폴른 포로들을 붙잡아 실험하며 지옥에서 태어난 흉물로 바꾸어 놓았다. 켈다나스, 오큘레스와 함께 지옥영혼 실험장을 급습해 아직 구할 수 있는 이들을 풀어 주고, 그럴 수 없는 이들은 안식에 들게 했다. 그곳에서 목격한 참상은 함께 싸운 모든 반란군의 결의를 더욱 굳게 할 뿐이었다."
L["Elisande's Retort"] = "엘리산드의 반격"
L["Embodiment"] = "현신"
L["Emerald Dragon Tears"] = "에메랄드 용의 눈물"
L["Emergency Efforts"] = "비상 대응"
L["Emergency Response"] = "응급 대응"
L["Emissary"] = "사절"
L["Emissary Brighthoof"] = "사절 브라이트후프"
L["Emmarel Shadewarden"] = "에마렐 셰이드워든"
L["Empire of Dirt"] = "먼지의 제국"
L["Empower the Council's soul reserves. Dungeon delves, mad alchemists, and the question: who is truly worthy of power?"] = "의회의 영혼 저장고를 강화하세요. 던전 탐험, 미친 연금술사, 그리고 하나의 질문. 진정으로 힘을 가질 자격이 있는 자는 누구인가?"
L["Empty Package"] = "빈 꾸러미"
L["Empyrean Society Report"] = "창공 협회 관련 보고서"
L["Ending the Blood Trolls"] = "혈트롤의 최후"
L["Ending the Crescent Curse"] = "초승달의 저주를 푸는 법"
L["Ending the Inquisitor"] = "심문관의 최후"
L["Enemies Within"] = "내부의 적"
L["Enter Nightmare"] = "악몽으로의 초대"
L["Enter the Crimsonwood, face Gorak Tul's grand rite, and drive a stake into the heart of the Drust king's power."] = "진홍숲에 들어가 고라크 툴의 거대한 의식에 맞서고, 드러스트 왕의 힘의 심장에 말뚝을 박으세요."
L["Enter the dungeon, cleanse Yu'lon's sacred temple, and destroy the Sha of Doubt where it has taken root."] = "던전에 들어가 위론의 신성한 사원을 정화하고, 그곳에 뿌리내린 의심의 샤를 처치하세요."
L["Enter the Firelands and negotiate with Smolderon, the new Firelord, to secure the fire elementals' allegiance."] = "불의 땅에 들어가 새로운 화염군주 스몰데론과 협상하여 불 정령들의 충성을 확보하십시오."
L["Enter the Nightmare itself to relive the War of the Ancients and awaken Malorne, the great white stag, to fight once more."] = "악몽 그 자체로 들어가 고대의 전쟁을 다시 겪고, 거대한 흰 수사슴 말로른을 깨워 다시 한번 싸우게 하세요."
L["Envoy of the Alliance"] = "얼라이언스 특사"
L["Ephemeral Manastorm Projector"] = "단기 마나폭풍 투영기"
L["Epilogue (Sylvanas Loyalists)"] = "에필로그 (실바나스 충성파)"
L["Ernest Carlisle"] = "어니스트 칼라일"
L["Erunak Stonespeaker called you to the deeps — Sharas'dal, the Scepter of Tides, had been sensed stirring beneath the ocean floor. You descended into the crushing darkness where water elementals guarded the weapon with fierce devotion. The Scepter of Tides chose to rise with you, and the seas themselves seemed to bow as you surfaced."] = "에루낙 스톤스피커가 심해로 불렀다. 파도의 홀 샤라스달이 해저 아래에서 꿈틀거리는 것이 감지된 것이다. 숨 막히는 어둠 속으로 내려가자, 물의 정령들이 맹렬한 헌신으로 무기를 지키고 있었다. 파도의 홀은 함께 떠오르기를 택했고, 수면 위로 올라오자 바다마저 고개를 숙이는 듯했다."
L["Esara Verrinde"] = "이사라 베린드"
L["Essence of Plague"] = "역병의 정수"
L["Essence Triangulation"] = "정수 삼각 측량"
L["Establish a supply of ancient mana to sustain the nightfallen rebels and prevent them from withering."] = "나이트폴른 반란군을 지탱하고 그들이 메마른 자로 전락하지 않도록, 고대 마나를 공급할 방법을 마련하세요."
L["Establishing a Connection"] = "통신 시작"
L["Establishing Superiority"] = "우월성 입증"
L["Establishing The Uncrowned"] = "무관의 자 결성"
L["Eternal Unrest"] = "영원히 쉬지 못하는 영혼"
L["Eternal Vigil"] = "영원한 경계"
L["Evelyn Pare"] = "에벌린 페어"
L["Ever Eastward"] = "동쪽으로"
L["Everburning"] = "영원불꽃"
L["Everything Contained"] = "모든 것을 봉인하라"
L["Everything In Its Place"] = "모든 일이 해결되고"
L["Examining the Epitaphs"] = "비문 조사"
L["Exarch Maladaar"] = "총독 말라다르"
L["Excision"] = "적출"
L["Executor Zygand"] = "집행관 자이건드"
L["Exodar / Outland / Bloodmyst Isle"] = "엑소다르 / 아웃랜드 / 핏빛안개 섬"
L["Experimental Instability"] = "실험적인 불안정성"
L["Exploiting an Opening"] = "구멍 탐험"
L["Explore ancient ley line tunnels beneath Suramar, discovering forgotten power that could turn the tide."] = "수라마르 아래 고대 지맥 터널을 탐험하며, 판도를 뒤집을 수 있는 잊힌 힘을 찾아내세요."
L["Explosives in the Foundry"] = "용광로의 폭발물"
L["Explosivity"] = "폭발성"
L["Eye of Azshara: A Magical Affliction"] = "아즈샤라의 눈: 마법의 고통"
L["Eye of Azshara: The Frozen Soul"] = "아즈샤라의 눈: 얼어붙은 영혼"
L["Face Grand Magistrix Elisande herself as she unleashes the power of the Nightwell against the rebellion."] = "반란군을 향해 밤샘의 힘을 풀어놓는 대마법학자 엘리산드와 직접 맞서세요."
L["Face to Face With Consequence"] = "결과를 직시하라"
L["Falconhurst is under siege. Break the hag's hold on the village, forge weapons of old, and learn to fight the Drust with fire."] = "매의 언덕이 포위되었습니다. 마을을 옭아맨 마귀할멈의 속박을 깨뜨리고, 옛 무기를 벼리고, 불로 드러스트와 싸우는 법을 배우세요."
L["Falconhurst was overrun — a hag had enslaved the village, and wicker monsters patrolled the streets. Inquisitor Cleardawn led the charge: you broke the hag's spell, freed the villagers, and held the barricade against waves of cursed attackers. Warren Ashton, the village blacksmith, remembered the old ways — weapons of silver and iron, blessed in ember. You forged an arsenal from his teachings and learned the most important lesson of all: the Drust feared fire. With blessed blades and burning brands, you were ready for the Crimsonwood."] = "매의 언덕은 이미 함락된 상태였다. 마귀할멈이 마을을 노예로 삼았고, 고리버들 괴물들이 거리를 순찰했다. 심문관 클리어돈이 돌격을 이끌었다. 마귀할멈의 주문을 깨뜨리고, 마을 사람들을 풀어 주고, 저주받은 공격자들의 파상 공세에 맞서 방어벽을 지켰다. 마을 대장장이 워렌 애쉬턴은 옛 방식을 기억하고 있었다. 잿불로 축복한 은과 철의 무기였다. 그의 가르침에 따라 무기를 벼려 내고, 무엇보다 중요한 교훈을 얻었다. 드러스트는 불을 두려워한다는 것이었다. 축복받은 칼날과 타오르는 횃불을 손에 들고, 진홍숲으로 갈 준비를 마쳤다."
L["Fall Back!"] = "후퇴하라!"
L["Fall of the Lich King"] = "리치 왕의 몰락"
L["Fallen Idols"] = "빼앗긴 우상"
L["False Orders"] = "거짓 명령서"
L["Family Heirlooms"] = "가문의 가보"
L["Family Tree"] = "가계도"
L["Fancy Lads and Buccaneers"] = "신입 해적단원"
L["Fangs of Ashamane"] = "아샤메인의 송곳니"
L["Fangs of the Devourer"] = "포식자의 송곳니"
L["Faol warned you about Light's Wrath — a staff of such devastating holy power that the Kirin Tor had sealed it in the Nexus Vault, deeming it too dangerous for any mortal. But desperate times demanded desperate weapons. You breached the Vault's defenses and claimed the staff, feeling its barely contained fury surge through you. Light's Wrath was not a gentle weapon — it was the Light's anger given form."] = "파올은 빛의 분노에 관해 경고했다. 너무나 파괴적인 신성한 힘을 지닌 지팡이라, 키린 토가 어떤 필멸자에게도 위험하다고 여겨 마력의 금고에 봉인해 둔 것이었다. 하지만 절박한 시대에는 절박한 무기가 필요했다. 금고의 방어를 뚫고 지팡이를 손에 넣자, 간신히 억눌린 격노가 온몸을 휘감는 것이 느껴졌다. 빛의 분노는 온화한 무기가 아니었다. 빛의 노여움이 형체를 얻은 것이었다."
L["Farseer Aggralan"] = "선견자 아그랄란"
L["Farseer Nobundo"] = "선견자 노분도"
L["Farseer's Campaign"] = "선견자의 대장정"
L["Farseer's Raging Tempest"] = "선견자의 성난 폭풍"
L["Fate of the Horde"] = "호드의 운명"
L["Fate of the Nightborne"] = "나이트본의 운명"
L["Fate's End"] = "운명의 끝"
L["Father Gustav"] = "신부 구스타프"
L["Father Kamaros"] = "신부 카마로스"
L["Fear is Our Weapon"] = "공포는 곧 우리의 무기"
L["Fearsome Jang"] = "용감무쌍한 장"
