L["Felbound Beasts"] = "지옥결속 야수"
L["Felo'melorn"] = "펠로멜로른"
L["Felstorm's Plea"] = "펠스톰의 간청"
L["Field Evaluation"] = "현장 평가"
L["Field Repairs"] = "현장 수리"
L["Fight through cursed Corlain, storm Waycrest Manor, and confront Lady Waycrest and Gorak Tul in the dungeon's depths."] = "저주받은 콜레인을 헤치고 나아가 웨이크레스트 저택을 습격하고, 던전 깊은 곳에서 부인 웨이크레스트와 고라크 툴에 맞서세요."
L["Fighting With Fire"] = "불로 맞서기"
L["Final Exit"] = "마지막 출구"
L["Finality"] = "최후"
L["Find Ebonchill, the staff of Alodi — the first Guardian of Tirisfal — frozen in time within a pocket dimension."] = "티리스팔의 첫 수호자 알로디의 지팡이 에본칠을 찾으세요. 그것은 작은 차원 속에서 시간이 멈춘 채 얼어붙어 있습니다."
L["Find Lulubelle Fizzlebang in Stormheim, coerce a demon confession, and complete the Council's final selection."] = "스톰하임에서 루루벨 피즐뱅을 찾고, 악마를 다그쳐 자백을 받아 낸 뒤, 의회의 마지막 선발을 마무리하세요."
L["Find the Ancient Hero"] = "고대 영웅 발견"
L["Find the Boy"] = "소년을 찾아라"
L["Find the Scepter of Sargeras, a weapon that can tear rifts between worlds with a single strike."] = "단 한 번의 일격으로 세계 사이에 균열을 낼 수 있는 무기, 살게라스의 홀을 찾으세요."
L["Finding Ebonchill"] = "칠흑한기는 어디에"
L["Finding Fizzlebang"] = "피즐뱅 찾기"
L["Finding the Scepter"] = "홀을 찾아서"
L["Finding Your Center"] = "중심을 찾아서"
L["Finish Me!"] = "날 끝내줘!"
L["Finish Them!"] = "놈들을 끝장내자!"
L["Finishing the Job"] = "마무리"
L["Finna Bjornsdottir"] = "핀나 비요른스도티르"
L["Fire Is Always the Answer"] = "정답은 언제나 불"
L["Firelord Smolderon"] = "화염군주 스몰데론"
L["First Arcanist Thalyssra"] = "첫 번째 비전술사 탈리스라"
L["First Contact"] = "첫 조우"
L["First Legion Forward Camp"] = "1군단 전진기지"
L["Fists of the Heavens"] = "천상의 주먹"
L["Fit For a Pirate"] = "해적의 자격"
L["Fizzi Tinkerbow"] = "피지 팅커보우"
L["Fleet Admiral Tethys"] = "함대 사령관 테시스"
L["Fleet Admiral Tethys told the tale of the Dreadblades — cursed cutlasses that brought ruin to every captain who wielded them. You sailed to the burial site and pried them from the skeletal grip of their last owner, accepting the curse along with the power. The sea itself seemed to shudder as you brought them aboard."] = "함대 사령관 테시스는 공포의 칼날에 관한 이야기를 들려주었다. 그것을 휘두른 모든 선장에게 파멸을 가져온 저주받은 해적검이었다. 매장지로 항해해 마지막 주인의 해골 손아귀에서 칼날을 빼냈고, 힘과 함께 저주도 받아들였다. 칼날을 배에 싣자 바다마저 몸서리치는 듯했다."
L["Fletcher's Hollow is cursed — villagers turned to wicker constructs. Track the three witch sisters responsible and expose their matron."] = "활장이의 골짜기가 저주에 걸려 마을 사람들이 고리버들 인형으로 변했습니다. 이 일을 벌인 세 마녀 자매를 추적해 그들을 이끄는 여주인의 정체를 밝혀내세요."
L["Fletcher's Hollow was worse than Fallhaven. The curse here had turned villagers into wicker constructs — living husks of thorns and hatred. Lucille led you through the ruins, saving who you could and putting down those beyond help. The trail pointed to three witch sisters working in concert. You charmed the lifeless, followed a revealing missive, and tracked the murderous matron to her lair. With the coven cell destroyed and an airtight alibi for who was truly behind the corruption, the pattern became clear — this was no scattered curse. It was organized. It was a war."] = "활장이의 골짜기는 낙엽의 안식처보다 더 처참했다. 이곳의 저주는 마을 사람들을 고리버들 인형으로 바꾸어 놓았다. 가시와 증오로 이루어진 살아 있는 껍데기였다. 루실을 따라 폐허를 지나며 구할 수 있는 이들은 구하고, 구할 수 없는 이들은 쓰러뜨렸다. 흔적은 힘을 합쳐 움직이는 세 마녀 자매를 가리켰다. 생명 없는 것들을 홀리고, 단서가 담긴 서신을 따라, 살인을 일삼는 여주인을 그녀의 소굴까지 추적했다. 마녀단의 한 분파를 무너뜨리고 타락의 진짜 배후를 둘러싼 빈틈없는 알리바이까지 밝혀내자, 그 양상이 분명해졌다. 이것은 흩어진 저주가 아니었다. 조직적이었다. 전쟁이었다."
L["Flockmaster Sergio"] = "무리조련사 세르지오"
L["Flow Control"] = "흐름 제어하기"
L["Flying Colors"] = "완벽한 마무리"
L["Flynn Fairwind"] = "플린 페어윈드"
L["Focusing the Energies"] = "에너지 집중"
L["Fog of War"] = "전장의 안개"
L["Follow Matthias Lehner through Arthas' own memories to the foot of the citadel and Tirion's final gambit."] = "마시어스 레넷을 따라 아서스의 기억 속을 지나 성채의 발치와 티리온의 마지막 승부수에 이르세요."
L["Follow old friends across Pandaria, retracing the journey that shaped the Wandering Isle and the pandaren who left it behind. The mists have lifted, the war has moved on, and a new generation needs to understand what its elders carried into exile.\n\nWalk the slopes of Kun-Lai, sit at the brewmaster's hearth in the Valley of the Four Winds, and listen to stories the rest of the world has only just begun to hear."] = "옛 친구들을 따라 판다리아를 가로지르며, 유랑도와 그 섬을 떠나온 판다렌들을 빚어낸 여정을 되짚어 보세요. 안개는 걷혔고, 전쟁은 지나갔으며, 새로운 세대는 어른들이 망명길에 짊어지고 온 것이 무엇인지 이해해야 합니다.\n\n쿤라이의 비탈을 걷고, 네 바람의 계곡에 있는 양조사의 화롯가에 앉아, 세상이 이제 막 듣기 시작한 이야기에 귀 기울이세요."
L["Following In His Footsteps"] = "발길을 따라"
L["Following the Curse"] = "저주를 따라서"
L["For Gnomeregan!"] = "놈리건을 위하여!"
L["For those who once swore loyalty to the Banshee Queen, a final message arrives — not to excuse the past, but to acknowledge it. The Forsaken move forward, but the echoes of old vows still linger in the ruins of Lordaeron."] = "한때 밴시 여왕에게 충성을 맹세했던 이들에게 마지막 전언이 도착한다. 과거를 변명하기 위함이 아니라, 과거를 인정하기 위한 것이다. 포세이큰은 앞으로 나아가지만, 옛 맹세의 메아리는 여전히 로데론의 폐허에 남아 있다."
L["Forcing Fate's Hand"] = "운명의 손 잡아 끌기"
L["Foreman Mann"] = "현장감독 만"
L["Foreman Raike"] = "현장감독 레이케"
L["Forensic Science"] = "부검의 미학"
L["Forfeit Souls"] = "영혼을 판 자들"
L["Forging the Armor"] = "방어구 벼리기"
L["Forgotten Shadows"] = "잊혀진 어둠"
L["Fortifying the Temple"] = "사원을 강화하려면"
L["Forward Camp is the last flat ground on the way to the citadel. Sappers finish what the bomb chain started. Sky-Commander Keller and Sky-Commander Ichman land their gunship crews to patch what the bombing shook loose. Matthias Lehner, the voice from the saronite pits, begins to speak plainly — and sends you into the Army of the Damned, into the wreckage beneath Sindragosa's broken hill, and into the futility of a hero's last charge. Everything he shows you has the shape of a confession."] = "전진 기지는 성채로 가는 길에 남은 마지막 평지다. 공병들이 연쇄 폭파가 시작한 일을 마무리한다. 하늘사령관 켈러와 하늘사령관 이치먼이 포격함 승무원들을 내려보내 폭격으로 흔들린 곳을 보수한다. 사로나이트 채굴장에서 들려오던 목소리, 마시어스 레넷이 마침내 솔직하게 말하기 시작한다. 그리고 저주받은 자들의 군대 속으로, 신드라고사의 부서진 언덕 아래 잔해 속으로, 한 영웅의 마지막 돌격이 남긴 허망함 속으로 이끈다. 그가 보여 주는 모든 것은 고백의 모습을 하고 있다."
L["Four dungeons. Four keys. Harlan Sweete and his pirates in Freehold, Overseer Korgus in Tol Dagor, Vol'zith the Whisperer beneath the Shrine of the Storm, the Drust Gorak Tul in Waycrest Manor — all of them fell. The Kul Tiran fleet, locked away by enemies and time and a nation that had stopped believing in itself, was free again. Then came the Siege of Boralus: Priscilla Ashvane, revealed as the architect of Kul Tiras's rot, made her last stand in the harbor. She fell too.\n\nIn Unity Square, Katherine Proudmoore stood before her daughter for the first time in years. She spoke the words no one had expected her to say: she stepped aside. She named Jaina Lord Admiral. She called her back — not as a Kul Tiran returning home, but as the heir to a seat her mother had been keeping warm. The fleet sailed. The song that Jaina's father had sung to her as a child played across the harbor."] = "네 개의 던전. 네 개의 열쇠. 자유지대의 할란 스위트와 그의 해적들, 톨 다고르의 감독관 코르거스, 폭풍의 사원 아래에 도사린 속삭임의 볼지스, 웨이크레스트 저택의 드루스트 고라크 툴. 모두 쓰러졌다. 적과 세월, 그리고 스스로를 믿지 않게 된 나라에 의해 묶여 있던 쿨 티란 함대가 다시 자유를 찾았다. 그리고 보랄러스 공성전이 벌어졌다. 쿨 티라스를 좀먹은 장본인으로 드러난 프리실라 애쉬베인이 항구에서 최후의 저항을 벌였다. 그녀 역시 쓰러졌다.\n\n화합의 광장에서 캐서린 프라우드무어는 수년 만에 처음으로 딸 앞에 섰다. 그리고 아무도 예상하지 못한 말을 꺼냈다. 그녀는 물러나겠다고 했다. 제이나를 대제독으로 임명했다. 고향으로 돌아온 쿨 티란으로서가 아니라, 어머니가 지켜 온 자리의 후계자로서 그녀를 다시 불러들인 것이다. 함대가 출항했다. 제이나의 아버지가 어린 그녀에게 불러 주던 노래가 항구에 울려 퍼졌다."
L["Fractured Forces"] = "쪼개진 연합"
L["Fragments of Disaster"] = "재앙의 파편"
L["Frazzle Geargrinder"] = "프라즐 기어그라인더"
L["Free Your Mind"] = "실력 발휘"
L["Freeing Our Brothers"] = "형제 구출"
L["Friends in Cages"] = "우리에 갇힌 친구"
L["Friends On the Outside"] = "이방인 친구"
L["Friends With Benefits"] = "도움이 되는 친구"
L["Fringe Science Benefits"] = "괴짜 과학의 승리"
L["From Acherus: The Ebon Hold, the Knights of the Ebon Blade wage their own war against the Burning Legion. The order has no king. It has a Deathlord, and the Deathlord is you.\n\nRaise champions from graveyards across history, gather an army that does not fear death, and decide how far the Ebon Blade is willing to go when the living world needs monsters on its side."] = "아케루스: 칠흑의 요새에서 칠흑의 기사단은 불타는 군단을 상대로 그들만의 전쟁을 벌입니다. 기사단에는 왕이 없습니다. 오직 죽음의 군주가 있을 뿐이며, 이제 그 자리에 오를 차례입니다.\n\n역사 속 묘지 곳곳에서 용사들을 일으키고, 죽음을 두려워하지 않는 군대를 모으고, 산 자의 세계가 괴물을 아군으로 필요로 할 때 칠흑의 기사단이 어디까지 나아갈지 결정하세요."
L["From Dreadscar Rift, a pocket of the Twisting Nether claimed by force, the Council of the Black Harvest commands demons to fight demons. It is dangerous work, which is exactly why warlocks are suited to it.\n\nAs Netherlord, rebuild the council, bargain with powers that should not be trusted, and prove that a stolen weapon can still be aimed."] = "힘으로 차지한 뒤틀린 황천의 한 조각, 공포흉터 균열에서 검은 수확 의회는 악마를 부려 악마와 싸우게 합니다. 위험한 일이지만, 바로 그렇기에 흑마법사에게 어울리는 일입니다.\n\n황천의 군주로서 의회를 재건하고, 믿어서는 안 될 힘과 거래하며, 훔친 무기도 얼마든지 겨눌 수 있음을 증명하세요."
L["From the Depths of Azjol-Nerub"] = "아졸네룹의 심연에서"
L["From the Fel Hammer on Mardum, the Illidari wage war against the Burning Legion with the very weapons of the enemy. Their methods are feared, their purpose is absolute, and their enemies know them well.\n\nAs the chosen Slayer, unite the demon hunters, reclaim old ground, and carry the fight into places where fel fire has ruled for ages."] = "마르둠의 지옥 망치호에서 일리다리는 적의 무기를 그대로 들고 불타는 군단과 전쟁을 벌입니다. 그들의 방식은 두려움의 대상이고, 그들의 목적은 절대적이며, 적들은 그들을 잘 알고 있습니다.\n\n선택받은 학살자로서 악마사냥꾼들을 하나로 모으고, 옛 땅을 되찾고, 지옥불이 오랜 세월 지배해 온 곳으로 싸움을 이어 가세요."
L["From Trueshot Lodge high in the mountains, the Unseen Path watches over Azeroth. Its hunters know the old trails, the hidden passes, and the signs most armies march past without seeing.\n\nAs the order's newest champion, recruit legendary trackers, root out Legion threats, and defend the wild places and cities that still need sharp eyes on the horizon."] = "높은 산중의 정조준 오두막에서 보이지 않는 길은 아제로스를 지켜봅니다. 그들의 사냥꾼들은 옛 오솔길과 숨겨진 고갯길, 그리고 대부분의 군대가 보지 못하고 지나치는 흔적들을 알고 있습니다.\n\n결사의 가장 새로운 용사로서 전설적인 추적자들을 영입하고, 군단의 위협을 뿌리 뽑고, 여전히 지평선을 예리하게 지켜볼 눈이 필요한 야생과 도시를 지키세요."
L["From Whence They Came"] = "어디서 나온 물건인가?"
L["Frostmourne"] = "서리한"
L["Frozen Memories"] = "얼어붙은 기억"
L["Fu Zan, the Wanderer's Companion"] = "방랑자의 동반자 푸잔"
L["Full Might of the Elves"] = "모든 엘프의 힘"
L["Fun With Landmines"] = "즐거운 지뢰 체험"
L["Furious Familiars"] = "사나워진 동물들"
L["Furious Fowl"] = "날짐승 내장"
L["Futility"] = "부질없는 일"
L["G.E.A.R. Up"] = "노움 특공대 준비 완료!"
L["G'Hanir, the Mother Tree"] = "그하니르, 어머니 나무"
L["Gaining the Upper Hand"] = "우위 선점"
L["Gakin the Darkbinder"] = "대흑마법사 게이킨"
L["Gakin the Darkbinder dispatched troops while Ritssyn uncovered troubling archives — bloodstones were appearing across the Broken Isles, corrupting the land with fel energy. You traveled to Azsuna where Kira Iresoul was already investigating. Together you traced the bloodstone bandits to their source, tested a theory on the stones' hunger for blood, and repaid the debt with fire. Jubeka Shadowbreaker and Zinnin Smythe joined the Council as champions. A daring rescue followed — the Council looked after its own."] = "대흑마법사 게이킨이 병력을 파견하는 동안, 릿신은 불길한 기록을 찾아냈다. 부서진 섬 곳곳에 혈석이 나타나 지옥의 기운으로 땅을 타락시키고 있었다. 아즈스나로 가자 키라 아이어소울이 이미 조사를 벌이고 있었다. 함께 혈석 도적단을 근원까지 추적하고, 피를 갈망하는 돌에 관한 가설을 시험하고, 불로 빚을 갚아 주었다. 주베카 섀도브레이커와 지닌 스마이드가 용사로서 의회에 합류했다. 이어서 대담한 구출이 벌어졌다. 의회는 자기 사람을 결코 버리지 않았다."
L["Galakrond and the Scourge"] = "갈라크론드와 스컬지"
L["Galgar's Cactus Apple Surprise..."] = "갈가르의 선인장 사과 별미..."
L["Garona Halforcen"] = "가로나 하프오큰"
L["Garrosh sent the Horde to seize whatever had been hidden in the mists. Instead, Hellscream's Fist fell burning into the Jade Forest. Nazgrim drove the survivors forward with fire and discipline, but the first victory curdled quickly. Taran Zhu named the consequence of the Horde's fury: sha. The Horde regrouped at Honeydew Village, pulled its scattered officers out of danger, and learned that Pandaria would answer violence with something far older than either faction expected."] = "가로쉬는 안개 속에 숨겨진 것은 무엇이든 차지하라며 호드를 보냈다. 그러나 헬스크림의 철권호는 불길에 휩싸인 채 비취 숲으로 추락했다. 나즈그림은 불과 규율로 생존자들을 몰아붙였지만, 첫 승리는 금세 변질되었다. 타란 주는 호드의 분노가 낳은 결과에 이름을 붙였다. 바로 샤였다. 호드는 꿀이슬 마을에서 재정비하고, 흩어진 장교들을 위험에서 구해 내며, 판다리아가 폭력에 대해 어느 진영도 예상하지 못한 훨씬 오래된 무언가로 응답한다는 것을 깨달았다."
L["Gates of the Nighthold"] = "밤의 요새의 관문"
L["Gathering of the Storms"] = "모여드는 폭풍"
L["Gauging Our Progress"] = "진행 상황 확인"
L["Geirrvif"] = "가이르비프"
L["General Draven"] = "장군 드레이븐"
L["General Nazgrim"] = "장군 나즈그림"
L["Generosity Abounds"] = "푸짐한 선물"
L["Genn Greymane"] = "겐 그레이메인"
L["Gentle Mother Hanae"] = "자애로운 어머니 하나에"
L["Get Back Here!"] = "돌아와!"
L["Get the Key"] = "열쇠를 찾아"
L["Get to Ymirheim!"] = "이미르하임을 향하여!"
L["Get Your Bearings"] = "할 일 찾기"
L["Getting Permission"] = "허락은 주먹을 타고"
L["Getting the Message"] = "대족장의 응답"
L["Gi-Oh"] = "기오"
L["Gilneas survived exile through loyalty, discipline, and the will to endure. By facing the darkness within and without, you helped carry that legacy forward."] = "길니아스는 충성과 규율, 그리고 견뎌 내겠다는 의지로 망명의 세월을 버텨 냈다. 안팎의 어둠과 맞서며, 그 유산을 앞으로 이어 가는 데 힘을 보탰다."
L["Give Me Fuel, Give Me Fire"] = "연료를 주세요, 동력을 주세요"
L["Giving It All We've Got"] = "끝없는 굶주림"
L["Glenbrook Homestead, Drustvar"] = "글렌브룩 농장, 드러스트바"
L["Gnomercy!"] = "무자. B.!"
L["Gnomeregan"] = "놈리건"
L["Gnomeregan's Finest"] = "놈리건 최정예 부대"
L["Go with Honor, Friend"] = "명예롭게 싸우길, 친구여"
L["Goldrinn"] = "골드린"
L["Good Fiery Boy"] = "용맹한 충견"
L["Good For Something?"] = "어딘가에 유용한?"
L["Gorkun Ironskull"] = "고르쿤 아이언스컬"
L["Grab and Go"] = "데리고 올라가기"
L["Grand Anchorite Almonen"] = "대수도자 알모넨"
L["Grand Artificer Romuul"] = "대기술병 로뮬"
L["Grand Executor Mortuus"] = "대집행관 모르투스"
L["Grand Magistrix Elisande sealed the city, sending her Duskwatch to crush any hint of dissent. The crackdown was swift and merciless. You fought through patrols and barricades to evacuate nightfallen sympathizers before they could be captured, but not everyone made it out. As the gates slammed shut, the rebellion was forced deeper underground."] = "대마법학자 엘리산드는 도시를 봉쇄하고, 황혼감시대를 보내 반대의 기미를 철저히 짓밟았다. 탄압은 신속하고 무자비했다. 순찰대와 바리케이드를 뚫고 나이트폴른 동조자들이 붙잡히기 전에 대피시켰지만, 모두가 빠져나오지는 못했다. 성문이 굳게 닫히자, 반란군은 더 깊은 지하로 숨어들 수밖에 없었다."
L["Grandmaster's Campaign"] = "대사부의 대장정"
L["Greatmother Icemist"] = "대모 아이스미스트"
L["Greatmother Icemist weeps over a quiet fire. Her son is chained somewhere beneath this frozen plain, and her daughter Banthok is ready to cut every Anub'ar web in the world to bring him home. The Taunka are a proud and wounded people, shaggy cousins to the Tauren whose strength the Scourge has long bled for sport. If they rise again, they rise with the Horde."] = "대모 아이스미스트가 고요한 모닥불 앞에서 눈물을 흘린다. 그녀의 아들은 이 얼어붙은 평원 아래 어딘가에 사슬로 묶여 있고, 딸 반토크는 그를 데려오기 위해서라면 세상의 모든 아눕아르 거미줄을 끊을 각오가 되어 있다. 타운카는 자부심 강하지만 상처 입은 종족이다. 타우렌의 덥수룩한 사촌인 그들의 힘을, 스컬지는 오랫동안 재미 삼아 짜내 왔다. 그들이 다시 일어선다면, 호드와 함께 일어설 것이다."
L["Green Technology"] = "녹색 기술"
L["Green-ish Energy"] = "녹색 성장의 구린내"
L["Grif Wildheart spoke of Titanstrike — a rifle of immense power forged by Mimiron himself in the halls of Ulduar. You embarked on a beastly expedition to recover the weapon, facing titan constructs and wild guardians. When you finally held Titanstrike, its mechanisms hummed with the power of a thousand storms."] = "그리프 와일드하트는 티탄강타에 관해 이야기했다. 울두아르의 전당에서 미미론이 직접 벼려 낸 막강한 힘의 소총이었다. 그 무기를 되찾기 위해 야수 원정에 나서 티탄 피조물과 야생의 수호자들에 맞섰다. 마침내 티탄강타를 손에 쥐자, 그 장치들이 천 개의 폭풍이 지닌 힘으로 웅웅거렸다."
L["Grim Tidings"] = "암울한 소식"
L["Grip of Nightmare"] = "악몽의 손아귀"
L["Grommash Hold, Orgrimmar"] = "그롬마쉬 요새, 오그리마"
L["Grookin Hill"] = "그루끼끼 언덕"
L["Grookin Hill roared to life in exactly the way a hozen fortress would: loud, improvised, and enthusiastic about explosives. Chief Kah Kah had given the Horde a foothold, but Nazgrim still needed scouts, maps, and pressure against the Alliance. Rivett sent messages through ridiculous means, Shokia and the scouts reported enemy positions, and the Horde learned how the jinyu, SI:7, and Alliance soldiers fit together. By the end, Guerrillas in our Midst became Burning Down the House. The hozen pact held, and the road to Dawn's Blossom opened through smoke."] = "그루끼끼 언덕은 호젠 요새다운 방식으로 깨어났다. 시끄럽고, 즉흥적이며, 폭발물에 열광하는 모습으로. 족장 카 카가 호드에 발판을 내주었지만, 나즈그림에게는 여전히 정찰병과 지도, 그리고 얼라이언스를 압박할 수단이 필요했다. 리벳은 터무니없는 방법으로 전갈을 보냈고, 쇼키아와 정찰병들은 적의 위치를 보고했으며, 호드는 진위족과 SI:7, 얼라이언스 병사들이 어떻게 맞물려 있는지 알게 되었다. 마침내 '적은 가까이에'는 '초가삼간 불태우기'로 이어졌다. 호젠과의 협약은 굳건했고, 새벽의 꽃으로 가는 길이 연기 속에서 열렸다."
L["Ground Commander Koup"] = "지상군 사령관 쿠프"
L["Ground Commander Xutjja"] = "지상군 사령관 수트야"
L["Groundskeeper Wu"] = "관리인 우"
L["Grovebound"] = "숲의 결속"
L["Growing Power"] = "강해지는 힘"
L["Grumnus Steelshaper"] = "그룸누스 스틸셰이퍼"
L["Guerrillas in our Midst"] = "적은 가까이에"
L["Guided by Kel'danath's research, you descended into ancient caverns beneath Suramar, where moonlight filtered through crystal and the memories of the city's founding still lingered. You discovered the hidden legacy of Valewalker Farodin and the Arcan'dor — a tree of immense power that might hold the key to curing the nightfallen's addiction to the Nightwell."] = "켈다나스의 연구를 길잡이 삼아 수라마르 아래 고대 동굴로 내려갔다. 그곳에서는 달빛이 수정을 통해 스며들고, 도시가 세워지던 시절의 기억이 여전히 남아 있었다. 계곡방랑자 파로딘의 숨겨진 유산과 아칸도르를 발견했다. 막대한 힘을 지닌 이 나무는 밤샘에 대한 나이트폴른의 중독을 치료할 열쇠가 될지도 몰랐다."
L["Gunpowder Research"] = "화약 연구"
L["Guts and Gore"] = "내장과 피"
L["Halduron Brightwing"] = "할두런 브라이트윙"
L["Halford Wyrmbane"] = "할포드 웜베인"
L["Hall of the Guardian / Broken Isles"] = "수호자의 전당 / 부서진 섬"
L["Halls of Valor"] = "용맹의 전당"
L["Halls of Valor: Odyn's Cauldron"] = "용맹의 전당: 오딘의 가마솥"
L["Halls of Valor: The Brewmaster"] = "용맹의 전당: 양조사를 만나다"
L["Halting the Empire's Fall"] = "제국의 쇠망을 막기 위하여"
L["Hamuul Runetotem sends an urgent summons. Through the Emerald Dreamway, you discover the Dreamgrove and take up a weapon of legend."] = "하멀 룬토템이 긴급히 소집합니다. 에메랄드의 꿈길을 지나 꿈의 숲을 발견하고 전설의 무기를 손에 넣습니다."
L["Hanzabu"] = "한자부"
L["Hanzabu leads you to Bwonsamdi, loa of death, deep in his Necropolis. He will fight the blood trolls — for one million souls."] = "한자부가 네크로폴리스 깊은 곳에 있는 죽음의 로아 브원삼디에게로 안내합니다. 브원삼디는 피의 트롤과 싸워 주겠다고 합니다. 대가는 영혼 백만 개입니다."
L["Hanzabu, servant of the death loa, led you into Bwonsamdi's Necropolis — a place where the veil between the living and the dead was thin enough to talk through. Bwonsamdi was many things: charming, unsettling, and entirely in control of any room he entered. He had watched the blood trolls desecrate his death shrines and steal souls that were owed to him. He was not pleased. The deal he offered was simple — his power in exchange for one million souls delivered to his realm. You cleansed his temple of spirits who had fled to G'huun, repelled Grand Ma'da Ateena's interruption of the sealing ritual, and sealed the pact. A deal with a death loa is not something you walk back from."] = "죽음의 로아를 섬기는 한자부가 브원삼디의 네크로폴리스로 길을 안내했다. 그곳은 산 자와 죽은 자 사이의 장막이 말소리가 건너갈 만큼 얇은 곳이었다. 브원삼디는 여러 얼굴을 지닌 존재였다. 매력적이면서도 섬뜩했고, 어디에 들어서든 그 자리를 완전히 장악했다. 그는 피의 트롤이 자신의 죽음의 제단을 더럽히고 자기 몫의 영혼을 훔쳐 가는 것을 지켜보았고, 이를 결코 달가워하지 않았다. 그가 내건 거래는 단순했다. 자신의 영역에 영혼 백만 개를 바치면 그 대가로 힘을 빌려주겠다는 것이었다. 그의 사원에서 그훈에게 달아난 영혼들을 몰아내고, 봉인 의식을 방해하러 온 큰마마 아티나를 물리친 끝에 계약이 맺어졌다. 죽음의 로아와 맺은 계약은 되돌릴 수 없는 법이다."
L["Hao Mann"] = "하오 만"
L["Harmful If Swallowed"] = "고통스러운 증명법"
L["Harnessing Power"] = "마구의 힘"
