L["Held Captive!"] = "포로를 구출하라!"
L["Hellscream's Fist crashes into Pandaria, leaving Nazgrim to turn wreckage, survivors, and frightened locals into a foothold."] = "헬스크림의 철권호가 판다리아에 추락합니다. 나즈그림은 잔해와 생존자, 겁에 질린 현지 주민들을 모아 거점을 마련해야 합니다."
L["Help Chief Telemancer Oculeth restore the teleportation network, opening new paths across Suramar."] = "수석 이동술사 오큘레스를 도와 순간이동 연결망을 복구하고 수라마르 곳곳으로 향하는 새 길을 여십시오."
L["Helping the Cause"] = "마지막 도움"
L["Helya's Horn"] = "헬리아의 뿔피리"
L["Hemet Nesingwary"] = "헤멧 네싱워리"
L["Hemet Nesingwary joined the hunt in Highmountain, his expertise invaluable as you tracked the Legion's movements. But the true threat emerged in Azsuna — leyworms corrupted by demonic energy, twisting the beasts of the land into weapons. Working with Kira Iresoul, you lured out the source of the corruption and tamed it, proving that a hunter's bond with nature was stronger than any demon's magic."] = "헤멧 네싱워리가 높은산에서 사냥에 합류했다. 군단의 움직임을 추적하는 동안 그의 전문 지식은 더없이 귀중했다. 그러나 진짜 위협은 아즈스나에서 모습을 드러냈다. 악마의 기운에 타락한 지맥벌레들이 그 땅의 야수들을 비틀어 무기로 바꾸고 있었던 것이다. 키라 아이어소울과 함께 타락의 근원을 꾀어내 길들였고, 사냥꾼과 자연의 유대가 그 어떤 악마의 마법보다 강하다는 것을 증명했다."
L["Herald Their Demise"] = "파멸을 알리는 전령"
L["Herding Goats"] = "염소몰이"
