L["Highlord Bolvar Fordragon"] = "대영주 볼바르 폴드라곤"
L["Highlord Bolvar Fordragon leads you up the spiral of Wyrmrest Temple. Alexstrasza the Life-Binder has watched the war in Dragonblight with ancient, weary eyes. She owes the Alliance nothing. She owes the living everything. If she can be moved, her fire will answer for Azeroth's dead — and a ruby wing will carry you over ground no army could cross."] = "대영주 볼바르 폴드라곤이 고룡쉼터 사원의 나선형 길을 따라 위로 이끈다. 생명의 어머니 알렉스트라자는 용의 안식처에서 벌어지는 전쟁을 오래되고 지친 눈으로 지켜보아 왔다. 그녀는 얼라이언스에 빚진 것이 없다. 그러나 살아 있는 이들에게는 모든 것을 빚졌다. 그녀의 마음을 움직일 수 있다면, 그녀의 불길이 아제로스의 죽은 이들을 대신해 응답할 것이다. 그리고 붉은 날개에 올라, 어떤 군대도 건널 수 없는 땅을 넘어갈 수 있을 것이다."
L["Highlord Darion Mograine"] = "대영주 다리온 모그레인"
L["Highlord Demitrian"] = "대영주 데미트리안"
L["Highlord Tirion Fordring"] = "대영주 티리온 폴드링"
L["Highlord's Campaign"] = "대영주의 대장정"
L["Highlord's Golden Charger"] = "대영주의 황금 군마"
L["Highmountain Hunters"] = "높은산의 사냥꾼들"
L["Hir'eek, the Bat Loa"] = "박쥐 로아, 히르이크"
L["Hired Help"] = "도움이 필요해"
L["Hobart Grapplehammer"] = "호바트 그래플해머"
L["Hobart Grapplehammer has a masterpiece, a deadline, and a former employer determined that neither will reach completion. Trade Prince Gallywix has eyes everywhere, and the workshop where the work has to happen is exactly as glamorous as Crapopolis sounds.\n\nReunite old allies, outplay better-funded saboteurs, and keep one bombastic invention from being seized, sold, stolen, exploded, or all four in sequence."] = "호바트 그래플해머에게는 걸작 하나와 마감일, 그리고 그 둘 중 어느 것도 끝을 보지 못하게 하려고 작정한 전 고용주가 있습니다. 무역왕 갤리윅스의 눈은 어디에나 있고, 작업을 해야 할 작업장은 쓰레기 광장이라는 이름에 딱 어울리는 만큼 화려합니다.\n\n옛 동료들을 다시 모으고, 자금줄이 더 든든한 방해 공작원들을 한 수 앞서 제압하십시오. 요란한 발명품 하나가 압수당하거나, 팔려 가거나, 도둑맞거나, 폭발하지 않도록, 혹은 그 넷을 차례로 겪지 않도록 지켜 내십시오."
