L["Hunt a Legion commander through Stormheim, prepare the Fel Hammer for interdimensional travel, and invade the demon world Niskara."] = "스톰하임에서 군단 지휘관을 추적하고, 차원 간 이동을 위해 지옥망치를 준비한 뒤, 악마의 세계 니스카라를 침공하십시오."
L["Hunt down the Twinblades of the Deceiver — warglaives forged in felfire and wielded by a champion of the Legion."] = "기만자의 쌍날검을 찾아내십시오. 지옥불로 벼려 낸 이 전투검은 군단의 용사가 휘두르고 있습니다."
