L["In ancient Drust ruins, Lucille discovers the Order of Embers — an old organization of witch hunters. She vows to rebuild it."] = "고대 드루스트 유적에서 루실이 오래된 마녀 사냥꾼 조직인 잿불단을 발견합니다. 그녀는 잿불단을 재건하겠다고 맹세합니다."
