L["In Defense of Dalaran"] = "달라란 사수"
L["In Gloom Hollow, the great frog loa Krag'wa hungers — and he is willing to fight if you can earn his trust. Become a friend of the frogs."] = "어두운 공동에서 위대한 개구리 로아 크라그와가 굶주리고 있습니다. 그의 신뢰를 얻는다면 함께 싸워 줄 것입니다. 개구리들의 친구가 되십시오."
L["In Netherlight Temple, priests of the Light and the Void unite under one banner. Faith, shadow, discipline, and doubt all have a place when the world is facing annihilation.\n\nAs High Priest, bridge old divides, investigate zealots and lost allies, and hold together a conclave built from powers that do not always agree they should stand side by side."] = "황천빛 사원에서 빛과 공허의 사제들이 하나의 깃발 아래 뭉칩니다. 세상이 멸망을 앞둔 지금, 신앙과 암흑, 수양과 의심 모두 설 자리가 있습니다.\n\n대사제로서 오랜 분열을 메우고, 광신자들과 행방불명된 동료들을 조사하십시오. 그리고 나란히 서야 한다는 데 늘 동의하지는 않는 힘들로 이루어진 의회를 하나로 묶어 내십시오."
L["In Search of the Eye"] = "도적이라서 행복합니다"
L["In Search of Wisdom"] = "지혜를 찾아서"
L["In the Bag"] = "당선 확실"
L["In the Business of Souls"] = "영혼의 문제"
L["In the Forest Ward, the Venthyr teach humility by giving souls hope and then hunting them down. The Accuser helps you see the cruelty beneath the lesson."] = "숲 구역에서 벤티르는 영혼들에게 희망을 준 뒤 그들을 사냥하는 방식으로 겸손을 가르칩니다. 규탄자는 그 가르침 밑에 숨은 잔혹함을 깨닫도록 돕습니다."
L["In the Hall of the Drust King"] = "드러스트 왕의 전당"
L["In the Ruin of Rebellion"] = "반란군이 몰락한 자리에서"
L["In the wake of the Peak of Serenity's fall, you prepared to strike back. The Fists of the Heavens — enchanted handwraps that crackled with storm energy — were said to channel the very fury of the skies. You fought through the Legion's forces to claim them, and with each punch, thunder rolled across the battlefield."] = "평온의 봉우리가 함락된 뒤, 반격을 준비했다. 폭풍의 기운이 파직거리는 마법 손싸개인 천상의 주먹은 하늘의 격노를 그대로 담아낸다고 전해졌다. 군단의 병력을 뚫고 나아가 그것을 손에 넣었고, 주먹을 내지를 때마다 전장에 천둥이 울려 퍼졌다."
L["In twilight shadows, Faol revealed the existence of Xal'atath — a blade forged in the age of the Black Empire, before even the titans came to Azeroth. The dagger whispered constantly, its voice ancient and knowing, full of secrets that could drive lesser minds mad. You claimed it from a twilight cult's grasp, and from that moment on, the whispers never stopped. Xal'atath remembered everything — and it wanted you to know."] = "황혼의 그림자 속에서 파올은 잘아타스의 존재를 밝혔다. 티탄이 아제로스에 오기도 전, 검은 제국 시대에 벼려진 칼날이었다. 단검은 끊임없이 속삭였다. 모든 것을 아는 듯한 그 고대의 목소리에는 나약한 정신을 미치게 할 비밀이 가득했다. 황혼의 이교도들에게서 단검을 빼앗은 그 순간부터 속삭임은 멈추지 않았다. 잘아타스는 모든 것을 기억했고, 그 모든 것을 알려 주고 싶어 했다."
L["Infiltrate the Nightborne wine trade, disrupting the flow of arcwine that keeps the populace loyal to the Grand Magistrix."] = "나이트본의 포도주 거래망에 잠입해, 주민들을 대행정관에게 충성하도록 붙잡아 두는 비전 포도주의 흐름을 끊으십시오."
L["Infiltrate the Scarlet Onslaught, the fanatical remnant of the Scarlet Crusade, and recruit a defector to your cause."] = "붉은십자군의 광신적인 잔당인 붉은 돌격대에 잠입해, 변절자 한 명을 아군으로 끌어들이십시오."
L["Infiltrate Zalamar disguised as a blood troll. The bat loa Hir'eek has been corrupted — you must end the corruption and the loa with it."] = "피의 트롤로 변장하고 잘라마르에 잠입하십시오. 박쥐 로아 히르이크가 타락했습니다. 타락을 끝내야 하며, 그 로아도 함께 끝내야 합니다."
L["Infiltrating Our Enemies"] = "적진에 침투하라"
L["Information at Any Cost"] = "반드시 알아내야 할 정보"
L["Informing Our Allies"] = "아군에게 정보 전달"
L["Initiate Da-Nel"] = "수습생 다넬"
L["Inkmaster Wei"] = "잉크장인 웨이"
L["Inquisitor Cleardawn"] = "심문관 클리어돈"
L["Inquisitor Cleardawn leads the southern campaign through the old roads, clearing Drust strongholds along the way."] = "심문관 클리어돈이 옛길을 따라 남부 원정을 이끌며 곳곳의 드루스트 요새를 소탕합니다."
L["Inquisitor Cleardawn took command of the southern front. Through the old roads you marched — ancient paths the Drust had walked millennia before. The pieces of history you uncovered told a chilling story: the Drust had not simply been defeated in the past. They had been driven into hiding, and they had been waiting. You gave their soldiers an honorable discharge — the permanent kind — and pushed through to a clear victory. But the Drust ruins at Gol Osigr loomed ahead, and the fall of the Drust was far from over."] = "심문관 클리어돈이 남부 전선의 지휘를 맡았다. 수천 년 전 드루스트가 걸었던 고대의 길, 그 옛길을 따라 행군했다. 발견한 역사의 조각들은 섬뜩한 이야기를 들려주었다. 드루스트는 과거에 그저 패배한 것이 아니었다. 그들은 숨어든 채 때를 기다리고 있었던 것이다. 드루스트 병사들에게는 명예로운 전역을 안겨 주었다. 다시는 돌아올 수 없는 전역을. 그렇게 길을 뚫고 확실한 승리를 거두었다. 하지만 앞에는 골 오시그의 드루스트 유적이 버티고 있었고, 드루스트의 몰락은 아직 끝나려면 멀었다."
L["Inquisitor Stelia's Sinstone"] = "심문관 스텔리아의 죄악석"
L["Inquisitor Sterntide"] = "심문관 스턴타이드"
L["Inquisitor Vilhelm's Sinstone"] = "심문관 빌헬름의 죄악석"
L["Inside the Frozen Citadel"] = "얼어붙은 성채 안으로"
L["Instant Messaging"] = "희망은 불꽃을 타고"
L["Instructor Myang"] = "교관 미앙"
L["Instructor Xann"] = "교관 산"
L["Insurrection"] = "반란"
L["Insurrection: Crafting War"] = "반란: 전쟁 준비"
L["Intense Concentration"] = "고도로 농축된 정수"
L["Interest Yah In A Pint?"] = "한번 보시지요?"
L["Into Darkness"] = "어둠 속으로"
L["Into Duskwood"] = "그늘숲 속으로"
L["Into Hostile Territory"] = "적진으로"
L["Into Our Ranks"] = "충원"
L["Into the Crevasse"] = "갈라진 틈 속으로"
L["Into the Crimsonwood"] = "진홍숲으로"
L["Into The Darkness"] = "어둠 속으로"
L["Into the Dragonblight"] = "용의 안식처로"
L["Into the Fold"] = "맞아들일 준비"
L["Into The Frozen Heart Of Northrend"] = "노스렌드의 얼어붙은 심장으로"
L["Into the Heart of Tiragarde"] = "티라가드의 심장부로"
L["Into the Light"] = "빛 속으로"
L["Into the Mists"] = "안개 속으로"
L["Into the Oculus"] = "마력의 눈 안으로"
L["Into the Void"] = "공허 속으로"
L["Into The Wild Green Yonder"] = "푸르른 창공 저편으로"
L["Investigate bloodstone corruption in Azsuna. Kira Iresoul proves her worth as the Council recruits new champions."] = "아즈스나에서 혈석의 타락을 조사하십시오. 의회가 새로운 용사를 모집하는 가운데 키라 아이어소울이 자신의 가치를 증명합니다."
L["Investigate conspiracy and betrayal tied to Stormwind's past and the Defias Brotherhood."] = "스톰윈드의 과거와 데피아즈 결사단에 얽힌 음모와 배신을 조사하십시오."
L["Investigate void disturbances in Azsuna alongside Zabra Hexx and Yalia Sagewhisper."] = "자브라 헥스, 야리아 세이지위스퍼와 함께 아즈스나에서 일어난 공허의 교란을 조사하십시오."
L["Invitation of the Master"] = "대영주의 초대"
L["Invitation to the Spirit Festival"] = "영혼 축제 초대"
L["Iron-Body Ponshu"] = "철근육 폰슈"
L["Iron-Body Ponshu received a desperate report — Tian Monastery was under attack. You rushed to its defense alongside Taran Zhu, the grim Shado-Pan lord, and The Monkey King, whose tricks proved as deadly as any blade. Instructor Myang held the line while you slowed the Legion's spread, and together you struck down the Hand of Keletress who led the assault. High Elder Cloudfall oversaw the monastery's rebuilding, and both Taran Zhu and The Monkey King pledged themselves as your champions."] = "철근육 폰슈에게 절박한 보고가 들어왔다. 티엔 수도원이 공격받고 있다는 것이었다. 엄격한 음영파의 군주 타란 주, 그리고 어떤 칼날만큼이나 치명적인 속임수를 쓰는 원숭이 왕과 함께 수도원을 지키러 달려갔다. 교관 미앙이 전선을 지키는 동안 군단의 확산을 늦췄고, 힘을 합쳐 공격을 이끈 켈레트레스의 손을 쓰러뜨렸다. 대장로 클라우드폴이 수도원 재건을 이끌었고, 타란 주와 원숭이 왕은 모두 용사가 되어 충성을 맹세했다."
L["Iron-Body Ponshu revealed that Sheilun — the staff of Emperor Shaohao himself — had been hidden since the emperor used it to shroud Pandaria in mist ten thousand years ago. You followed the trail of ancient magic to its resting place, where Shaohao's mists still swirled protectively around the staff. When you claimed Sheilun, the mists parted willingly — as if the emperor had been waiting for someone to carry his burden."] = "철근육 폰슈는 황제 샤오하오의 지팡이 셰이룬이 숨겨져 있다고 밝혔다. 만 년 전 황제가 그 지팡이로 판다리아를 안개 속에 감춘 뒤로 줄곧 자취를 감춘 채였다. 고대 마법의 흔적을 따라 지팡이가 잠든 곳에 이르자, 샤오하오의 안개가 여전히 지팡이를 감싸며 소용돌이치고 있었다. 셰이룬을 손에 쥐자 안개는 기꺼이 걷혔다. 마치 황제가 자신의 짐을 짊어질 누군가를 기다려 온 것처럼."
L["Iron-Body Ponshu spoke of a legend — the Storm Brew, a drink of such power it could turn the tide of any battle. The recipe was held by Aegira, a vrykul brewmaster who had perfected her craft in the Halls of Valor over centuries. You entered Odyn's domain, earned the right to brew alongside Aegira, and retrieved the ingredients from Odyn's own cauldron. The Storm Brew was unlike anything brewed on Azeroth — and with it, your weapon was reforged to its full power. The Grandmaster's campaign was complete."] = "철근육 폰슈가 한 전설을 들려주었다. 어떤 전투의 흐름도 뒤바꿀 만큼 강력한 술, 폭풍주에 관한 이야기였다. 그 비법은 수 세기 동안 용맹의 전당에서 솜씨를 갈고닦은 브리쿨 양조사 아이기라가 지니고 있었다. 오딘의 영역에 들어가 아이기라와 함께 술을 빚을 자격을 얻고, 오딘의 가마솥에서 직접 재료를 구해 왔다. 폭풍주는 아제로스에서 빚어진 어떤 술과도 달랐고, 그 힘으로 무기는 다시 벼려져 완전한 힘을 되찾았다. 대사부의 대장정이 마침내 끝났다."
L["Iron-Body Ponshu told you of Fu Zan — a simple-looking staff that had been passed from wanderer to wanderer since the dawn of the monk tradition. It looked like a walking stick, but those who carried it found that no enemy could stand against them. You tracked it through remote monasteries and dangerous wilds, and when you took it up, it felt like an old friend settling into your hand."] = "철근육 폰슈는 푸 잔에 대해 이야기했다. 수도사의 전통이 시작된 이래 방랑자에게서 방랑자로 전해져 온, 소박해 보이는 지팡이였다. 겉보기에는 평범한 지팡이였지만, 그것을 지닌 자 앞에서는 어떤 적도 버티지 못했다. 외딴 수도원과 위험한 황야를 지나 그 행방을 쫓았고, 마침내 손에 쥐었을 때 지팡이는 오랜 친구처럼 손에 익숙하게 감겼다."
L["Ironforge / Dun Morogh / Loch Modan"] = "아이언포지 / 던 모로 / 모단 호수"
L["Isolating Zalamar"] = "잘라마르 고립시키기"
L["It Could Kill Us All"] = "꿩 먹고 알 먹기"
L["It Hungers for Blood"] = "피에 굶주린 혈석"
L["It's All Fun and Games"] = "즐거운 장난"
L["It's Called Borrowing"] = "우린 이걸 빌린다고 해요"
L["It's Not a Spirit Festival Without Spirits"] = "영혼 축제에 영혼이 빠지면 안 되지"
L["Iterating Upon Success"] = "예행연습"
L["Izzy"] = "이지"
L["Jace Darkweaver"] = "제이스 다크위버"
L["Jace Darkweaver told the story of the Aldrachi — a warrior race so fierce they defeated the demon lord Sargeras sent to enslave them. Rather than serve, they fell on their own blades. Those weapons had been lost for millennia, but Jace had found a lead. You followed it through a series of trials, establishing a connection to the blades through sheer will. The Aldrachi Warblades chose you — the first wielder since the race that forged them chose extinction over submission."] = "제이스 다크위버는 알드라키의 이야기를 들려주었다. 살게라스가 그들을 노예로 삼으려고 보낸 악마 군주를 물리쳤을 만큼 사나운 전사 종족이었다. 섬기느니 차라리 그들은 스스로 칼날 위로 쓰러졌다. 그 무기들은 수천 년 동안 자취를 감추었지만, 제이스가 단서를 찾아냈다. 단서를 따라 일련의 시험을 거쳤고, 오로지 의지만으로 칼날과의 연결을 이어 냈다. 알드라키 전쟁검은 새 주인을 택했다. 그 검을 벼려 낸 종족이 굴복 대신 멸망을 택한 이래 처음 맞이하는 주인이었다."
L["Jaded Heart"] = "아련한 마음 한 덩이"
L["Jagged Shards"] = "톱니 조각"
L["Jailbreak"] = "탈옥"
L["Jaina brought you to Kul Tiras aboard the Alliance fleet, and the moment she stepped off the ship she was surrounded by Proudmoore Guard acting on Katherine's orders. Her own mother had her arrested for treason. You were thrown in Tol Dagor prison alongside her — until Flynn Fairwind, a sailor with nothing to lose and excellent lock-picking instincts, got you both out. Cyrus Crestfall and the 7th Legion met you on the outside. The road to earning Kul Tiras back for the Alliance runs through three zones — and through a rift between mother and daughter that has been open for years."] = "제이나와 함께 얼라이언스 함대를 타고 쿨 티라스에 도착했지만, 그녀가 배에서 내리자마자 캐서린의 명령을 받은 프라우드무어 경비병이 그녀를 에워쌌다. 친어머니가 그녀를 반역죄로 체포한 것이다. 제이나와 함께 톨 다고르 감옥에 갇혔으나, 잃을 것 하나 없는 데다 자물쇠 따는 감각만큼은 탁월한 선원 플린 페어윈드 덕분에 함께 탈출할 수 있었다. 밖에서는 사이러스 크레스트폴과 제7군단이 기다리고 있었다. 쿨 티라스를 다시 얼라이언스의 편으로 되찾으려면 세 지역을 거쳐야 한다. 그리고 수년째 벌어져 있던 어머니와 딸 사이의 골도 넘어서야 한다."
L["Jaina Proudmoore"] = "제이나 프라우드무어"
L["Jaina Proudmoore brings the Alliance to Kul Tiras — and is immediately arrested by her own mother's guards the moment she sets foot on the docks. Katherine Proudmoore, Lord Admiral in her daughter's absence, has not forgiven Jaina for the death of her father Daelin. Jaina is imprisoned in Tol Dagor. You break out with the help of a disgraced sailor named Flynn Fairwind, surface in a Kul Tiras rebuilding itself from the inside out, and learn that three zones of unrest must be addressed before Kul Tiras will trust the Alliance — or her."] = "제이나 프라우드무어가 얼라이언스를 이끌고 쿨 티라스에 도착하지만, 부두에 발을 딛는 순간 친어머니의 경비병들에게 체포됩니다. 딸이 없는 동안 대제독 자리를 지켜 온 캐서린 프라우드무어는 제이나의 아버지 데일린이 죽은 일로 아직 딸을 용서하지 않았습니다. 제이나는 톨 다고르에 갇힙니다. 불명예를 안고 쫓겨난 선원 플린 페어윈드의 도움으로 탈옥한 뒤에는 안에서부터 스스로를 재건하고 있는 쿨 티라스에 발을 딛게 됩니다. 그리고 쿨 티라스가 얼라이언스를, 그리고 제이나를 믿게 하려면 혼란에 빠진 세 지역의 문제부터 해결해야 한다는 사실을 알게 됩니다."
L["Jaina Proudmoore was once Theramore's defender and the Alliance's most celebrated mage. When the Horde dropped a mana bomb on her city, she emerged from the wreckage transformed: her hair turned white, her grief hardened into fury, and old friendships began to fall away.\n\nWhen Battle for Azeroth begins, Jaina returns to Kul Tiras, the home that remembers her not as a hero, but as the daughter who let Daelin Proudmoore die. What follows is a journey through estrangement, politics, old guilt, and the question of whether a broken bond can still be mended."] = "제이나 프라우드무어는 한때 테라모어의 수호자이자 얼라이언스에서 가장 칭송받는 마법사였습니다. 호드가 그녀의 도시에 마나 폭탄을 떨어뜨렸을 때, 그녀는 잔해 속에서 완전히 변한 모습으로 나타났습니다. 머리카락은 하얗게 셌고, 슬픔은 분노로 굳어졌으며, 오랜 우정은 하나둘 멀어지기 시작했습니다.\n\n격전의 아제로스가 시작되자 제이나는 쿨 티라스로 돌아갑니다. 그곳은 그녀를 영웅이 아니라 데일린 프라우드무어를 죽게 내버려 둔 딸로 기억하는 고향입니다. 그 뒤로 이어지는 것은 소원해진 관계와 정치, 오래된 죄책감, 그리고 한번 끊어진 유대를 다시 이을 수 있는가라는 물음을 따라가는 여정입니다."
L["Jaina Proudmoore, now Lord Admiral, turns the Kul Tiran fleet against the Zandalari Empire. The plan: draw the Horde's forces deep into Nazmir with the Abyssal Scepter while the Alliance fleet strikes Zuldazar harbor from the south. Jaina personally freezes the harbor, and the Battle of Dazar'alor begins."] = "이제 대제독이 된 제이나 프라우드무어가 쿨 티란 함대를 잔달라 제국으로 돌립니다. 계획은 이렇습니다. 심연의 홀로 호드의 병력을 나즈미르 깊숙이 끌어들이는 사이, 얼라이언스 함대가 남쪽에서 줄다자르 항구를 공격하는 것입니다. 제이나가 직접 항구를 얼려 버리고, 다자알로 전투가 시작됩니다."
L["Jarum Skymane"] = "자룸 스카이메인"
L["Jeek Jeek"] = "지크 지크"
L["Ji Firepaw"] = "지 파이어포우"
L["Ji Firepaw (Horde)"] = "지 파이어포우 (호드)"
L["Join Maiev and the Wardens against old corruption and reclaim a symbol of night elf devotion."] = "마이에브 및 감시자들과 함께 오랜 타락에 맞서고, 나이트 엘프 신앙의 상징을 되찾으십시오."
L["Join the Gnomeregan Engineering and Aviation Reserve as it tests the most ambitious aircraft to leave a workshop since the Great War. Old Gnomeregan is still dangerous, and not every threat beneath the city is content to stay buried.\n\nRecruit specialists, salvage prototypes, and turn brilliant schematics into machines that actually fly, preferably with all limbs and eyebrows accounted for."] = "대전쟁 이후 작업장을 떠난 비행기 중 가장 야심 찬 기체를 시험하는 놈리건 공학 항공 예비대에 합류하십시오. 옛 놈리건은 여전히 위험하며, 도시 아래에 도사린 위협이 모두 얌전히 묻혀 있으려 하지는 않습니다.\n\n전문가를 영입하고, 시제품을 회수하고, 기발한 설계도를 실제로 나는 기계로 바꾸십시오. 되도록 팔다리와 눈썹은 하나도 잃지 않은 채로 말입니다."
L["Joining the Assault"] = "공격 합류"
L["Jojo Ironbrow"] = "조조 아이언브라우"
L["Jorach's Calling"] = "조라크의 부름"
L["Jorhuttam"] = "요르후탐"
L["Jotunheim"] = "요툰하임"
L["Journey deep into the Emerald Dream to recover G'Hanir, the branch from which all world trees grew."] = "에메랄드의 꿈 깊숙이 들어가, 모든 세계수가 자라난 가지 그하니르를 되찾으십시오."
L["Journey to Icecrown Citadel to reforge the shattered remnants of Frostmourne into twin runeblades."] = "얼음왕관 성채로 가서 산산조각 난 서리한의 파편을 두 자루의 룬검으로 다시 벼려 내십시오."
L["Journey to Nazmir"] = "나즈미르로의 여정"
L["Journey to the ancient groves of Val'sharah to find a seed that could save the Arcan'dor."] = "발샤라의 고대 숲으로 가서 아칸도르를 구할 수 있을지도 모를 씨앗을 찾으십시오."
L["Journey to the Broken Shore and the ruins of Stromgarde to claim the legendary two-handed sword once wielded by the troll-slaying king."] = "부서진 해변과 스트롬가드 폐허로 가서, 한때 트롤 학살자 왕이 휘둘렀던 전설의 양손검을 손에 넣으십시오."
L["Journey to the Middle of Nowhere"] = "망망대해로"
L["Journey to the ruins of Stromgarde to raise King Thoras Trollbane, the second Horseman, from his defiled grave."] = "스트롬가드 폐허로 가서 두 번째 기사인 국왕 토라스 트롤베인을 더럽혀진 무덤에서 일으키십시오."
L["Jubeka Shadowbreaker"] = "주베카 섀도브레이커"
L["Judgment"] = "심판"
L["Judgment Awaits"] = "심판이 기다린다"
L["Judgment Day Comes!"] = "심판의 날!"
L["Jump-Capable"] = "도약 가능"
L["Jungo, Herald of G'huun"] = "그훈의 전령 준고"
L["Just for Safekeeping, Of Course"] = "물론 그저 안전 차원에서..."
L["Justicar Julia Celeste"] = "심판관 줄리아 셀레스트"
L["Kai Wanderbrew"] = "카이 원더브루"
L["Kai-Lin Honeydew"] = "카이린 허니듀"
L["Kalec's Plan"] = "칼렉의 계획"
L["Kaltunk"] = "칼툰크"
L["Kanrethad Ebonlocke"] = "칸레타드 에본로크"
L["Kasea Angerforge"] = "카시 앵거포지"
L["Katherine Proudmoore"] = "캐서린 프라우드무어"
L["Kathra'natir has possessed Meryl Felstorm. Storm the Oculus with Khadgar to save the Tirisgarde's founder and destroy the dreadlord."] = "카스라나티르가 메릴 펠스톰에게 빙의했습니다. 카드가와 함께 마력의 눈으로 쳐들어가 티리스가드의 창립자를 구하고 공포의 군주를 처치하십시오."
L["Kayn Sunfury"] = "카인 선퓨리"
L["Kayn Sunfury arranged the hunt for the Twinblades of the Deceiver — a pair of warglaives crackling with felfire, wielded by one of the Legion's own champions. You tracked the demon through shadowed ruins and claimed the blades in combat. They burned in your hands, eager for the blood of their former masters."] = "카인 선퓨리가 기만자의 쌍날검 사냥을 준비했다. 지옥불이 타닥거리는 한 쌍의 전투검으로, 군단의 용사 중 하나가 휘두르고 있었다. 그림자 드리운 폐허를 지나 악마를 추적했고, 전투 끝에 칼날을 손에 넣었다. 칼날은 손안에서 불타올랐다. 옛 주인들의 피를 갈망하면서."
L["Keep Yer Feet On The Ground"] = "두 발로 땅을 단단히 딛고서"
L["Keep Your Friends Close"] = "친구는 가까이에"
L["Keeper Remulos"] = "수호자 레물로스"
L["Keeper Remulos spoke of G'Hanir — the mother branch from which Nordrassil, Teldrassil, and every world tree had grown. It slumbered deep in the Emerald Dream, and the Nightmare sought to consume it. You ventured into the Dream's purest heart and returned with G'Hanir in hand, its leaves still green with the life of an entire world."] = "수호자 레물로스가 그하니르에 대해 이야기했다. 놀드랏실과 텔드랏실, 그리고 모든 세계수가 자라난 어머니 가지였다. 그하니르는 에메랄드의 꿈 깊은 곳에 잠들어 있었고, 악몽은 그것을 삼키려 했다. 꿈의 가장 순수한 심장부로 들어가 그하니르를 손에 들고 돌아왔다. 그 잎사귀는 온 세상의 생명을 머금은 채 여전히 푸르렀다."
L["Kel'danath's Legacy"] = "켈다나스의 유산"
L["Keritose Bloodblade"] = "케리토스 블러드블레이드"
L["Keula"] = "큘라"
L["Kevo ya Siti"] = "케보 야 시티"
L["Key members of the resistance have vanished. Search the city to find them before it's too late."] = "저항군의 핵심 인물들이 사라졌습니다. 너무 늦기 전에 도시를 뒤져 그들을 찾으십시오."
L["Key members of the resistance vanished without a trace — taken in the night by Elisande's agents. You tracked them through Suramar's twisting streets, from soul cages to smuggler's routes, pulling allies from the jaws of captivity. The message was clear: the Grand Magistrix knew about the rebellion, and she was coming for them all."] = "저항군의 핵심 인물들이 흔적도 없이 사라졌다. 밤사이 엘리산드의 첩자들에게 끌려간 것이다. 수라마르의 구불구불한 거리를 누비며 그들을 추적했고, 영혼 감옥에서 밀수꾼의 길까지 뒤져 붙잡힌 동료들을 구해 냈다. 메시지는 분명했다. 대행정관은 반란을 알고 있었고, 그들 모두를 노리고 있었다."
L["Khadgar's Discovery"] = "카드가의 발견"
L["Kibli Killohertz"] = "키블리 킬로헤르츠"
L["Kill Kher Shan"] = "케르 샨 사냥"
L["Killing Two Scourge With One Skeleton"] = "스컬지 둘에 해골 하나씩 처치"
L["Killohertz"] = "킬로헤르츠"
L["King of the Hill"] = "언덕의 왕"
L["King of the Mountain"] = "등산의 제왕"
L["King Varian's command sent you after the missing White Pawn: Prince Anduin Wrynn. The Skyfire found Pandaria and immediately found the Horde. Admiral Rogers turned the gunship into a weapon, Sully McLeary got you onto the ground, and Paw'don Village became the Alliance's first real foothold. Every step inland was paid for in smoke, wounded soldiers, stolen supplies, and the first glimpse of sha born from the armies' violence. By the time Ga'trul fell at Twinspire Keep, the Alliance had survived its landing - but Taylor and Anduin were still missing."] = "바리안 국왕의 명령에 따라 사라진 하얀 졸, 안두인 린 왕자를 찾아 나섰다. 하늘불꽃호는 판다리아를 발견하자마자 호드와 맞닥뜨렸다. 로저스 제독은 비행포함을 무기로 바꾸었고, 설리 매클리어리는 지상으로 내려갈 길을 열었으며, 포우돈 마을은 얼라이언스의 첫 번째 제대로 된 거점이 되었다. 내륙으로 한 걸음 나아갈 때마다 연기와 부상병, 약탈당한 보급품이라는 대가를 치렀고, 군대의 폭력에서 태어난 샤의 모습도 처음으로 드러났다. 쌍둥이 첨탑 요새에서 가트룰이 쓰러졌을 무렵 얼라이언스는 상륙에서 살아남았지만, 테일러와 안두인의 행방은 여전히 묘연했다."
L["Kira Iresoul"] = "키라 아이어소울"
L["Kitty?"] = "고양이 손님?"
L["Knight-Captain Drosche"] = "기사대장 드로쉬"
L["Knights of the Ebon Blade"] = "칠흑의 기사단"
L["Knock It Off!"] = "그만 둬!"
L["Knowing Our Enemy"] = "지옥사냥개 바로 알기"
L["Knowledge is a Terrible Burden"] = "아는 것이 병"
L["Koltira Deathweaver"] = "콜티라 데스위버"
L["Kor'kron Squad Leader"] = "코르크론 분대장"
L["Kor'vas Bloodthorn"] = "코르바스 블러드쏜"
L["Kor'vas Bloodthorn calls you to the Fel Hammer on Mardum, where the Illidari prepare for war against the Legion."] = "코르바스 블러드쏜이 마르둠의 지옥망치로 부릅니다. 그곳에서 일리다리가 군단과의 전쟁을 준비하고 있습니다."
L["Kor'vas Bloodthorn found you in Dalaran with an urgent message — the Illidari needed a leader. You answered the call and claimed a weapon forged from the demons' own power. On Mardum, the Fel Hammer became your stronghold — a Legion command ship turned against its former masters. With Kayn Sunfury at your side, you gazed through the Hunter's Gaze across the Broken Isles and directed the Illidari's wrath."] = "코르바스 블러드쏜이 긴급한 전갈을 들고 달라란으로 찾아왔다. 일리다리에게 지도자가 필요하다는 것이었다. 부름에 응해 악마들의 힘으로 벼려 낸 무기를 손에 넣었다. 마르둠에서는 지옥망치가 새로운 거점이 되었다. 옛 주인들에게 칼끝을 돌린 군단 지휘함이었다. 카인 선퓨리를 곁에 두고, 사냥꾼의 응시로 부서진 섬 전역을 내려다보며 일리다리의 분노를 이끌었다."
L["Koukou's Rampage"] = "코우코우의 광란"
L["Krag'wa the Terrible"] = "크라그와의 분노"
L["Kul Tiras"] = "쿨 티라스"
L["Kung Din"] = "쿵 딘"
L["Kvaldir on Call"] = "크발디르를 활용할 차례"
L["Lady Jaina Proudmoore"] = "여군주 제이나 프라우드무어"
L["Lady Jaina Proudmoore — or Lady Sylvanas Windrunner, if you ride under a darker banner — has found a door. Not a welcome one. A seam in the citadel's foundation, wide enough for a small party willing to see what they should not. Through the Forge of Souls. Through the Pit of Saron. Into the Halls of Reflection, where something waits that has been waiting a long time."] = "여군주 제이나 프라우드무어가, 혹은 더 어두운 깃발 아래 싸운다면 여군주 실바나스 윈드러너가 문 하나를 찾아냈다. 반가운 문은 아니다. 성채 기반에 난 틈으로, 보지 말아야 할 것을 기꺼이 보려는 소수의 일행이 지나갈 만큼 넓다. 영혼의 제련소를 지나. 사론의 구덩이를 지나. 투영의 전당으로. 그곳에서는 아주 오랫동안 기다려 온 무언가가 기다리고 있다."
L["Lady Liadrin"] = "여군주 리아드린"
L["Lady Liadrin and the blood elves of Silvermoon answer the call, joining the fight for their distant kin."] = "여군주 리아드린과 실버문의 블러드 엘프들이 부름에 응해, 멀리 떨어진 동족을 위한 싸움에 합류합니다."
L["Lady Lunastre"] = "루나스트르와의 만남"
L["Lady Remor'za"] = "여군주 레모르자"
L["Lady S'theno"] = "여군주 스테노"
L["Lady Sylvanas Windrunner"] = "여군주 실바나스 윈드러너"
L["Lament of the Highborne"] = "명가의 애가"
L["Lashk"] = "라쉬크"
L["Lashk brought you to Torga, and what you found broke something in the air around you. The sea turtle loa — ancient beyond reckoning, the kind of creature that outlasted empires — had been slowly bled by the blood trolls for years. He was almost gone when you arrived. You fought through the blood trolls claiming his shores, sought Bwonsamdi's intercession for a dying loa, and freed the souls trapped around him. Torga died. He just did it on his own terms, with the Horde at his side. Bwonsamdi, for once, was almost respectful. Lashk said nothing. Some losses don't require words."] = "라쉬크를 따라 토르가에게 갔고, 그곳에서 본 광경에 주위의 무언가가 무너져 내리는 듯했다. 헤아릴 수 없이 오래된, 제국들보다도 오래 살아남는 부류의 존재인 바다거북 로아는 수년 동안 피의 트롤들에게 서서히 피를 빼앗기고 있었다. 도착했을 때 그는 거의 숨이 끊어져 가고 있었다. 그의 해안을 차지한 피의 트롤들을 뚫고 나아가, 죽어 가는 로아를 위해 브원삼디의 중재를 구하고, 그 주위에 갇힌 영혼들을 풀어 주었다. 토르가는 죽었다. 다만 자신이 원하는 방식으로, 호드를 곁에 둔 채 죽었다. 브원삼디마저 이번만큼은 예의를 갖추는 듯했다. 라쉬크는 아무 말도 하지 않았다. 어떤 상실에는 말이 필요 없는 법이다."
L["Last Piece of the Puzzle"] = "퍼즐의 마지막 조각"
L["Lay of the Land"] = "지형 파악"
L["Lea Stonepaw told of the Claws of Ursoc — weapons that carried the strength of the bear god who had given his life defending Azeroth. You entered the nightmare-touched dens where the Claws had been hidden and fought through the corruption to reclaim them. The weight of Ursoc's sacrifice settled into your hands along with the weapons — a guardian's burden, willingly carried."] = "레아 스톤포우가 우르속의 발톱에 대해 들려주었다. 아제로스를 지키다 목숨을 바친 곰의 신의 힘이 깃든 무기였다. 발톱이 숨겨진, 악몽에 물든 굴로 들어가 타락을 헤치고 무기를 되찾았다. 무기와 함께 우르속의 희생이 지닌 무게도 손에 내려앉았다. 기꺼이 짊어진 수호자의 짐이었다."
L["Lead a covert strike beneath Icecrown Citadel, closer to Frostmourne than any living hand has come."] = "얼음왕관 성채 지하로 은밀한 기습을 이끌고, 살아 있는 자 중 누구보다도 서리한에 가까이 다가가십시오."
L["Lead G.E.A.R. through a high-tech campaign against old enemies and reclaim gnomish pride."] = "놈리건 공학 항공 예비대(G.E.A.R.)를 이끌고 오랜 적에 맞서 첨단 기술 작전을 펼쳐, 노움의 자존심을 되찾으십시오."
L["Lead the allied armies through the streets of Suramar in a desperate push toward the Nighthold."] = "연합군을 이끌고 수라마르 거리를 가로질러 밤의 요새를 향해 필사적인 진격을 펼치십시오."
L["Lead the Ebon Blade to the Broken Shore, tame a frost wyrm, and claim the Vilebrood Vanquisher as your mount."] = "칠흑의 기사단을 이끌고 부서진 해변으로 향하십시오. 서리고룡을 길들여 악의 무리 정복자를 탈것으로 얻으십시오."
L["Lead the Illidari to the Broken Shore. Defend the Fel Hammer, recruit Lady S'theno, and earn the Slayer's Felbroken Shrieker."] = "일리다리를 이끌고 부서진 해변으로 향하십시오. 지옥망치를 방어하고, 여군주 스테노를 영입하고, 학살자의 지옥타락 비명꾼을 얻으십시오."
L["Lead the united Conclave to Niskara, rescue captured allies, and earn the title of High Priest."] = "하나로 뭉친 의회를 이끌고 니스카라로 가서 붙잡힌 동료들을 구출하고, 대사제의 칭호를 얻으십시오."
L["Leader of the Illidari"] = "일리다리의 지도자"
L["Leaders of the Horde"] = "호드의 지도자들이여"
L["Leading by Example"] = "귀감이 되어 이끌기"
L["Leading the Charge"] = "나를 따르라"
L["Learning From the Dead"] = "망자의 가르침"
L["Leave None Standing"] = "그리고 아무도 없었다"
L["Leave Our Mark"] = "흔적을 남겨라"
L["Legacy of the Bronzebeard"] = "브론즈비어드 가의 유산"
L["Legacy of the Icebreaker"] = "얼음파괴자의 유산"
L["Legion"] = "군단"
L["Legion Commander Tyralion"] = "군단 사령관 티랄리온"
L["Legion Commander Yorik"] = "군단 사령관 요릭"
L["Legion: The Legion Returns"] = "군단: 돌아온 군단"
L["Lending a Hand"] = "손 빌려 주기"
L["Let Sleeping Wolves Lie"] = "그 누가 잠자는 늑대의 코털을 건드리나"
L["Let the Baron Know"] = "남작에게 보고"
L["Let the Hunt Begin"] = "사냥 개시"
L["Let Them Burn"] = "활활 타올라라"
L["Let's Rumble!"] = "힘겨루기 한판 승부!"
L["Lethal Efficiency"] = "치명적인 게시판"
L["Leyworm Lure"] = "지맥벌레 간식"
L["Li Li Stormstout"] = "리 리 스톰스타우트"
L["Liadrin's Command"] = "리아드린의 명령"
L["Lieutenant Sanders"] = "부관 샌더스"
L["Life Held Hostage"] = "인질로 잡힌 몸"
L["Light Within the Darkness"] = "어둠 속의 빛"
L["Light's Wrath"] = "빛의 격노"
L["Lighting Up the Sky"] = "하늘을 밝히다"
L["Lilian Voss"] = "릴리안 보스"
L["Lilian Voss was raised by the Scarlet Crusade to hate the undead, and then she died, rose, and became one. Trained from childhood to purify the Forsaken, she wakes in Deathknell as the very thing her father taught her to burn.\n\nFollow her from the cellars of the Crusade through Scholomance and the politics of Lordaeron, where vengeance, identity, and belonging keep asking for different answers."] = "릴리안 보스는 언데드를 증오하도록 붉은십자군의 손에 길러졌지만, 죽었다가 되살아나 그녀 자신이 언데드가 되었습니다. 어릴 적부터 포세이큰을 정화하도록 훈련받은 그녀는, 죽음의 종소리 마을에서 아버지가 불태우라고 가르친 바로 그 존재가 되어 깨어납니다.\n\n십자군의 지하실에서 스칼로맨스, 그리고 로데론의 정치판까지 그녀의 뒤를 따르십시오. 그곳에서 복수와 정체성, 소속감은 저마다 다른 답을 요구합니다."
L["Lilian's hunt for dark knowledge leads her into the cursed academy of Scholomance. Within its halls she confronts Darkmaster Gandling — but the darkness she wields threatens to consume her entirely. She must destroy the forbidden tomes and end the suffering, or become the very evil she hunts."] = "어둠의 지식을 쫓던 릴리안은 저주받은 학원 스칼로맨스에 들어섭니다. 그곳에서 암흑스승 간들링과 맞서지만, 그녀가 휘두르는 어둠이 그녀를 완전히 집어삼키려 합니다. 금지된 서적을 파괴하고 고통을 끝내야 합니다. 그러지 못하면 그녀 자신이 쫓던 악이 되고 말 것입니다."
L["Lilian's pursuit of power led her into Scholomance, the cursed academy of necromancy. Through a talking skull she guided you to destroy the Four Tomes of forbidden knowledge and end the suffering within those walls. But when she faced Darkmaster Gandling, the darkness she wielded nearly consumed her. She survived — but the line between hunter and monster grew thinner."] = "힘을 갈구하던 릴리안은 저주받은 강령술 학원 스칼로맨스로 향했다. 그녀는 말하는 해골을 통해 금지된 지식이 담긴 네 권의 마법서를 파괴하고 그 벽 안의 고통을 끝내도록 길을 안내했다. 하지만 암흑스승 간들링과 맞섰을 때, 그녀가 휘두르던 어둠이 그녀를 거의 집어삼킬 뻔했다. 그녀는 살아남았지만, 사냥꾼과 괴물 사이의 경계는 더욱 희미해졌다."
L["Lin Applebloom"] = "린 애플블룸"
L["Lin Tenderpaw"] = "린 텐더포우"
L["Lina Whitepaw"] = "리나 화이트포우"
L["Lingering Scars"] = "사라지지 않는 흉터"
L["Lion's Heritage"] = "사자의 유산"
L["Little Lu"] = "꼬마 루"
L["Little One Lost"] = "길 잃은 꼬마"
L["Livin' on the Ledge"] = "마루에 살다"
L["Lo Wanderbrew"] = "로 원더브루"
L["Loa-Free Diet"] = "목불인견"
L["Lockdown"] = "봉쇄"
L["Logistical Matters"] = "병참 문제"
L["Looking for Lukou"] = "루코우 찾기"
L["Looking for Something Specific"] = "어떤 물건을 찾아서"
L["Loot and Plunder!"] = "파괴와 약탈!"
L["Lor'themar Theron"] = "로르테마르 테론"
L["Loramus, Is That You?"] = "로라무스, 당신인가요?"
L["Lord Chamberlain"] = "시종장"
L["Lord Chamberlain escorts you toward Castle Nathria. Sire Denathrius receives your plea with perfect elegance — and asks you to help restore order first."] = "시종장이 나스리아 성채로 안내합니다. 대영주 데나트리우스는 완벽하게 우아한 태도로 탄원을 받아들이고, 먼저 질서를 되찾는 일을 도와 달라고 요청합니다."
L["Lord Grayson Shadowbreaker"] = "그레이슨 섀도브레이커 경"
L["Lord Jorach Ravenholdt"] = "조라크 라벤홀트 경"
L["Lord Maxwell Tyrosus"] = "맥스웰 티로서스 경"
L["Lord Maxwell Tyrosus calls paladins from every order to the Sanctum of Light beneath Light's Hope Chapel."] = "맥스웰 티로서스 경이 모든 기사단의 성기사들을 희망의 빛 예배당 아래 빛의 성소로 소집합니다."
L["Lord Maxwell Tyrosus issued an urgent summons — the Silver Hand was reforming, and Light's Hope Chapel would be its heart. You descended into the Sanctum of Light, hidden beneath the chapel for centuries, where paladins of every faith gathered. Tyrosus named you champion, and you claimed a weapon of legend. Lady Liadrin pledged the Blood Knights' strength, and the Silver Hand rode again."] = "맥스웰 티로서스 경이 긴급히 소집령을 내렸다. 은빛 성기사단이 다시 결성되고 있으며, 희망의 빛 예배당이 그 중심이 될 것이었다. 수 세기 동안 예배당 아래 숨겨져 있던 빛의 성소로 내려가자, 온갖 신앙의 성기사들이 모여 있었다. 티로서스에게 용사로 지명받고 전설의 무기를 손에 넣었다. 여군주 리아드린은 피의 기사단의 힘을 보태겠다고 맹세했고, 은빛 성기사단은 다시 한번 말을 달렸다."
L["Lord Maxwell Tyrosus pointed you toward Truthguard — a shield forged by the titans themselves, imbued with the power to protect the righteous and shatter the deceitful. You traveled to the Shrine of the Truthguard and faced the shield's ancient tests. Truthguard weighed nothing in the hands of the pure — and everything in the hands of the unworthy. It chose you."] = "맥스웰 티로서스 경은 진실의 수호자를 가리켰다. 티탄이 직접 벼려 낸 방패로, 의로운 자를 지키고 거짓된 자를 부수는 힘이 깃들어 있었다. 진실의 수호자 제단으로 가서 방패의 고대 시험에 맞섰다. 진실의 수호자는 순수한 자의 손에서는 아무 무게도 느껴지지 않았고, 자격 없는 자의 손에서는 한없이 무거웠다. 방패는 새 주인을 택했다."
L["Lord Maxwell Tyrosus spoke the name that every paladin knew — the Ashbringer. The blade that had burned with holy fire in Alexandros Mograine's hands, that had been corrupted and redeemed, that had shattered the Scourge at Light's Hope Chapel. You sought guidance and followed the weapon's trail to its resting place. When you drew the Ashbringer, holy fire erupted along its edge, and the weight of every paladin who had carried it settled onto your shoulders."] = "맥스웰 티로서스 경이 모든 성기사가 아는 이름을 입에 올렸다. 파멸의 인도자. 알렉산드로스 모그레인의 손에서 성스러운 불꽃으로 타올랐고, 타락했다가 구원받았으며, 희망의 빛 예배당에서 스컬지를 산산이 부순 검이었다. 인도를 구한 뒤 무기의 흔적을 따라 검이 잠든 곳에 이르렀다. 파멸의 인도자를 뽑아 들자 칼날을 따라 성스러운 불꽃이 솟구쳤고, 그 검을 들었던 모든 성기사의 무게가 어깨 위에 내려앉았다."
L["Lord Thorval"] = "토르발 경"
L["Lord Waycrest has vanished and a curse grips the village of Fallhaven. Lucille Waycrest enlists your help to hunt the witches responsible."] = "군주 웨이크레스트가 사라지고 낙엽의 안식처 마을이 저주에 사로잡혔습니다. 루실 웨이크레스트가 그 배후의 마녀들을 사냥하는 데 도움을 청합니다."
L["Lordaeron"] = "로데론"
L["Lordaeron has been reclaimed, the penance accepted. But for those who once swore loyalty to the Banshee Queen, a message finds its way back through the dark — one last task, carried by a familiar messenger."] = "로데론을 되찾았고, 속죄는 받아들여졌습니다. 그러나 한때 밴시 여왕에게 충성을 맹세했던 이들에게 어둠을 뚫고 전갈 하나가 도착합니다. 낯익은 전령이 전하는 마지막 임무입니다."
L["Lordaeron is in Forsaken hands again, but old enemies still haunt the forests beyond its walls. The Scarlet Crusade clings to its strongholds, Gilneas has not forgotten, and a former queen's absence leaves difficult questions behind.\n\nLilian Voss has a mission in Silverpine, and she needs someone who knows what it means to be Forsaken: to stand at a graveside, remember, and choose again what the second life is for."] = "로데론은 다시 포세이큰의 손에 들어왔지만, 성벽 너머의 숲에는 여전히 옛 적들이 도사리고 있습니다. 붉은십자군은 요새에 매달려 버티고, 길니아스는 잊지 않았으며, 전 여왕의 부재는 어려운 질문들을 남겼습니다.\n\n릴리안 보스는 은빛소나무 숲에서 임무를 수행해야 하며, 포세이큰이 된다는 것이 무엇인지 아는 이가 필요합니다. 무덤가에 서서 기억하고, 두 번째 삶이 무엇을 위한 것인지 다시 선택한다는 것의 의미를 아는 이 말입니다."
L["Lorewalker Cho"] = "전승지기 초"
L["Lorewalker Cho did not answer Nazgrim's campaign with orders. He answered with tea, old stones, and the patient insistence that Pandaria had a story before the Horde arrived. You walked a mile in another person's shoes, listened to the forest's dead, peered into the past, and traced the branches of Cho's own family. The lesson was not gentle, but it was necessary: this land remembers what people bring into it. Then the river swallowed you, the hozen found you, and Chief Kah Kah's orders dragged the lesson back into the campaign. You left Cho with more questions than victories, which was probably the point."] = "전승지기 초는 나즈그림의 원정에 명령으로 답하지 않았다. 그는 차와 오래된 돌, 그리고 호드가 오기 전에도 판다리아에는 이야기가 있었다는 끈질긴 가르침으로 답했다. 남의 입장이 되어 걸어 보고, 숲의 망자들에게 귀 기울이고, 과거를 들여다보고, 초 가문의 내력을 거슬러 올라갔다. 가르침은 부드럽지 않았지만 꼭 필요했다. 이 땅은 사람들이 가지고 들어온 것을 기억한다는 것이었다. 그러다 강물에 휩쓸렸고, 호젠들에게 발견되었으며, 족장 카 카의 명령이 그 가르침을 다시 원정 속으로 끌고 들어왔다. 초에게서 얻은 것은 승리보다 질문이 더 많았다. 아마 그것이 핵심이었을 것이다."
L["Lorewalker Cho's Lesson"] = "전승지기 초의 가르침"
L["Lorewalker Stonestep"] = "전승지기 스톤스텝"
L["Lost in Darkness"] = "어둠 속 방황"
L["Lost in the Desiccation"] = "말라붙은 땅에서 길을 잃다"
L["Lost My Spark"] = "잃어버린 불꽃"
L["Lost Shipment"] = "잃어버린 소중한 것"
L["Lothraxion"] = "로스락시온"
L["Love's Labor"] = "총알 배달"
L["Lucille realized that scattered witch hunting would never be enough. A slight detour through the mountains — past yetis and salvaged supplies — led to the ruins of Gol Var, where ancient bones whispered of the Order of Embers. Centuries ago, the Order had been Drustvar's shield against the Drust and their dark magic. Lucille read the histories carved in stone and rune-etched bone, and made her decision: the Order of Embers would rise again. She would lead it, and you would be her blade."] = "루실은 흩어진 채 벌이는 마녀 사냥으로는 결코 충분하지 않다는 것을 깨달았다. 예티 무리와 회수한 보급품을 거쳐 산을 살짝 둘러 가는 길은 골 바르 유적으로 이어졌고, 그곳의 고대 유골들은 잿불단에 대해 속삭였다. 수 세기 전, 잿불단은 드루스트와 그들의 어둠의 마법에 맞서 드러스트바를 지키는 방패였다. 루실은 돌과 룬이 새겨진 뼈에 남은 역사를 읽고 결단을 내렸다. 잿불단을 다시 일으키겠다고. 그녀가 잿불단을 이끌 것이고, 그녀의 칼날이 되어 줄 이도 이미 곁에 있었다."
L["Lucille stands accused of witchcraft herself. Marshal Reade demands proof of her innocence through superstitious trials."] = "이번에는 루실 자신이 마녀로 고발당했습니다. 원수 리드는 미신에 기댄 시험으로 그녀의 결백을 증명하라고 요구합니다."
