L["Mathias Shaw laid out the strategy in Proudmoore Keep: use the Abyssal Scepter to create a false assault on Nazmir and lure the Horde fleet away from Zuldazar. While Zandalari forces rushed south to repel the distraction, the Alliance fleet would hit the harbor directly. You spent two weeks fighting through Nazmir swamps, disabling Zandalari machinery, and holding the line at the Blood Gate — long enough for the fleet to round the coast.\n\nThen Jaina froze the harbor. The water turned to ice beneath Zandalari hulls. The Alliance sailed straight through. The Battle of Dazar'alor — the most audacious naval assault in a generation — had begun. Lord Admiral Jaina Proudmoore, fighting in her own waters, had brought the war home."] = "마티아스 쇼가 프라우드무어 요새에서 작전을 설명했다. 심연의 홀로 나즈미르에 거짓 공격을 꾸며 호드 함대를 줄다자르에서 멀리 끌어내는 것이었다. 잔달라 병력이 미끼를 막으러 남쪽으로 몰려가는 사이, 얼라이언스 함대가 항구를 정면으로 들이칠 계획이었다. 2주 동안 나즈미르의 늪지를 헤치며 싸우고, 잔달라의 장치를 무력화하고, 피의 관문에서 전선을 지켰다. 함대가 해안을 돌아 나올 때까지.\n\n그리고 제이나가 항구를 얼렸다. 잔달라 함선의 선체 아래에서 바닷물이 얼음으로 변했다. 얼라이언스 함대는 그대로 뚫고 나아갔다. 한 세대를 통틀어 가장 대담한 해상 공격, 다자알로 전투가 시작되었다. 자신의 무대인 바다에서 싸우는 대제독 제이나 프라우드무어가 전쟁을 적의 심장부로 끌고 간 것이다."
L["Mathias Shaw, spymaster of SI:7, had been captured and replaced by a dreadlord impostor. You infiltrated the enemy stronghold alongside Taoshi, cutting through guards and wards to reach Shaw's cell. The rescue was harrowing — but when the real Shaw stood free and the impostor was exposed, the conspiracy's days were numbered."] = "SI:7의 수장 마티아스 쇼가 붙잡혔고, 공포의 군주가 그로 위장해 그 자리를 차지하고 있었다. 타오스와 함께 적의 요새에 잠입해 경비병과 결계를 뚫고 쇼의 감방에 다다랐다. 구출은 아슬아슬했지만, 진짜 쇼가 풀려나고 사칭자의 정체가 드러나자 음모의 날도 얼마 남지 않게 되었다."
L["Mathias Shaw, spymaster of SI:7, has gone missing. A daring rescue mission takes you deep behind enemy lines."] = "SI:7의 수장 마티아스 쇼가 실종되었습니다. 대담한 구출 작전을 위해 적진 깊숙이 들어갑니다."
