L["Meryl Felstorm"] = "메릴 펠스톰"
L["Meryl Felstorm appeared with an urgent plea — Kathra'natir, a cunning dreadlord, had broken free of his prison and threatened all of Dalaran. You fought the demon back and descended into the Hall of the Guardian, an ancient sanctum beneath the city. There, Meryl revealed the Tirisgarde — an ancient order of mages sworn to defend Azeroth against the Burning Legion. With a weapon of legend in hand and The Great Akazamzarak's theatrical assistance, you reforged the order and took your place as its champion."] = "메릴 펠스톰이 다급히 도움을 청했다. 교활한 공포의 군주 카스라나티르가 감옥을 부수고 나와 달라란 전체를 위협하고 있었다. 악마를 물리친 뒤 도시 아래의 고대 성소, 수호자의 전당으로 내려갔다. 그곳에서 메릴은 불타는 군단에 맞서 아제로스를 지키기로 맹세한 고대 마법사 조직, 티리스가드의 존재를 밝혔다. 전설의 무기를 손에 쥐고 위대한 아카잠자락의 요란한 도움을 받아, 조직을 재건하고 그 용사의 자리에 올랐다."
L["Meryl Felstorm pointed you toward Aluneth — the Greatstaff of the Magna, once wielded by Aegwynn, Guardian of Tirisfal. The staff had been sealed away for good reason: it was sentient, willful, and dangerously powerful. You found it in an arcane vault crackling with unbound energy, and when you grasped it, Aluneth's voice echoed in your mind — condescending, impatient, and undeniably brilliant. You had a weapon. It had opinions."] = "메릴 펠스톰은 알루네스를 가리켰다. 한때 티리스팔의 수호자 에이그윈이 휘둘렀던 마그나의 대지팡이였다. 이 지팡이가 봉인된 데는 그럴 만한 이유가 있었다. 자아를 지녔고, 고집스러웠으며, 위험할 만큼 강력했기 때문이다. 속박에서 풀려난 기운이 파직거리는 비전 금고에서 지팡이를 찾아 움켜쥐자, 알루네스의 목소리가 머릿속에 울려 퍼졌다. 거들먹거리고, 성미 급하고, 부정할 수 없을 만큼 명석한 목소리였다. 무기를 얻었다. 그리고 그 무기에게는 할 말이 많았다."
L["Meryl Felstorm, an ancient mage, pleads for help against a dreadlord. Together you reforge the Tirisgarde in the Hall of the Guardian."] = "고대의 마법사 메릴 펠스톰이 공포의 군주에 맞설 도움을 청합니다. 함께 수호자의 전당에서 티리스가드를 재건합니다."
L["Meryl spoke of Ebonchill — the staff of Alodi, the very first Guardian of Tirisfal, sealed within a pocket dimension of frozen time. You breached the dimensional barrier and entered a world where time stood still, ice crystals hanging motionless in the air. At its heart, Ebonchill waited — cold, patient, and ancient beyond measure. When you took it, the pocket dimension shattered, and the staff's frost spread through your veins like a promise."] = "메릴은 흑한에 대해 이야기했다. 최초의 티리스팔의 수호자 알로디의 지팡이로, 시간이 얼어붙은 차원 주머니 속에 봉인되어 있었다. 차원의 장벽을 뚫고 들어가자 시간이 멈춘 세계가 펼쳐졌고, 얼음 결정들이 허공에 꼼짝 않고 떠 있었다. 그 중심에서 흑한이 기다리고 있었다. 차갑고, 참을성 있고, 헤아릴 수 없이 오래된 모습으로. 지팡이를 손에 넣자 차원 주머니가 산산이 부서졌고, 지팡이의 냉기가 약속처럼 혈관을 타고 퍼져 나갔다."
