L["Naralex"] = "나랄렉스"
L["Naralex revealed the location of the Scythe of Elune — an artifact of immense power forged from Elune's staff and the Fang of Goldrinn. You journeyed through cursed lands to claim it, feeling the pull of both the moon's light and the beast within. The Scythe chose you, and with it came the weight of every druid who had wielded it before."] = "나랄렉스는 엘룬의 낫이 있는 곳을 밝혔다. 엘룬의 지팡이와 골드린의 송곳니로 벼려 낸, 엄청난 힘을 지닌 유물이었다. 저주받은 땅을 지나 그것을 찾아 나서는 동안, 달빛과 내면의 야수가 동시에 끌어당기는 것을 느꼈다. 엘룬의 낫은 새 주인을 택했고, 그와 함께 이전에 낫을 휘둘렀던 모든 드루이드의 무게도 짊어지게 되었다."
L["Naralex, the druid who once fell to the Nightmare in the Wailing Caverns, sensed dire growth spreading through the Dream. Together you ventured into nightmare-twisted lands, sampling the corruption to understand its nature. In Malorne's Refuge you found the great stag's sanctuary under siege. You tracked the source of the corruption to its heart and recovered the Idol of the Wilds — an ancient artifact that could turn the tide against the Nightmare."] = "한때 통곡의 동굴에서 악몽에 굴복했던 드루이드 나랄렉스가 꿈속에 불길한 성장이 퍼져 나가는 것을 감지했다. 함께 악몽에 뒤틀린 땅으로 들어가 타락의 표본을 채취하며 그 본질을 파악했다. 말로른의 은거처에서는 위대한 수사슴의 성소가 포위당해 있었다. 타락의 근원을 그 심장부까지 추적한 끝에 야생의 우상을 되찾았다. 악몽과의 싸움에서 흐름을 뒤집을 수 있는 고대 유물이었다."
L["Natalie Seline"] = "나탈리 세린"
L["Nathanos Blightcaller"] = "나타노스 블라이트콜러"
L["Nathanos Blightcaller and Lilian Voss lead a covert strike into the heart of Tiragarde Sound. While Nathanos secures the mountain outpost, Lilian takes command of the Bridgeport operation — sabotaging Ashvane foundries, planting explosives, and riding through the chaos she created."] = "나타노스 블라이트콜러와 릴리안 보스가 티라가드 해협 한복판으로 은밀한 기습을 이끕니다. 나타노스가 산악 전초기지를 확보하는 동안, 릴리안은 다리항구 작전을 지휘합니다. 애쉬베인 주조소를 파괴하고, 폭발물을 설치하고, 자신이 일으킨 혼란 속을 질주합니다."
L["Nathanos led an expedition to dig up a fallen Kul Tiran war hero for resurrection. As you searched the graveyards of Drustvar, Lilian grew quiet. Unearthing the dead, raising them against their will — it was exactly what had been done to her. She carried out her orders, but the questions in her eyes said everything her lips would not."] = "나타노스는 부활시킬 쿨 티란의 전쟁 영웅을 파내기 위해 원정대를 이끌었다. 드러스트바의 묘지들을 뒤지는 동안 릴리안은 말이 없어졌다. 죽은 자를 파내고, 그 의지에 반해 일으켜 세우는 것. 그것은 바로 그녀에게 일어났던 일이었다. 그녀는 명령을 수행했지만, 입으로는 하지 않는 말을 그녀의 눈에 담긴 물음이 모두 말해 주고 있었다."
L["Navigate the treacherous politics of Suramar's noble houses alongside the cunning Ly'leth Lunastre."] = "교활한 라일레스 루나스트르와 함께 수라마르 귀족 가문들의 위험한 정치 싸움을 헤쳐 나가십시오."
L["Nazgrim"] = "나즈그림"
L["Nazgrim rescues Zin'jun, breaks the Alliance airstrip, and follows the trail to the edge of Cho's lesson."] = "나즈그림이 진준을 구출하고, 얼라이언스 비행장을 무너뜨린 뒤, 초의 가르침이 시작되는 곳까지 흔적을 따라갑니다."
L["Nazgrim's Command"] = "나즈그림의 명령"
L["Nazmir"] = "나즈미르"
L["Nazmir is a dying land: ancient, cursed, and crawling with blood trolls whose rituals stain the swamp red. Stranded among loa whose temples have fallen and whose followers have turned to darker powers, you will need help from gods who rarely give anything freely.\n\nForge uneasy bargains, follow the trail through fetid ruins and broken pacts, and learn why the oldest powers in Zandalar still fear what waits beneath the mud."] = "나즈미르는 죽어 가는 땅입니다. 오래되고 저주받았으며, 늪을 붉게 물들이는 의식을 벌이는 피의 트롤이 우글거립니다. 신전은 무너지고 추종자들은 더 어두운 힘에 돌아선 로아들 사이에 고립된 채, 좀처럼 아무것도 거저 내주지 않는 신들의 도움을 구해야 합니다.\n\n불안한 거래를 맺고, 썩은 내 나는 폐허와 깨진 맹약을 따라 흔적을 쫓으며, 잔달라에서 가장 오래된 힘들조차 왜 진흙 아래 도사린 것을 여전히 두려워하는지 알아내십시오."
L["Nazmir is swallowed by blood and shadow. Princess Talanji leads the Horde into the swamp to find the loa and stop the blood troll advance."] = "나즈미르가 피와 어둠에 잠겼습니다. 공주 탈란지가 호드를 이끌고 늪으로 들어가 로아를 찾고 피의 트롤의 진격을 막으려 합니다."
L["Nazmir, the Forbidden Swamp"] = "금지된 늪지대 나즈미르"
L["Nectarbreeze Orchard was not a battlefield until the mogu made it one. Shao the Defiant and Gentle Mother Hanae needed survivors rallied, hardware recovered, and slavers driven off before the orchard became another wound. From there the road bent toward Emperor's Omen and Greenstone Quarry, where the Serpent's Heart had stalled. Foreman Mann had no jade, Hao Mann was trapped, and the miners were running on fear. By freeing farmers, saving workers, and bringing jade back to the statue, you helped the forest rebuild something sacred while the armies outside kept finding reasons to break things."] = "감로바람 과수원은 모구가 쳐들어오기 전까지 전장이 아니었다. 저항자 샤오와 자애로운 어머니 하나에에게는 과수원이 또 하나의 상처가 되기 전에 생존자를 규합하고, 장비를 되찾고, 노예상을 몰아낼 이가 필요했다. 그곳에서부터 길은 황제의 예언과 녹옥 채석장으로 굽어졌고, 그곳에서는 용의 심장 작업이 멈춰 있었다. 현장감독 만에게는 비취가 없었고, 하오 만은 갇혀 있었으며, 광부들은 두려움만으로 버티고 있었다. 농부들을 풀어 주고, 일꾼들을 구하고, 석상에 비취를 가져다주며 숲이 신성한 무언가를 다시 세우도록 도왔다. 그동안에도 바깥의 군대들은 무언가를 부술 이유를 계속 찾아내고 있었다."
L["Need More Info"] = "정보 부족"
L["Needs of the Hunters"] = "사냥꾼이 활약할 때"
L["Negative Blood"] = "나쁜 피"
L["Neltharion's Lair: Braid of the Underking"] = "넬타리온의 둥지: 지저왕의 댕기머리"
L["Netherlight Temple"] = "황천빛 사원"
L["Netherlight Temple / Broken Isles"] = "황천빛 사원 / 부서진 섬"
L["Netherlord's Campaign"] = "황천군주의 대장정"
L["Network Security"] = "순간이동 연구소"
L["New Recruit"] = "신병 교육"
