L["Nightmare Catcher"] = "증오, 뼈와 힘줄"
L["Nikki the Gossip"] = "수다쟁이 니키"
L["Nimi Brightcastle"] = "나이미 브라이트캐슬"
L["No Escape"] = "피난민 소탕"
L["No Goblin Left Behind"] = "고블린의 뜨거운 전우애"
