L["No Plan Survives Contact with the Enemy"] = "적과 마주칠 때, 계획은 사치다"
L["No Price Too High"] = "어떤 대가를 치러서라도"
L["No Reason to Stay"] = "머물 이유가 없다"
L["No Rest For The Wicked"] = "악당을 위한 휴식은 없다"
L["No Sanctuary"] = "성역은 없다"
L["Nobundo spoke of Ra-den, the titan keeper who had shaped Azeroth's storms. His weapon — the Fist of Ra-den — lay hidden in a vault sealed since the ordering of the world. You braved the coming storm to claim it, and when lightning struck the weapon in your hands, the power of a titan keeper surged through you."] = "노분도는 아제로스의 폭풍을 빚어낸 티탄 수호자 라덴에 대해 이야기했다. 그의 무기인 라덴의 주먹은 세상이 질서를 갖춘 이래 봉인된 금고 속에 숨겨져 있었다. 다가오는 폭풍을 무릅쓰고 그것을 손에 넣었고, 손에 쥔 무기에 번개가 내리치자 티탄 수호자의 힘이 온몸으로 솟구쳤다."
L["Nodd Codejack"] = "노드 코드잭"
L["Noggenfogger's Reasonable Request"] = "노겐포저의 당당한 요청"
L["Noressa"] = "노레사"
L["Not a Bug"] = "암흑의 첩보원"
L["Not A Toothless Dragon"] = "그래도 용은 용"
L["Not everyone who followed the Banshee Queen has made peace with what came after. A message finds its way to the ruins of Lordaeron for those who haven't."] = "밴시 여왕을 따랐던 이들이 모두 그 뒤에 일어난 일과 화해한 것은 아닙니다. 아직 그러지 못한 이들을 위해, 로데론의 폐허로 전갈 하나가 도착합니다."
L["Not Fit for This Plane"] = "다른 차원의 존재"
L["Not-So-Honorable Combat"] = "그리 명예롭지 않은 전투"
L["Nothing Like the Classic"] = "고전이 최고야"
L["Novice Elreth"] = "수련사제 엘레스"
L["Now With More Mechanical Fowl"] = "기계 새 나가신다"
L["Nullified"] = "중화"
L["Oath Breaker"] = "언약 파기하기"
L["Oath of Service"] = "봉사의 서약"
L["Oath of the Windlord"] = "바람의 군주의 약속"
L["Oculeth Ex Machina"] = "오큘레스와 기계의 혼"
L["Oculeth's Workshop"] = "오큘레스의 연구소"
L["Odds and Ends"] = "다양한 재료들"
L["Odyn"] = "오딘"
L["Odyn and the Valarjar"] = "오딘의 명"
L["Odyn called you to battle, but the Gjallarhorn — the sacred horn that summons the Valarjar to war — had been stolen. Hymdall sent you into Stormheim where you found Svergan Stormcloak, a vrykul king whose honor had been stripped by the thieves. Together you broke his chains, recovered the horn, and tracked a massive worm to the summit of Highmountain. With Svergan's oath sworn and the beast Jorhuttam slain, the Valarjar stood ready for war once more."] = "오딘이 전투에 소집했지만, 발라리아르를 전쟁으로 불러 모으는 성스러운 뿔피리 걀라르호른이 도난당한 상태였다. 하임달의 지시로 스톰하임에 가자, 도둑들에게 명예를 빼앗긴 브리쿨 왕 폭풍망토 스베르간이 있었다. 함께 그의 사슬을 끊고 뿔피리를 되찾은 뒤, 거대한 벌레를 쫓아 높은산 정상까지 올라갔다. 스베르간이 맹세를 바치고 야수 요르후탐이 쓰러지자, 발라리아르는 다시 한번 전쟁에 나설 채비를 마쳤다."
L["Odyn reaches out to old allies in Ulduar and sends you to deliver a message to Helya in the Maw of Souls. Titan keepers join the fight."] = "오딘이 울두아르의 옛 동맹들에게 손을 내밀고, 영혼의 아귀에 있는 헬리야에게 전갈을 전하라고 보냅니다. 티탄 수호자들도 싸움에 합류합니다."
L["Odyn sent you into the Maw of Souls with a defiant message for Helya — the Valarjar would not be broken. In the ancient halls of Ulduar, you rallied the titan keepers to the cause. Dvalen Ironrune, steadfast guardian of the forge, and Thorim, Odyn's own son, pledged themselves to the Valarjar. You retrieved Ymiron's broken blade from the Maw as proof that even the mightiest of Helya's champions could fall."] = "오딘은 헬리야에게 보내는 도전의 전갈을 들려 영혼의 아귀로 보냈다. 발라리아르는 결코 꺾이지 않으리라는 전갈이었다. 울두아르의 고대 전당에서는 티탄 수호자들을 대의 아래 결집시켰다. 대장간의 굳건한 수호자 드바렌 아이언룬과 오딘의 아들 토림이 발라리아르에 충성을 맹세했다. 영혼의 아귀에서 이미론의 부러진 칼날을 되찾아, 헬리야의 가장 강력한 용사조차 쓰러질 수 있다는 증거로 삼았다."
L["Odyn spoke of Strom'kar, the Warbreaker — a blade forged in the ancient empire of Arathor and wielded by King Thoradin against the Amani trolls. You traveled to the ruins of Stromgarde and fought through the shadows to reclaim the sword from its cursed resting place. The blade hummed with ancient power as you raised it — a weapon worthy of the Battlelord."] = "오딘은 전쟁파괴자 스트롬카르에 대해 이야기했다. 고대 아라소르 제국에서 벼려져 국왕 소라딘이 아마니 트롤에 맞서 휘둘렀던 검이었다. 스트롬가드 폐허로 가서 어둠을 뚫고, 저주받은 안식처에서 검을 되찾았다. 검을 치켜들자 칼날이 고대의 힘으로 울렸다. 전투군주에게 걸맞은 무기였다."
L["Odyn summons the greatest warriors to serve under your command. Build your forces and prepare Skyhold for war against the Legion."] = "오딘이 가장 위대한 전사들을 불러 모아 지휘를 맡깁니다. 병력을 갖추고 군단과의 전쟁에 대비해 하늘보루를 준비하십시오."
L["Odyn's Summons"] = "오딘의 소환"
L["Of Myth and Fable"] = "신화와 전설"
L["Of Water and Blood"] = "물과 선혈"
L["Off to Court"] = "궁정을 향하여"
L["Old Allies"] = "오랜 동료"
L["Old Colleagues"] = "옛 동료들"
L["Old Friends, New Opportunities"] = "오랜 친구, 새로운 기회"
L["Old Man Misteye"] = "노인 미스트아이"
L["Old Soldier"] = "노병"
L["On Daumyr's Wings"] = "다우미르를 타고"
L["On Eagle's Wings"] = "독수리의 날개를 타고"
L["On Her Majesty's Secret Service"] = "여왕폐하 대작전"
L["On Public Display"] = "공공연한 전시"
L["On Ruby Wings"] = "루비의 날개 위에"
L["On the Broken Shore, brew a cure for a fallen brewmaster, then follow the trail of Ban-Lu — a legendary celestial tiger."] = "부서진 해변에서 쓰러진 양조사를 위한 치료제를 빚은 뒤, 전설의 천신 호랑이 반루의 흔적을 따라가십시오."
L["On the Broken Shore, Lady Liadrin led the Silver Hand's assault. Delas Moonfang's past caught up with her — an ancestor's curse threatened her family. You broke the curse, freed Nerus Moonfang from his torment, and earned another champion for the order. When the Shore was secured, Lord Grayson Shadowbreaker sent you to the Hammer of Dalaran — the legendary forge — where Alard Schmied crafted armor worthy of a Highlord. In the shadows beneath the city, a golden charger waited, and it carried you into the light."] = "부서진 해변에서 여군주 리아드린이 은빛 성기사단의 공격을 이끌었다. 델라스 문팽의 과거가 그녀의 발목을 잡았다. 조상의 저주가 그녀의 가문을 위협한 것이다. 저주를 깨뜨리고 네루스 문팽을 고통에서 해방시켜, 기사단의 또 다른 용사를 얻었다. 해변이 확보되자, 그레이슨 섀도브레이커 경은 전설적인 대장간인 달라란의 망치로 길을 안내했다. 그곳에서 알라드 슈미트가 대영주에 걸맞은 갑옷을 만들었다. 도시 아래의 그림자 속에서는 황금 군마가 기다리고 있었고, 그 군마에 올라 빛 속으로 달려 나갔다."
L["On the Broken Shore, rescue Kanrethad Ebonlocke from imprisonment and earn the Netherlord's Chaotic Wrathsteed."] = "부서진 해변에서 칸레타드 에본로크를 감금에서 구출하고 황천군주의 혼돈 격노군마를 얻으십시오."
L["On the Broken Shore, the Legion had corrupted wild beasts into felbound monstrosities. Shandris Feathermoon coordinated the assault while Nighthuntress Syrenne led you deep into enemy territory to soothe the wounded creatures and strike at the source of the corruption. When the Broken Shore was secured, you answered a final call — the Night of the Wilds, where a wolfhawk tested your worth as a hunter. It found you worthy, and pledged its loyalty to the Huntmaster."] = "부서진 해변에서 군단은 야생 짐승들을 타락시켜 지옥에 속박된 괴물로 만들었다. 샨드리스 페더문이 공격을 지휘하는 동안, 밤사냥꾼 시렌느는 적진 깊숙이 길을 이끌어 상처 입은 짐승들을 달래고 타락의 근원을 공격하게 했다. 부서진 해변이 확보되자 마지막 부름에 응했다. 야생의 밤, 그곳에서 늑대매 한 마리가 사냥꾼으로서의 자격을 시험했다. 늑대매는 자격을 인정했고, 사냥꾼 대가에게 충성을 맹세했다."
