L["Orders are Orders"] = "까라면 까야지"
L["Orgrim's Hammer"] = "오그림의 망치호"
L["Orgrim's Hammer is Warchief Garrosh's answer to the Skybreaker — a Horde gunship with a bone to pick. Sky-Reaver Korm Blackscar runs the deck. Sky-Commander Ichman flies the line. Brother Keltan blesses the cannons. The first sortie drops into Ymirheim, where the Scourge mines its saronite. The second swings west to the Broken Front, where a Horde column was hit broadside and left scattered. After that comes the grind: Poke and Prod, Against the Giants, Coprous the Defiled, the goblin Nargle Lashcord and his Fringe Engineer Tezzla. Farther west, past the Valley of Lost Hope, Koltira Deathweaver pries the Desolation Gate open with bent Scourge gear and colder patience. By the time Orgrim's Hammer swings east, the Guardians of Corp'rethar are already bleeding."] = "오그림의 망치호는 하늘파괴자호에 맞선 대족장 가로쉬의 답이다. 앙갚음을 벼르는 호드의 비행포함이다. 갑판은 하늘약탈자 코름 블랙스카가 맡고 있다. 하늘사령관 이크만은 전선의 비행을 지휘한다. 수사 켈탄은 대포에 축복을 내린다. 첫 출격은 스컬지가 사로나이트를 캐는 이미르하임으로 내려간다. 두 번째 출격은 서쪽의 부서진 전선으로 향한다. 그곳에서는 호드 행렬이 측면을 강타당해 흩어져 있다. 그다음은 고된 싸움의 연속이다. ‘적을 알아내는 법’, ‘거인에 맞서라!’, ‘타락자 코프루스’, 그리고 고블린 나글 래시코드와 그의 괴짜 기술자 테즐라. 더 서쪽, 잃어버린 희망의 골짜기 너머에서는 콜티라 데스위버가 구부러진 스컬지 장비와 더 차가운 인내심으로 황폐의 관문을 비틀어 연다. 오그림의 망치호가 동쪽으로 선회할 무렵, 코프레사르의 수호자들은 이미 피를 흘리고 있다."
