L["Pandaren heritage lives in stories carried by many voices. Through festival rites, old memories, and shared traditions, you helped weave those voices into a new legacy."] = "판다렌의 유산은 수많은 목소리가 전하는 이야기 속에 살아 있다. 축제 의식과 오랜 기억, 함께 나눈 전통을 통해 그 목소리들을 엮어 새로운 유산을 만드는 데 힘을 보탰다."
L["Pandaria / Wandering Isle"] = "판다리아 / 유랑도"
L["Panic at the Brewery"] = "공포의 양조장"
L["Parting Gifts"] = "작별의 선물"
L["Parqual Fintallas"] = "파쿠알 핀탈라스"
L["Dorn Plainstalker"] = "도른 플레인스토커"
L["Past the Argent line, the Ebon Blade works in cruder tools. Uzo Deathcaller keeps a pen of vrykul prisoners the Crusade cannot know about. Bragi the Mad waits at Jotunheim with a grudge, a list of vargul he wants back, and an increasingly unhinged plan for their recovery. The Bone Witch sells her favors in bones. And at Valhalas, the vrykul hold court for the worthy dead — which means admission, for the right kind of monster, can be earned. Read the bones. Kill the water terror. Find the ancient hero. Win the challenge rounds. Put on their skin. Walk out over their corpses. By the time the hall goes quiet, the Ebon Blade has one last errand — a banshee's revenge, and a Duke who needs his competition eliminated."] = "은빛십자군의 전선 너머에서, 칠흑의 기사단은 더 거친 수단을 쓴다. 우조 데스콜러는 십자군이 알아서는 안 될 브리쿨 포로들의 우리를 관리한다. 미치광이 브라기는 원한과 되찾고 싶은 바르굴의 명단, 그리고 점점 더 정신 나간 회수 계획을 품고 요툰하임에서 기다린다. 해골 마녀는 뼈를 대가로 호의를 판다. 그리고 발할라스에서는 브리쿨이 자격 있는 망자들을 위한 자리를 마련한다. 다시 말해, 적당한 부류의 괴물이라면 입장 자격을 얻어 낼 수도 있다는 뜻이다. 뼈를 읽어라. 물속의 공포를 처치하라. 고대 영웅을 찾아라. 도전 시합에서 승리하라. 그들의 가죽을 뒤집어써라. 그들의 시체를 밟고 걸어 나와라. 전당이 잠잠해질 무렵, 칠흑의 기사단에게는 마지막 심부름이 남아 있다. 밴시의 복수, 그리고 경쟁자를 제거해야 하는 한 공작."
L["Patch"] = "패치"
L["Patch rallied the assault force at Bloodfire Ravine. Talanji stood at the front. The loa — Krag'wa, what remained of Bwonsamdi's power, even the memory of Torga — were with you. The blood trolls had held the Blood Gate as the last barrier between Nazmir and the heart of their god's prison. You blew through their defenses, toppled their totems, and drove a path of fire through their strongest ranks. Grand Ma'da Ateena fell. In the silence after, Titan Keeper Hezrel delivered the final revelation: G'huun still breathed beneath the earth. Nazmir had been reclaimed — but the blood god's prison was cracking. The raid on Uldir was no longer optional."] = "패치가 핏빛불꽃 협곡에 공격대를 집결시켰다. 탈란지가 선두에 섰다. 로아들도 함께였다. 크라그와, 남아 있는 브원삼디의 힘, 토르가에 대한 기억마저도. 피의 트롤들은 나즈미르와 그들의 신이 갇힌 감옥의 심장부 사이를 가로막는 마지막 장벽, 피의 관문을 지키고 있었다. 그들의 방어선을 날려 버리고, 토템을 쓰러뜨리고, 가장 강한 대열을 불길로 꿰뚫었다. 큰마마 아티나가 쓰러졌다. 뒤이은 정적 속에서, 티탄 수호자 헤즈렐이 마지막 진실을 전했다. 그훈은 여전히 땅 아래에서 숨 쉬고 있었다. 나즈미르는 되찾았지만, 피의 신을 가둔 감옥에는 금이 가고 있었다. 이제 울디르 공격은 선택이 아니었다."
