L["Princess Tess Greymane guided you through a web of coded messages and hidden vaults to recover the Kingslayers — Garona's legendary daggers, stained with the blood of a king. You infiltrated a Stormwind prison, broke codes, and retrieved the blades from their resting place, returning them to the hands of an assassin who knew their weight better than anyone."] = "공주 테스 그레이메인의 안내를 받아 암호문과 숨겨진 금고의 미로를 헤치며 왕 시해자를 되찾았다. 왕의 피로 얼룩진 가로나의 전설적인 단검이었다. 스톰윈드 감옥에 잠입하고, 암호를 풀고, 잠들어 있던 단검을 되찾아 그 무게를 누구보다 잘 아는 암살자의 손에 되돌려 놓았다."
L["Priorities!"] = "우선순위!"
L["Priscilla Ashvane has been quietly dismantling the Proudmoore Admiralty from within — bribing officials, sabotaging trade, and positioning herself to absorb the family's political legacy while Katherine grieves her son Derek and her estrangement from Jaina. Unraveling the conspiracy takes you across Tiragarde Sound, from Boralus's counting houses to Ashvane prison cells, until the truth lands at Genn Greymane's feet in Boralus Harbor."] = "프리실라 애쉬베인은 안에서부터 프라우드무어 해군을 조용히 해체해 왔습니다. 관리들을 매수하고, 무역을 방해하고, 캐서린이 아들 데릭을 잃은 슬픔과 제이나와의 불화에 잠겨 있는 동안 가문의 정치적 유산을 집어삼킬 준비를 해 온 것입니다. 음모를 파헤치는 여정은 보랄러스의 회계소에서 애쉬베인의 감옥까지 티라가드 해협 곳곳으로 이어지며, 마침내 진실은 보랄러스 항구에 있는 겐 그레이메인의 발치에 이르게 됩니다."
L["Prisoner of Interest"] = "위험한 죄수"
