L["Prowler Problems"] = "골칫덩이 호랑이들"
L["Pruning the Garden"] = "정원 손질"
L["Purge the Unclean"] = "불순물 정화"
L["Pushing through the farmlands around Deathknell, you clashed with the Scarlet Crusade at their palisade. Inside the fortifications you found Lilian — captured by the zealots she once served. Her captors didn't care that she had been one of them. To the Crusade, she was just another undead abomination to be purged."] = "죽음의 종소리 마을 주변의 농지를 헤치고 나아가 방책에서 붉은십자군과 맞붙었다. 요새 안에서 발견한 릴리안은 한때 자신이 섬기던 광신자들에게 붙잡혀 있었다. 그녀를 붙잡은 자들은 그녀가 한때 동료였다는 사실 따위는 신경 쓰지 않았다. 십자군에게 그녀는 정화해야 할 또 하나의 언데드 괴물일 뿐이었다."
L["Put on vrykul skin, fight through Valhalas's trials, and pay a Bone Witch's debt in blood."] = "브리쿨의 가죽을 뒤집어쓰고 발할라스의 시험을 헤쳐 나간 뒤, 해골 마녀의 빚을 피로 갚으십시오."
L["Put the Royal Apothecary Society's new weapon through its paces."] = "왕실 약제사 협회의 신무기를 시험해 보십시오."
