L["Rebuilding the Order"] = "연맹 재건"
L["Recharging the Blade"] = "성검 재충전하기"
L["Recover Felo'melorn, the Flamestrike — the ancient blade of the Sunstrider dynasty, lost in the frozen halls of Icecrown."] = "얼음왕관의 얼어붙은 전당에서 잃어버린 선스트라이더 왕조의 고대 검, 불기둥 펠로멜로른을 되찾으십시오."
L["Recover Light's Wrath, a staff of terrible holy power sealed away in the Nexus Vault because it was too dangerous to wield."] = "휘두르기엔 너무 위험해 마력의 금고에 봉인된, 무시무시한 신성한 힘을 지닌 지팡이 빛의 격노를 되찾으십시오."
L["Recover lost tradition, confront painful history, and stand against lingering eredar corruption."] = "잃어버린 전통을 되찾고, 고통스러운 역사와 마주하며, 남아 있는 에레다르의 타락에 맞서십시오."
L["Recover Natalie Seline, a priest who delved too deep into the Void, from the shadow realm where she has been lost."] = "공허 속으로 너무 깊이 파고들었던 사제 나탈리 세린을, 그녀가 길을 잃은 어둠의 영역에서 구해 내십시오."
L["Recover Sheilun, the staff of Emperor Shaohao, who shrouded Pandaria in mist for ten thousand years."] = "만 년 동안 판다리아를 안개로 감쌌던 황제 샤오하오의 지팡이 셰이룬을 되찾으십시오."
L["Recover the ancient bow of the Windrunner family, lost when Alleria Windrunner vanished beyond the Dark Portal."] = "알레리아 윈드러너가 어둠의 문 너머로 사라지면서 함께 잃어버린 윈드러너 가문의 고대 활을 되찾으십시오."
L["Recover the Claws of Ursoc, the great bear god's weapons, from the nightmares that have claimed them."] = "위대한 곰의 신의 무기인 우르속의 발톱을 그것을 집어삼킨 악몽에서 되찾으십시오."
L["Recover the Maw of the Damned, a vampiric axe that drains the life from its victims to sustain its wielder."] = "희생자의 생명력을 빨아들여 주인을 지탱하는 흡혈 도끼, 저주받은 자의 아귀를 되찾으십시오."
L["Recover the Silver Hand, the holy mace of the original paladins, lost since the founding of the order."] = "기사단이 창설된 이래 자취를 감춘, 최초의 성기사들이 쓰던 신성한 철퇴 은빛 손을 되찾으십시오."
L["Recover the Skull of the Man'ari, a demonic focus of immense summoning power used by the eredar lords."] = "에레다르 군주들이 사용하던, 엄청난 소환의 힘을 지닌 악마의 매개체 만아리의 해골을 되찾으십시오."
L["Recover, restore, and reforge an ancient Bronzebeard relic."] = "고대 브론즈비어드 유물을 되찾고, 복원하고, 다시 벼려 내십시오."
L["Recovering Remnants"] = "파편 복원"
L["Recruit Archmage Kalec and Archmage Modera as champions. Build the Tirisgarde's forces and establish operations."] = "대마법사 칼렉과 대마법사 모데라를 용사로 영입하십시오. 티리스가드의 병력을 갖추고 작전 기반을 마련하십시오."
L["Recruit the first champions of the Unseen Path and send troops into the field across the Broken Isles."] = "보이지 않는 길의 첫 용사들을 영입하고, 부서진 섬 곳곳으로 부대를 파견하십시오."
