L["Renathal gathered the Harvesters and turned Sinfall's mirrors against Castle Nathria. Light cut across the ramparts, loyalists scattered, and the rebellion surged toward Denathrius. Then the Master stopped pretending. He had not failed to save the Shadowlands from the anima drought — he had helped cause it, hoarding the realm's lifeblood and pouring it into the Maw for the Jailer. Revendreth's gothic theater became something far larger and worse: the first clear proof that the machinery of Death itself had been betrayed. Denathrius retreated into Castle Nathria, and the fight for the Shadowlands changed forever."] = "레나탈이 수확자들을 규합하고 죄악의 몰락지의 거울들을 나스리아 성채로 돌렸다. 빛이 성벽을 가르자 충성파는 흩어졌고, 반란군은 데나트리우스를 향해 몰려들었다. 그러자 주인은 더 이상 가면을 쓰지 않았다. 그는 어둠땅을 령 가뭄에서 구하지 못한 것이 아니었다. 오히려 가뭄을 일으키는 데 가담했다. 이 영역의 생명줄을 쌓아 두었다가 간수를 위해 나락으로 쏟아부은 것이다. 레벤드레스의 고딕풍 연극은 훨씬 더 거대하고 끔찍한 무언가가 되었다. 죽음의 체계 그 자체가 배신당했다는 첫 번째 명백한 증거였다. 데나트리우스는 나스리아 성채로 물러났고, 어둠땅을 위한 싸움은 영원히 달라졌다."
L["Renathal's rebellion marches on Castle Nathria. Denathrius reveals the truth: Revendreth's stolen anima is being sent into the Maw."] = "레나탈의 반란군이 나스리아 성채로 진격합니다. 데나트리우스가 진실을 밝힙니다. 레벤드레스에서 훔친 령이 나락으로 보내지고 있었던 것입니다."
L["Rendezvous with the Courier"] = "급사와의 만남"
L["Rendezvous with the Libation"] = "신의 약주호와의 만남"
L["Rendle"] = "렌들"
L["Rensar Greathoof"] = "렌사르 그레이트후프"
L["Report from Tian Monastery"] = "티엔 수도원의 소식"
L["Repurposing Their Village"] = "마을 개조"
L["Requesting Reinforcements"] = "지원 요청"
L["Requires completing all three Kul Tiras zone storylines (Tiragarde Sound, Drustvar, and Stormsong Valley). Speak to Cyrus Crestfall in Boralus to begin. This chapter includes four dungeon quests: Tol Dagor, Shrine of the Storm, Waycrest Manor, and Siege of Boralus."] = "쿨 티라스 지역 이야기 세 개(티라가드 해협, 드러스트바, 스톰송 계곡)를 모두 완료해야 합니다. 보랄러스에서 사이러스 크레스트폴과 대화하여 시작하십시오. 이 장에는 톨 다고르, 폭풍의 사원, 웨이크레스트 저택, 보랄러스 공성전의 던전 퀘스트 네 개가 포함되어 있습니다."
L["Requires completing the Tiragarde Sound main storyline (\"Trouble in Tiragarde Sound\"). Begin with the Ashvane Trading Company investigation in Boralus."] = "티라가드 해협 주요 이야기(‘티라가드 해협의 분쟁’)를 완료해야 합니다. 보랄러스에서 애쉬베인 무역회사 조사부터 시작하십시오."
L["Rescue a brilliant arcanist trapped by withered nightfallen and secure his knowledge for the growing rebellion."] = "메마른 자들에게 갇힌 뛰어난 비전술사를 구출하고, 커져 가는 반란을 위해 그의 지식을 확보하십시오."
L["Rescue a captive High Chief and bring a new people into the Horde."] = "붙잡힌 대추장을 구출하고 새로운 종족을 호드로 맞아들이십시오."
L["Rescue Koltira Deathweaver from imprisonment and forge deathchargers worthy of the Four Horsemen."] = "콜티라 데스위버를 감금에서 구출하고 4기사에 걸맞은 죽음의 군마를 벼려 내십시오."
L["Rescue monks captured by the vrykul in Stormheim. Recruit Angus Ironfist, Hiro, and Sylara Steelsong as champions."] = "스톰하임에서 브리쿨에게 붙잡힌 수도사들을 구출하십시오. 앵거스 아이언피스트, 히로, 실라라 스틸송을 용사로 영입하십시오."
L["Residual Fallout"] = "잔류물 낙진"
L["Resisting Arrest"] = "억압에 저항하기"
L["Resource Management"] = "크발디르 활용하기"
L["Rest in Peace"] = "평화롭게 잠드시오"
L["Restoring Equilibrium"] = "균형 복원"
L["Restoring Jade's Purity"] = "비취의 순수함을 지켜라"
L["Retaliation"] = "복수"
L["Retest Now"] = "재실험"
L["Retrace the Scourge invasion and witness the memories that shaped the blood elves."] = "스컬지 침공의 발자취를 되짚어 블러드 엘프를 만들어 낸 기억들을 목격하십시오."
