L["Return to the Black Temple to confront echoes of the past and secure reinforcements from Illidan's former stronghold."] = "검은 사원으로 돌아가 과거의 메아리와 맞서고, 일리단의 옛 요새에서 지원군을 확보하십시오."
L["Return to the Chamber of Shadows"] = "그림자의 방으로"
L["Return to the Echo Isles"] = "메아리 섬 귀환"
L["Return to the Echo Isles where the Darkspear first made landfall in exile, and listen for loa whose voices have grown quieter since the tribe took its place inside the Horde. The new generation has forgotten more than it realizes.\n\nSeek the loa where they still answer, perform the rites where they are still owed, and remember the Darkspear as a people with roots deeper than any banner."] = "검은창 부족이 유배 끝에 처음 발을 디뎠던 메아리 섬으로 돌아가, 부족이 호드의 일원이 된 이후 목소리가 점점 희미해진 로아들에게 귀를 기울이십시오. 새로운 세대는 스스로 아는 것보다 더 많은 것을 잊어버렸습니다.\n\n아직 응답하는 로아를 찾고, 아직 치러야 할 의식을 거행하며, 검은창이 그 어떤 깃발보다 깊은 뿌리를 지닌 부족임을 기억하십시오."
L["Return to the Firelands"] = "다시 불의 땅으로"
L["Return to the Harbor"] = "항구로 귀환"
L["Return to the Surface"] = "지상으로 돌아가기"
L["Revendreth"] = "레벤드레스"
L["Revendreth is a gothic realm of sinstones, vampire courts, and ritual penance: the place where prideful souls are meant to be broken open, judged, and remade. Sent to seek anima for the starving Shadowlands, you arrive in a kingdom that is already fraying.\n\nPrince Renathal and the Court of Harvesters are gathering resistance, Sire Denathrius still rules from above, and every misted street carries another rumor about where Revendreth's loyalty truly lies."] = "레벤드레스는 죄악석과 흡혈귀 궁정, 의례적인 속죄로 이루어진 고딕풍의 영역입니다. 오만한 영혼들이 부서지고, 심판받고, 다시 빚어지는 곳입니다. 굶주린 어둠땅을 위해 령을 구하라는 임무를 받고 도착한 곳은 이미 무너져 가는 왕국입니다.\n\n왕자 레나탈과 수확자의 궁정은 저항 세력을 모으고 있고, 대영주 데나트리우스는 여전히 높은 곳에서 군림하며, 안개 낀 거리마다 레벤드레스의 충성이 진정 어디를 향하는지에 대한 소문이 떠돕니다."
L["Revenge for the Vargul"] = "바르굴 대신 복수를!"
L["Revenge, Served Cold"] = "피도 눈물도 없이"
L["Revenge: Served Hot"] = "뜨거운 복수"
L["Revered"] = "매우 우호적"
L["Reversal"] = "반전"
L["Revive old rites and prove yourself to the spirit of orcish tradition."] = "옛 의식을 되살리고 오크 전통의 혼 앞에 자신을 증명하십시오."
L["Reviving Tradition"] = "전통의 부활"
L["Rexxar"] = "렉사르"
L["Ride the Alliance gunship from Ymirheim to the Broken Front to the Desolation Gate."] = "얼라이언스 비행포함에 올라 이미르하임에서 부서진 전선을 거쳐 황폐의 관문까지 향하십시오."
L["Ride the Horde gunship from Ymirheim to the Broken Front to the Desolation Gate."] = "호드 비행포함에 올라 이미르하임에서 부서진 전선을 거쳐 황폐의 관문까지 향하십시오."
L["Ride to Wyrmrest Temple and kneel before Alexstrasza, the Life-Binder."] = "고룡쉼터 사원으로 가서 생명의 어머니 알렉스트라자 앞에 무릎을 꿇으십시오."
L["Riding the Wavelength: The Bombardment"] = "파장을 타고: 폭격"
L["Righting Wrongs"] = "잘못 바로잡기"
L["Riko"] = "리코"
L["Rise Up"] = "올라가기"
L["Rise, Champions"] = "일어나라, 용사들이여"
L["Rise, Forsaken"] = "일어나라, 포세이큰"
L["Rise, Godfrey"] = "일어나라, 고드프리"
L["Rising Shadows"] = "어둠의 부활"
L["Rising Troubles"] = "되살아난 골칫거리"
L["Ritssyn Flamescowl"] = "릿신 플레임스카울"
L["Ritssyn Flamescowl appeared in Dalaran with a proposition — the Council of the Black Harvest needed a sixth member, and you had been chosen. The Council operated from Dreadscar Rift, a pocket of the Twisting Nether they had ripped from demonic control and claimed as their own. You proved your worth, claimed an artifact weapon steeped in dark power, and took your seat on the Council. Calydus — a demon bound to serve the warlocks — helped establish the Rift as your base of operations."] = "릿신 플레임스카울이 달라란에 나타나 제안을 건넸다. 검은 수확 의회에 여섯 번째 일원이 필요한데, 그 자리에 선택되었다는 것이었다. 의회는 공포흉터 균열을 본거지로 삼고 있었다. 뒤틀린 황천의 한 조각을 악마의 손아귀에서 빼앗아 자신들의 것으로 만든 곳이었다. 자격을 증명하고, 어둠의 힘에 흠뻑 젖은 유물 무기를 손에 넣고, 의회의 자리에 앉았다. 흑마법사를 섬기도록 속박된 악마 칼리두스가 균열을 작전 기지로 꾸리는 일을 도왔다."
L["Ritssyn Flamescowl needs a sixth member for the Council of the Black Harvest. You are chosen — but the seat comes with a price."] = "릿신 플레임스카울은 검은 수확 의회의 여섯 번째 일원을 찾고 있습니다. 그 자리에 선택되었지만, 거기에는 대가가 따릅니다."
L["Ritual Artifacts"] = "의식의 유물"
L["Ritual Effects"] = "의식의 준비물"
L["Ritual Reagents"] = "의식에 필요한 재료"
L["Ritual Recovery"] = "의식 복구"
L["Rivett Clutchpop"] = "리벳 클러치팝"
L["Road Rations"] = "전투 식량 준비"
L["Rokhan"] = "로칸"
L["Rokhan led you into Gloom Hollow, where the ancient frog loa Krag'wa brooded in the dark. The blood trolls had massacred his followers and desecrated his totems, and Krag'wa was in no mood for diplomacy. You hunted the hunters who had slaughtered his priests, restored his shrines, and prepared the kind of feast that only a frog loa the size of a temple could appreciate. Krag'wa was pleased. He was also terrifying. The agreement was simple enough: he would fight with the Horde against the blood trolls and G'huun. In Gloom Hollow, that counted as a warm welcome."] = "로칸의 안내로 들어선 어두운 공동에서는 고대의 개구리 로아 크라그와가 어둠 속에서 생각에 잠겨 있었다. 피의 트롤이 그의 추종자들을 학살하고 토템을 더럽혔으니, 크라그와는 외교를 논할 기분이 아니었다. 그의 사제들을 도륙한 사냥꾼들을 사냥하고, 제단을 복원하고, 사원만 한 개구리 로아나 즐길 법한 성찬을 준비했다. 크라그와는 흡족해했다. 동시에 무시무시했다. 합의는 간단했다. 그가 호드와 함께 피의 트롤과 그훈에 맞서 싸우겠다는 것이었다. 어두운 공동에서는 그 정도면 따뜻한 환대였다."
L["Rotten Old Memories"] = "썩어버린 옛 추억"
L["Ruinous Rituals"] = "파멸의 의식"
L["Ruins of Lordaeron"] = "로데론의 폐허"
L["Rumor Has It"] = "소문은 꼬리를 물고"
L["Rune Ruination"] = "룬 파괴"
L["Runic Resistance"] = "룬의 수수께끼"
