L["Saronite Mines"] = "사로나이트 광산"
L["Sassy Hardwrench"] = "새시 하드렌치"
L["Saurfang is gone. Nathanos Blightcaller has been dispatched to find him — and bring him back before he becomes a problem."] = "사울팽이 사라졌습니다. 나타노스 블라이트콜러가 그를 찾아, 골칫거리가 되기 전에 데려오라는 명을 받았습니다."
L["Saurfang leads the charge on the gate to the Lich King's domain."] = "사울팽이 리치 왕의 영역으로 향하는 관문에 돌격을 이끕니다."
L["Saurfang leads the Horde up the spiral of Wyrmrest to bargain with the Dragon Queen."] = "사울팽이 호드를 이끌고 고룡쉼터의 나선형 길을 올라 용의 여왕과 협상에 나섭니다."
L["Saurfang the Younger"] = "사울팽의 아들"
L["Saurfang the Younger calls you to the Kor'kron Vanguard. The Taunka are blood-sworn, the Nerubians silenced, and the Forsaken have their weapons. The old Orc himself takes you to Wyrmrest Temple — to kneel, or rather to bargain, before Alexstrasza the Life-Binder. The dragons remember every Horde blade that ever flashed in anger at the Second War. Whether they answer the Warchief's call is another matter."] = "사울팽의 아들이 코르크론 선봉기지로 부른다. 타운카는 피의 맹세를 마쳤고, 네루비안은 잠잠해졌으며, 포세이큰은 무기를 손에 넣었다. 이제 늙은 오크가 직접 고룡쉼터 사원으로 데려간다. 생명의 어머니 알렉스트라자 앞에 무릎을 꿇기 위해, 아니, 협상을 하기 위해. 용들은 제2차 대전쟁 때 분노에 차 번뜩였던 호드의 칼날 하나하나를 모두 기억한다. 그들이 대족장의 부름에 응할지는 또 다른 문제다."
L["Saurfang's last act before the gate was a summons sent to every Horde leader still standing. By the time the crowd outside Orgrimmar thinned and the silence settled in, they were already gathering: Baine, Lor'themar, Ji Firepaw, and Lilian Voss, who now spoke for a Forsaken people their former Warchief had used as weapons and discarded. In the middle of it, Lilian stepped away from the main hall to broker a quieter conversation — one that had to happen before anything else could move: Forsaken leadership, face to face with Calia Menethil and Derek Proudmoore. Hidden, necessary, and hers to arrange. Then the full council assembled. The Warchief's throne was empty. Lilian made the case for leaving it that way. No single voice, no single will — a council, the way the Horde had always needed to work but never quite managed. The others listened. Then they agreed."] = "관문으로 향하기 전, 사울팽이 마지막으로 한 일은 아직 살아 있는 모든 호드 지도자에게 소집령을 보내는 것이었다. 오그리마 밖의 군중이 흩어지고 정적이 내려앉을 무렵, 그들은 이미 모여들고 있었다. 바인, 로르테마르, 지 파이어포우, 그리고 릴리안 보스. 릴리안은 이제 옛 대족장이 무기로 쓰다 버린 포세이큰을 대변하고 있었다. 그 와중에 릴리안은 본회의장에서 물러나 조용한 대화를 주선했다. 다른 무엇보다 먼저 이루어져야 할 대화, 포세이큰의 지도부가 칼리아 메네실, 데릭 프라우드무어와 직접 마주하는 자리였다. 은밀하고, 필요하며, 그녀가 마련해야 할 일이었다. 그런 다음 전체 회의가 열렸다. 대족장의 왕좌는 비어 있었다. 릴리안은 그 자리를 그대로 비워 두자고 주장했다. 하나의 목소리도, 하나의 의지도 아닌 의회. 호드가 언제나 그래야 했지만 끝내 이루지 못했던 방식이었다. 다른 이들은 귀를 기울였다. 그리고 동의했다."
