L["Scouting reports painted a grim picture — Legion assassins had infiltrated the Broken Isles, targeting the Unseen Path's agents. You tracked them through Stormheim, rescuing Hudson Crawford from an ambush and calling Beastmaster Hilaire home from the wilds. In Highmountain, you found Rexxar living among the beasts and convinced the legendary hunter to join your cause. With new champions at your side, the Unseen Path's eyes grew sharper."] = "정찰 보고는 암울한 상황을 전했다. 군단의 암살자들이 부서진 섬에 잠입해 보이지 않는 길의 요원들을 노리고 있었다. 스톰하임을 가로질러 그들을 추적하며, 매복에 걸린 허드슨 크로포드를 구하고 야생에 나가 있던 야수조련사 힐라이르를 불러들였다. 높은산에서는 짐승들 사이에서 살아가던 렉사르를 찾아내, 전설적인 사냥꾼을 설득해 대의에 합류시켰다. 새로운 용사들이 곁에 서자, 보이지 않는 길의 눈은 더욱 날카로워졌다."
L["Scouting reports reveal Legion assassins targeting the Unseen Path. Track them across Stormheim while recruiting Rexxar and Hilaire."] = "정찰 보고에 따르면 군단의 암살자들이 보이지 않는 길을 노리고 있습니다. 렉사르와 힐라이르를 영입하면서 스톰하임 전역에서 그들을 추적하십시오."
