L["Seek aid from the night elves and blood elves, bridging ten thousand years of division for a common cause."] = "나이트 엘프와 블러드 엘프에게 도움을 구해, 만 년에 걸친 분열을 넘어 공동의 대의 아래 하나가 되게 하십시오."
L["Seek Fu Zan, a legendary staff carried by monks across the ages, now lost in the wilds."] = "오랜 세월 수도사들이 지니고 다녔으나 지금은 야생 어딘가에서 자취를 감춘 전설의 지팡이, 푸 잔을 찾으십시오."
L["Seek out a shield forged from a scale of Neltharion himself, hidden deep within the mountains where the earth remembers."] = "대지가 기억하는 산맥 깊숙한 곳에 숨겨진, 넬타리온의 비늘로 벼려 낸 방패를 찾으십시오."
L["Seek out Aegira, a vrykul brewmaster in the Halls of Valor, and brew the legendary Storm Brew to empower your forces."] = "용맹의 전당에 있는 브리쿨 양조사 아이기라를 찾아가, 아군에게 힘을 불어넣을 전설의 폭풍주를 빚으십시오."
L["Seek Out the Lorewalker"] = "전승지기를 찾아서"
L["Seek T'uure, a crystal beacon forged by the naaru, whose light has guided the faithful through the darkest ages."] = "가장 어두운 시대에도 신실한 자들을 인도해 온 빛, 나루가 벼려 낸 수정 신호기 투레를 찾으십시오."
L["Seek the Aldrachi Warblades, weapons of a race that defeated a demon lord and chose death over servitude."] = "악마 군주를 물리치고 굴종 대신 죽음을 택한 종족의 무기, 알드라키 전쟁검을 찾으십시오."
L["Seek the ancient eagle spear Talonclaw in the peaks of Highmountain, a weapon sacred to the hunters of old."] = "옛 사냥꾼들에게 신성한 무기였던 고대의 독수리 창 갈퀴발톱을 높은산의 봉우리에서 찾으십시오."
L["Seek the Fist of Ra-den, a weapon forged by the titan keeper who tamed the storms of Azeroth."] = "아제로스의 폭풍을 길들인 티탄 수호자가 벼려 낸 무기, 라덴의 주먹을 찾으십시오."
L["Seek the Scythe of Elune, a weapon of terrible power tied to the worgen curse and the moon goddess herself."] = "늑대인간의 저주, 그리고 달의 여신과 깊이 얽힌 무시무시한 힘의 무기, 엘룬의 낫을 찾으십시오."
L["Seek the staff of the Guardian Aegwynn — Aluneth, a weapon of pure arcane power that has a mind of its own."] = "수호자 에이그윈의 지팡이를 찾으십시오. 스스로 생각하는 순수한 비전의 무기, 알루네스입니다."
L["Seek the Unsavory"] = "불미스러운 사건"
L["Seek Truthguard, a titan-forged shield that protects the worthy and strikes down the false."] = "자격 있는 자를 지키고 거짓된 자를 쓰러뜨리는, 티탄이 벼려 낸 방패 진실의 수호자를 찾으십시오."
L["Seek Ulthalesh, a scythe that reaps souls from the living and binds them in eternal torment."] = "산 자의 영혼을 거두어 영원한 고통 속에 속박하는 낫, 울살레시를 찾으십시오."
