L["Sinfall gave the rebels a foothold, but they still needed their prince. In the ruins of his first rebellion, you found what Denathrius had left behind: cages, broken allies, and Renathal himself, imprisoned as an example. With Theotar, the Accuser, and General Draven at your side, you tore open the prison, stole the key, and pulled Renathal back from Torghast's shadow. The prince returned humbled but unbroken. He had lost a rebellion once. This time, he would not stand alone."] = "죄악의 몰락지는 반란군에게 발판이 되어 주었지만, 그들에게는 여전히 왕자가 필요했다. 그의 첫 번째 반란이 남긴 폐허에서, 데나트리우스가 남겨 둔 것들을 발견했다. 우리, 부서진 동료들, 그리고 본보기로 갇혀 있는 레나탈. 테오타르, 규탄자, 장군 드레이븐과 함께 감옥을 부수고, 열쇠를 훔치고, 토르가스트의 그림자에서 레나탈을 다시 끌어냈다. 왕자는 겸허해졌지만 꺾이지 않은 채 돌아왔다. 그는 한 번 반란에 실패했다. 이번에는 혼자가 아닐 것이다."
L["Sinstone Delivery"] = "죄악석 시키신 분"
L["Siouxsie the Banshee"] = "밴시 시우크시"
L["Sire Denathrius"] = "대영주 데나트리우스"
L["Sire Denathrius pointed you at the Accuser, one of the Harvesters standing against him. Lord Chamberlain's hunt was brutal and theatrical: tear through her followers, read the sinstones of her inquisitors, and use those names to drag the guilty into judgment. But the deeper you went, the less clean the story became. The Accuser had punished pride for ages, and she understood what Denathrius's court had become. When her own secret was revealed, it was not simple innocence that saved her — it was the terrible truth that Revendreth's ruler had turned repentance into control."] = "대영주 데나트리우스는 자신에게 맞서는 수확자 중 하나인 규탄자를 쫓으라고 했다. 시종장의 사냥은 잔인하고도 연극적이었다. 그녀의 추종자들을 쓸어버리고, 그녀의 심문관들의 죄악석을 읽고, 그 이름들로 죄인들을 심판대에 끌어내는 것. 하지만 깊이 파고들수록 이야기는 점점 단순하지 않게 되었다. 규탄자는 오랜 세월 오만을 벌해 왔고, 데나트리우스의 궁정이 무엇으로 변했는지 알고 있었다. 그녀 자신의 비밀이 드러났을 때 그녀를 구한 것은 단순한 결백이 아니었다. 레벤드레스의 통치자가 참회를 지배의 도구로 바꾸어 놓았다는 끔찍한 진실이었다."
L["Skull of the Man'ari"] = "만아리의 해골"
