L["Snowfeather, a majestic eagle, arrived in Dalaran bearing an urgent summons. You followed the bird to Trueshot Lodge high in the mountains, where Emmarel Shadewarden revealed the Unseen Path — a secret order of hunters that had watched over Azeroth for generations. You swore the Oath of Service, claimed a weapon of legend, and took your place among their ranks."] = "위풍당당한 독수리 흰깃이 긴급한 소환장을 들고 달라란에 날아왔다. 새를 따라 산 높은 곳의 정조준 오두막에 이르자, 에마렐 셰이드워든이 보이지 않는 길의 존재를 밝혔다. 여러 세대에 걸쳐 아제로스를 지켜 온 사냥꾼들의 비밀 결사였다. 봉사의 서약을 맹세하고, 전설의 무기를 손에 넣고, 그들의 일원으로 자리를 잡았다."
L["So Long, Sister"] = "자매여, 편히 쉬길"
L["Some Knowledge Shouldn't Be Shared"] = "모르는 게 약"
