L["Something broke inside Lilian Voss. Shadow magic erupted from her hands as she tore through the crusaders with a fury that terrified even the Forsaken. She marched to the tower where her father, High Priest Benedictus Voss, waited — and when he condemned her as a monster, she killed him. Then she vanished, leaving nothing but silence and the smell of burning."] = "릴리안 보스의 내면에서 무언가가 무너졌다. 그녀의 손에서 암흑 마법이 터져 나왔고, 포세이큰조차 두려워할 만큼의 분노로 십자군을 찢어발겼다. 그녀는 아버지 대사제 베네딕투스 보스가 기다리는 탑으로 향했다. 그리고 그가 그녀를 괴물이라 단죄하자, 그녀는 그를 죽였다. 그 뒤 그녀는 자취를 감췄다. 남은 것은 침묵과 무언가 타는 냄새뿐이었다."
L["Something in the Water"] = "물속에 뭔가 있어"
L["Something Valuable, Perhaps?"] = "어쩌면 세기의 발견?"
L["Something's Not Quite Right..."] = "뭔가 옳지 않아..."
L["Soothing Wounds"] = "상처 진정시키기"
L["Soul Beacon"] = "영혼의 등불"
L["Soulbound"] = "영혼의 거래"
L["Souls for the Death Loa"] = "죽음의 로아에게 바치는 영혼"
L["South of the Pinnacle, past the rim of the Valley of Echoes, a little Scarlet outpost called Blackwatch keeps quiet company with the Scourge it claims to hate. The Argent Crusade has questions about that. Grimly wants the plague altars in pieces. Father Kamaros, somehow still alive, has a list of his own wounded. Doctor Olakin Sainrith is busy inside the lab cooking something that was never meant to breathe. Overhead, the Flesh Giant Champion walks the ice. Inside Malykriss's foundry, the Runesmiths still pound the Scourge's armor — and one old vrykul skeleton is about to do more work dead than it ever did alive."] = "봉우리 남쪽, 메아리 골짜기 가장자리 너머에는 어둠의 감시초소라는 작은 붉은십자군 전초기지가 있다. 그들은 증오한다고 주장하는 스컬지와 조용히 어울리고 있다. 은빛십자군은 이에 대해 묻고 싶은 것이 있다. 그림리는 역병 제단을 산산조각 내고 싶어 한다. 어떻게든 아직 살아 있는 신부 카마로스에게는 따로 챙겨야 할 부상자 명단이 있다. 박사 올라킨 세인리스는 실험실 안에서 결코 숨 쉬어서는 안 될 무언가를 만드느라 바쁘다. 그 위로는 살점 거인 용사가 얼음 위를 걷는다. 말리크리스의 주조소 안에서는 룬대장장이들이 여전히 스컬지의 갑옷을 두드리고 있다. 그리고 늙은 브리쿨 해골 하나가 살아 있을 때보다 죽어서 더 많은 일을 하려 한다."
