L["Stand on the Pinnacle beside a dying paladin while the world's powers weigh his fate."] = "세상의 권력자들이 죽어 가는 성기사의 운명을 저울질하는 동안, 봉우리 위에서 그의 곁을 지키십시오."
L["Stand with Eitrigg, Aggra, and the clans as the Kosh'harg, the great festival of clan and ancestor, is reborn on Azeroth. The Horde has crossed worlds and survived wars, but some rites still need hands to carry them forward.\n\nWalk through Durotar and Nagrand with shamans and young initiates, hear the names of forebears spoken aloud, and remember that orc heritage is more than fang or blade."] = "부족과 조상을 기리는 위대한 축제 코쉬하르그가 아제로스에서 되살아나는 지금, 아이트리그와 아그라, 그리고 부족들과 함께하십시오. 호드는 세상을 건너고 전쟁에서 살아남았지만, 어떤 의식들은 여전히 그것을 이어 갈 손길이 필요합니다.\n\n주술사들, 어린 입문자들과 함께 듀로타와 나그란드를 거닐며, 조상들의 이름이 소리 내어 불리는 것을 듣고, 오크의 유산이 송곳니나 칼날 이상의 것임을 기억하십시오."
L["Stand with Moira Thaurissan as the Dark Iron clan steps out of Blackrock's shadow and claims its place beside the other dwarven clans. Old pride still smolders in the forges, and old enemies still know the names of the halls beneath the mountain.\n\nWalk through places where fire shaped a people, recover what was scattered, and prove that Dark Iron loyalty is earned in heat, craft, and memory."] = "검은무쇠 부족이 검은바위의 그늘에서 벗어나 다른 드워프 부족들 곁에 자리를 잡는 지금, 모이라 타우릿산과 함께하십시오. 대장간에는 여전히 오랜 자부심이 불씨처럼 남아 있고, 오랜 적들은 여전히 산 아래 전당들의 이름을 알고 있습니다.\n\n불이 한 종족을 빚어낸 곳들을 거닐고, 흩어진 것들을 되찾으며, 검은무쇠의 충성은 열기와 솜씨, 그리고 기억으로 얻어진다는 것을 증명하십시오."
L["Stand with Tess and the Gilneans to face the Nightbane and reaffirm your people's resolve."] = "테스와 길니아스인들과 함께 나이트베인에 맞서고, 동족의 결의를 다시 다지십시오."
