L["Stormwind's legacy was tested by old enemies and old mistakes. You followed the trail from the city to Westfall and Northshire, exposed the conspiracy, and helped preserve the honor of the kingdom."] = "스톰윈드의 유산은 옛 적들과 지난 과오로 시험받았다. 도시에서 서부 몰락지대와 북녘골까지 흔적을 따라가 음모를 폭로하고, 왕국의 명예를 지키는 데 힘을 보탰다."
