L["Strengthen the Dreamgrove by recruiting champions, training troops, and establishing flight paths through the ancient dreamways."] = "용사를 영입하고, 병력을 훈련하고, 고대의 꿈길을 잇는 비행 경로를 마련해 꿈의 숲의 힘을 키우십시오."
