L["Subtlety had its limits in Nazmir. Patch — a goblin with strong opinions about explosives and personal safety — had a solution for the blood troll barricades that was loud, expensive, and effective. You wrangled his scattered crew, gathered everything they needed, and let them do what goblins do best. The blood troll fortifications that had blocked the advance for weeks turned to rubble in an afternoon. Talanji watched the smoke rise with something close to satisfaction. The path deeper into Nazmir was open."] = "나즈미르에서 은밀함에는 한계가 있었다. 폭발물과 개인 안전에 대해 확고한 의견을 지닌 고블린 패치에게는 피의 트롤 방책을 해결할 방법이 있었다. 시끄럽고, 비싸고, 효과적인 방법이었다. 흩어진 그의 일꾼들을 불러 모으고, 필요한 것들을 전부 구해 준 다음, 고블린이 가장 잘하는 일을 하게 내버려 두었다. 몇 주 동안 진격을 가로막았던 피의 트롤 요새는 단 한나절 만에 잔해가 되었다. 탈란지는 피어오르는 연기를 거의 만족에 가까운 표정으로 바라보았다. 나즈미르 깊숙이 들어가는 길이 열렸다."
L["Sufficient Motivation"] = "충분한 동기 부여"
L["Sully \"The Pickle\" McLeary"] = "\"작은 고추\" 설리 맥리어리"
L["Summoner Morn"] = "소환사 모른"
L["Summoning the Sisters"] = "자매 소환"
L["Sunke Khang"] = "쑨커 캉"
L["Sunwell Plateau"] = "태양샘 고원"
L["Supply Only the Finest Goons"] = "최상급 수행"
L["Suramar"] = "수라마르"
L["Suramar is an ancient elven city sealed behind a magical barrier for ten thousand years, now opened under the shadow of the Burning Legion. Within the walls, the highborne depend on the arcwine of the Nightwell; outside them, the nightfallen wither without its magic.\n\nAid First Arcanist Thalyssra and her rebellion as they gather allies, infiltrate noble houses, and learn how to challenge a city that has survived by hiding from the world."] = "수라마르는 만 년 동안 마법 방벽 뒤에 봉인되어 있던 고대 엘프의 도시로, 이제 불타는 군단의 그림자 아래에서 그 문이 열렸습니다. 성벽 안의 명가는 밤샘의 비전 포도주에 의존하고, 성벽 밖의 나이트폴른은 그 마법 없이 메말라 갑니다.\n\n첫 번째 비전술사 탈리스라와 그녀의 반란군을 도와 동맹을 모으고, 귀족 가문에 잠입하고, 세상으로부터 숨어 살아남아 온 도시에 맞서는 법을 익히십시오."
L["Survey Says..."] = "조사에 따르면..."
L["Survey the City"] = "성 조사"
L["Survival Skills"] = "생존의 왕도"
L["Survive the Night"] = "한밤을 버티며"
L["Svergan Stormcloak"] = "폭풍망토 스베르간"
L["Svergan's Promise"] = "스베르간의 약속"
L["Swallowed Whole"] = "꿀꺽 삼켰어요"
L["Swear the blood oath at Agmar's Hammer and dig the Horde's claws into the frozen plain."] = "아그마르의 망치에서 피의 맹세를 하고, 얼어붙은 평원에 호드의 발톱을 깊이 박으십시오."
L["Sweete's Strongbox"] = "스위트의 금고"
L["Sylvanas found a crack in Icecrown's defenses and sent you in alongside her. The Forge of Souls. The Pit of Saron. And finally the Halls of Reflection, where she came face to face with the memory of the man who murdered her and enslaved her people. She asked Uther the Lightbringer what would become of Arthas when he died. He told her the only way to truly end the Lich King was at the Frozen Throne where he was made. Then he warned her, in the same breath, that her own fate in death would not be kind. She said nothing. She called for the gunship and got everyone out."] = "실바나스는 얼음왕관의 방어에서 틈을 찾아내 함께 그 안으로 들어갔다. 영혼의 제련소. 사론의 구덩이. 그리고 마침내 투영의 전당. 그곳에서 그녀는 자신을 살해하고 동족을 노예로 만든 남자의 기억과 마주했다. 그녀는 빛의 수호자 우서에게 아서스가 죽으면 어떻게 되는지 물었다. 우서는 리치 왕을 진정으로 끝낼 유일한 방법은 그가 만들어진 얼어붙은 왕좌에서뿐이라고 답했다. 그러고는 같은 숨에, 죽음 이후 그녀 자신의 운명도 결코 자비롭지 않을 것이라고 경고했다. 그녀는 아무 말도 하지 않았다. 비행포함을 불러 모두를 탈출시켰을 뿐이었다."
L["Sylvanas has found a crack in Icecrown's defenses. She leads a covert strike through three dungeons — the Forge of Souls, the Pit of Saron, and the Halls of Reflection — to reach something she has been waiting years to confront."] = "실바나스가 얼음왕관의 방어에서 틈을 찾아냈습니다. 그녀는 영혼의 제련소, 사론의 구덩이, 투영의 전당까지 세 던전을 거치는 은밀한 기습을 이끌며, 수년 동안 맞서기를 기다려 온 무언가를 향해 나아갑니다."
L["Sylvanas is gone. The Horde's leaders gather to decide what it becomes without her — and Lilian Voss speaks for the Forsaken."] = "실바나스가 떠났습니다. 호드의 지도자들이 그녀 없는 호드의 앞날을 정하기 위해 모이고, 릴리안 보스가 포세이큰을 대변합니다."
L["Sylvanas is gone. What remains of the Horde gathers to decide what it becomes without her."] = "실바나스가 떠났습니다. 남은 호드가 모여 그녀 없이 어떤 길을 걸을지 결정합니다."
L["Sylvanas shatters the Helm of Domination and tears open the sky above Icecrown. The leaders of Azeroth follow her into death itself — and find that she left someone behind."] = "실바나스가 지배의 투구를 부수고 얼음왕관 위의 하늘을 찢어 엽니다. 아제로스의 지도자들은 그녀를 쫓아 죽음 그 자체 속으로 들어가고, 그녀가 남겨 두고 간 누군가를 발견합니다."
L["Sylvanas went to Icecrown and took the Helm of Domination from Bolvar Fordragon's head. Then she broke it. The veil between the living world and the realm of death split apart where she stood, and she stepped through and left. Bolvar used the shards to open a second rift — he and Jaina, Thrall, Baine, and Anduin went in after her. They landed in the Maw, the prison at the bottom of the Shadowlands, a place no soul had ever escaped from. Sylvanas was already gone deeper in. She had left Anduin behind, locked in a cage in the Tremaculum, to be broken slowly by the Jailer's forces — a message, maybe, or an experiment. Jaina found him. The Jailer's magic had already started working on Baine, poisoning his spirit through a cursed dagger. There was no clean escape: the river of souls, Gorgoa, cut across the only path out, and the Jailer's armies were moving to seal it. The group fought their way through, kept each other standing, and crossed. They came out the other side with Anduin freed and the full shape of the threat finally visible. Sylvanas had not just started a war. She had chosen a side in one that had been running since before Azeroth existed."] = "실바나스는 얼음왕관으로 가서 볼바르 폴드라곤의 머리에서 지배의 투구를 벗겨 냈다. 그리고 그것을 부숴 버렸다. 그녀가 선 자리에서 산 자의 세계와 죽음의 영역 사이의 장막이 찢어졌고, 그녀는 그 틈을 지나 떠났다. 볼바르는 파편을 이용해 두 번째 균열을 열었고, 그와 제이나, 스랄, 바인, 안두인이 그녀를 뒤쫓아 들어갔다. 그들이 떨어진 곳은 어둠땅의 밑바닥에 있는 감옥, 어떤 영혼도 탈출한 적 없는 나락이었다. 실바나스는 이미 더 깊은 곳으로 사라진 뒤였다. 그녀는 안두인을 나락의 구렁에 있는 우리에 가둔 채 남겨 두었다. 간수의 병력이 그를 서서히 꺾어 놓도록. 어쩌면 전언이었고, 어쩌면 실험이었다. 제이나가 그를 찾아냈다. 간수의 마법은 이미 바인에게도 손을 뻗어, 저주받은 단검으로 그의 영혼을 오염시키고 있었다. 깔끔한 탈출은 없었다. 영혼의 강 고르고아가 유일한 탈출로를 가로질렀고, 간수의 군대는 그 길을 봉쇄하려 움직이고 있었다. 일행은 싸우며 길을 뚫었고, 서로를 지탱하며 강을 건넜다. 반대편에 다다랐을 때 안두인은 풀려나 있었고, 위협의 전모가 마침내 드러났다. 실바나스는 단순히 전쟁을 일으킨 것이 아니었다. 아제로스가 존재하기 전부터 이어져 온 전쟁에서 한쪽 편을 택한 것이었다."
L["Sylvanas Windrunner"] = "실바나스 윈드러너"
L["Sympathizers Among the Shal'dorei"] = "샬도레이의 동조자들"
L["Syra Goldendraft"] = "시라 골든드래프트"
L["T'uure, Beacon of the Naaru"] = "나루의 신호기 투레"
L["Tactical Matters"] = "전술가의 의견"
L["Tactical Planning"] = "작전을 짜야할 때"
L["Tactician Tinderfell"] = "전술가 틴더펠"
L["Taelia"] = "탤리아"
L["Taelia sent you to Drustvar, where Lord Waycrest had vanished and a dark curse was spreading. In Fallhaven, Cyril White led you through the signs of witchcraft — hexed villagers, twisted familiars, and effigies that pulsed with dark magic. You met Lucille Waycrest, the lord's daughter, who refused to sit idle while her land rotted. Together you hunted the witches through Fallhaven, cracking their curses and burning their effigies. The final effigy crumbled, but the witches' power ran far deeper than one village."] = "탤리아는 군주 웨이크레스트가 사라지고 어두운 저주가 퍼지고 있는 드러스트바로 보냈다. 낙엽의 안식처에서 시릴 화이트가 마녀의 술수가 남긴 흔적을 따라 길을 안내했다. 저주받은 마을 사람들, 뒤틀린 사역마들, 어둠의 마법으로 고동치는 입상들. 그곳에서 영주의 딸 루실 웨이크레스트를 만났다. 그녀는 자신의 땅이 썩어 가는 것을 가만히 앉아 지켜볼 생각이 없었다. 함께 낙엽의 안식처 곳곳에서 마녀들을 사냥하며 저주를 깨뜨리고 입상을 불태웠다. 마지막 입상이 무너졌지만, 마녀들의 힘은 한 마을보다 훨씬 깊이 뻗어 있었다."
L["Take Me To Your Leader"] = "지도자에게 데려다주세요"
L["Take part in the Spirit Festival and walk both Tushui and Huojin threads of pandaren heritage."] = "영혼 축제에 참여해 판다렌 유산의 두 갈래, 투슈이와 후오진의 길을 모두 걸으십시오."
L["Take the High Road"] = "고지를 향해"
L["Takes One to Know One"] = "사돈 남 말"
L["Taking a Promenade"] = "대정원 산책"
L["Taking Charge"] = "임무 수행"
L["Taking Control"] = "힘 빼앗기"
L["Taking the Blood Gate"] = "피의 관문 점령"
L["Tal-Inara"] = "탈이나라"
L["Tal-Inara sent you toward Revendreth with a plea for aid: Ardenweald was starving, the Heart of the Forest was weakening, and Sire Denathrius was said to be a master of anima. Revendreth greeted you with teeth behind every smile. Rendle introduced the rules of the realm — sinstones, punishment, service, and the long work of repentance. Lord Chamberlain offered polished courtesy while rebels struck at the roads and Darkhaven buckled under the anima drought. The place looked like a vampire court and spoke like a church of atonement, but something in its foundations was already cracking."] = "탈이나라는 도움을 청하는 전언과 함께 레벤드레스로 보냈다. 몽환숲은 굶주리고 있었고, 숲의 심장부는 약해지고 있었으며, 대영주 데나트리우스는 령의 대가로 알려져 있었다. 레벤드레스는 미소 뒤마다 이빨을 숨긴 채 맞이했다. 렌들은 이 영역의 규칙을 알려 주었다. 죄악석, 형벌, 봉사, 그리고 길고 긴 참회의 과정. 시종장은 세련된 예의를 갖추었지만, 그사이 반란군은 길목을 습격했고 어둠안식처는 령 가뭄에 무너져 가고 있었다. 이곳은 흡혈귀의 궁정처럼 보였고 속죄의 교회처럼 말했지만, 그 토대 어딘가에는 이미 금이 가고 있었다."
L["Talanji brought you to Nazmir, the oldest and most cursed of the Zandalari lands. The swamp had been swallowed — blood trolls pressed inward from every angle, their offerings feeding something dark and hungry beneath the earth. Rokhan read the signs: to push back the blood tide, you'd need the loa. Ancient, capricious, and rarely willing to be asked. You cut through the blood troll front lines, took in the full scope of the devastation, and prepared to seek out the only powers old enough to matter in Nazmir."] = "탈란지는 잔달라의 땅 중 가장 오래되고 가장 저주받은 나즈미르로 이끌었다. 늪은 이미 잠식당해 있었다. 피의 트롤이 사방에서 밀려들었고, 그들의 제물은 땅 아래의 굶주린 어둠을 먹이고 있었다. 로칸이 징조를 읽었다. 피의 물결을 밀어내려면 로아가 필요했다. 오래되고, 변덕스러우며, 부탁을 들어주는 일이 좀처럼 없는 존재들이었다. 피의 트롤의 최전선을 뚫고, 참상의 전모를 확인한 뒤, 나즈미르에서 의미 있을 만큼 오래된 유일한 힘들을 찾아 나설 준비를 했다."
L["Talking Skull"] = "말하는 해골"
L["Talon Terror"] = "갈퀴발톱의 공포"
L["Talon's Call"] = "갈퀴발톱의 부름"
L["Talonclaw"] = "갈퀴발톱"
L["Taming their Beasts"] = "야수 길들이기"
L["Taoshi"] = "타오스"
L["Tapping the Leylines"] = "지맥을 찾아서"
L["Taran Zhu"] = "타란 주"
L["Target of Opportunity"] = "굴러들어온 기회"
L["Tavernkeeper's Fate"] = "선술집 주인의 운명"
L["Tea Party"] = "다과회"
L["Tech It Up a Notch"] = "한 단계 위로"
L["Tech It Up A Notch"] = "한 단계 위로"
L["Technical Wizardry"] = "기술적인 마술"
L["Teddies and Tea"] = "다과회의 손님들"
L["Telemantic Expanse"] = "이동술의 달인"
L["Temel, the Sin Herald"] = "죄악의 전령 테멜"
L["Temple of the Jade Serpent"] = "옥룡사"
L["Temporal Investigations"] = "시간 조사"
L["Ten thousand years of division between the elven peoples had to be bridged if Suramar was to be freed. You stood between night elf and blood elf, forging an uneasy alliance from shared purpose. Lady Liadrin and Tyrande Whisperwind each brought their people's strength to the cause, while you cleared the Promenade of Elisande's defenses."] = "수라마르를 해방하려면 엘프 종족들 사이의 만 년에 걸친 분열을 메워야 했다. 나이트 엘프와 블러드 엘프 사이에 서서, 공동의 목표로 불안한 동맹을 맺어 냈다. 여군주 리아드린과 티란데 위스퍼윈드는 각자 동족의 힘을 대의에 보탰고, 그동안 산책로에서 엘리산드의 방어 병력을 몰아냈다."
L["Teng Applebloom"] = "텅 애플블룸"
L["Terrace of Ten Thunders"] = "열 천둥의 정원"
L["Testing a Theory"] = "이론 검증"
L["Testing Loyalties"] = "충성의 시험"
L["Thalyssra's Abode"] = "탈리스라의 영지"
L["Thalyssra's Drawers"] = "탈리스라의 서랍"
L["Thank Your Guide"] = "인도자에게 감사하라"
L["Thas'dorah, Legacy of the Windrunners"] = "윈드러너의 유산 타스도라"
L["Thassarian"] = "타사리안"
L["Thassarian came with a personal request — Koltira Deathweaver, his old friend and fellow death knight, had been imprisoned beneath the Undercity by Sylvanas Windrunner. You freed Koltira from his chains, and he pledged himself to your cause. Then came the steeds — Salanar the Horseman forged deathchargers in Neltharion's Lair and the Darkheart Thicket, crafting mounts worthy of the Horsemen from nightmares and shadow."] = "타사리안이 개인적인 부탁을 들고 찾아왔다. 그의 오랜 친구이자 동료 죽음의 기사인 콜티라 데스위버가 실바나스 윈드러너에 의해 언더시티 지하에 갇혀 있다는 것이었다. 콜티라를 사슬에서 풀어 주자, 그는 대의에 충성을 맹세했다. 그다음은 군마였다. 기사 살라나르가 넬타리온의 둥지와 어둠심장 숲에서 악몽과 어둠으로 4기사에 걸맞은 죽음의 군마를 벼려 냈다."
L["That Which Haunts the Dead"] = "망자를 부르는 마녀"
L["That's Abominable!"] = "혐오스러운 친구"
L["The Accuser"] = "규탄자"
L["The Accuser sent you to find Prince Renathal, and the trail led to Theotar, the Mad Duke. He was scattered, brilliant, and broken in a way that made perfect sense in Revendreth. His morning was a catastrophe of lost servants, forged warrants, forbidden research, and tea. Beneath the absurdity was the Ember Ward, a district burned by the Light so fiercely that even Venthyr feared its glow. You crossed that desiccated ruin, pieced together Theotar's memories, and secured Sinfall as a rebel refuge. Revendreth's comedy had teeth, but it also had a heart: the rebellion finally had a home."] = "규탄자는 왕자 레나탈을 찾으라고 보냈고, 흔적은 미치광이 공작 테오타르에게로 이어졌다. 그는 산만하고, 명석하고, 레벤드레스에서라면 완벽히 이해가 가는 방식으로 망가져 있었다. 그의 아침은 사라진 하인들, 위조된 영장, 금지된 연구, 그리고 차로 뒤범벅된 대참사였다. 그 우스꽝스러움 아래에는 잿불 지구가 있었다. 빛에 너무도 맹렬하게 불탄 나머지 벤티르조차 그 빛을 두려워하는 구역이었다. 바싹 말라 버린 그 폐허를 건너고, 테오타르의 기억을 짜 맞추고, 죄악의 몰락지를 반란군의 피난처로 확보했다. 레벤드레스의 희극에는 이빨이 있었지만, 심장도 있었다. 반란군에게 마침내 집이 생긴 것이다."
L["The Accuser's Fate"] = "규탄자의 운명"
L["The Accuser's Secret"] = "규탄자의 비밀"
L["The Accuser's Sinstone"] = "규탄자의 죄악석"
L["The Advisor and the Arcanist"] = "비전술사의 조언가"
L["The Afflictor's Key"] = "괴롭히는 자의 열쇠"
L["The Aid of the Loa"] = "로아의 가호"
L["The Aid of the Tides"] = "파도의 도움"
L["The Air Stands Still"] = "오늘만큼은 평화"
L["The Alliance and Horde did not discover Pandaria gently. They arrived as wreckage, orders, pursuit, and fire, then tried to make allies before they understood what the land would remember.\n\nThe Jade Forest is the first lesson of Pandaria: every doubt, every grudge, and every easy answer has weight. Follow the campaign from the first landings into a land where war leaves marks deeper than banners in the mud."] = "얼라이언스와 호드는 판다리아를 조용히 발견하지 않았습니다. 그들은 잔해와 명령, 추격과 불길로 도착했고, 이 땅이 무엇을 기억하게 될지 이해하기도 전에 동맹을 맺으려 했습니다.\n\n비취 숲은 판다리아의 첫 번째 가르침입니다. 모든 의심, 모든 원한, 그리고 모든 손쉬운 답에는 무게가 있습니다. 첫 상륙에서부터 원정을 따라가, 전쟁이 진흙에 꽂힌 깃발보다 더 깊은 흔적을 남기는 땅으로 들어서십시오."
L["The Alliance finds Taylor, courts the Pearlfin jinyu, and follows Cho's strange methods to Prince Anduin."] = "얼라이언스는 테일러를 찾고, 진주지느러미 진위의 환심을 사고, 초의 기묘한 방식을 따라 안두인 왕자에게 다다릅니다."
L["The Alliance fleet came while Dazar'alor was still recovering from everything the Horde had sacrificed to protect it. Jaina Proudmoore led the assault through the sacred pyramid, floor by floor, past every guardian the Zandalari could muster. King Rastakhan, knowing the city could not hold, made a desperate bargain — calling on Bwonsamdi's power directly, burning his own life force to drive the invaders back.\n\nBwonsamdi got his king in the end. Rastakhan fell. But the death loa was there to receive him, and the deal struck in Nazmir had never promised anything more than that — the power to fight, not the guarantee of survival. Talanji watched her father die holding a city that still stood. Bwonsamdi, for his part, was exactly as somber as a loa of death ever gets. The soul of a king is not nothing."] = "다자알로가 호드가 그곳을 지키기 위해 치른 모든 희생에서 아직 회복하지 못했을 때 얼라이언스 함대가 들이닥쳤다. 제이나 프라우드무어는 잔달라가 그러모을 수 있는 모든 수호자를 지나 신성한 피라미드를 한 층씩 공략하며 공격을 이끌었다. 도시가 버틸 수 없음을 안 왕 라스타칸은 필사적인 거래를 했다. 브원삼디의 힘을 직접 불러내, 자신의 생명력을 불태워 침략자들을 몰아낸 것이다.\n\n결국 브원삼디는 자신의 왕을 얻었다. 라스타칸이 쓰러졌다. 하지만 죽음의 로아는 그를 맞이하기 위해 그 자리에 있었고, 나즈미르에서 맺은 계약은 애초에 그 이상을 약속한 적이 없었다. 싸울 힘을 주었을 뿐, 살아남는다는 보장은 하지 않았다. 탈란지는 아버지가 여전히 서 있는 도시를 지키며 죽어 가는 모습을 지켜보았다. 브원삼디는 죽음의 로아로서 보일 수 있는 딱 그만큼 엄숙했다. 왕의 영혼은 결코 하찮은 것이 아니다."
L["The Alliance has come for Lordaeron. Sylvanas holds the walls of the Forsaken capital as Jaina and Anduin lead the siege."] = "얼라이언스가 로데론으로 진격해 왔습니다. 제이나와 안두인이 포위 공격을 이끄는 가운데, 실바나스는 포세이큰의 수도 성벽을 지킵니다."
L["The Alliance strikes at the heart of the Zandalari empire. King Rastakhan calls on Bwonsamdi — and pays the price."] = "얼라이언스가 잔달라 제국의 심장부를 공격합니다. 왕 라스타칸은 브원삼디에게 힘을 청하고, 그 대가를 치릅니다."
L["The allied armies — nightfallen, blood elves, night elves, and vrykul — marched through the streets of Suramar in a united front. You fought alongside Thalyssra at the vanguard, pushing through Elisande's desperate defenses block by block. The fighting was brutal, but the staging point was secured — the Nighthold was within reach."] = "나이트폴른, 블러드 엘프, 나이트 엘프, 브리쿨로 이루어진 연합군이 하나의 전선을 이루어 수라마르의 거리를 진군했다. 선봉에서 탈리스라와 함께 싸우며 엘리산드의 필사적인 방어를 한 구역씩 뚫고 나아갔다. 싸움은 처절했지만 집결지는 확보되었다. 밤의 요새가 손에 닿을 거리에 있었다."
L["The allied forces breach the Nighthold itself, confronting the source of Elisande's power."] = "연합군이 마침내 밤의 요새에 진입해 엘리산드가 지닌 힘의 근원과 맞선다."
L["The Anub'ar Nerubians boil up from the Pit of Narjun — spider-warriors of a civilization that should have stayed dead. They strike the Horde's supply lines by night and drag the wounded into the dark by morning. Senior Sergeant Juktok wants them ended at the source. Valnok Windrager is already saddling the wyverns. Agmar will not leave this flank open."] = "아눕아르 네루비안이 나르준의 구덩이에서 끓어오르듯 쏟아져 나온다. 진작 사라졌어야 할 문명의 거미 전사들이다. 그들은 밤마다 호드의 보급로를 습격하고, 아침이 오기 전에 부상자들을 어둠 속으로 끌고 간다. 정예수호병 주크토크는 근원부터 뿌리 뽑기를 원한다. 발노크 윈드레이저는 벌써 와이번에 안장을 얹고 있다. 아그마르는 이 측면을 무방비로 내버려 두지 않을 것이다."
L["The Anvil-Thane's Designs"] = "엔빌테인의 도안"
L["The Arcan'dor — the ancient tree nurtured in Shal'Aran — began to wither, its roots cracking and leaves curling despite all efforts. Valewalker Farodin led you on a desperate search for fragments of arcane power scattered across Suramar's ruins. In the end, you secured a branch of the Arcan'dor itself, stabilizing the tree and keeping alive the dream of a cure for the nightfallen."] = "샬아란에서 가꿔 온 고대의 나무 아칸도르가 시들기 시작했다. 온갖 노력에도 뿌리는 갈라지고 잎은 말려 들어갔다. 계곡방랑자 파로딘과 함께 수라마르의 폐허 곳곳에 흩어진 비전 마력의 조각을 찾아 필사적으로 헤맸다. 결국 아칸도르의 가지 하나를 손에 넣어 나무를 안정시켰고, 나이트폴른을 치유하겠다는 꿈도 이어 갈 수 있었다."
L["The Arcan'dor is struggling to survive. Race against time to find what it needs before the tree withers."] = "아칸도르가 간신히 버티고 있다. 나무가 시들기 전에 필요한 것을 찾아내야 한다. 시간이 얼마 없다."
L["The Arcan'dor needed something that could not be found in Suramar — a seed blessed by the wild magic of Val'sharah. You journeyed with Thalyssra's allies to retrieve it, channeling ley energy through Oculeth's projectors and Valtrois's calculations. The seed took root, and the Arcan'dor bloomed with renewed strength, its fruit offering the first true cure for the nightfallen's dependence on the Nightwell."] = "아칸도르에게 필요한 것은 수라마르에서는 구할 수 없었다. 바로 발샤라의 야생 마력으로 축복받은 씨앗이었다. 탈리스라의 동료들과 함께 씨앗을 찾아 나섰고, 오큘레스의 투사기와 발트루아의 계산을 거쳐 지맥 에너지를 끌어왔다. 씨앗은 뿌리를 내렸고, 아칸도르는 새로운 힘으로 꽃을 피웠다. 그 열매는 나이트폴른이 밤샘에 의존하는 상태를 치료할 최초의 진정한 해독제가 되었다."
L["The Arcane Way"] = "비전의 길"
L["The Arcane Way opened a path back to the Black Temple — Illidan's fortress, now empty and echoing with memories. Belath Dawnblade led you through its halls where the ghosts of the Illidari's past still lingered. A confrontation with the temple's remaining defenses proved that the demon hunters had grown beyond what they once were. New recruits joined from among the temple's guards, and the Fel Hammer's ranks swelled."] = "비전의 길이 검은 사원으로 돌아가는 길을 열었다. 일리단의 요새였던 그곳은 이제 텅 빈 채 기억만 메아리치고 있었다. 벨라스 돈블레이드는 일리다리의 과거가 아직 유령처럼 맴도는 회랑으로 길을 안내했다. 사원에 남은 방어 병력과 맞서 싸우며, 악마사냥꾼들이 예전의 모습을 훌쩍 넘어섰음이 증명되었다. 사원의 경비병 중에서 새로운 신병들이 합류했고, 지옥 망치호의 병력은 더욱 불어났다."
L["The Archdruid's Campaign"] = "대드루이드의 대장정"
L["The Archmage's Campaign"] = "대마법사의 대장정"
L["The Arcway: Long Buried Knowledge"] = "비전로: 오랫동안 묻혀 있던 지식"
L["The Arcway: Opening the Arcway"] = "비전로: 비전로를 열어라"
L["The Argent Vanguard is the last friendly ground at the southern edge of Icecrown. Crusade Commander Entari drills the new arrivals into shape. Father Gustav's engineers run the fleshbeast bombardier; Siegemaster Fezzik's jumpbot waits for one more idiot willing to take the breach. Past the tent line, the ground sours into the Valley of Echoes — and past that, Crusaders' Pinnacle, where Tirion Fordring means to draw a line the Scourge cannot cross."] = "은빛십자군 선봉기지는 얼음왕관 남쪽 끝에 남은 마지막 아군 거점이다. 십자군 사령관 엔타리는 새로 도착한 병사들을 혹독하게 훈련시킨다. 신부 구스타프의 기술자들은 살덩이짐승 폭격기를 운용하고, 공성전문가 페지크의 점프봇은 돌파구로 뛰어들 멍청이 하나를 더 기다리고 있다. 천막 너머로는 땅이 점점 썩어 들어가며 메아리 골짜기로 이어지고, 그 너머에는 십자군 봉우리가 있다. 티리온 폴드링은 그곳에 스컬지가 넘을 수 없는 선을 그으려 한다."
L["The Art of Being a Water Terror"] = "공포의 물 정령 다루기"
L["The Art of Flow"] = "흐름의 미학"
L["The Art of War"] = "전쟁의 기술"
L["The Ashbringer"] = "파멸의 인도자"
L["The Authority of Revendreth"] = "레벤드레스의 지배자"
L["The Banshee Queen"] = "밴시 여왕"
L["The Battle for Broken Shore"] = "부서진 해변 전투"
L["The Battle For Crusaders' Pinnacle"] = "십자군 봉우리를 위한 전투"
L["The Battle for Lordaeron"] = "로데론 전투"
L["The Battle of Bloodfire Ravine"] = "핏빛불꽃 협곡 전투"
L["The Battle of Dazar'alor"] = "다자알로 전투"
L["The Battlelord's Campaign"] = "전투군주의 대장정"
L["The Bees' Knees"] = "말벌 다리"
L["The Best and Brightest"] = "가장 현명하고 가장 뛰어난 자"
L["The Big Bad Wolfe"] = "커다랗고 나쁜 늑대"
L["The Blessing of the Ancestors"] = "선조의 축복"
L["The Blessing of the Clan"] = "부족의 축복"
L["The Blessing of the Land"] = "땅의 축복"
L["The Blight Congress"] = "파멸의 회의"
L["The Blood of Demons"] = "악마의 피"
L["The Bloody Truth"] = "피투성이 진실"
L["The Bone Witch"] = "해골 마녀"
L["The Boon of A'dal"] = "아달이 베푼 은혜"
L["The Boon of Alexstrasza"] = "알렉스트라자가 베푼 은혜"
L["The Boon of Remulos"] = "레물로스가 베푼 은혜"
L["The Brand of Damnation"] = "저주의 낙인"
L["The Bridgeport Ride"] = "다리항구 달리기"
L["The Broken Front"] = "파괴된 싸움터"
L["The Broken Shore"] = "부서진 해변"
L["The Broken Shore brought an unwelcome ally — Magatha Grimtotem, the elder crone who had murdered Cairne Bloodhoof. She demanded a place in the Earthen Ring in exchange for her considerable power, and the elements themselves seemed to agree. You worked alongside her through gritted teeth, breaking chains and quelling snakes, while Nobundo led the main assault. Firelord Smolderon's offense scorched the Legion's fortifications, and when the calm came after the storm, Consular Celestos summoned you to a gathering of storms — where a tempest given form became your mount, the Farseer's Raging Tempest."] = "부서진 해변에서 반갑지 않은 동맹이 나타났다. 케른 블러드후프를 살해한 늙은 마녀, 마가타 그림토템이었다. 그녀는 막강한 힘을 내놓는 대가로 대지 고리회의 자리를 요구했고, 정령들마저 이에 동의하는 듯했다. 이를 악물고 그녀와 함께 사슬을 끊고 뱀들을 진압하는 동안, 노분도는 본대의 공격을 이끌었다. 화염군주 스몰데론의 공세가 군단의 요새를 불태웠다. 폭풍이 지나가고 고요가 찾아오자, 집정관 셀레스토스가 폭풍의 집회로 불러들였다. 그곳에서 형체를 얻은 폭풍이 탈것이 되었다. 바로 선견자의 성난 폭풍이었다."
L["The Broken Shore burned with felfire, and Odyn sent you to lead the Valarjar into the heart of the assault. You recruited new forces, armed them for the battles ahead, and ventured into Helheim itself to recover stolen souls and claim Helya's own horn as a trophy. When Kvaldir raiders answered your call and the last of the missing champions returned, Odyn summoned you for one final trial — the Trial of Rage. You emerged victorious, and a bloodthirsty war wyrm knelt before its new master."] = "부서진 해변이 지옥불로 타오르자, 오딘은 발라리아르를 이끌고 공격의 한복판으로 뛰어들라 명했다. 새 병력을 모아 다가올 전투에 대비해 무장시켰고, 헬하임까지 들어가 빼앗긴 영혼들을 되찾고 헬리아의 뿔나팔을 전리품으로 차지했다. 크발디르 약탈자들이 부름에 응하고 실종되었던 마지막 용사들이 돌아오자, 오딘은 마지막 시험인 분노의 시험으로 불러들였다. 시험에서 승리하자, 피에 굶주린 전쟁 비룡이 새 주인 앞에 무릎을 꿇었다."
L["The Broken Shore called, and the Ebon Blade answered. Minerva Ravensorrow joined as your newest champion, harnessing power from the very demons you slew. You led an expedition to the Peak of Bones where an army of undead rose at your command, fought alongside Thorim's flame, and defeated the Bonemother. On Daumyr's wings you soared above the battlefield, and when the final ride came, you claimed the Vilebrood Vanquisher — a frost wyrm that knelt before the Deathlord."] = "부서진 해변이 부르자 칠흑의 기사단이 응답했다. 미네르바 레이븐소로우가 새 용사로 합류해, 쓰러뜨린 악마들에게서 힘을 끌어냈다. 원정대를 이끌고 뼈의 봉우리에 오르자 언데드 군대가 명령에 따라 일어섰다. 토림의 불꽃과 함께 싸워 뼈어미를 처치했다. 다우미르를 타고 전장 위로 날아올랐으며, 마지막 비행에서는 죽음군주 앞에 무릎 꿇은 서리고룡, 혐오둥지 정복자를 손에 넣었다."
L["The Broken Shore demanded the Dreamgrove's strength. Thisalee Crow, fierce and fearless, joined your cause as the war escalated. Rensar Greathoof channeled the Dreamgrove's power to aid the Legionfall assault, granting you the ability to call upon nature even in the most fel-scarred land. When the battle was won, Thisalee brought word of Aviana under attack — you rushed to defend the mother of flight and earned the Lunarwing form, soaring above the world as only an Archdruid could."] = "부서진 해변에서 꿈숲의 힘이 필요해졌다. 전쟁이 격화되자 사납고 두려움을 모르는 티살리 크로우가 대의에 합류했다. 렌사르 그레이트후프는 꿈숲의 힘을 끌어내 군단척결 공세를 지원했고, 지옥의 상처가 가장 깊은 땅에서도 자연을 부를 수 있는 힘을 주었다. 전투에서 승리하자 티살리가 아비아나가 공격받고 있다는 소식을 전했다. 서둘러 달려가 비행의 어머니를 지켜 냈고, 그 대가로 달날개 변신을 얻었다. 오직 대드루이드만이 할 수 있는 방식으로 세상 위를 날게 된 것이다."
L["The Broken Shore demanded the Tirisgarde's full power. Aethas Sunreaver, once exiled from Dalaran, returned to lead the mage offensive. You uncovered a nightborne workshop hidden on the Shore, secured its secrets, and armed Dalaran's defenses against a Legion counterattack. When the dust settled, Khadgar entrusted you with one final task — recovering the legendary Discs of Norgannon. From their power, the Archmage's Prismatic Disc was forged — a flying platform that shifted between arcane, fire, and frost as you willed it."] = "부서진 해변에서 티리스가드의 모든 힘이 필요해졌다. 한때 달라란에서 추방당했던 에이타스 선리버가 돌아와 마법사들의 공세를 이끌었다. 해변에 숨겨진 나이트본의 작업장을 찾아내 그 비밀을 확보했고, 군단의 반격에 맞서 달라란의 방어를 강화했다. 먼지가 가라앉자 카드가가 마지막 임무를 맡겼다. 전설적인 노르간논의 원반을 되찾는 일이었다. 그 힘으로 대마법사의 분광 원반이 만들어졌다. 뜻에 따라 비전, 화염, 냉기의 모습으로 바뀌는 비행 원반이었다."
L["The Broken Shore held a prisoner the Council had long sought — Kanrethad Ebonlocke, the warlock who had tried to bind a pit lord and paid the price with his freedom. Shinfel and Jubeka led the search while you culled the Legion cult guarding him and contained the fel crystals keeping him sealed. Kanrethad was freed, scarred but unbroken, and joined as your newest champion. Then came the final rite — Mor'zul Bloodbringer opened a portal to Xoroth, where a wrathsteed of chaotic fire waited. You broke its will and bent it to yours, and the Netherlord's Chaotic Wrathsteed carried you from the flames."] = "부서진 해변에는 의회가 오랫동안 찾아 헤맨 포로가 있었다. 구덩이 군주를 속박하려다 자유를 대가로 치른 흑마법사, 칸레타드 에본로크였다. 신펠과 주베카가 수색을 이끄는 동안, 그를 지키던 군단 광신도들을 처단하고 그를 가둔 지옥 수정을 억제했다. 풀려난 칸레타드는 상처 입었지만 꺾이지 않았고, 새 용사로 합류했다. 이어 마지막 의식이 시작되었다. 모르줄 블러드브링어가 조로스로 향하는 차원문을 열자, 혼돈의 불길로 이루어진 격노마가 기다리고 있었다. 그 의지를 꺾어 굴복시키자, 황천군주의 혼돈의 격노마가 주인을 태우고 불길 속에서 달려 나왔다."
L["The Broken Shore was a rout. The Horde threw everything at the Legion's landing force and bled for it. Vol'jin took a wound that no healer could close. By the time the retreat was called, he was dying. He summoned Sylvanas, told her the loa had whispered her name, and asked her to lead. She stood there for a moment — the Dark Lady of the Forsaken, who had never wanted anything to do with the Horde's politics — and said yes. She walked out of that room as Warchief. Nobody, including her, fully understood what that meant yet."] = "부서진 해변 전투는 참패였다. 호드는 군단의 상륙 부대에 모든 것을 쏟아부었고, 그만큼 피를 흘렸다. 볼진은 어떤 치유사도 아물게 할 수 없는 상처를 입었다. 후퇴 명령이 떨어졌을 때 그는 이미 죽어 가고 있었다. 그는 실바나스를 불러 로아가 그녀의 이름을 속삭였다고 전하며 호드를 이끌어 달라고 부탁했다. 그녀는 잠시 그 자리에 서 있었다. 호드의 정치와는 엮이고 싶어 한 적 없던 포세이큰의 어둠의 여왕이었다. 그리고 그녀는 승낙했다. 그 방을 나설 때 그녀는 대족장이었다. 그것이 무엇을 의미하는지, 그녀 자신을 포함해 아직 누구도 온전히 이해하지 못했다."
L["The Broken Shore was crawling with demons, and Kor'vas coordinated the Illidari's assault from the Fel Hammer itself. When the Legion counterattacked, you defended the ship in a desperate battle above the battlefield. Lady S'theno, a naga exile who had fought demons for millennia, joined your cause after you restored balance to the Broken Shore's ley lines. When the war was won, a felbat — the Felbroken Shrieker — recognized you as its master, and the Slayer took to the skies."] = "부서진 해변은 악마들로 들끓었고, 코르바스는 지옥 망치호에서 일리다리의 공격을 지휘했다. 군단이 반격해 오자 전장 위에서 필사적으로 싸우며 함선을 지켜 냈다. 수천 년 동안 악마와 싸워 온 추방된 나가, 여군주 스테노는 부서진 해변의 지맥에 균형을 되찾아 주자 대의에 합류했다. 전쟁에서 승리하자 지옥박쥐 한 마리가 새 주인을 알아보았다. 바로 지옥부서진 비명박쥐였다. 그렇게 학살자는 하늘로 날아올랐다."
L["The Bulk of the Guard"] = "대규모 경비병"
L["The Burden of Proof"] = "파란만장 무죄 입증"
L["The Call of Battle"] = "전투의 부름"
L["The Call of Icecrown"] = "얼음왕관의 부름"
L["The Call to War"] = "전쟁의 부름"
L["The Calm After the Storm"] = "폭풍 후의 고요"
L["The Campaign Begins"] = "작전 시작"
L["The campaign pushes into the ruins of Gilneas. A traitor needs to be dealt with, and the Gilneas Liberation Front is running out of room to maneuver."] = "전투는 길니아스의 폐허로 이어진다. 배신자를 처리해야 하고, 길니아스 해방 전선은 운신할 여지를 잃어 가고 있다."
L["The Captive Spymaster"] = "사로잡힌 첩보단장"
L["The Chain Gun And You"] = "퇴로를 뚫어라"
L["The Champion's Return"] = "용사의 귀환"
L["The citadel's gates are not for hammering. Sergeant Stackhammer knows it. Sergeant Kregga knows it. The Alliance and Horde sappers have quieter work — crawl into the saronite pits beneath Sindragosa's Fall and set the charges that will shake the foundations from below. Before the pits go up, a voice begins to whisper out of the saronite dark. Whoever he is, he knows a name. He wants it spoken. He wants you to come back when the dust settles and hear the rest of his story at the First Legion Forward Camp."] = "성채의 관문은 망치로 두들겨 부술 곳이 아니다. 하사관 스택해머도 알고, 하사관 크레가도 안다. 얼라이언스와 호드의 공병들에게는 더 조용한 일이 있다. 신드라고사의 추락지 아래 사로나이트 구덩이로 기어 들어가, 아래에서 토대를 뒤흔들 폭약을 설치하는 것이다. 구덩이가 터지기 전, 사로나이트의 어둠 속에서 누군가 속삭이기 시작한다. 그가 누구든, 그는 어떤 이름을 알고 있다. 그는 그 이름이 입 밖에 나오기를 원한다. 그리고 먼지가 가라앉으면 1군단 전진기지로 돌아와 나머지 이야기를 들어 달라고 한다."
L["The clans gathered once more, and old ways found new meaning. Through trials of land, clan, and ancestors, you helped the orcs reclaim identity not as they were, but as they choose to be now."] = "부족들이 다시 한번 모였고, 옛 방식은 새로운 의미를 찾았다. 대지와 부족, 선조의 시련을 거치며, 오크들이 과거의 모습이 아니라 지금 스스로 선택한 모습으로 정체성을 되찾도록 도왔다."
L["The Clarion Call"] = "청명한 부름"
L["The Clessington Will"] = "클레싱턴의 의지"
L["The Codex of Command"] = "지휘의 고서"
L["The Coming Storm"] = "다가오는 폭풍"
L["The Conclave was united — Light and Shadow standing together for the first time. The final test came on Niskara, a Legion prison world where priests and paladins alike were held captive. With Aponi Brightmane and Lord Maxwell Tyrosus lending their strength, you crossed Legion lines and broke the chains. United as one, the Conclave shattered the demon garrison. Alonsus Faol himself pledged as your champion, and Moira Thaurissan forged your weapon anew. You were named High Priest of Netherlight — a title that carried the weight of every faith you had united."] = "회합이 하나로 뭉쳤다. 빛과 암흑이 처음으로 함께 선 것이다. 마지막 시험은 니스카라에서 찾아왔다. 사제와 성기사가 모두 포로로 붙잡혀 있는 군단의 감옥 세계였다. 아포니 브라이트메인과 맥스웰 티로서스 경의 힘을 빌려 군단의 전선을 넘고 사슬을 끊었다. 하나가 된 회합은 악마 주둔군을 산산이 부수었다. 알론서스 파올이 직접 용사가 되기로 맹세했고, 모이라 타우릿산은 무기를 새로 벼려 주었다. 그리고 황천빛의 대사제라는 칭호를 받았다. 하나로 모은 모든 신앙의 무게가 담긴 칭호였다."
L["The Cost of War"] = "전쟁의 대가"
L["The Council convened to address Archmage Vargoth's disappearance. Khadgar led you to Vargoth's retreat, where the signs of struggle told a grim story. Following in his footsteps, you traced magical residue across the Broken Isles. Kalec's investigation revealed the truth was worse than anyone feared — Vargoth hadn't simply vanished. Something had taken him, and that something was connected to the dreadlord Kathra'natir."] = "의회가 소집되어 대마법사 바르고스의 실종 문제를 논의했다. 카드가의 안내로 바르고스의 은거지에 가 보니, 몸싸움의 흔적이 불길한 이야기를 들려주고 있었다. 그의 발길을 따라 부서진 섬 곳곳에 남은 마법의 흔적을 추적했다. 칼렉의 조사로 드러난 진실은 누구의 예상보다도 끔찍했다. 바르고스는 그냥 사라진 것이 아니었다. 무언가가 그를 데려갔고, 그것은 공포군주 카스라나티르와 연결되어 있었다."
L["The Council is in Session"] = "충격에 빠진 의회"
L["The Council needed more power — souls to fuel the Dreadscar Rift's defenses. You retrieved an unclaimed soul from Black Rook Hold, built a soul beacon to gather energy, and recruited Ernest Carlisle — a mad alchemist who turned goat herding into an art form. Shinfel Blightsworn and Kira Iresoul earned their champion marks, and the Council debated who among them was truly worthy of the power they wielded. The Vault of the Wardens provided the answer: power belonged to those who could take it and hold it."] = "의회에는 더 많은 힘이 필요했다. 공포흉터 균열의 방어를 유지할 영혼들이었다. 검은 떼까마귀 요새에서 주인 없는 영혼을 되찾고, 에너지를 모을 영혼 신호기를 세운 뒤, 염소 치기를 예술의 경지로 끌어올린 미치광이 연금술사 어니스트 칼라일을 영입했다. 신펠 블라이트스원과 키라 아이어소울은 용사의 자격을 얻었고, 의회는 그들 중 누가 그 힘을 휘두를 자격이 진정 있는지 논쟁했다. 감시관의 금고가 답을 주었다. 힘은 그것을 빼앗아 지켜 낼 수 있는 자의 것이었다."
L["The Council's sixth seat remained contested — and the answer lay with Lulubelle Fizzlebang, a gnome warlock with more ambition than common sense. You found her in Stormheim, coerced a confession from a captured demon, and cleaned up someone else's mess along the way. Lulubelle proved her worth through sheer stubborn brilliance, and the Summoning of the Sisters sealed the pact. With all six members chosen and your weapon forged to its full dark potential, the Council of the Black Harvest was complete. You were named Netherlord."] = "의회의 여섯 번째 자리는 여전히 주인이 정해지지 않았다. 그 답은 상식보다 야망이 큰 노움 흑마법사, 루루벨 피즐뱅에게 있었다. 스톰하임에서 그녀를 찾아내고, 사로잡은 악마에게서 자백을 받아 내고, 그 와중에 남이 벌여 놓은 난장판까지 수습했다. 루루벨은 지독한 고집과 재기로 자신의 가치를 증명했고, 자매 소환 의식으로 계약이 맺어졌다. 여섯 명이 모두 선택되고 무기가 어둠의 잠재력을 온전히 발휘하게 되자, 검은 수확 의회가 완성되었다. 그리고 황천군주라는 칭호를 받았다."
L["The Crimsonwood was the Drust king's domain — a forest so thick with dark magic that the trees themselves attacked. You saved Master Ashton from the thorns, gathered what you needed from the cursed woods, and went deeper. Inquisitor Cleardawn never flinched as you faced the matrons of the Crimsonwood one by one. At the heart of it all stood Gorak Tul's hall, where the grand rite would have brought the Drust back in full force. You stopped it — barely — and stuck the embers into the heart of his power. Gorak Tul retreated, wounded but not destroyed. Lucille was waiting."] = "진홍숲은 드러스트 왕의 영역이었다. 어둠의 마법이 너무 짙어 나무들마저 덤벼드는 숲이었다. 가시덤불에서 대가 애쉬튼을 구하고, 저주받은 숲에서 필요한 것을 모은 뒤 더 깊이 들어갔다. 진홍숲의 가모장들과 하나씩 맞서는 동안에도 심문관 클리어돈은 조금도 움츠러들지 않았다. 그 모든 것의 중심에는 고라크 툴의 전당이 있었다. 대의식이 치러졌다면 드러스트가 온전한 힘으로 되살아났을 것이다. 가까스로 의식을 저지하고, 그 불씨를 그의 힘의 심장부에 꽂아 넣었다. 고라크 툴은 상처를 입었지만 소멸하지 않은 채 물러났다. 루실이 기다리고 있었다."
L["The Crusaders' Pinnacle"] = "십자군 봉우리"
L["The Crux of the Plan"] = "계획의 핵심"
L["The Crypt Keeper"] = "납골당지기"
L["The Culling of Stratholme"] = "옛 스트라솔름"
L["The Curse of Fletcher's Hollow"] = "활장이의 골짜기에 내린 저주"
L["The Dark Heart of Nazmir"] = "나즈미르의 검은 심장"
L["The Dark Iron legacy is forged, not inherited. By proving your worth in brawls, smithing, and service, you helped secure the clan's heritage for a new era."] = "검은무쇠의 유산은 물려받는 것이 아니라 벼려 내는 것이다. 난투와 대장기술, 봉사로 자신의 가치를 증명하며, 새로운 시대를 맞은 부족의 유산을 지켜 내도록 도왔다."
L["The Dark Lady Calls"] = "어둠의 여왕의 부름"
L["The Darkness Within"] = "내면의 어둠"
L["The Darkspear were pulled toward old fears and dark power, but chose another path. By restoring their ties to Kevo ya Siti, Lukou, and Jani, you helped your people remember who they are and what they stand for."] = "검은창 부족은 오랜 두려움과 어둠의 힘에 이끌렸지만, 다른 길을 택했다. 케보 야 시티, 루코우, 자니와의 유대를 되살려, 동족들이 자신이 누구이며 무엇을 지키려 하는지 되새기도록 도왔다."
L["The Dawning Light"] = "새로운 시작"
L["The Day Hope Died"] = "희망이 사라진 날"
L["The Dead and the Damned"] = "죽은 자와 저주받은 자"
L["The Deathlord's Campaign"] = "죽음군주의 대장정"
L["The Defense of Tian Monastery"] = "티엔 수도원 방어"
L["The Delicate Art of Telemancy"] = "정교한 이동 기술"
L["The Demi-God's Return"] = "반신의 귀환"
L["The Desolate Council"] = "황폐의 의회"
L["The Double Hozen Dare"] = "왕겁쟁이"
L["The draenei's strength comes from memory, faith, and resilience. By sharing burdens old and new, you helped your people move forward without forgetting what they endured."] = "드레나이의 힘은 기억과 신앙, 그리고 꺾이지 않는 의지에서 나온다. 오래된 짐과 새로운 짐을 함께 나누며, 동족들이 견뎌 온 시간을 잊지 않고 앞으로 나아가도록 도왔다."
L["The Dragonblight Campaign"] = "용의 안식처 원정"
L["The Dreadblades"] = "공포의 검"
L["The dreadlord has been hiding among your allies all along. The hunt ends on the Broken Shore in a final confrontation."] = "공포군주는 줄곧 아군 사이에 숨어 있었다. 사냥은 부서진 해변에서 벌어지는 최후의 결전으로 막을 내린다."
L["The dreadlord Kathra'natir had been one step ahead all along — and his final move was possessing Meryl Felstorm himself. With the Tirisgarde's founder corrupted from within, Khadgar rallied every resource: a magical affliction cured in the Eye of Azshara, the might of the Tirisgarde focused into a single strike. You stormed the Oculus and faced Kathra'natir in Meryl's body, tearing the demon free without destroying the mage. Meryl stood free, Vargoth was rescued, and your weapon was reforged. The Kirin Tor bestowed upon you the title of Archmage."] = "공포군주 카스라나티르는 처음부터 한 발 앞서 있었다. 그리고 그의 마지막 수는 메릴 펠스톰 본인에게 빙의하는 것이었다. 티리스가드의 창시자가 안에서부터 타락하자, 카드가는 모든 자원을 끌어모았다. 아즈샤라의 눈에서 마법 질병을 치료하고, 티리스가드의 힘을 단 한 번의 일격에 집중시켰다. 마력의 눈으로 쳐들어가 메릴의 몸을 차지한 카스라나티르와 맞섰고, 마법사를 해치지 않고 악마만을 떼어 냈다. 메릴은 자유를 되찾았고, 바르고스는 구출되었으며, 무기는 다시 벼려졌다. 키린 토는 대마법사의 칭호를 내렸다."
L["The Dreadlord's Prize"] = "악마가 탐내는 유물"
L["The Dreamgrove"] = "꿈숲"
L["The Dreamgrove / Broken Isles"] = "꿈숲 / 부서진 섬"
L["The Dreamgrove needed defenders. Rensar Greathoof tasked you with growing the order's power — recruiting champions to stand at your side and training troops drawn from every corner of Azeroth's wilds. Skylord Omnuron opened new paths through the Dreamway, connecting the Dreamgrove to the wider world. With each branch that grew, the sanctuary's roots dug deeper."] = "꿈숲에는 수호자가 필요했다. 렌사르 그레이트후프는 교단의 힘을 키우는 임무를 맡겼다. 곁을 지킬 용사들을 모으고, 아제로스의 야생 곳곳에서 모여든 병력을 훈련시키는 일이었다. 하늘군주 옴누론은 꿈길을 통해 새 길을 열어 꿈숲을 더 넓은 세상과 이었다. 가지가 하나씩 자랄 때마다 성소의 뿌리는 더 깊이 파고들었다."
L["The Dreamway"] = "달숲의 의식"
L["The Duke"] = "공작"
L["The Ebon Watcher"] = "칠흑의 감시자"
L["The Elder's Instruments"] = "장로의 장비"
L["The Elements Call..."] = "정령의 부름"
L["The Emerald Nightmare"] = "에메랄드의 악몽"
L["The Emerald Nightmare spreads unchecked. Naralex leads you into the corrupted wilds to find the Idol of the Wilds before the Nightmare claims it."] = "에메랄드의 악몽이 걷잡을 수 없이 퍼져 나간다. 나랄렉스를 따라 타락한 야생으로 들어가, 악몽이 차지하기 전에 야생의 우상을 찾아야 한다."
L["The Emperor's Gift"] = "황제가 남긴 선물"
L["The Empyrean Society"] = "천상 협회"
L["The Enemy of My Enemy..."] = "적의 적은..."
L["The Eve of Battle"] = "전투 전야"
L["The Eye of Odyn"] = "오딘의 눈"
L["The faction war reaches the Serpent's Heart, shatters the seal, and releases the Sha of Doubt."] = "진영 간의 전쟁이 용의 심장에 이르러 봉인을 부수고, 의심의 샤를 풀어놓는다."
L["The Fall of Ga'trul"] = "가트룰의 몰락"
L["The Fall of the Sunwell"] = "태양샘의 몰락"
L["The Fall of Zuldazar"] = "줄다자르의 몰락"
L["The Fangs of Ashamane"] = "아샤메인의 송곳니"
L["The Fangs of Ashamane — twin daggers blessed by the wild god of the hunt — had been lost in the wilds of Val'sharah. You tracked them through ancient feral grounds, facing guardians left by Ashamane herself. When you grasped the Fangs, the spirit of the great cat surged through you, and the wilds themselves seemed to sharpen around your senses."] = "사냥의 야생신이 축복한 쌍단검, 아샤메인의 송곳니는 발샤라의 야생 어딘가에서 사라졌다. 고대의 야수 영역을 따라 그 흔적을 추적하며, 아샤메인이 직접 남긴 수호자들과 맞섰다. 송곳니를 움켜쥐자 거대한 고양이의 영혼이 몸속으로 밀려들었고, 야생 그 자체가 감각을 둘러싸고 더욱 날카로워지는 듯했다."
L["The Farseer's Campaign"] = "선견자의 대장정"
L["The Fate of Bloodbane"] = "블러드베인의 최후"
L["The Fate of Hodir"] = "호디르의 운명"
L["The Fate of Kanrethad"] = "칸레타드의 운명"
L["The Fate of Saurfang"] = "사울팽의 운명"
L["The Fate of Sylvanas"] = "실바나스의 운명"
L["The Fearstalker"] = "공포추적자"
L["The Fel Hammer / Broken Isles"] = "지옥 망치호 / 부서진 섬"
L["The Fel Hammer needed to become more than a ship — it needed to become an army. Battlelord Gaardoun helped recruit champions while Kor'vas organized the broken warriors scattered across the Broken Isles. You proved your immortal soul was strong enough to lead, and the Illidari acknowledged you as their commander. The demon hunters were no longer scattered outcasts — they were a blade pointed at the Legion's heart."] = "지옥 망치호는 단순한 배 이상이 되어야 했다. 하나의 군대가 되어야 했다. 전투군주 가르둔이 용사들을 모으는 것을 도왔고, 코르바스는 부서진 섬 곳곳에 흩어진 상처 입은 전사들을 규합했다. 불멸의 영혼이 군대를 이끌 만큼 강하다는 것을 증명하자, 일리다리는 새 지휘관을 받아들였다. 악마사냥꾼들은 더 이상 흩어진 추방자가 아니었다. 그들은 군단의 심장을 겨눈 칼날이었다."
L["The Felsoul Experiments"] = "지옥영혼 실험"
L["The final assault on Grand Ma'da Ateena. The Horde, the loa, and a death god march together into the Blood Gate. G'huun waits beneath."] = "큰마마 아티나를 향한 최후의 공세. 호드와 로아, 그리고 죽음의 신이 함께 피의 관문으로 진군한다. 그 아래에서 그훈이 기다린다."
L["The Final Blow!"] = "최후의 일격!"
L["The final breach. You entered the Nighthold itself, fighting through the last of Elisande's loyalists to reach the seat of her power. When the Grand Magistrix fell and the Nightwell's corrupting influence was severed, Thalyssra stepped forward to lead her people into a new era. The nightfallen were nightborne once more — free to choose their own fate."] = "최후의 돌파. 밤의 요새로 진입해 엘리산드의 마지막 충신들을 뚫고 그녀의 권좌에 이르렀다. 대마법학자가 쓰러지고 밤샘의 타락한 영향력이 끊어지자, 탈리스라가 앞으로 나서 동족을 새 시대로 이끌었다. 나이트폴른은 다시 나이트본이 되었다. 이제 스스로 운명을 선택할 수 있었다."
L["The final campaign began with demonic runes appearing across the Broken Isles — the Legion was closing in. You deciphered their meaning in Black Rook Hold, captured a Legion gateway, and stormed Niskara to rescue Hodir, imprisoned by demons since the war began. With every titan keeper free and every rune decoded, Odyn forged your weapon anew and declared you Battlelord of the Valarjar — a title not bestowed in ten thousand years."] = "마지막 원정은 부서진 섬 곳곳에 악마의 룬이 나타나면서 시작되었다. 군단이 조여 오고 있었다. 검은 떼까마귀 요새에서 룬의 의미를 해독하고, 군단 관문을 점령한 뒤 니스카라로 쳐들어가 전쟁이 시작된 이래 악마들에게 갇혀 있던 호디르를 구출했다. 모든 티탄 관리인이 풀려나고 모든 룬이 해독되자, 오딘은 무기를 새로 벼리고 발라리아르의 전투군주로 선포했다. 1만 년 동안 누구에게도 내려지지 않았던 칭호였다."
L["The Final Effigy"] = "마지막 입상"
L["The final Horseman must be raised from the most sacred ground in Azeroth. Darion Mograine makes the ultimate sacrifice."] = "마지막 기사는 아제로스에서 가장 신성한 땅에서 일으켜야 한다. 다리온 모그레인이 궁극의 희생을 치른다."
L["The final hunt led to the Broken Shore, where a dreadlord had been hiding among your allies in plain sight. With Lilian Voss at your side, you set the trap — false orders, planted evidence, and a trail that led the demon straight into your blade. The Uncrowned had done what armies could not: killed a devil wearing a friend's face."] = "마지막 사냥은 부서진 해변으로 이어졌다. 그곳에서 공포군주는 버젓이 아군 사이에 숨어 있었다. 릴리안 보스와 함께 덫을 놓았다. 거짓 명령과 조작된 증거, 그리고 악마를 곧장 칼날 앞으로 이끄는 흔적이었다. 왕관 없는 자들은 군대도 해내지 못한 일을 해냈다. 친구의 얼굴을 한 악마를 처단한 것이다."
L["The Final Shadow"] = "마지막 일원"
L["The final test. Decipher demonic runes, rescue Hodir from a Legion prison world, and prove yourself worthy of the Battlelord title."] = "마지막 시험. 악마의 룬을 해독하고, 군단의 감옥 세계에서 호디르를 구출해 전투군주의 칭호를 받을 자격을 증명해야 한다."
L["The Firelord's Command"] = "불의 군주의 명령"
L["The Firelord's Offense"] = "화염군주의 공격"
L["The First Assault"] = "첫 번째 공세"
L["The First to Fall"] = "최초로 쓰러진 자"
L["The First Watch"] = "첫 번째 감시"
L["The Firstborn Rises"] = "가장 먼저 부름 받은 자"
L["The Fist of Ra-den"] = "라덴의 주먹"
L["The Flesh Giant Champion"] = "살덩이 거인 용사"
L["The Flight of the Banshee"] = "밴시의 비행"
L["The Fog of War"] = "전장의 안개"
L["The Forest Ward revealed Revendreth at its most predatory. The Fearstalker and his hounds called it penance: let condemned souls glimpse escape, then chase them until pride broke under terror. You learned the ritual, stalked the quarry, and watched the Accuser's doubts harden into rebellion. The hunt was supposed to humble sinners, but it had become sport for nobles who fed on fear. By the time you reached Dredhollow and broke the Hopebreakers, the shape of the war was clear. This was not order against chaos. It was cruelty against the last pieces of Revendreth still trying to remember mercy."] = "숲 감시구역에서 레벤드레스는 가장 포식자다운 얼굴을 드러냈다. 공포추적자와 그의 사냥개들은 그것을 속죄라 불렀다. 단죄된 영혼들에게 탈출의 희망을 보여 준 뒤, 오만이 공포에 짓눌려 꺾일 때까지 뒤쫓는 것이었다. 의식을 익히고 사냥감을 추적하며, 고발자의 의심이 반란의 의지로 굳어 가는 것을 지켜보았다. 사냥은 죄인들을 겸허하게 만들기 위한 것이었지만, 이제는 공포를 먹고 사는 귀족들의 유희가 되어 있었다. 공포 골짜기에 이르러 희망파괴자들을 무너뜨렸을 무렵, 전쟁의 윤곽은 분명해졌다. 이것은 질서와 혼돈의 싸움이 아니었다. 잔혹함과, 아직 자비를 기억하려 애쓰는 레벤드레스의 마지막 조각들 사이의 싸움이었다."
L["The Forlorn Soul"] = "황량한 영혼"
L["The Forsaken are marching on Silverpine Forest. Warchief Garrosh Hellscream has heard what Sylvanas is doing to grow their numbers — and he is not pleased."] = "포세이큰이 은빛소나무 숲으로 진군한다. 대족장 가로쉬 헬스크림은 실바나스가 병력을 불리려고 무슨 짓을 하는지 전해 들었고, 그것을 결코 달가워하지 않는다."
L["The Forsaken Blight"] = "포세이큰 파멸의 역병"
L["The Forsaken Blight and You: How Not to Die"] = "포세이큰 파멸의 역병과 당신: 죽지 않는 비결"
L["The Forsaken Daughter"] = "포세이큰의 딸"
L["The Forsaken High Command was busy when Garrosh Hellscream showed up with a grievance. He'd heard what Sylvanas was doing — using the Val'kyr to raise human dead as new Forsaken, growing her forces beyond what the Horde had sanctioned. He told her to stop. She asked him, face to face, what the difference was between her and the Lich King. He didn't have a good answer. The campaign continued."] = "가로쉬 헬스크림이 불만을 품고 찾아왔을 때, 포세이큰 고위 사령부는 한창 분주했다. 그는 실바나스가 하는 일을 전해 들었다. 발키르를 이용해 인간의 시체를 새로운 포세이큰으로 일으키고, 호드가 승인한 수준을 넘어 병력을 키우고 있다는 것이었다. 그는 당장 그만두라고 했다. 실바나스는 그의 얼굴을 똑바로 보며 자신과 리치 왕이 무엇이 다르냐고 물었다. 그는 제대로 답하지 못했다. 원정은 계속되었다."
L["The Forsaken moved on. Lordaeron was theirs again, and the long war had its accounting. But some loyalties don't dissolve with a verdict. Dori'thur arrived in the ruins of Lordaeron bearing a message — not from a queen, not a command, just acknowledgment. The hunt Sylvanas began in death has no end date. The souls in the Maw number in the countless. She is still there, freeing them one by one. The message asked nothing. It only said: she remembers who stood with her."] = "포세이큰은 앞으로 나아갔다. 로데론은 다시 그들의 것이 되었고, 오랜 전쟁은 셈을 마쳤다. 하지만 어떤 충성은 판결 하나로 사라지지 않는다. 도리투르가 전갈을 들고 로데론의 폐허를 찾아왔다. 여왕의 전갈도, 명령도 아닌, 그저 잊지 않았다는 표시였다. 실바나스가 죽음 속에서 시작한 사냥에는 끝이 없다. 나락의 영혼은 헤아릴 수 없이 많다. 그녀는 아직 그곳에서 영혼을 하나씩 풀어 주고 있다. 전갈은 아무것도 요구하지 않았다. 단지 이렇게 전할 뿐이었다. 그녀는 자신의 곁에 섰던 이들을 기억한다고."
L["The Forsaken Plague"] = "포세이큰 역병"
L["The Forsaken push into the farmlands of Tirisfal, where the Scarlet Crusade holds a fortified palisade. Someone from Deathknell has gone missing."] = "포세이큰은 티리스팔의 농지로 진격한다. 그곳에는 붉은십자군이 방책을 세우고 버티고 있다. 죽음의 종소리 마을에서 누군가가 실종되었다."
L["The Four Tomes"] = "네 개의 고서"
L["The Fourth Horseman"] = "네 번째 기사"
L["The Frozen Halls"] = "얼어붙은 전당"
L["The Frozen Throne"] = "얼어붙은 왕좌"
L["The Fruit of Our Efforts"] = "노력의 결실"
L["The Gilneas Liberation Front"] = "길니아스 해방전선"
L["The Gjallarhorn"] = "외치는 뿔피리"
L["The Gjallarhorn — the horn that calls the worthy to battle — has been stolen. Hunt down the thieves across Stormheim and reclaim it."] = "합당한 자들을 전장으로 부르는 외치는 뿔피리를 누군가 훔쳐 갔다. 스톰하임 전역에서 도둑들을 추적해 되찾아야 한다."
L["The Gnome Behind the Trogg"] = "트로그 배후의 노움"
L["The Gondolier"] = "나룻배 사공"
L["The Grandmaster's Campaign"] = "대사부의 대장정"
L["The graveyards of Drustvar hold fallen Kul Tiran war heroes — soldiers too valuable to leave buried. Nathanos leads the expedition to unearth Marshal M. Valentine, while Lilian questions what separates the Horde's methods from the horrors she once suffered at the hands of the Scarlet Crusade."] = "드러스트바의 묘지에는 쓰러진 쿨 티란의 전쟁 영웅들이 잠들어 있다. 그대로 묻어 두기엔 너무 아까운 병사들이다. 나타노스는 원수 M. 발렌타인을 파내기 위한 원정을 이끌고, 릴리안은 호드의 방식이 자신이 붉은십자군의 손에 겪었던 참상과 무엇이 다른지 의문을 품는다."
L["The Great Akazamzarak"] = "위대한 아카잠자락"
L["The Great Banquet"] = "대연회"
L["The Great Escape"] = "최후의 탈출"
L["The Great Stonemother"] = "위대한 바위 어머니"
L["The Greatest Duelist"] = "최강의 검투사"
L["The Grove of Terror"] = "공포의 숲"
L["The Guardians of Corp'rethar"] = "코프레타르의 수호자"
L["The Hand of Keletress"] = "켈리트레스의 손"
L["The Heart of the Dreadscar"] = "공포흉터의 심장"
L["The Hidden City"] = "숨겨진 도시"
L["The Hidden Need"] = "베일에 가려진 고난"
L["The High Elder"] = "대장로"
L["The High Overlord"] = "대군주"
L["The High Priest's Campaign"] = "대사제의 대장정"
L["The Highlord's Campaign"] = "대영주의 대장정"
L["The Hooded Crusader's campaign reached the Scarlet Monastery itself. You retrieved the blessed blades of the Anointed — weapons consecrated to destroy the undead — and drove them into High Inquisitor Whitemane. The irony was not lost on Lilian: the Crusade's holiest weapons, wielded by the dead, against the Crusade's own champion."] = "두건 쓴 성전사의 원정은 마침내 붉은십자군 수도원에 이르렀다. 언데드를 멸하기 위해 축성된 무기, 성유 받은 자의 축복받은 칼날을 되찾아 종교재판관 화이트메인에게 꽂아 넣었다. 릴리안은 그 아이러니를 놓치지 않았다. 십자군의 가장 성스러운 무기가 죽은 자의 손에 들려, 십자군의 용사를 겨눈 것이다."
L["The Hooded Crusader's campaign reaches the Scarlet Monastery. Two blessed blades rest within its halls — consecrated weapons anointed to destroy the undead. High Inquisitor Whitemane commands everything inside."] = "두건 쓴 성전사의 원정이 붉은십자군 수도원에 이른다. 그 회랑 안에는 언데드를 멸하도록 축성된 축복받은 칼날 두 자루가 잠들어 있다. 수도원 안의 모든 것은 종교재판관 화이트메인의 지휘 아래 있다."
L["The Horde has split in two. Saurfang rallies those who oppose Sylvanas, while loyalists prepare to crush the rebellion."] = "호드가 둘로 갈라졌다. 사울팽은 실바나스에게 맞서는 이들을 규합하고, 충성파는 반란을 짓밟을 준비를 한다."
L["The Horde marched into Ashenvale with speed and purpose. You pushed through Night Elf defenses, secured the roads, and drove toward the coast beneath Teldrassil. The Night Elves fought well but the Horde had the numbers and Sylvanas had a plan. The World Tree loomed at the end of it — massive, ancient, and full of civilians who had not escaped in time. Sylvanas stood at its base with the battle won and the tree in reach. A Night Elf prisoner asked what the people inside had done to deserve this. Sylvanas spoke about hope being the enemy. Then she gave the order. Teldrassil burned. The smoke was visible from Stormwind. Whatever Sylvanas had been building toward, this was no longer a war anyone could call limited."] = "호드는 빠르고 단호하게 잿빛 골짜기로 진군했다. 나이트 엘프의 방어선을 뚫고 도로를 확보한 뒤, 텔드랏실 아래 해안을 향해 밀고 나아갔다. 나이트 엘프는 잘 싸웠지만, 호드에게는 수적 우위가 있었고 실바나스에게는 계획이 있었다. 그 끝에는 세계수가 우뚝 서 있었다. 거대하고, 오래되었으며, 미처 피난하지 못한 민간인들로 가득한 나무였다. 실바나스는 전투에서 승리한 채 나무 밑동에 섰고, 세계수는 손이 닿는 곳에 있었다. 나이트 엘프 포로 하나가 저 안의 사람들이 무슨 짓을 했기에 이런 일을 당해야 하느냐고 물었다. 실바나스는 희망이야말로 적이라고 말했다. 그리고 명령을 내렸다. 텔드랏실이 불탔다. 그 연기는 스톰윈드에서도 보였다. 실바나스가 무엇을 향해 나아가고 있었든, 이제 이 전쟁을 제한적이라고 부를 수 있는 사람은 아무도 없었다."
L["The Horde needs a tidesage's power over the sea. Lilian and Rexxar track one down in Stormsong Valley — Thomas Zelling, a dying man willing to trade his humanity for a few more years with his family. When the ritual is done, Lilian must watch Zelling's wife recoil from the husband she no longer recognizes. The scene is painfully familiar."] = "호드에게는 바다를 다스리는 파도현자의 힘이 필요하다. 릴리안과 렉사르는 스톰송 계곡에서 한 명을 찾아낸다. 가족과 몇 년이라도 더 함께하기 위해 인간성을 내놓으려는 죽어 가는 남자, 토마스 젤링이다. 의식이 끝나자, 릴리안은 젤링의 아내가 더는 알아볼 수 없게 된 남편에게서 움츠러드는 모습을 지켜보아야 한다. 그 장면은 고통스러울 만큼 익숙하다."
L["The Horde's banner flies over Agmar's Hammer, driven into the permafrost like a spear into a cold chest. Emissary Brighthoof calls for warriors willing to bind themselves to the Warchief's campaign. Overlord Agmar tolerates no softness — the Scourge presses on every side, and a red-eyed gate on the horizon waits to be broken."] = "아그마르의 망치 위로 호드의 깃발이 휘날린다. 차가운 가슴에 창을 꽂듯 영구 동토에 박아 넣은 깃발이다. 사절 브라이트후프는 대족장의 원정에 몸을 바칠 전사들을 찾는다. 대군주 아그마르는 나약함을 용납하지 않는다. 스컬지가 사방에서 조여 오고, 지평선 너머 붉은 눈의 관문이 부서지기만을 기다리고 있다."
L["The Horde's hozen alliance becomes a proper forward campaign from Grookin Hill."] = "호드와 호젠의 동맹이 그루끼끼 언덕을 거점으로 한 본격적인 전진 원정으로 발전한다."
L["The Horde's war at sea claims a significant prize: Derek Proudmoore, son of the Lord Admiral, goes down with his ship in the waters off Kul Tiras. Hobart Grapplehammer equips you with experimental diving gear as Dread-Admiral Tattersail leads the expedition into the deep. What Sylvanas intends to do with the body is not yet spoken aloud — but the silence on the ship ride home says enough."] = "호드의 해상 전쟁이 중대한 전리품을 거둔다. 대제독의 아들 데릭 프라우드무어가 쿨 티라스 앞바다에서 배와 함께 가라앉은 것이다. 호바트 그래플해머가 실험용 잠수 장비를 지급하고, 공포제독 태터세일이 심해로 향하는 원정을 이끈다. 실바나스가 그 시신으로 무엇을 하려는지는 아직 아무도 입 밖에 내지 않는다. 하지만 돌아오는 배 위의 침묵이 많은 것을 말해 준다."
L["The Hunt"] = "사냥"
L["The Hunter and the Prince"] = "사냥꾼과 왕자"
L["The Hunter of Heroes"] = "영웅을 사냥하는 자"
L["The Hunter's Call"] = "사냥꾼의 부름"
L["The Hunter's Gaze"] = "사냥꾼의 시선"
L["The Huntmaster's Campaign"] = "사냥지배자의 대장정"
L["The Idol of the Wilds breathed new life into the Dreamgrove. Archdruid Hamuul Runetotem and the irrepressible Mylune pledged themselves as champions, along with the spirited Brightwing. Together you focused the Dreamgrove's energies into its portal, strengthening the connection between the waking world and the Dream. The Cenarion Circle stood united — and the Nightmare would feel its wrath."] = "야생의 우상이 꿈숲에 새 생명을 불어넣었다. 대드루이드 하뮬 룬토템과 넘치는 기운을 주체하지 못하는 마일룬, 그리고 활기찬 빛나래가 용사로서 힘을 보태기로 맹세했다. 함께 꿈숲의 기운을 차원문에 집중시켜, 깨어 있는 세계와 꿈 사이의 연결을 더욱 굳건히 했다. 세나리온 의회는 하나로 뭉쳤고, 악몽은 그 분노를 맛보게 될 것이었다."
L["The Imposter"] = "단장 사칭"
L["The Invasion of Niskara"] = "니스카라 침공"
L["The Iron Fist"] = "무쇠 주먹"
L["The Jade Forest"] = "비취 숲"
L["The Jade Serpent"] = "옥룡"
L["The Jade Witch"] = "옥의 마녀"
L["The Jailer was dead. Sylvanas was whole again — every fragment of her soul restored from where she had given it away. She stood in silence with the full weight of what she had done pressing down on her at last. Then she walked. Down the long road through Oribos, past the faces of the people she had condemned, she came before Tyrande Whisperwind — who had more right to judge her than anyone alive or dead. Tyrande spoke her sentence. Sylvanas accepted it without a word of protest. She would spend eternity freeing the souls she had imprisoned in the Maw, sending them through the veil one by one. Not as punishment. As penance, freely chosen."] = "간수는 죽었다. 실바나스는 다시 온전해졌다. 스스로 내주었던 영혼의 조각이 모두 되돌아온 것이다. 그녀는 자신이 저지른 일의 무게를 마침내 온전히 짊어진 채 말없이 서 있었다. 그리고 걸음을 옮겼다. 오리보스를 가로지르는 긴 길을 따라, 자신이 단죄했던 이들의 얼굴을 지나, 티란데 위스퍼윈드 앞에 섰다. 산 자와 죽은 자를 통틀어 그녀를 심판할 자격이 가장 큰 이였다. 티란데가 판결을 내렸다. 실바나스는 한마디 항변도 없이 그것을 받아들였다. 그녀는 나락에 가두었던 영혼들을 하나씩 풀어 장막 너머로 보내며 영원을 보내게 될 것이다. 형벌로서가 아니었다. 스스로 택한 속죄였다."
L["The Jailer's Defeat"] = "간수의 패배"
L["The kaldorei endured calamity without abandoning duty. By hunting corruption in Felwood and standing beside the Wardens, you helped preserve the legacy of Elune's people."] = "칼도레이는 재앙 속에서도 의무를 저버리지 않았다. 악령숲에서 타락을 사냥하고 감시관들 곁에 서서, 엘룬의 백성이 남긴 유산을 지켜 내도록 도왔다."
L["The Keeper's Favor"] = "수호자의 친절"
L["The Keys to Success in Freehold"] = "자유지대 성공의 열쇠"
L["The King Rises"] = "진정한 왕의 부활"
L["The King's Command"] = "국왕 폐하의 명령"
L["The Kingslayers"] = "국왕 시해자"
L["The Kor'kron at Wyrmrest"] = "고룡쉼터의 코르크론"
L["The Kor'kron Vanguard!"] = "코르크론 선봉기지로!"
L["The Kosh'harg"] = "코쉬하그"
L["The Kul Tiran fleet — decades of Proudmoore naval heritage — is scattered and locked behind four keys held by enemies who have taken root across the nation: pirates in Freehold, corrupt wardens in Tol Dagor, drowned tidesages in the Shrine of the Storm, and Drust witches in Waycrest Manor. The keys must be taken by force. At the end, Priscilla Ashvane makes one final move — and Jaina faces her mother in a square in Boralus, in front of the entire fleet, for the first time since Theramore fell."] = "수십 년에 걸친 프라우드무어 해군의 전통이 깃든 쿨 티란 함대는 뿔뿔이 흩어진 채, 나라 곳곳에 뿌리내린 적들이 쥔 네 개의 열쇠 뒤에 묶여 있다. 자유지대의 해적들, 톨 다고르의 부패한 간수들, 폭풍의 사원의 익사한 파도현자들, 그리고 웨이크레스트 저택의 드러스트 마녀들이다. 열쇠는 힘으로 빼앗아야 한다. 마지막에 프리실라 애쉬베인이 최후의 수를 두고, 제이나는 테라모어가 무너진 뒤 처음으로 보랄러스의 광장에서 함대 전체가 지켜보는 가운데 어머니와 마주한다."
L["The Last Line Of Defense"] = "최후의 방어"
L["The Last Witch Doctor of Krag'wa"] = "크라그와의 마지막 의술사"
L["The Leaper"] = "껑충이"
L["The Legion has established a foothold in Azsuna. Lead the Silver Hand to Faronaar and recruit new champions in battle."] = "군단이 아즈스나에 거점을 마련했다. 은빛 성기사단을 이끌고 파로나아르로 향해, 전투 속에서 새로운 용사들을 모아야 한다."
L["The Legion has landed on the Broken Shore. The Horde answers the call — but this battle will cost far more than anyone expected."] = "군단이 부서진 해변에 상륙했다. 호드는 부름에 응하지만, 이 전투는 누구의 예상보다도 훨씬 큰 대가를 요구할 것이다."
L["The Legion launches a direct assault on Dalaran through the Violet Hold. Rally the Unseen Path's champions for the final defense."] = "군단이 보랏빛 요새를 통해 달라란을 직접 공격한다. 보이지 않는 길의 용사들을 모아 최후의 방어에 나서야 한다."
L["The Legion's grip on Faronaar in Azsuna was tightening. Lord Grayson Shadowbreaker dispatched you to break it. With Vindicator Boros at your side, you cut through demon ranks and destroyed their communication orbs. Justicar Julia Celeste fought with a fury that earned her a place among your champions. The Codex of Command — a Legion tactical manual — was recovered from the battlefield, but its contents were locked behind demonic encryption."] = "아즈스나의 파로나아르를 조이는 군단의 손아귀가 점점 강해지고 있었다. 그레이슨 섀도브레이커 경은 그것을 끊어 내라는 임무를 맡겼다. 구원자 보로스와 함께 악마의 대열을 베어 나가며 통신 구슬을 파괴했다. 심판관 줄리아 셀레스트는 맹렬하게 싸워 용사의 자리를 얻었다. 군단의 전술 교본인 지휘의 고서를 전장에서 되찾았지만, 그 내용은 악마의 암호로 잠겨 있었다."
L["The Librarian's Quandary"] = "사서의 곤경"
L["The Lich King commands you to raise the Four Horsemen anew. The first to rise is Nazgrim, the fallen Horde general."] = "리치 왕이 4기사를 새로 일으키라고 명한다. 가장 먼저 일어설 자는 쓰러진 호드의 장군, 나즈그림이다."
L["The Lich King reveals the location of Apocalypse, a runesword that brings death to everything it touches."] = "리치 왕이 닿는 모든 것에 죽음을 가져오는 룬검, 대재앙의 위치를 밝힌다."
L["The Lich King's reign ends at the Frozen Throne. For Sylvanas, the aftermath is more personal than anyone outside Icecrown will ever know."] = "리치 왕의 통치가 얼어붙은 왕좌에서 막을 내린다. 실바나스에게 그 여파는 얼음왕관 바깥의 누구도 결코 알 수 없을 만큼 사적인 것이다."
L["The Lich King's voice echoed through Acherus, pointing you toward Apocalypse — a blade of pure death forged in an age of darkness. You followed the trail through Duskwood alongside Revil Kost, hunting the Dark Riders who had stolen the sword. In the depths of Deadwind Pass, you wrested Apocalypse from their skeletal grip. The blade hummed with necrotic power, eager to fulfill the promise of its name."] = "리치 왕의 목소리가 아케러스에 울려 퍼지며 대재앙이 있는 곳을 가리켰다. 어둠의 시대에 벼려진 순수한 죽음의 칼날이었다. 레빌 코스트와 함께 그늘숲을 가로지르며 검을 훔쳐 간 어둠의 기수들을 추적했다. 저승바람 고개 깊은 곳에서, 그들의 해골 손아귀로부터 대재앙을 빼앗아 냈다. 칼날은 사령의 힘으로 웅웅 울리며, 그 이름이 약속하는 바를 이루기를 갈망했다."
L["The Light and the Void"] = "빛과 공허"
L["The Light Below"] = "저 아래의 빛"
L["The Light's Wrath"] = "빛의 분노"
L["The Lion's Cage"] = "사자 우리"
L["The Loa Trials"] = "로아의 시련"
L["The Long Hunt"] = "기나긴 사냥"
L["The Long Knives"] = "긴 칼"
L["The Lost Glacier"] = "잃어버린 빙하"
L["The Mad Duke"] = "미친 공작"
L["The Maelstrom / Broken Isles"] = "혼돈의 소용돌이 / 부서진 섬"
L["The Maelstrom's Air Pillar was failing, and only an elemental lord could restore it. Advisor Sevel tracked the Blessed Blade of the Windseeker — the key to freeing Thunderaan, Prince of Air. You journeyed to Highlord Demitrian, reforged the blade, and climbed to the skies above. There, you recharged the weapon and broke Thunderaan's bonds. The Windlord surged free, his winds howling across the Broken Isles. He swore an oath to the Earthen Ring, and Consular Celestos and Nobundo stood with you as the Air Pillar blazed back to life."] = "혼돈의 소용돌이의 바람의 기둥이 무너져 가고 있었고, 정령의 군주만이 그것을 되살릴 수 있었다. 조언자 세벨은 바람의 왕자 썬더란을 해방할 열쇠, 바람추적자의 성검을 추적했다. 대영주 데미트리안을 찾아가 검을 다시 벼리고, 하늘 높이 올라갔다. 그곳에서 무기에 힘을 다시 채우고 썬더란의 속박을 끊었다. 바람군주가 풀려나자 그의 바람이 부서진 섬 전역에 울부짖었다. 그는 대지 고리회에 충성을 맹세했고, 바람의 기둥이 다시 타오르는 동안 집정관 셀레스토스와 노분도가 곁을 지켰다."
L["The Maelstrom's Air Pillar weakens. Reforge the Blessed Blade of the Windseeker and return Thunderaan to power."] = "혼돈의 소용돌이의 바람의 기둥이 약해지고 있다. 바람추적자의 성검을 다시 벼려 썬더란의 힘을 되찾아 주어야 한다."
L["The March to Nazmir"] = "나즈미르를 향하여"
L["The Marshal's Grave"] = "원수의 무덤"
L["The Masks We Wear"] = "가면무도회"
L["The Master"] = "주인"
L["The Master Awaits"] = "주인님이 기다리신다"
L["The Master of Lies"] = "거짓의 주인"
L["The Master of Revendreth"] = "레벤드레스의 주인"
L["The Master of Swords"] = "검의 대가"
L["The Master's Plan"] = "달인의 음모"
L["The Mead Master"] = "벌꿀술의 대가"
L["The Mech of Death"] = "죽음의 포격기"
L["The Might of the Horde"] = "호드의 힘"
L["The Might of the Tirisgarde"] = "티리스가드의 힘"
