L["The Mission"] = "임무"
L["The Monkey King"] = "원숭이 왕"
L["The MOTHERLODE!!"] = "왕노다지 광산!!"
L["The Murderous Matron"] = "치명적인 대모"
L["The Mysterious Island"] = "수수께끼의 섬"
L["The Mysterious Paladin"] = "의문의 성기사"
L["The Nation of Kul Tiras"] = "쿨 티라스"
L["The Nature of the Beast"] = "야수의 성질"
L["The Necropolis"] = "죽음의 사원"
L["The Nerubian Menace"] = "네루비안의 위협"
L["The Netherlord's Campaign"] = "황천군주의 대장정"
L["The New Blood"] = "새로운 피"
L["The New Clessington Estate"] = "새로운 클레싱턴 영지"
L["The New Guard"] = "새로운 수호자의 탄생"
L["The Next Level Has Arrived"] = "다음 단계로"
L["The Nightborne Apprentice"] = "나이트본 수습생"
L["The Nightborne Pact"] = "나이트본의 맹세"
L["The Nightfallen"] = "나이트폴른"
L["The Nighthold"] = "밤의 요새"
L["The Nighthold: Lord of the Shadow Council"] = "밤의 요새: 어둠의 의회 지도자"
L["The Nighthold: The Eye of Aman'Thul"] = "밤의 요새: 아만툴의 눈"
L["The Nighthuntress Beckons"] = "밤사냥꾼의 부름"
L["The Old Bear"] = "늙은 곰"
L["The Old Fashioned Way"] = "구닥다리 방식"
L["The Old Knight"] = "백전노장의 기사"
L["The Only Way Out is Through"] = "유일한 탈출구"
L["The Only Way to Travel"] = "유일한 이동 수단"
L["The Order of Embers"] = "잿불단"
L["The Path of the Dreadscar"] = "공포흉터의 길"
L["The Path of War"] = "전쟁의 길"
L["The Path to Salvation"] = "구원을 향한 길"
L["The Path to the Citadel"] = "성채로 가는 길"
L["The Peak of Bones"] = "뼈의 봉우리"
L["The Peak of Serenity falls to the Legion. Rally the surviving monks at the Temple of Five Dawns on the Wandering Isle."] = "평온의 봉우리가 군단에게 함락된다. 살아남은 수도사들을 유랑도의 다섯 새벽 사원으로 불러 모아야 한다."
L["The Pearlfin Situation"] = "진주지느러미 마을의 상황"
L["The Penitent Hunt"] = "참회의 사냥"
L["The Perfect Opportunity"] = "완벽한 기회"
L["The Pinnacle is won. Its flagstaff flies the white hand of the Argent Crusade above the whole of southern Icecrown. But at the edge of the Fleshwerks below, Crusader Bridenbrad is dying. The plague has him. Father Gustav cannot let a hero end this way. Keeper Remulos, Alexstrasza the Life-Binder, and A'dal — three ancient powers who still remember the Light — each in turn weigh the cost. Whatever answer comes will come in its own time. Meanwhile, gryphon-riders and wyvern-masters circle the Pinnacle, waiting to lift the next wave of soldiers up to the gunships — the Skybreaker and Orgrim's Hammer — hanging over the northern gates."] = "봉우리를 손에 넣었다. 그 깃대에는 은빛십자군의 하얀 손 깃발이 얼음왕관 남부 전역을 내려다보며 휘날린다. 하지만 아래쪽 살덩이작업장 가장자리에서 성전사 브라이든브래드가 죽어 가고 있다. 역병이 그를 집어삼켰다. 신부 구스타프는 영웅이 이렇게 끝나게 둘 수 없다. 수호자 레물로스, 생명의 어머니 알렉스트라자, 그리고 아달. 아직 빛을 기억하는 세 고대의 존재가 차례로 그 대가를 저울질한다. 어떤 답이 오든, 그것은 제때가 되어야 올 것이다. 그동안 그리핀 기수와 와이번 조련사들이 봉우리 위를 맴돌며, 북쪽 관문 위에 떠 있는 비행선 하늘파괴자호와 오그림의 망치호로 다음 병력을 실어 나를 때를 기다린다."
L["The Pirate's Bay"] = "해적의 만"
L["The Pit of Saron"] = "사론의 구덩이"
L["The Power of Thousands"] = "모두의 힘을 모아서"
L["The Power to Survive"] = "생존에 필요한 힘"
L["The Power Within"] = "잠재된 힘"
L["The Price of Victory"] = "승리의 대가"
L["The Pride of Kul Tiras"] = "쿨 티라스의 자존심"
L["The Pride of the Sin'dorei"] = "신도레이의 긍지"
L["The Purging Of Scourgeholme"] = "스컬지홀름 정화"
L["The Raven's Eye"] = "까마귀의 눈"
L["The rebellion emerged from hiding and seized the Waning Crescent district in an act of open defiance. You helped Oculeth triangulate and rescue an imprisoned ally put on public display as a warning, then established the first openly rebel-held territory in Suramar City. The Dusk Lily — the rebellion's symbol — flew for the first time where Elisande's banners once hung."] = "반란군은 은신처에서 나와 기우는 초승달 지구를 장악하며 공공연히 반기를 들었다. 오큘레스를 도와 본보기로 공개 전시된 동지의 위치를 삼각측량으로 찾아내 구출했고, 수라마르 성 안에 처음으로 반란군이 드러내 놓고 장악한 영토를 세웠다. 반란의 상징인 황혼 백합이 엘리산드의 깃발이 걸려 있던 자리에서 처음으로 휘날렸다."
L["The rebellion grows bolder, establishing a foothold in the Waning Crescent district of Suramar City."] = "더욱 대담해진 반란군이 수라마르 성의 기우는 초승달 지구에 거점을 마련한다."
L["The Remedy of Lordaeron"] = "로데론 개선책"
L["The Restless Dead"] = "안식 없는 죽음"
L["The Return of Twilight"] = "다시 드리워진 황혼"
L["The Rider of Blood"] = "혈기의 기수"
L["The Rider of Frost"] = "냉기의 기수"
L["The Rider of the Unholy"] = "부정의 기수"
L["The Rider's Bind"] = "기수의 교감"
L["The Right Tool For The Job"] = "일에 적합한 도구"
L["The Ritual of Tides"] = "파도의 의식"
L["The Road of Pain"] = "고통의 길"
L["The Road to Corlain"] = "콜레인으로 가는 길"
L["The Ruined Kingdom"] = "몰락한 왕국"
L["The Ruins of Gol Var"] = "골 바르 폐허"
L["The Rumpus"] = "난투극"
L["The Runesmiths of Malykriss"] = "말리크리스의 룬대장장이"
L["The Rush'kah"] = "러쉬카"
L["The saronite mines beneath Ymirheim are not just a supply line. They are something older, colder, and hungrier than any ore vein on Azeroth. The metal whispers. Miners chained to the walls hear their names called by voices they once loved. The Argent Crusade has quiet questions about what prolonged exposure does to a living mind. The answers do not make it out of the tunnels."] = "이미르하임 아래의 사로나이트 광산은 단순한 보급로가 아니다. 그것은 아제로스의 어떤 광맥보다 더 오래되고, 더 차갑고, 더 굶주린 무언가다. 금속이 속삭인다. 벽에 사슬로 묶인 광부들은 한때 사랑했던 이들의 목소리가 자신의 이름을 부르는 것을 듣는다. 은빛십자군은 그것에 오래 노출되면 살아 있는 정신이 어떻게 되는지 조용히 의문을 품는다. 그 답은 갱도 밖으로 나오지 못한다."
L["The Scarlet Assault"] = "붉은십자군 수도원 습격"
L["The Scarlet Commander"] = "붉은십자군 사령관"
L["The Scarlet Crusade has returned to Silverpine Forest. Lilian Voss needs a champion to go in quietly, earn their trust, and open the way for the Forsaken to strike."] = "붉은십자군이 은빛소나무 숲으로 돌아왔다. 릴리안 보스는 조용히 잠입해 그들의 신뢰를 얻고, 포세이큰이 공격할 길을 열어 줄 용사를 필요로 한다."
L["The Scarlet Halls"] = "붉은십자군 전당"
L["The Scarlet Massacre"] = "붉은십자군 학살의 날"
L["The Scarlet Monastery"] = "붉은십자군 수도원"
L["The Scarlet Onslaught — fanatical remnants of the Crusade — were gathering strength, and Faol saw an opportunity. You infiltrated their ranks disguised as an envoy, walking among zealots who would have burned you alive. Deep inside, you found Mariella — a heretic within their own ranks who had seen through the madness. You liberated her fellow apostates and brought Mariella Ward into the Conclave, her faith tempered by hard truth rather than blind fury."] = "십자군의 광신적인 잔당인 붉은십자군 돌격대가 세력을 키우고 있었고, 파올은 그것을 기회로 보았다. 사절로 변장해 그들의 대열에 잠입했고, 정체가 드러나면 산 채로 불태워 버렸을 광신도들 사이를 걸었다. 그 깊숙한 곳에서 광기의 실체를 꿰뚫어 본, 그들 내부의 이단자 마리엘라를 찾아냈다. 그녀와 뜻을 같이한 배교자들을 해방하고 마리엘라 워드를 회합으로 데려왔다. 그녀의 신앙은 맹목적인 분노가 아닌 냉엄한 진실로 단련되어 있었다."
L["The Scarlet Onslaught has buried itself in the black ice of western Icecrown. The fortress is called the Shadow Vault. High Abbot Landgren commands it now. The Ebon Blade's plan is ugly — wear the Scarlet's own colors, pray nobody looks twice, and open every door from the inside. When the Vault falls, Baron Sliver holds court in its upper halls. Vereth the Cunning sketches the roads out in blood. The Lich King's saronite quarries are pried open. Above the Vault, the flying necropolis of Malykriss still hangs, with four riders of the Bloodbane order riding out the apocalypse in miniature: one of the Unholy, one of Frost, one of Blood, and the name that binds them."] = "붉은십자군 돌격대가 얼음왕관 서부의 검은 얼음 속에 틀어박혔다. 그 요새의 이름은 어둠의 무기고다. 지금은 대수도원장 랜드그렌이 지휘하고 있다. 칠흑의 기사단의 계획은 추악하다. 붉은십자군의 군복을 입고, 아무도 두 번 쳐다보지 않기를 기도하며, 안에서부터 모든 문을 여는 것이다. 무기고가 함락되면 남작 슬리버가 위층 회랑에서 자리를 잡는다. 교활한 베레스는 피로 탈출로를 그린다. 리치 왕의 사로나이트 채석장이 비틀려 열린다. 무기고 위에는 여전히 하늘을 나는 네크로폴리스 말리크리스가 떠 있고, 블러드베인 기사단의 네 기수가 축소판 종말을 이끌고 달려 나온다. 부정의 기수, 냉기의 기수, 혈기의 기수, 그리고 그들을 하나로 묶는 이름이다."
L["The Scarlet Palisade"] = "단홍빛 울타리"
L["The Scarlet Spy"] = "붉은 첩자"
L["The Scent of Magic"] = "마법의 냄새"
L["The School of Roguery"] = "도적 기술 학교"
L["The Scourgestone"] = "스컬지석"
L["The Scouts Return"] = "정찰대의 귀환"
L["The Scryer's Dilemma"] = "점술가의 딜레마"
L["The Scythe of Elune"] = "엘룬의 낫"
L["The Seal is Broken"] = "깨어진 봉인"
L["The Seal's Power"] = "인장의 힘"
L["The Search for Vargoth"] = "바르고스 수색"
L["The search for Zin'jun began as a rescue and became a campaign. The hozen had stripped him of his gear, the Alliance had dug in at Strongarm Airstrip, and Nazgrim needed every advantage he could improvise. You recovered Zin'jun's belongings, assaulted the airstrip, broke key Alliance officers, and learned that Captain Doren had been consumed by the darkness Taran Zhu warned about. Kiryn and Rivett turned Alliance wreckage into intelligence and acid rain, and Nazgrim sent you to read the shape of the land itself. Lay of the Land was the hinge: the war had carried you this far, but Cho was waiting to show you what the Horde had actually stepped into."] = "진준을 찾는 일은 구출 작전으로 시작해 하나의 원정이 되었다. 호젠은 그의 장비를 빼앗아 갔고, 얼라이언스는 우격다짐 비행장에 진을 쳤으며, 나즈그림은 임기응변으로 짜낼 수 있는 모든 이점이 필요했다. 진준의 소지품을 되찾고, 비행장을 공격하고, 얼라이언스의 핵심 장교들을 무너뜨렸으며, 대장 도렌이 타란 주가 경고했던 어둠에 집어삼켜졌다는 것을 알게 되었다. 키린과 리벳은 얼라이언스의 잔해를 정보와 산성비로 바꾸어 놓았고, 나즈그림은 땅의 형세를 직접 살피라고 보냈다. 지형 파악은 전환점이었다. 전쟁은 여기까지 이끌어 왔지만, 초는 호드가 실제로 어디에 발을 들였는지 보여 주려고 기다리고 있었다."
L["The Seat of the Triumvirate"] = "삼두정의 권좌"
L["The second Horseman would be Thoras Trollbane, the warrior-king of Stromgarde who had been murdered by his own son. You traveled to the ruined kingdom where Trollbane's restless spirit lingered, betrayed even in death. Prince Galen, the traitor-son, stood in your way — but regicide was a small price for the Ebon Blade. You cut Galen down and raised his father, and Thoras Trollbane rode once more, his fury undimmed by centuries in the grave."] = "두 번째 기사는 친아들에게 살해당한 스트롬가드의 전사왕, 토라스 트롤베인이 될 것이었다. 트롤베인의 안식하지 못한 영혼이 죽어서도 배신당한 채 떠도는 폐허가 된 왕국으로 향했다. 배신자 아들 왕자 갈렌이 앞을 가로막았지만, 칠흑의 기사단에게 국왕 시해쯤은 사소한 대가였다. 갈렌을 베어 쓰러뜨리고 그 아버지를 일으키자, 토라스 트롤베인이 다시 말을 달렸다. 수백 년을 무덤에서 보냈어도 그의 분노는 조금도 사그라들지 않았다."
L["The Seed of Ages"] = "세월의 씨앗"
L["The Serpent's Heart"] = "용의 심장"
L["The Serpent's Heart gave the temple the jade it needed, but Yu'lon could not simply appear on command. Elder Sage Rain-Zhu sent you through the temple's doubts and duties: Wise Mari's scrying, Lorewalker Stonestep's living library, Fei's cloud serpents, and the fireworks that would light the sky for a rebirth. At last Yu'lon emerged, ancient and luminous, and thanked you for helping the forest remember hope. For a moment, it felt like the war might be smaller than the wonder around it."] = "용의 심장 덕분에 사원은 필요한 비취를 얻었지만, 위론은 부른다고 그냥 나타나지 않았다. 원로 현자 레인주는 사원의 의심과 의무를 하나씩 거치게 했다. 현명한 마리의 점술, 전승지기 스톤스텝의 살아 있는 도서관, 페이의 운룡들, 그리고 재탄생을 위해 하늘을 밝힐 불꽃놀이까지. 마침내 고대의 빛을 발하며 모습을 드러낸 위론은 숲이 희망을 기억하도록 도와준 것에 감사를 전했다. 잠시나마, 전쟁이 그 주변의 경이로움보다 작게 느껴졌다."
L["The Setting Sun"] = "지는 태양"
L["The Shadow of Death"] = "죽음의 그림자"
L["The Shadow of Gilneas"] = "길니아스의 그림자"
L["The Shadow Vault"] = "어둠의 무기고"
L["The Shadowblade's Campaign"] = "그림자칼날의 대장정"
L["The Shadows Reveal"] = "그림자 밖으로"
L["The Shardmaidens"] = "조각의 여주인"
L["The Silkwood Road"] = "명주숲으로 가는 길"
L["The Silver Hand"] = "은빛 성기사단"
L["The Silver Hand marshaled for war. You led the assault on Niskara — a demon world where Aponi Brightmane was held captive. Through waves of demons you fought, Aponi's libram serving as a beacon. When you found her, she was wounded but unbroken. Together with Delas Moonfang — who chose to become a paladin that day — you shattered the Legion's forces on Niskara. The mind of the enemy lay open, and the Silver Hand's unity was forged in fire."] = "은빛 성기사단이 전쟁을 위해 집결했다. 아포니 브라이트메인이 포로로 잡혀 있는 악마의 세계, 니스카라로 공격을 이끌었다. 아포니의 일지를 길잡이 삼아 밀려드는 악마의 물결을 뚫고 싸워 나갔다. 마침내 찾아낸 그녀는 상처를 입었지만 꺾이지 않은 상태였다. 그날 성기사가 되기로 결심한 델라스 문팽과 함께 니스카라의 군단 병력을 산산이 부수었다. 적의 속내가 낱낱이 드러났고, 은빛 성기사단의 결속은 불길 속에서 단련되었다."
L["The Sin'dorei remember through ritual, grief, and endurance. You carried the Sunwell's flame through Ghostlands and Quel'Danas, stood witness to the fall of legends, and helped preserve the memory that still defines your people."] = "신도레이는 의식과 슬픔, 그리고 인내로 기억한다. 유령의 땅과 쿠엘다나스를 지나 태양샘의 불꽃을 옮기고, 전설들의 몰락을 지켜보며, 동족을 지금도 정의하는 기억을 지켜 내도록 도왔다."
L["The Sinstone"] = "죄악석"
L["The Sixth"] = "여섯 번째"
L["The Skies Above"] = "비어있는 왕좌"
L["The Skybreaker"] = "하늘파괴자호"
L["The Skyfire reaches Pandaria hunting for Admiral Taylor and Prince Anduin, but the Alliance lands in the middle of a Horde war zone."] = "하늘불꽃호가 제독 테일러와 안두인 왕자를 찾아 판다리아에 도착하지만, 얼라이언스는 호드의 전쟁터 한복판에 내려앉는다."
L["The Slayer's Campaign"] = "학살자의 대장정"
L["The Solution Solution"] = "분해 용액"
L["The Speaker Awaits"] = "대변자가 기다린다"
L["The Spirit of the Hunter"] = "사냥꾼의 영혼"
L["The Spirit of Thunder Ridge"] = "천둥 마루의 영혼"
L["The spirits called, and you answered. By walking between worlds and standing with Baine and the spiritwalkers, you helped the Shu'halo restore harmony and honor their ancestors."] = "영혼들이 불렀고, 그 부름에 응했다. 두 세계 사이를 걸으며 바인과 영혼방랑자들 곁에 서서, 슈할로가 조화를 되찾고 선조를 기리도록 도왔다."
L["The Spiritwalkers"] = "영혼방랑자들"
L["The Splintered Path"] = "갈라진 길"
L["The Sprites' Plight"] = "곤경에 처한 요마"
L["The Stone That Started A Revolution"] = "혁명도 돌 하나에서 시작"
L["The Stoneborn"] = "돌숨결"
L["The Stormwind Extraction"] = "스톰윈드 침투"
L["The Strength of the Storm"] = "폭풍의 힘"
L["The Strike on Boralus"] = "보랄러스 습격"
L["The Strongarm Airstrip"] = "우격다짐 비행장"
L["The Stuff of Dreams"] = "꿈의 물건"
L["The Sum is Greater than the Parts"] = "뭉치면 세진다"
L["The Sunken Graveyard"] = "가라앉은 무덤"
L["The Sunken Vault"] = "가라앉은 석실"
L["The Sword of Kings"] = "왕의 검"
L["The Tale of Ban-Lu"] = "반루의 이야기"
L["The Temple of the Jade Serpent"] = "옥룡사"
L["The third Horseman would be the most controversial — High Inquisitor Whitemane of the Scarlet Crusade, a zealot who had burned the undead with holy fire for years. You led the assault on the Scarlet Monastery, cutting through fanatical defenders in a massacre that painted the halls red. When Whitemane fell, you raised her — and the woman who had sworn to destroy every death knight opened her eyes as one. The irony was not lost on anyone."] = "세 번째 기사는 가장 논란이 많은 선택이 될 것이었다. 수년간 언데드를 신성한 불길로 태워 온 광신도, 붉은십자군의 종교재판관 화이트메인이었다. 붉은십자군 수도원으로 공격을 이끌어, 회랑을 붉게 물들인 학살 속에서 광신적인 수비대를 베어 나갔다. 화이트메인이 쓰러지자 그녀를 일으켰다. 모든 죽음의 기사를 멸하겠다고 맹세했던 여인이 죽음의 기사가 되어 눈을 떴다. 그 아이러니를 모르는 이는 아무도 없었다."
L["The Threads that Stick"] = "끈끈한 실가닥"
L["The Three Sisters"] = "세 자매"
L["The time for subtlety had passed. You helped Oculeth build war machines, gathered supplies with Valtrois, trained civilian volunteers into a fighting force, and armed the rebellion with weapons taken from the Legion itself. When the trial by demonfire proved the rebels could hold their own, there was nothing left to do but march."] = "은밀하게 움직일 때는 지났다. 오큘레스를 도와 전쟁 기계를 만들고, 발트루아와 함께 물자를 모으고, 민간인 자원자들을 전투 병력으로 훈련시켰으며, 군단에게서 빼앗은 무기로 반란군을 무장시켰다. 악마불의 시련으로 반란군이 제 몫을 해낼 수 있음이 증명되자, 남은 일은 진군뿐이었다."
L["The time had come to strike at the Nightmare's heart. Keeper Remulos guided you through a rift into the Dream's darkest depths, where you relived the War of the Ancients — watching Archimonde the Defiler lay waste to the world ten thousand years ago. In that crucible of memory and shadow, you reached Malorne himself. The great white stag stirred, rose, and returned to the waking world. With the demi-god reborn and your weapon forged anew, the Cenarion Circle had become a force even the Legion feared."] = "악몽의 심장부를 칠 때가 왔다. 수호자 레물로스의 안내로 균열을 지나 꿈의 가장 어두운 심연으로 들어갔고, 그곳에서 고대의 전쟁을 다시 겪었다. 1만 년 전 파멸자 아키몬드가 세상을 황폐하게 만드는 광경을 지켜본 것이다. 기억과 어둠이 뒤엉킨 그 시련의 도가니 속에서 말로른에게 닿았다. 거대한 흰 수사슴이 꿈틀거리더니 일어나 깨어 있는 세계로 돌아왔다. 반신이 다시 태어나고 무기가 새로 벼려지자, 세나리온 의회는 군단마저 두려워하는 세력이 되었다."
L["The Tirisgarde needed power, and power came in the form of legends. Archmage Kalec — the blue dragon who once guarded the Sunwell — and Archmage Modera of the Council of Six both pledged their strength. Archmage Omniara trained troops while Archmage Melis provided the technical wizardry to keep the Hall of the Guardian running. The Tirisgarde was no longer a relic of history — it was a force."] = "티리스가드에는 힘이 필요했고, 그 힘은 전설의 모습으로 찾아왔다. 한때 태양샘을 지켰던 푸른용 대마법사 칼렉과 6인 의회의 대마법사 모데라가 모두 힘을 보태기로 맹세했다. 대마법사 옴니아라는 병력을 훈련시켰고, 대마법사 멜리스는 수호자의 전당이 굴러가도록 기술적인 마법을 제공했다. 티리스가드는 더 이상 역사의 유물이 아니었다. 하나의 세력이었다."
L["The Tirisgarde Reborn"] = "되살아난 티리스가드"
L["The titans built Uldir to study the Old Gods — to understand the corruption before they tried to cure it. What they created instead was G'huun: a proto-god of blood and shadow, born in a lab, every safeguard bypassed. Sealed in stasis for millennia, fed by the blood trolls until he was strong enough to break containment himself. Uldir was not a dungeon. It was a prison that had started to answer back.\n\nYou fought through the facility's corrupted wards — past G'huun's lieutenants, through the experiments that had gone wrong in the age before trolls had language — and reached the heart of the prison. G'huun fell. The blood god's thousand-year campaign to break free ended in the same titan vault it began in. Nazmir would take generations to recover. The trolls who had given their lives feeding G'huun would never be fully redeemed. But the earth was quiet again, and the seal held."] = "티탄은 고대 신을 연구하기 위해 울디르를 세웠다. 치료를 시도하기 전에 먼저 타락을 이해하려 한 것이다. 그러나 그들이 대신 만들어 낸 것은 그훈이었다. 실험실에서 태어나 모든 안전장치를 우회한, 피와 어둠의 원시 신이었다. 수천 년 동안 정지 상태로 봉인된 채, 피의 트롤들이 바친 피를 먹고 스스로 봉쇄를 깨뜨릴 만큼 강해졌다. 울디르는 던전이 아니었다. 그것은 반격하기 시작한 감옥이었다.\n\n시설의 타락한 결계를 뚫고, 그훈의 부관들을 지나, 트롤이 언어를 갖기도 전의 시대에 잘못되어 버린 실험들을 헤치고 감옥의 심장부에 이르렀다. 그훈이 쓰러졌다. 자유를 향한 피의 신의 천 년에 걸친 투쟁은 그것이 시작된 바로 그 티탄 금고에서 막을 내렸다. 나즈미르가 회복하려면 여러 세대가 걸릴 것이다. 그훈을 먹이느라 목숨을 바친 트롤들은 결코 완전히 구원받지 못할 것이다. 그러나 대지는 다시 고요해졌고, 봉인은 버텼다."
L["The Tome of Blighted Implements"] = "황폐화 도구의 고서"
L["The Touch of an Aspect"] = "위상의 손길"
L["The trail leads to Azsuna, where a leyworm infestation masks something far more dangerous. Hemet Nesingwary lends his expertise."] = "흔적은 아즈스나로 이어진다. 그곳에 들끓는 지맥벌레 뒤에는 훨씬 더 위험한 무언가가 숨어 있다. 헤멧 네싱워리가 전문 지식을 빌려준다."
L["The trail leads to Crusader's Run and the tower of High Priest Benedictus Voss. A daughter has come a long way to find her father — and what he says to her will determine everything."] = "흔적은 십자군의 터와 대사제 베네딕투스 보스의 탑으로 이어진다. 딸은 아버지를 찾아 먼 길을 왔다. 그리고 그가 딸에게 하는 말이 모든 것을 결정할 것이다."
L["The Trial of Ban-Lu"] = "반루의 시험"
L["The Trial of Rage"] = "분노의 시험"
L["The Truth of the Grave"] = "무덤의 진실"
L["The Twilight Master"] = "황혼의 지배자"
L["The Underrot"] = "썩은굴"
L["The Underrot: Sealing G'huun's Corruption"] = "썩은굴: 그훈의 타락체 봉인"
L["The Undersea Ledge"] = "깊은 바다 절벽"
L["The Unkillable"] = "무적자"
L["The Unseen Blade"] = "보이지 않는 검"
L["The Unseen Path"] = "드러나지 않은 길"
L["The unthinkable happened — the Peak of Serenity, the monks' sacred mountain, fell to a Legion assault. As smoke rose from the ruins, you gathered the survivors and led them to the Temple of Five Dawns on the Wandering Isle. There, Fearsome Jang named you Grandmaster of the order, and you claimed an artifact weapon to carry into the war ahead. Iron-Body Ponshu began organizing the scattered monks into a fighting force."] = "있을 수 없는 일이 일어났다. 수도사들의 성산인 평온의 봉우리가 군단의 공격에 함락된 것이다. 폐허에서 연기가 피어오르는 가운데 생존자들을 모아 유랑도의 다섯 새벽 사원으로 이끌었다. 그곳에서 용감무쌍한 장은 교단의 대사부로 임명했고, 다가올 전쟁에 들고 갈 유물 무기를 손에 넣었다. 철근육 폰슈는 흩어진 수도사들을 전투 병력으로 조직하기 시작했다."
L["The Val'kyr raise new Forsaken in the crypt of Deathknell. One of them is Lilian Voss — daughter of the Scarlet Crusade's High Priest, raised as the very thing she was trained to destroy."] = "발키르가 죽음의 종소리 마을의 지하묘지에서 새로운 포세이큰을 일으킨다. 그중 하나가 릴리안 보스다. 붉은십자군 대사제의 딸인 그녀는 멸하도록 훈련받았던 바로 그 존재로 되살아났다."
L["The Valewalker's Burden"] = "계곡방랑자의 짐"
L["The Valley of Echoes is a bowl of old Scourge work. Plague altars cough smoke into the wind; restless dead pace the rim by moonlight. Father Gustav wants scourgestones. The Ebon Watcher wants the altars cold. The Argent Crusade wants the road cleared north — to the Pinnacle, where Tirion Fordring has already set his banner. When the banner flies, the whole rim of Icecrown hears it, and the gunships in the northern sky start warming their engines."] = "메아리 골짜기는 스컬지가 오래전에 만들어 놓은 분지다. 역병 제단은 바람 속으로 연기를 토해 내고, 안식하지 못한 망자들은 달빛 아래 가장자리를 서성인다. 신부 구스타프는 스컬지석을 원한다. 칠흑의 감시자는 제단이 식기를 원한다. 은빛십자군은 북쪽 길이 뚫리기를 원한다. 티리온 폴드링이 이미 깃발을 꽂은 봉우리로 가는 길이다. 그 깃발이 휘날리면 얼음왕관 가장자리 전체가 그 소식을 듣고, 북쪽 하늘의 비행선들이 엔진을 데우기 시작한다."
L["The Vanguard's wreckage proved Anduin had survived, but it also pulled the Alliance into the Pearlfin jinyu's crisis. Taylor and Bold Karasshi had been captured by the Slingtail hozen, and the only way forward was through the pits. You freed prisoners, recovered waterspeaker relics, broke Kung Din's hold, and helped the Pearlfin decide whether the Alliance deserved their trust. SI:7's reports then made the bargain real: the Horde had armed the hozen, so Taylor trained the jinyu to fight back. When the trail finally led to Cho, the search changed shape. Tea, stories, and a strange brew opened the way to Anduin, who was already choosing curiosity over command."] = "선봉호의 잔해는 안두인이 살아남았다는 증거였지만, 동시에 얼라이언스를 진주지느러미 진위의 위기 속으로 끌어들였다. 테일러와 대담한 카라쉬는 투석꼬리 호젠에게 사로잡혔고, 앞으로 나아갈 길은 구덩이를 지나는 것뿐이었다. 포로들을 풀어 주고, 물의 대변자의 유물을 되찾고, 쿵 딘의 지배를 무너뜨리며, 진주지느러미가 얼라이언스를 믿을 수 있을지 판단하도록 도왔다. 이어 SI:7의 보고가 이 거래를 현실로 만들었다. 호드가 호젠을 무장시켰으니, 테일러는 진위가 맞서 싸울 수 있도록 훈련시켰다. 마침내 흔적이 초에게 이어지자, 수색은 모습을 바꾸었다. 차와 이야기, 그리고 묘한 술 한 잔이 안두인에게 가는 길을 열었다. 안두인은 이미 지휘보다 호기심을 택하고 있었다."
L["The Vanishing Lord"] = "사라진 군주"
L["The Vault of the Tirisgarde"] = "티리스가드의 금고"
L["The Vile Hold"] = "타락의 요새"
L["The Village of Glenbrook"] = "글렌브룩 마을"
L["The Vindicator's Plea"] = "구원자의 탄원"
L["The Violet Citadel, Dalaran"] = "보랏빛 성채, 달라란"
L["The VIP List"] = "귀빈 명부"
L["The voice in the dark has a name now — Matthias Lehner. He claims to know the Lich King better than any living thing should. His memories run like a buried river through the Frozen Wastes. He leads you to a dragon's corpse. To a hunter and a prince. To the knowledge that cannot be unknown. Whether he can be trusted is a judgement you will make when the road ends — at the foot of the citadel, where Tirion Fordring lifts the Ashbringer and calls for one more charge."] = "어둠 속의 목소리에게 이제 이름이 생겼다. 마시어스 레넷이다. 그는 어떤 살아 있는 존재보다도 리치 왕을 잘 안다고 주장한다. 그의 기억은 얼어붙은 황무지 밑을 흐르는 지하수처럼 이어진다. 그는 용의 시체로, 사냥꾼과 왕자에게로, 한번 알면 되돌릴 수 없는 지식으로 이끈다. 그를 믿을 수 있는지는 길이 끝나는 곳에서 판단하게 될 것이다. 성채의 발치, 티리온 폴드링이 파멸의 인도자를 들어 올리며 마지막 돌격을 외치는 그곳에서."
L["The Wakening"] = "각성"
L["The Wanderer's Companion"] = "방랑자의 친구"
L["The Wanderers"] = "방랑자"
L["The Waning Crescent"] = "기우는 초승달"
L["The war at sea gave the Horde what blades on land could not: Derek Proudmoore, heir to Kul Tiras, dead at the bottom of the ocean. Hobart Grapplehammer put you in a diving suit and you went down. The ocean floor was littered with the wreckage of the battle — dog tags, sunken ships, the bones of sailors on both sides. You found Derek and hauled him up. No one said what Sylvanas would do with him. No one had to."] = "해상 전쟁은 지상의 칼날로는 얻을 수 없던 것을 호드에게 안겨 주었다. 쿨 티라스의 후계자 데릭 프라우드무어가 바다 밑바닥에 죽어 있었다. 호바트 그래플해머가 잠수복을 입혀 주었고, 그렇게 깊은 바다로 내려갔다. 해저에는 전투의 잔해가 널려 있었다. 인식표와 가라앉은 배들, 그리고 양 진영 선원들의 뼈였다. 데릭을 찾아 끌어 올렸다. 실바나스가 그를 어떻게 할지는 아무도 말하지 않았다. 말할 필요도 없었다."
L["The war ended. Sylvanas was gone. And Lilian Voss led the Forsaken home.\n\nThey came back to ruins — streets flooded with Blight, Undercity dark and broken. Calia Menethil walked beside her, daughter of the last king of Lordaeron, and between the two of them they held the Forsaken together through all of it: the plague work, the dead to bury, the city to reclaim room by room. At the end they formed the Desolate Council — Lilian, Calia, Velonara, Belmont, Faranell — not a Dark Lady, not a warchief. A council. Their own.\n\nLilian Voss, who had spent her whole life as something to be used and discarded, had become the person her people followed home."] = "전쟁이 끝났다. 실바나스는 떠났다. 그리고 릴리안 보스가 포세이큰을 이끌고 고향으로 돌아왔다.\n\n그들이 돌아온 곳은 폐허였다. 거리는 역병으로 넘쳐흘렀고, 언더시티는 어둡게 무너져 있었다. 로데론 최후의 왕의 딸, 칼리아 메네실이 그녀 곁을 걸었다. 두 사람은 함께 그 모든 시간 동안 포세이큰을 하나로 지켜 냈다. 역병을 치우고, 망자를 묻고, 도시를 방 하나하나 되찾아 갔다. 그리고 마침내 황폐의 의회를 세웠다. 릴리안, 칼리아, 벨로나라, 벨몬트, 파라넬. 어둠의 여왕도, 대족장도 아닌 의회였다. 그들 자신의 의회였다.\n\n평생을 이용당하고 버려지는 존재로 살아온 릴리안 보스는, 이제 동족이 따라 고향으로 돌아오는 사람이 되어 있었다."
L["The War for Silverpine"] = "은빛소나무 숲 전쟁"
L["The war in the Shadowlands is over. Sylvanas stands before those she has wronged — and must face what comes next."] = "어둠땅의 전쟁은 끝났다. 실바나스는 자신이 상처 입힌 이들 앞에 서서, 앞으로 다가올 일을 마주해야 한다."
L["The war moves to the Broken Shore. Aethas Sunreaver leads the Tirisgarde's assault, and you earn the Archmage's Prismatic Disc."] = "전쟁의 무대가 부서진 해변으로 옮겨 간다. 에이타스 선리버가 티리스가드의 공세를 이끌고, 대마법사의 분광 원반을 손에 넣는다."
L["The war moves to the Broken Shore. Contend with Magatha Grimtotem, secure Smolderon's flame, and earn a mount of living storm."] = "전쟁의 무대가 부서진 해변으로 옮겨 간다. 마가타 그림토템을 상대하고, 스몰데론의 불꽃을 확보해, 살아 있는 폭풍의 탈것을 얻어야 한다."
L["The war moves to the Broken Shore. Lead the Unseen Path against the Legion's corrupted beasts and earn the trust of a loyal wolfhawk."] = "전쟁의 무대가 부서진 해변으로 옮겨 간다. 보이지 않는 길을 이끌고 군단의 타락한 야수들에 맞서, 충성스러운 늑대매의 신뢰를 얻어야 한다."
L["The war moves to the Broken Shore. Rally the Valarjar for a final push, brave the depths of Helheim, and earn your war wyrm."] = "전쟁의 무대가 부서진 해변으로 옮겨 간다. 발라리아르를 결집해 마지막 공세에 나서고, 헬하임의 심연을 견뎌 내, 전쟁 비룡을 손에 넣어야 한다."
L["The War of the Ancients"] = "고대의 전쟁"
L["The War of Thorns"] = "가시의 전쟁"
L["The war reaches the Broken Shore. Break a family curse, then forge the Highlord's Golden Charger at the Hammer of Dalaran."] = "전쟁이 부서진 해변에 이른다. 한 가문의 저주를 풀고, 달라란의 망치에서 대영주의 황금 군마를 벼려 내야 한다."
L["The war reaches the Broken Shore. Defend the wilds, recruit Thisalee Crow, and earn the Archdruid's Lunarwing flight form."] = "전쟁이 부서진 해변에 이른다. 야생을 지키고, 티살리 크로우를 영입해, 대드루이드의 달날개 비행 변신을 얻어야 한다."
L["The War Within"] = "내부 전쟁"
L["The Warchief Cometh"] = "대족장의 등장"
L["The Warchief sets her sights on Darkshore. What unfolds there will make the Fourth War impossible to contain."] = "대족장이 어둠해안을 노린다. 그곳에서 벌어질 일로 인해 제4차 대전쟁은 더 이상 걷잡을 수 없게 될 것이다."
L["The Warchief's Fleet"] = "대족장의 함대"
L["The Warsong at the Wrathgate"] = "분노의 관문의 전쟁노래 부족"
L["The Warswords of the Valarjar called to you — twin blades said to contain the fury of a hundred battles. Odyn sent you to Stormheim to hunt the hero-slayer who had stolen them. Through storm and fire, you tracked the thief to their lair and pried the swords from their grip. The runes along the blades blazed to life in your hands, as if they had been waiting."] = "발라리아르의 전쟁검이 부르고 있었다. 백 번의 전투에서 쌓인 분노가 깃들어 있다는 쌍검이었다. 오딘은 검을 훔쳐 간 영웅 학살자를 사냥하라며 스톰하임으로 보냈다. 폭풍과 불길을 뚫고 도둑의 소굴까지 추적해 그 손아귀에서 검을 빼앗았다. 칼날을 따라 새겨진 룬이 손안에서 살아난 듯 타올랐다. 마치 오랫동안 기다려 온 것처럼."
L["The Way Back Home"] = "집으로 돌아가는 길"
L["The Way of the Tiger"] = "백호의 길"
L["The Waycrest Daughter"] = "웨이크레스트 가문의 딸"
L["The Wayward Crone"] = "문제의 마녀"
L["The Wayward Dead"] = "방황하는 망자"
L["The White Pawn"] = "하얀 싹"
L["The Will of the Naaru"] = "나루의 의지"
L["The Winter Queen needs anima, and Revendreth is supposed to be the realm that knows how to harvest it. Your request begins in Darkhaven, where every sin has a stone."] = "겨울 여왕에게는 령이 필요하다. 그리고 레벤드레스는 령을 거두는 법을 아는 왕국이어야 한다. 요청은 모든 죄마다 돌이 하나씩 있는 곳, 어둠안식처에서 시작된다."
L["The witch hunt turned on Lucille herself — Marshal Everit Reade accused the Waycrest daughter of sorcery. In a land gripped by paranoid suspicion, even nobility was not above the trials. You gathered proof of Lucille's innocence through the marshal's superstitious tests: walking through the woods that watched, enduring ambush, and passing the trial by superstition. A pungent alchemical solution revealed the true witches hiding in plain sight. The burden of proof was met, but the experience left its mark — in Drustvar, trust was a luxury no one could afford."] = "마녀사냥의 칼끝이 루실 자신을 향했다. 치안대장 에버릿 리드가 웨이크레스트 가문의 딸을 마법을 부린 죄로 고발한 것이다. 편집증적인 의심에 사로잡힌 땅에서는 귀족조차 시련을 피할 수 없었다. 치안대장의 미신에 찌든 시험을 거치며 루실의 결백을 입증할 증거를 모았다. 지켜보는 숲을 지나고, 매복을 견뎌 내고, 미신의 시련을 통과했다. 코를 찌르는 연금술 용액이 버젓이 숨어 있던 진짜 마녀들의 정체를 드러냈다. 입증 책임은 다했지만, 그 경험은 흔적을 남겼다. 드러스트바에서 신뢰란 누구도 누릴 수 없는 사치였다."
L["The Witchwood of Drustvar"] = "드러스트바의 마녀림"
L["The Woods Have Eyes"] = "숲의 감시자들"
L["The World is Not Enough"] = "세상은 좁다"
L["The Wrathgate"] = "분노의 관문"
L["The Wrathsteed of Xoroth"] = "소로시안 분노마"
L["The Zealot Rises"] = "광신도의 부활"
L["The zone ends where its warning began: inside the Temple of the Jade Serpent. The sha has seeped into wisdom, memory, discipline, and flame. Wise Mari, Lorewalker Stonestep, Liu Flameheart, and the temple's defenders are all trapped in doubt's reflection. By cleansing the temple and defeating the Sha of Doubt, you do what the armies outside could not: stop feeding the darkness long enough to face it. The Jade Forest is not untouched anymore. It is wounded, changed, and still alive."] = "이 지역의 이야기는 경고가 시작된 곳에서 끝난다. 바로 옥룡사 안이다. 샤가 지혜와 기억, 수련, 그리고 불꽃에까지 스며들었다. 현명한 마리, 전승지기 스톤스텝, 리우 플레임하트, 그리고 사원의 수호자들이 모두 의심이 비추는 환영에 갇혀 있다. 사원을 정화하고 의심의 샤를 물리침으로써, 바깥의 군대가 해내지 못한 일을 해낸다. 어둠을 마주할 수 있을 만큼 오래, 어둠에 먹이를 주는 일을 멈춘 것이다. 비취 숲은 이제 더 이상 온전하지 않다. 상처 입고 변했지만, 여전히 살아 있다."
L["Theotar"] = "테오타르"
L["Theotar, the Mad Duke, may know where Prince Renathal is. His ruined tea party leads through the Light-scarred Ember Ward and back to Sinfall."] = "미친 공작 테오타르는 왕자 레나탈의 행방을 알고 있을지도 모른다. 엉망이 된 그의 다과회는 빛에 그을린 잿불 지구를 지나 다시 죄악의 몰락지로 이어진다."
L["Theotar's Mission"] = "테오타르의 임무"
L["Therazane"] = "테라제인"
L["Therazane the Stonemother sent a tremor through the Maelstrom — a cry for help. Deepholm, the elemental plane of earth, was being consumed by the Twilight's Hammer once more. You descended into the stone realm and found Therazane besieged, her domain crumbling. Together you destroyed the cult's forces, unmasked their master's plan, and unleashed the elements against them. Therazane promised the earth's strength to the Earthen Ring, and Muln Earthfury pledged himself as your champion."] = "바위어머니 테라제인이 혼돈의 소용돌이로 진동을 보냈다. 도움을 청하는 외침이었다. 대지의 정령계인 심원의 영지가 또다시 황혼의 망치단에게 잠식당하고 있었다. 바위의 영역으로 내려가 보니, 테라제인은 포위당한 채 영지가 무너져 내리고 있었다. 함께 이교단의 병력을 섬멸하고, 그들의 주인이 꾸민 계획을 폭로했으며, 정령들의 힘을 풀어 그들에게 맞섰다. 테라제인은 대지 고리회에 대지의 힘을 약속했고, 멀른 어스퓨리는 용사로서 충성을 맹세했다."
L["There is Another"] = "하나 더"
L["There Is No Plan \"B\""] = "다른 계획은 있을 수 없다"
L["Theryn"] = "테린"
L["They Move Against Us"] = "적의 동향"
L["They Will Know Fear"] = "공포를 선사하노라"
L["They Won't Know What Hit Them"] = "의표를 찌르는 묘수"
L["They're So Thorny!"] = "앗 따가워!"
L["Things Gaardoun Needs"] = "가르둔에게 필요한 것"
L["Thinly Veiled Threats"] = "드리운 위협"
L["This Ain't Mine"] = "지뢰밭 개간"
L["This Is Retribution"] = "이것이 응징이다"
L["This is the Hour of the Forsaken"] = "포세이큰의 시간"
L["This Land is Ours"] = "우리의 영토"
L["This Time, Leave a Trail"] = "이번엔 흔적을 남기자"
L["This Was Home"] = "고향이었던 것"
L["Thisalee Crow"] = "티살리 크로우"
L["Thomas Zelling"] = "토마스 젤링"
L["Thomas Zelling was a dying tidesage who traded his humanity for undeath, desperate for a few more years with his family. You and Lilian performed the ritual that raised him — and then watched his wife recoil in horror from the husband she no longer recognized. Lilian stood in silence as the scene played out, seeing her own story reflected in Zelling's shattered face. To be Forsaken, she finally understood, was not just a curse of the body."] = "토마스 젤링은 가족과 몇 년이라도 더 함께하기 위해 인간성을 버리고 언데드가 되기를 택한, 죽어 가던 파도현자였다. 릴리안과 함께 그를 되살리는 의식을 치렀다. 그리고 그의 아내가 더는 알아볼 수 없게 된 남편에게서 공포에 질려 물러서는 모습을 지켜보았다. 릴리안은 그 장면을 말없이 바라보며, 산산이 부서진 젤링의 얼굴에서 자신의 이야기를 보았다. 포세이큰이 된다는 것은 단지 육신의 저주만이 아니라는 것을, 그녀는 마침내 깨달았다."
L["Thorim"] = "토림"
L["Those Scrying Eyes"] = "점술의 눈"
L["Thousands of Years Ago..."] = "수천 년 전에는..."
L["Thrall"] = "스랄"
L["Thrall calls you to the Maelstrom, where the Earthen Ring fights to keep the world from tearing apart."] = "스랄이 혼돈의 소용돌이로 부른다. 그곳에서는 대지 고리회가 세상이 찢어지지 않도록 사투를 벌이고 있다."
L["Thrall could no longer hear the elements. The Doomhammer — Orgrim's weapon, carried through the First and Second Wars — had gone silent in his hands. He passed it to you, and the moment your fingers closed around the haft, thunder split the sky. The elements had chosen a new wielder. The Doomhammer was yours."] = "스랄은 더 이상 정령의 목소리를 들을 수 없었다. 1차, 2차 대전쟁을 거쳐 온 오그림의 무기, 파멸의 망치가 그의 손에서 침묵해 버린 것이다. 스랄이 망치를 건네주었고, 손가락이 자루를 감싸 쥐는 순간 천둥이 하늘을 갈랐다. 정령들이 새로운 주인을 선택했다. 파멸의 망치는 이제 새 주인의 것이었다."
L["Thrall passes the Doomhammer to you — the weapon of Orgrim Doomhammer, carried through two wars and across worlds."] = "스랄이 파멸의 망치를 건네준다. 두 번의 전쟁을 거치고 여러 세계를 건너온 오그림 둠해머의 무기다."
L["Thrall's summons brought you to the edge of the Maelstrom — the wound in the world where Deathwing had nearly torn Azeroth asunder. The Earthen Ring was losing the fight to hold it together. Farseer Nobundo stood at the eye of the storm, channeling what remained of the ring's power. You claimed an artifact weapon attuned to the elements, and Stormcaller Mylra and Duke Hydraxis pledged themselves as your first champions. The elements were restless — and they were listening."] = "스랄의 부름을 받고 혼돈의 소용돌이 끝자락에 이르렀다. 데스윙이 아제로스를 거의 갈라놓을 뻔했던 세상의 상처였다. 대지 고리회는 그것을 붙들어 두기 위한 싸움에서 밀리고 있었다. 선견자 노분도는 폭풍의 눈에 서서 고리회에 남은 힘을 끌어모으고 있었다. 정령과 조화를 이루는 유물 무기를 손에 넣었고, 폭풍소환사 마일라와 군주 히드락시스가 첫 용사로서 충성을 맹세했다. 정령들은 불안해하고 있었다. 그리고 귀를 기울이고 있었다."
L["Three Horsemen rode, but the fourth seat remained empty. The Lich King demanded a champion of unmatched power — and the only candidate lay buried beneath Light's Hope Chapel itself. You stormed the most sacred ground on Azeroth, battling paladins and holy guardians, only for the assault to fail against the Chapel's consecrated power. In the end, it was Darion Mograine who knelt and gave himself — dying so he could rise as the Fourth Horseman. With your weapon forged anew and all four riders assembled, you were named Deathlord of the Ebon Blade."] = "세 명의 기사가 일어섰지만, 네 번째 자리는 여전히 비어 있었다. 리치 왕은 비할 데 없는 힘을 지닌 용사를 요구했고, 유일한 후보는 희망의 빛 예배당 바로 아래에 묻혀 있었다. 아제로스에서 가장 신성한 땅으로 쳐들어가 성기사들과 성스러운 수호자들과 싸웠지만, 공격은 예배당의 축성된 힘 앞에 무너지고 말았다. 결국 무릎을 꿇고 자신을 바친 것은 다리온 모그레인이었다. 그는 죽음으로써 네 번째 기사로 일어섰다. 무기가 새로 벼려지고 네 기사가 모두 모이자, 칠흑의 기사단의 죽음군주라는 칭호를 받았다."
L["Throne of the Tides"] = "파도의 왕좌"
L["Thros, the Blighted Lands"] = "파멸의 땅 트로스"
L["Through Ly'leth Lunastre's connections, you obtained a magical disguise and walked the gilded streets of Suramar City as one of the Nightborne elite. Behind the masks and pleasantries, you made first contact with sympathizers among the nobility — those who whispered against Elisande but dared not act alone."] = "라일레스 루나스트르의 인맥을 통해 마법 변장을 손에 넣고, 나이트본 귀족의 일원으로서 수라마르 성의 화려한 거리를 거닐었다. 가면과 예의 바른 인사 뒤에서, 귀족들 가운데 뜻을 함께하는 이들과 처음으로 접촉했다. 엘리산드를 향해 불만을 속삭이면서도 홀로 나설 용기는 없던 이들이었다."
L["Through the Emerald Dreamway, you discover the Dreamgrove: a sanctuary of nature hidden in Val'sharah. The Legion's war is spreading into places that should have been beyond its reach.\n\nAs Archdruid of the Cenarion Circle, heal the wounds of the Nightmare, gather ancient allies, and call on powers older than any mortal battlefield."] = "에메랄드의 꿈길을 지나, 발샤라에 숨겨진 자연의 성소 꿈숲을 발견합니다. 군단의 전쟁은 결코 닿아서는 안 될 곳까지 번지고 있습니다.\n\n세나리온 의회의 대드루이드로서 악몽이 남긴 상처를 치유하고, 고대의 동맹을 모으고, 필멸자의 어떤 전장보다도 오래된 힘을 불러내십시오."
L["Through the Eye"] = "리치 왕의 눈으로"
L["Through the Old Roads"] = "옛길을 달려서"
L["Through the Shattered Sky"] = "산산이 조각난 하늘을 가로질러"
L["Through trogg-infested ruins, ancient records, and the heat of the forge, you helped restore a lost legacy and carry the mountain king's heritage into the present."] = "트로그가 들끓는 폐허와 고대의 기록, 그리고 대장간의 열기를 거쳐, 잃어버린 유산을 되살리고 산왕의 유산을 오늘날로 이어 가도록 도왔다."
L["Throwing SI:7 Off the Trail"] = "SI:7 따돌리기"
L["Thunder Bluff / Mulgore / Stonetalon"] = "썬더 블러프 / 멀고어 / 돌발톱 산맥"
L["Thunderaan"] = "썬더란"
L["Thurgaden's Designs"] = "투르가덴의 설계도"
L["Thus Begins the War"] = "이렇게 전쟁은 시작된다"
L["Tian Monastery"] = "티엔 수도원"
L["Tian Monastery is under siege. Fight alongside Taran Zhu and The Monkey King to drive back the Legion and rebuild the order."] = "티엔 수도원이 포위당했다. 타란 주와 원숭이 왕과 함께 싸워 군단을 몰아내고 교단을 재건해야 한다."
L["Tian Monastery offered a different kind of strength. You entered as a guest, sat at the banquet, then trained under masters who cared as much about patience as power. You made a weapon with Groundskeeper Wu, learned precision from Instructor Xann, faced sparring partners who turned humility into bruises, and endured the Rumpus without mistaking chaos for victory. Flying Colors was more than a graduation. It was Pandaria quietly asking whether you could be taught."] = "티엔 수도원은 다른 종류의 힘을 보여 주었다. 손님으로 들어가 연회 자리에 앉았고, 이어 힘만큼이나 인내를 중시하는 스승들 밑에서 수련했다. 관리인 우와 함께 무기를 만들고, 교관 산에게서 정밀함을 배웠으며, 겸손을 멍으로 가르쳐 주는 대련 상대들과 맞섰고, 혼돈을 승리로 착각하지 않으며 난장판을 견뎌 냈다. 완벽한 마무리는 단순한 수료식이 아니었다. 판다리아가 과연 배울 수 있는 자인지 조용히 묻는 자리였다."
L["Tickets, Please?"] = "표 검사가 있겠습니다"
L["Tide of Virmen"] = "토깽의 파도"
L["Tidesage Teachings"] = "파도현자의 가르침"
L["Time Flies When Yer Havin' Rum!"] = "럼주와 함께라면 뭐든 할 수 있어!"
L["Time for Answers"] = "응답할 시간"
L["Time is of the Essence"] = "시간이 없다!"
L["Time to Hide"] = "숨을 시간"
L["Time Yet Remains"] = "아직 시간은 있다"
L["Tiragarde Sound was rotting at its foundations. Priscilla Ashvane and the Ashvane Trading Company had corrupted the Admiralty's supply lines, bribed its officers, and turned institutional loyalty into a private racket — all while Katherine Proudmoore remained in the dark, managing the public appearances of a nation that was quietly being hollowed out beneath her. You dismantled the operation piece by piece, surfacing the evidence until the case against Ashvane was undeniable. Katherine met with Genn Greymane in Boralus Harbor. She still had not spoken to Jaina."] = "티라가드 해협은 그 토대부터 썩어 가고 있었다. 프리실라 애쉬베인과 애쉬베인 무역 회사는 해군성의 보급망을 부패시키고, 장교들을 매수했으며, 조직에 대한 충성을 사적인 돈벌이로 바꾸어 놓았다. 그동안 캐서린 프라우드무어는 아무것도 모른 채, 발밑에서 조용히 속이 비어 가는 나라의 겉모습을 관리하고 있었다. 그 조직을 하나하나 해체하며, 애쉬베인의 혐의를 부정할 수 없을 때까지 증거를 드러냈다. 캐서린은 보랄러스 항구에서 겐 그레이메인을 만났다. 그녀는 여전히 제이나와 이야기를 나누지 않았다."
L["Tirion's Gambit"] = "티리온의 계략"
L["Tirion's Help"] = "티리온의 도움"
L["Tirisfal Glades / Kul Tiras / Lordaeron"] = "티리스팔 숲 / 쿨 티라스 / 로데론"
L["Tirisfal Glades / Silverpine Forest"] = "티리스팔 숲 / 은빛소나무 숲"
L["Titan Keeper Hezrel"] = "티탄 수호자 헤즈렐"
L["Titan Keeper Hezrel had been running containment protocols in Nazmir longer than any troll civilization had existed. His facility was damaged, his routines degraded, and the thing he was containing was actively working to get out. G'huun — a failed titan experiment, a blood god born in a lab and deemed too dangerous to destroy — had been sealed beneath Nazmir since before the trolls arrived. You helped Hezrel repair his systems, purified the corrupted earth, cleared the undead and void creatures that had crept into the facility, and restored the containment. For now. What had already escaped, and the blood trolls' true purpose — feeding G'huun until he broke free on his own terms — was only becoming clear."] = "티탄 수호자 헤즈렐은 어떤 트롤 문명이 존재했던 시간보다도 오래 나즈미르에서 봉쇄 절차를 수행해 왔다. 그의 시설은 손상되었고, 일상 절차는 망가졌으며, 그가 가두고 있던 존재는 적극적으로 빠져나가려 하고 있었다. 그훈. 실패한 티탄의 실험이자, 실험실에서 태어나 파괴하기에도 너무 위험하다고 판단된 피의 신이었다. 그는 트롤들이 오기 전부터 나즈미르 아래에 봉인되어 있었다. 헤즈렐을 도와 시스템을 수리하고, 타락한 대지를 정화하고, 시설에 스며든 언데드와 공허의 존재들을 처치해 봉쇄를 되살렸다. 당분간은. 이미 빠져나간 것이 무엇인지, 그리고 그훈이 스스로 원하는 때에 풀려날 때까지 그를 먹여 살리는 피의 트롤들의 진짜 목적이 무엇인지가 이제야 드러나고 있었다."
