L["Torga, ancient sea turtle loa of Nazmir, is dying. The blood trolls have bled him for decades. You arrive too late to save him — but not too late to release him."] = "나즈미르의 고대 바다거북 로아, 토르가가 죽어 가고 있다. 피의 트롤들이 수십 년 동안 그의 피를 뽑아 왔다. 그를 구하기에는 너무 늦었지만, 그를 놓아주기에는 아직 늦지 않았다."
