L["Track down the Fangs of Ashamane, twin daggers imbued with the spirit of the wild god of feral druids."] = "야성 드루이드의 야생신이 지닌 영혼이 깃든 쌍단검, 아샤메인의 송곳니를 추적해야 한다."
L["Track down the legendary assassination daggers once wielded by Garona Halforcen, hidden away after the fall of a king."] = "한때 가로나 하프오큰이 휘둘렀던 전설적인 암살 단검을 추적해야 한다. 한 왕이 쓰러진 뒤 숨겨진 단검이다."
L["Track down Titanstrike, a legendary rifle forged by the titan keeper Mimiron, lost in the wilds of Ulduar."] = "티탄 관리인 미미론이 벼려 낸 전설적인 소총, 티탄의 일격을 추적해야 한다. 울두아르의 야생 어딘가에서 사라진 무기다."
