L["Travel from the Exodar to Bloodmyst Isle and onward to the broken sky of Outland, retracing the long flight of a people who have lost more worlds than most have ever known. The past is not distant for the draenei; it is written into every refuge.\n\nStand on ground still marked by betrayal, ask what faith can carry through grief, and help forge a future worthy of draenei endurance."] = "엑소다르에서 핏빛안개 섬을 거쳐 아웃랜드의 부서진 하늘까지, 대부분의 이들이 알지도 못하는 만큼 많은 세계를 잃어 온 한 민족의 기나긴 피난길을 되짚어 갑니다. 드레나이에게 과거는 먼 이야기가 아닙니다. 그들이 머문 모든 안식처에 새겨져 있습니다.\n\n아직 배신의 흔적이 남은 땅에 서서, 신앙이 슬픔을 어디까지 견뎌 낼 수 있는지 묻고, 드레나이의 인내에 걸맞은 미래를 함께 만들어 가십시오."
