L["Under Ly'leth Lunastre's guidance, you plunged into the viper pit of Nightborne politics — buying votes, silencing rivals, and navigating a web of alliances that shifted with every whispered rumor. Through cunning and carefully applied force, Ly'leth secured her position among the nobility and opened the path to the Arcway, an ancient tunnel network running beneath the city."] = "라일레스 루나스트르의 지도 아래, 독사 소굴 같은 나이트본 정치판에 뛰어들었다. 표를 사고, 경쟁자들의 입을 막고, 속삭이는 소문 하나에도 뒤바뀌는 동맹의 그물망을 헤쳐 나갔다. 교활한 수완과 신중하게 휘두른 힘으로, 라일레스는 귀족 사이에서 입지를 굳혔고 도시 아래를 가로지르는 고대의 지하 통로망, 비전로로 향하는 길을 열었다."
L["Undercover Sista"] = "잠입 요원 자매"
