L["Unlocks after defeating N'Zoth. Speak with Valeera Sanguinar in Zuldazar to begin."] = "느조스를 처치하면 해제됩니다. 줄다자르에서 발리라 생귀나르와 대화하여 시작하십시오."
L["Unnatural Consequences"] = "자연의 섭리"
