L["Uther the Lightbringer"] = "빛의 수호자 우서"
L["Vaelen Has Returned"] = "밸렌의 귀환"
L["Val'zuun"] = "발주운"
L["Valarjar Warsinger"] = "발라리아르 전쟁가수"
L["Valeera Sanguinar"] = "발리라 생귀나르"
L["Valeera Sanguinar led you on a hunt for the Raven's Eye, an ancient vrykul artifact capable of piercing any disguise. Your search took you through the Maw of Souls and into the haunted depths of Black Rook Hold, where you retrieved the artifact and deciphered a letter that revealed the true scope of the enemy's infiltration."] = "발리라 생귀나르는 어떤 변장도 꿰뚫어 볼 수 있는 고대 브리쿨의 유물, 까마귀의 눈을 찾는 사냥에 앞장섰다. 수색은 영혼의 아귀를 지나 검은 떼까마귀 요새의 유령 들린 깊은 곳까지 이어졌다. 그곳에서 유물을 되찾고, 적의 침투가 실제로 얼마나 광범위한지를 밝혀 주는 편지를 해독했다."
L["Valeera Sanguinar tracked a pair of shadow-forged blades to a demonic vault hidden between worlds. You fought through the Twisting Nether itself, confronting the demon Val'zuun who guarded the Fangs of the Devourer. The blades pulsed with hunger as you claimed them — weapons that devoured souls and grew stronger with every kill."] = "발리라 생귀나르는 그림자로 벼려진 한 쌍의 칼날을 추적해, 세계와 세계 사이에 숨겨진 악마의 금고를 찾아냈다. 뒤틀린 황천 속을 헤치고 나아가 포식자의 송곳니를 지키던 악마 발주운과 맞섰다. 손에 넣는 순간 칼날은 굶주림으로 고동쳤다. 영혼을 집어삼키고, 죽일 때마다 더 강해지는 무기였다."
L["Valewalker Farodin"] = "계곡방랑자 파로딘"
