L["Waking a Dreamer"] = "꿈꾸는 자 깨우기"
L["Walk Among Ghosts"] = "유령들 사이를 거닐며"
L["Walk north through the ruin of Scourgeholme and onto the high plateau of Crusaders' Pinnacle."] = "스컬지홀름의 폐허를 지나 북쪽으로 걸어가, 십자군 봉우리의 높은 고원에 올라야 한다."
L["Walk of Faith"] = "믿음의 발걸음"
L["Walk the long road that turned Prince Arthas Menethil into the Lich King, and the longer road taken by those who march north to face him. It begins in Stratholme, where a prince makes an unforgivable choice in the name of salvation.\n\nBetween that memory and Icecrown lie the dragon-haunted plains of Dragonblight, the howling reach of Northrend, and a campaign waged in the long shadow of Frostmourne."] = "왕자 아서스 메네실을 리치 왕으로 만든 기나긴 길, 그리고 그와 맞서기 위해 북쪽으로 진군하는 이들이 걸어간 더 기나긴 길을 따라갑니다. 이야기는 스트라솔름에서 시작됩니다. 한 왕자가 구원이라는 이름으로 용서받지 못할 선택을 내린 곳입니다.\n\n그 기억과 얼음왕관 사이에는 용의 망령이 떠도는 용의 안식처의 평원과 바람이 울부짖는 노스렌드의 땅, 그리고 서리한의 기나긴 그림자 아래에서 벌어지는 원정이 놓여 있습니다."
L["Walk the saronite tunnels below Ymirheim and test what the whispers can do to a soldier's mind."] = "이미르하임 아래의 사로나이트 갱도를 걸으며, 그 속삭임이 병사의 정신에 무슨 짓을 할 수 있는지 시험해야 한다."
L["Walk with Lor'themar through the memory of Quel'Thalas and what the Sin'dorei lost when Arthas marched on Silvermoon. The grief is older than many kingdoms, and the silence the Scourge left behind still has weight.\n\nStand where names are remembered, face old wounds with care, and honor the heritage of a people whose line endured even when the kingdom nearly did not."] = "로르테마르와 함께 쿠엘탈라스의 기억을 따라 걸으며, 아서스가 실버문으로 진군했을 때 신도레이가 잃은 것을 되돌아봅니다. 그 슬픔은 많은 왕국보다도 오래되었고, 스컬지가 남기고 간 침묵은 지금도 무겁게 남아 있습니다.\n\n이름이 기억되는 곳에 서서, 오래된 상처를 조심스럽게 마주하고, 왕국이 거의 무너질 때에도 혈통을 지켜 낸 민족의 유산을 기리십시오."
