L["Waycrest Manor"] = "웨이크레스트 저택"
L["Waycrest Manor: Draining the Heartsbane"] = "웨이크레스트 저택: 심장파멸의 힘 빼앗기"
L["Waycrest Manor: The Fallen Mother"] = "웨이크레스트 저택: 타락한 어머니"
L["We Meet at Light's Hope"] = "희망의 빛에서 함께하다"
L["We Must be Prepared!"] = "우린 준비가 되어야 한다!"
