L["Welcome Wagons"] = "전차 환영식"
L["What Comes After"] = "그 이후"
L["What Is Going On Here?"] = "무슨 꿍꿍이지?"
L["What Is Worth Fighting For"] = "싸울 가치가 있는 것"
L["What Remains of Marshal M. Valentine"] = "치안대장 M. 발렌타인이 남긴 것"
L["What Rots Beneath"] = "부패의 제단으로"
L["What Tomorrow Brings"] = "미래의 운명"
