L["What You May Regret"] = "후회로 끝나지 않도록"
L["What's in a Name Name?"] = "이름 이름이 뭐길래?"
L["What's Mined Is Yours"] = "비취를 그대 품 안에"
L["What's the Cache?"] = "목표는 통"
L["What's Their Problem?"] = "그들의 속사정"
L["Whatever Will Be"] = "될 대로 될지어다"
L["When a Plan Comes Together"] = "큰 그림"
L["When Smoochums was found in the woods, Abby was gone. In her place: a register listing every Glenbrook villager — most names struck through. Jonathan Hayes had his heart removed for a ritual. Samuel Hawthorne lay dead in the trees. Mary Hayes had turned witch and killed her own husband. Only Annie Warren survived, barely, imprisoned in a cave.\n\nAbby came back. She led you to a circle of candles with Smoochums — the cat, now sacrificed — at the center. She poured the tea. She said there was one more guest to meet. Then she ran, and the Conjured Horror arrived in her place."] = "숲에서 뽀뽀쟁이가 발견되었을 때, 애비는 사라지고 없었다. 그 자리에는 글렌브룩 주민 전원의 이름이 적힌 명부가 놓여 있었다. 대부분의 이름에는 줄이 그어져 있었다. 조나단 헤이즈는 의식에 쓰이느라 심장을 잃었다. 사무엘 호손은 나무 사이에 죽어 쓰러져 있었다. 메리 헤이즈는 마녀가 되어 자기 남편을 죽였다. 오직 애니 워렌만이 동굴에 갇힌 채 간신히 살아남았다.\n\n애비가 돌아왔다. 그녀는 촛불이 둥글게 늘어선 곳으로 이끌었다. 그 한가운데에는 제물로 바쳐진 고양이, 뽀뽀쟁이가 놓여 있었다. 그녀는 차를 따랐다. 그리고 만나야 할 손님이 한 명 더 있다고 말했다. 그러고는 달아났고, 그녀가 있던 자리에 창조된 공포가 나타났다."
L["When Spirits Whisper"] = "영혼이 속삭일 때"
L["When Spiritwalker Ussoh's vision revealed Baine's imminent execution, Lor'themar gathered a small band of rebels — Thrall, Saurfang, and others. You infiltrated Orgrimmar's depths, fought through Sylvanas's forces, and rescued Baine from his cell. Jaina Proudmoore, of all people, helped you escape. The Horde was fracturing, and this was just the beginning."] = "영혼방랑자 우소의 환영이 바인의 처형이 임박했음을 드러내자, 로르테마르는 스랄과 사울팽을 비롯한 소수의 반역자들을 모았다. 오그리마의 깊은 곳으로 잠입해 실바나스의 병력을 뚫고 감옥에서 바인을 구출했다. 다른 누구도 아닌 제이나 프라우드무어가 탈출을 도왔다. 호드는 갈라지고 있었고, 이것은 시작에 불과했다."
L["When the gate went quiet and Sylvanas left, Lilian Voss was already in the room. Baine, Lor'themar, Ji Firepaw — all the leaders who had waited out the war with their doubts held close — and the question nobody wanted to be first to say: what do they do about the Warchief's throne? Before the full council assembled, Lilian stepped away from the main hall to arrange a quieter meeting — Forsaken leadership, Calia Menethil, and Derek Proudmoore. Hidden, necessary, and entirely hers to broker. Then she came back into the room and made the case for leaving the throne empty. No single voice. A council, where every people kept their own weight and no one leader could burn the world on a private conviction. She had spent years being used by the powerful as a tool. She knew exactly what concentrated authority looked like from the receiving end. The others listened. They agreed. It was the first time Lilian Voss had spoken in a room full of power and been heard."] = "관문이 잠잠해지고 실바나스가 떠났을 때, 릴리안 보스는 이미 그 방에 있었다. 바인, 로르테마르, 지 파이어포우. 의심을 가슴에 품은 채 전쟁을 견뎌 온 모든 지도자들이 모여 있었고, 누구도 먼저 꺼내고 싶어 하지 않는 질문이 남아 있었다. 대족장의 왕좌를 어떻게 할 것인가? 전체 회의가 열리기 전, 릴리안은 본회의장을 벗어나 더 조용한 만남을 주선했다. 포세이큰 지도부, 칼리아 메네실, 그리고 데릭 프라우드무어였다. 은밀하고, 반드시 필요하며, 온전히 그녀가 성사시켜야 할 자리였다. 그러고는 다시 방으로 돌아와 왕좌를 비워 두자고 주장했다. 하나의 목소리가 아닌 의회. 모든 종족이 제 무게를 지니고, 어느 한 지도자도 사사로운 신념으로 세상을 불태울 수 없는 의회였다. 그녀는 수년 동안 권력자들에게 도구로 이용당해 왔다. 집중된 권력이 그것을 받는 쪽에서 어떻게 보이는지 정확히 알고 있었다. 다른 이들은 귀를 기울였다. 그리고 동의했다. 권력자들로 가득한 방에서 릴리안 보스가 입을 열고, 그 말이 받아들여진 것은 그때가 처음이었다."
L["When the Peak of Serenity falls to the Legion, the monks rally at the Temple of Five Dawns on the Wandering Isle. Their order bends, breathes, and returns to its center.\n\nAs Grandmaster, defend sacred training grounds, recruit legendary warriors, and seek the old brews and older lessons that turn discipline into strength."] = "평온의 봉우리가 군단에게 함락되자, 수도사들은 유랑도의 다섯 새벽 사원으로 모여듭니다. 그들의 교단은 휘어지고, 숨을 고르고, 다시 중심으로 돌아옵니다.\n\n대사부로서 신성한 수련장을 지키고, 전설적인 전사들을 모으며, 수련을 힘으로 바꾸어 줄 오래된 양조주와 그보다 더 오래된 가르침을 찾으십시오."
L["When There's a Will, There's a Way"] = "뜻이 있는 곳에 길이 있다"
L["Where Are They Coming From?"] = "도대체 어디서 왔을까?"
L["Where Dragons Fell"] = "용의 무덤"
L["Where In the World is Mathias?"] = "대체 마티아스는 어딨는 거야?"
L["Where is Prince Renathal?"] = "레나탈 왕자의 행방"
L["Where the Hammer Falls"] = "망치가 떨어지는 곳"
L["Whispers in the Void"] = "공허 속의 속삭임"
L["Wicked Wikkets"] = "사악한 우낏"
L["Will of the Valarjar"] = "발라리아르의 의지"
L["Will to Survive"] = "삶의 의지"
L["Win back the Anvil-Thane's designs and reforge Dark Iron pride through craft and grit."] = "모루영주의 설계도를 되찾고, 솜씨와 근성으로 검은무쇠의 자부심을 다시 벼려 내야 한다."
L["Wings of the Red Flight"] = "붉은용군단의 날개"
L["Wintergarde Keep clings to the broken edge of the Dragonblight, pinned between Naxxramas overhead and the plaguebearers boiling up from the Carrion Fields. Duke August Foehammer holds what he can. The 7th Legion bleeds for every mile of frozen ground. High Commander Wyrmbane has orders from Highlord Bolvar Fordragon — push east, past the dragonshrines, toward a black gate in a black mountain."] = "윈터가드 성채는 용의 안식처의 부서진 가장자리에 간신히 매달려 있다. 머리 위의 낙스라마스와 썩은고기 들판에서 끓어오르는 역병 운반자들 사이에 끼어 있는 것이다. 대공 어거스트 포해머는 지킬 수 있는 것을 지키고 있다. 제7군단은 얼어붙은 땅을 한 걸음 나아갈 때마다 피를 흘린다. 최고사령관 웜베인은 대영주 볼바르 폴드라곤에게서 명령을 받았다. 동쪽으로 진격해 용제단들을 지나, 검은 산의 검은 관문으로 향하라는 것이다."
L["Wise Mari"] = "현명한 마리"
L["Witch Doctor Kejabu"] = "의술사 케자부"
L["Witch Doctor Kejabu had a plan that required a certain willingness to look like the enemy. Disguised as blood trolls, you slipped into Zalamar, one of the blood cult's most fortified settlements. Inside you found something worse than blood trolls: Hir'eek, the bat loa, had turned. Corrupted by G'huun's influence, the loa now fed on his own people, demanding sacrifice. A corrupted loa was more dangerous than no loa at all. You poisoned the blood troll's brood, stripped away their rituals, and faced Hir'eek at the heart of his lair. The bat loa fell. It was not a victory to celebrate."] = "의술사 케자부에게는 적처럼 보이는 것을 마다하지 않는 각오가 필요한 계획이 있었다. 피의 트롤로 변장해, 피의 교단의 가장 견고한 정착지 중 하나인 잘라마르로 잠입했다. 그 안에서 피의 트롤보다 더 끔찍한 것을 발견했다. 박쥐 로아 히르이크가 등을 돌린 것이다. 그훈의 영향으로 타락한 로아는 이제 자신의 백성을 먹이로 삼으며 제물을 요구했다. 타락한 로아는 로아가 없는 것보다 더 위험했다. 피의 트롤의 새끼들에게 독을 풀고, 그들의 의식을 무력화한 뒤, 소굴 한가운데서 히르이크와 맞섰다. 박쥐 로아가 쓰러졌다. 축하할 만한 승리는 아니었다."
L["Witch Doctor Tzadah"] = "의술사 자다"
L["Witch Hunt"] = "마녀 사냥"
L["Witchrending"] = "마녀 분쇄하기"
L["With Air and Earth secured, Fire remained. You entered the Firelands — still scarred from Ragnaros' fall — and found a new Firelord reigning: Smolderon, younger and more calculating than his predecessor. Baron Scaldius served as intermediary while you proved yourself in trials of flame. The Brand of Damnation burned your skin as a mark of passage, and Smolderon's allegiance was won — grudgingly, but bound by elemental law. Rehgar Earthfury joined your champions, and your weapon was reforged with the power of all three elemental lords."] = "바람과 대지를 확보했으니 남은 것은 불이었다. 라그나로스가 쓰러진 상처가 아직 남아 있는 불의 땅에 들어가 보니, 새로운 화염군주가 군림하고 있었다. 전임자보다 젊고 더 계산적인 스몰데론이었다. 남작 스칼디우스가 중재자 역할을 하는 동안, 불꽃의 시련을 거치며 자신을 증명했다. 저주의 낙인이 통과의 증표로 살갗을 태웠고, 스몰데론의 충성을 얻어 냈다. 마지못한 충성이었지만 정령의 법칙에 묶인 것이었다. 레가르 어스퓨리가 용사로 합류했고, 무기는 세 정령 군주의 힘으로 새로 벼려졌다."
L["With clever engineering and fearless aerial operations, you dismantled a trogg-backed threat, defeated Sparkspanner, and proved Gnomeregan's ingenuity is stronger than ever."] = "기발한 기계공학과 두려움 없는 공중 작전으로 트로그를 등에 업은 위협을 해체하고, 스파크스패너를 물리쳐, 놈리건의 창의력이 그 어느 때보다 강하다는 것을 증명했다."
L["With Lordaeron newly reclaimed, old enemies resurfaced. The Scarlet Crusade established a foothold in Silverpine Forest, determined to purge the Forsaken from their ancestral lands. Under Lilian Voss's guidance, you gathered alchemical weapons, donned a stolen disguise, slipped into the enemy’s ranks, and opened the way for the Forsaken to strike back in force. When the dust settled, you stood as a proven champion — Forsaken by death, but not by purpose."] = "로데론을 되찾은 지 얼마 되지 않아, 옛 적들이 다시 모습을 드러냈다. 붉은십자군이 은빛소나무 숲에 거점을 마련하고, 포세이큰을 조상의 땅에서 몰아내겠다고 나선 것이다. 릴리안 보스의 지도 아래 연금술 무기를 모으고, 훔친 변장을 걸치고, 적진에 잠입해, 포세이큰이 대대적으로 반격할 길을 열었다. 먼지가 가라앉았을 때, 증명된 용사로서 그 자리에 서 있었다. 죽음으로 버림받았을지언정, 목적까지 버리지는 않은 포세이큰이었다."
L["With Niskara shattered, the Silver Hand stood triumphant. Arator the Redeemer — son of Turalyon and Alleria — joined your order, his half-elven heritage bridging every divide. Then came Lothraxion, a nathrezim infused with the Light itself — living proof that even demons could be redeemed. Lord Maxwell Tyrosus forged your weapon anew and bestowed the title of Highlord upon you — the first since the Lich King destroyed the original Silver Hand. A light in the darkness, brighter than ever."] = "니스카라가 무너지자 은빛 성기사단은 승리를 거머쥐었다. 투랄리온과 알레리아의 아들인 구원자 아라토르가 교단에 합류했고, 그의 하프엘프 혈통은 모든 분열을 잇는 다리가 되었다. 이어 빛 그 자체가 스며든 나스레짐, 로스락시온이 찾아왔다. 악마조차 구원받을 수 있다는 살아 있는 증거였다. 맥스웰 티로서스 경은 무기를 새로 벼리고 대영주의 칭호를 내렸다. 리치 왕이 원래의 은빛 성기사단을 무너뜨린 이후 처음이었다. 어둠 속의 빛이 그 어느 때보다 밝게 빛났다."
L["With Prince in Tow"] = "배는 왕자를 싣고"
L["With Sinfall secured, the rebellion moves to rescue Prince Renathal from the ruins of his failed uprising."] = "죄악의 몰락지를 확보한 반란군은 실패한 봉기의 폐허에서 왕자 레나탈을 구출하기 위해 움직인다."
L["With Sylvanas defeated and the war over, Lilian Voss and Calia Menethil lead the Forsaken back to Lordaeron. The city is choked with Blight, the halls of Undercity dark and half-collapsed. Together they fight to reclaim it — cleansing what can be saved, burying what cannot — and at the end, form the Desolate Council: a governing body the Forsaken chose for themselves."] = "실바나스가 패배하고 전쟁이 끝나자, 릴리안 보스와 칼리아 메네실은 포세이큰을 이끌고 로데론으로 돌아간다. 도시는 역병으로 숨이 막힐 듯하고, 언더시티의 회랑은 어둡고 절반쯤 무너져 있다. 두 사람은 함께 도시를 되찾기 위해 싸운다. 살릴 수 있는 것은 정화하고, 살릴 수 없는 것은 묻는다. 그리고 마침내 황폐의 의회를 세운다. 포세이큰이 스스로 선택한 통치 기구다."
L["With the Idol recovered, recruit Hamuul and Mylune as champions and power the Dreamgrove's portal to prepare for the final battle."] = "우상을 되찾았으니, 하뮬과 마일룬을 용사로 영입하고 꿈숲의 차원문에 힘을 불어넣어 최후의 전투에 대비해야 한다."
L["With the Serpent's Heart restored, you travel to Yu'lon's temple and help the sages prepare for her rebirth."] = "용의 심장이 되살아나자, 위론의 사원으로 가서 현자들이 그녀의 재탄생을 준비하도록 돕는다."
L["With the south secured, Marshal Reade led the march on Corlain — the ancestral seat of House Waycrest, now a fortress of the Heartsbane Coven. The first watch was grim: the town was sealed behind a magical barrier that killed anything that touched it. Inquisitor Notley scouted the approach while you gathered precious metals and crafted an improvised arsenal of witchrending weapons. Lucille herself struck the final blow against the barrier, shattering it with the Order's combined power. The road to Waycrest Manor was open."] = "남쪽을 확보하자, 치안대장 리드는 콜레인으로의 진군을 이끌었다. 웨이크레스트 가문의 선조 대대로의 본거지였으나, 이제는 심장파멸 마녀단의 요새가 된 곳이었다. 첫 번째 감시는 암울했다. 마을은 닿는 것은 무엇이든 죽이는 마법 장벽 뒤에 봉쇄되어 있었다. 심문관 노틀리가 접근로를 정찰하는 동안, 귀금속을 모아 마녀를 베어 낼 무기들을 급조했다. 장벽에 마지막 일격을 가한 것은 루실 자신이었다. 잿불단의 힘을 모두 모아 장벽을 산산이 부순 것이다. 웨이크레스트 저택으로 가는 길이 열렸다."
L["With the Unseen Path established, you set about building its strength. Loren Stormhoof was the first to answer the call, pledging as champion. Tactician Tinderfell organized scouts and soldiers, dispatching them across the Broken Isles to gather intelligence and hold the line while you prepared for the greater battles ahead."] = "보이지 않는 길이 세워지자, 그 힘을 키우는 일에 나섰다. 가장 먼저 부름에 응한 것은 로렌 스톰후프였고, 그는 용사로서 충성을 맹세했다. 전술가 틴더펠은 정찰병과 병사들을 조직해 부서진 섬 곳곳으로 보내 정보를 모으고 전선을 지키게 했다. 그동안 다가올 더 큰 전투를 준비했다."
L["Word came of monks captured by the vrykul in Stormheim. Angus Ironfist, a massive Pandaren brawler, led you into the frozen north where your brothers and sisters were being held. You quelled the tide of enemies, rebuilt the shattered defenses brick by brick, and freed every last monk. Hiro — a humble fighter who became a hero that day — and Sylara Steelsong joined your growing roster of champions. No monk would be left behind."] = "스톰하임에서 수도사들이 브리쿨에게 붙잡혔다는 소식이 들려왔다. 거구의 판다렌 격투가 앵거스 아이언피스트가 형제자매들이 갇혀 있는 얼어붙은 북쪽 땅으로 길을 이끌었다. 밀려드는 적의 물결을 잠재우고, 무너진 방어 시설을 벽돌 하나하나 다시 쌓아 올렸으며, 마지막 한 명까지 수도사들을 모두 풀어 주었다. 그날 영웅이 된 겸손한 격투가 히로와 실라라 스틸송이 늘어나는 용사의 대열에 합류했다. 단 한 명의 수도사도 남겨 두지 않았다."
L["Word on the Winds"] = "바람에 실려 오는 말"
L["Worthy of the Title"] = "칭호에 걸맞은 자격"
L["Wounds Beyond Flesh"] = "육신을 초월한 상처"
L["Wrath and Justice"] = "격노와 정의"
L["Wrath of the Lich King"] = "리치 왕의 분노"
L["Writing on the Wall"] = "장벽에 써 내려간 글"
L["Written in Stone"] = "돌의 힘"
L["Wyrmrest Temple, Dragonblight"] = "고룡쉼터 사원, 용의 안식처"
L["Xal'atath, Blade of the Black Empire"] = "살라타스, 검은 제국의 칼날"
L["Xiao"] = "샤오"
L["Xiao, the Eater"] = "식신 샤오"
L["Yalia Sagewhisper"] = "야리아 세이지위스퍼"
L["Years later, Lilian served the Horde on the shores of Kul Tiras. While Nathanos Blightcaller secured a mountain outpost, Lilian led you through Bridgeport — sabotaging foundries, planting explosives, and riding through the flames of your own making. She was efficient, ruthless, and completely in her element. The girl who once trembled in Deathknell was gone."] = "수년 뒤, 릴리안은 쿨 티라스의 해안에서 호드를 위해 싸우고 있었다. 나타노스 블라이트콜러가 산악 전초기지를 확보하는 동안, 릴리안은 다리항구로 앞장섰다. 주조소를 파괴하고, 폭약을 설치하고, 직접 일으킨 불길 속을 말을 달려 빠져나갔다. 그녀는 능숙하고 무자비했으며, 완전히 물 만난 물고기 같았다. 한때 죽음의 종소리 마을에서 떨고 있던 소녀는 이제 사라지고 없었다."
L["Years passed before Lilian surfaced again — this time as a hooded figure lurking inside the Scarlet Halls. She hired you to slaughter your way through the Crusade's ranks and steal their membership records. Every name on that list was a target. Lilian Voss was no longer running from the Crusade — she was hunting them down, one by one."] = "수년이 흐른 뒤에야 릴리안은 다시 모습을 드러냈다. 이번에는 붉은십자군 전당 안에 숨어 있는 두건 쓴 인물로서였다. 그녀는 십자군의 대열을 베어 나가며 그들의 단원 명부를 훔쳐 오라고 의뢰했다. 그 명부에 적힌 모든 이름이 표적이었다. 릴리안 보스는 더 이상 십자군에게서 도망치지 않았다. 이제는 그들을 하나씩 사냥하고 있었다."
L["Yeti to Rumble"] = "설인과의 한판"
L["You answered Khadgar's call and journeyed into the ancient city of Suramar, finding it sealed behind a shimmering barrier of arcane power. Beyond the wall, you discovered First Arcanist Thalyssra — once a leader of the Nightborne, now exiled and starving for mana. Together you claimed the ruins of Shal'Aran as a hidden refuge, a fragile spark of rebellion in the shadow of the Grand Magistrix."] = "카드가의 부름에 응해 고대 도시 수라마르로 향했지만, 도시는 일렁이는 비전 마력의 장벽 뒤에 봉인되어 있었다. 장벽 너머에서 첫 번째 비전술사 탈리스라를 만났다. 한때 나이트본의 지도자였으나, 이제는 추방되어 마나에 굶주리고 있었다. 함께 샬아란의 폐허를 숨겨진 피난처로 삼았다. 대마법학자의 그림자 아래에서 피어난, 위태로운 반란의 불씨였다."
L["You built The Uncrowned from a whisper into a force, recruiting legendary rogues like Vanessa VanCleef and Garona Halforcen as champions. From the Chamber of Shadows beneath Dalaran, you established a network of operatives across the Broken Isles and ensured the order's school of roguery could train the next generation of shadows."] = "속삭임에 불과했던 왕관 없는 자들을 하나의 세력으로 키워 내며, 바네사 밴클리프와 가로나 하프오큰 같은 전설적인 도적들을 용사로 영입했다. 달라란 아래 그림자의 방에서 부서진 섬 전역에 요원망을 구축했고, 교단의 도적 학교가 다음 세대의 그림자들을 길러 낼 수 있도록 했다."
L["You Can't Take the Sky from Me"] = "내게서 하늘을 빼앗을 순 없다"
L["You infiltrated the arcwine vineyards that kept Suramar's populace docile and dependent on Elisande's generosity. Working with Vintner Iltheux and the defiant Margaux, you sabotaged the production, poisoned the supply, and struck at the very system of control the Grand Magistrix had built. When Margaux fell to the Duskwatch's retribution, you ensured her sacrifice was not in vain — the rebellion now had its own supply of arcwine and the loyalty of those she inspired."] = "수라마르 주민들을 순종하게 만들고 엘리산드의 관대함에 의존하게 하던 비전포도주 포도원에 잠입했다. 양조사 일더스와 반항적인 마고와 함께 생산을 방해하고, 공급품에 독을 풀어, 대마법학자가 세운 통제 체계 그 자체를 공격했다. 마고가 황혼감시대의 보복으로 쓰러지자, 그녀의 희생이 헛되지 않도록 했다. 이제 반란군은 자체적인 비전포도주 공급원과, 그녀가 일깨운 이들의 충성을 얻었다."
L["You located Chief Telemancer Oculeth in his ruined workshop, surrounded by the wreckage of his life's work. Together you restored fragments of the ancient telemancy network, reactivating portals that would allow the rebels to move unseen across Suramar. The old telemancer's genius may have dulled with hunger, but his loyalty to Thalyssra never wavered."] = "수석 이동술사 오큘레스를 폐허가 된 작업장에서 찾아냈다. 그는 평생의 업적이 남긴 잔해에 둘러싸여 있었다. 함께 고대 이동술 연결망의 조각들을 복구해, 반란군이 수라마르 곳곳을 들키지 않고 오갈 수 있게 해 줄 차원문들을 다시 작동시켰다. 늙은 이동술사의 천재성은 굶주림에 무뎌졌을지 몰라도, 탈리스라를 향한 그의 충성은 결코 흔들리지 않았다."
L["You opened your eyes in the crypt of Deathknell, raised by the Val'kyr as one of the Forsaken. Among the newly risen was a young woman trembling with rage — Lilian Voss, daughter of the Scarlet Crusade's High Priest. While you accepted your new existence, she could not. She fled into the darkness, refusing to believe what she had become."] = "죽음의 종소리 마을의 지하묘지에서 눈을 떴다. 발키르의 손에 포세이큰으로 되살아난 것이다. 새로 일어난 이들 가운데 분노로 몸을 떠는 젊은 여인이 있었다. 붉은십자군 대사제의 딸, 릴리안 보스였다. 새로운 존재를 받아들인 것과 달리, 그녀는 그럴 수 없었다. 자신이 무엇이 되었는지 믿기를 거부하며 그녀는 어둠 속으로 달아났다."
L["You slipped into the Waning Crescent, a forgotten slum where nightfallen refugees huddled in the shadows of Suramar City. Working alongside Silgryn, you established supply lines, freed imprisoned allies, and built a network of safe houses right beneath the Duskwatch's nose. What began as a handful of desperate exiles became the backbone of an underground resistance."] = "수라마르 성의 그늘 속에 나이트폴른 피난민들이 웅크리고 있는 잊힌 빈민가, 기우는 초승달에 잠입했다. 실그린과 함께 보급로를 구축하고, 갇힌 동지들을 풀어 주고, 황혼감시대의 코앞에 은신처 연결망을 세웠다. 몇 안 되는 절박한 추방자들로 시작한 무리는 지하 저항군의 중추가 되었다."
L["You ventured into the ley line tunnels beneath Suramar, fighting corrupted creatures to restore the flow of ancient mana to Shal'Aran. The cavern hummed back to life as power surged through its crystalline conduits, giving the nightfallen refugees a lifeline against the withering that threatened to consume them all."] = "수라마르 아래의 지맥 터널로 들어가 타락한 존재들과 싸우며, 샬아란으로 고대의 마나가 다시 흐르게 했다. 수정 도관을 따라 힘이 솟구치자 동굴은 다시 살아난 듯 웅웅 울렸고, 나이트폴른 피난민들은 그들 모두를 집어삼키려던 쇠약에 맞설 생명줄을 얻었다."
L["You're Either With Us Or..."] = "우리와 한편이 아니라면..."
L["Your Attention, Please"] = "주목해 주세요"
L["Your Training Starts Now"] = "수련의 시작"
L["Yu'lon's rebirth did not end the war. It only made the cost clearer. The Alliance returned to Pearlfin Village; the Horde returned to Grookin Hill. Both sides prepared their local allies for the next blow, and Cho called for help with the last piece of an ancient puzzle. Then the seal broke. The Serpent's Heart cracked under the weight of fear, anger, and suspicion. Jade became weapon and prison, friends were scattered in the fallout, and the Sha of Doubt rose from the ruin. The Jade Forest's lesson had become impossible to ignore: the enemy was not only across the battlefield."] = "위론의 부활로 전쟁이 끝난 것은 아니었다. 그 대가가 더 분명해졌을 뿐이었다. 얼라이언스는 진주지느러미 마을로, 호드는 그루끼끼 언덕으로 돌아갔다. 양 진영은 다음 일격에 대비해 현지 동맹들을 준비시켰고, 초는 고대 수수께끼의 마지막 조각을 찾는 데 도움을 청했다. 그때 봉인이 깨졌다. 용의 심장은 공포와 분노, 의심의 무게를 견디지 못하고 금이 갔다. 비취는 무기이자 감옥이 되었고, 그 여파로 동료들은 뿔뿔이 흩어졌으며, 폐허 속에서 의심의 샤가 일어섰다. 비취 숲이 남긴 교훈은 이제 외면할 수 없었다. 적은 전장 건너편에만 있는 것이 아니었다."
L["Zabra Hexx"] = "자브라 헥스"
