L["For the Alliance, the Scarlet Crusade first looked like a distant Lordaeron problem: troubling enough for Brother Crowley to send word to Brother Anton, and troubling enough for Anton to send you onward. Raleigh the Devout understood what the red tabards meant. The Monastery was not merely a garrison. It was the heart of a militant faith losing its way."] = "얼라이언스에게 붉은십자군은 처음엔 먼 로데론의 골칫거리처럼 보였다. 그래도 수사 크롤리가 수사 안톤에게 소식을 보낼 만큼, 안톤이 다시 다음 행선지로 떠나보낼 만큼은 심상치 않은 일이었다. 경건한 신자 랄레이는 붉은 휘장이 무엇을 뜻하는지 알고 있었다. 수도원은 단순한 주둔지가 아니었다. 길을 잃어 가는 호전적인 신앙의 심장부였다."
