L["After the first foothold in Zereth Mortis was secured, Uther arrived in Haven with news from Oribos: Sylvanas had awakened. Her soul had been split since Frostmourne killed her, and the restored fragment forced her to face the Banshee Queen's atrocities as her own. In the vision Uther shared, the Ranger-General saw Teldrassil burn, rejected the comfort of pretending those crimes belonged to someone else, and chose to wake. The campaign then turned back to Zereth Mortis. Elder Ara led you through a pilgrimage to repair the ancient translocator to the Sepulcher. At the end, Sylvanas stood with Uther, Jaina, and Bolvar before the raid entrance. She knew Anduin was the key, and Uther convinced Jaina to let Sylvanas help free him."] = "제레스 모르티스에 첫 거점을 확보한 뒤, 우서가 오리보스의 소식을 안고 안식처에 도착했다. 실바나스가 깨어났다는 것이었다. 서리한에 죽임을 당한 이후 그녀의 영혼은 둘로 갈라져 있었고, 되찾은 조각은 그녀가 밴시 여왕의 만행을 자신의 죄로 마주하게 했다. 우서가 보여 준 환영 속에서 순찰대장은 텔드랏실이 불타는 광경을 보았고, 그 죄가 다른 누군가의 것인 척하는 위안을 거부한 채 깨어나기를 택했다. 이야기는 다시 제레스 모르티스로 돌아왔다. 장로 아라의 인도로 매장터로 향하는 고대 전송기를 복구하기 위한 순례가 이어졌다. 마침내 실바나스는 우서, 제이나, 볼바르와 함께 공격대 입구 앞에 섰다. 그녀는 안두인이 열쇠라는 것을 알고 있었고, 우서는 제이나를 설득해 실바나스가 그를 구하는 데 힘을 보태게 했다."
L["Aggressive Excavation"] = "공격적인 발굴"
L["Anduin has been rescued, but the Jailer still commands Domination. Bolvar and the Primus seek a way to turn the broken helm into a weapon of free will."] = "안두인은 구출되었지만, 간수는 여전히 지배의 힘을 쥐고 있습니다. 볼바르와 시초자는 부서진 투구를 자유 의지의 무기로 바꿀 방법을 찾습니다."
L["After Anduin was freed, the way forward was still blocked by the Jailer's Domination magic. Bolvar, Darion, Anduin, and Sylvanas all carried scars from the helm, the blade, or the will behind them. Their memories became part of the answer. In Bastion, Sylvanas faced the wound of what she had done and named the truth plainly: there was no absolution waiting inside a shard of memory, only the choice to keep resisting. The Primus reforged the Helm of Domination into the Crown of Wills, a symbol not of command, but of defiance. With it, Zovaal could finally be faced."] = "안두인이 풀려난 뒤에도 앞길은 여전히 간수의 지배 마법에 가로막혀 있었다. 볼바르, 다리온, 안두인, 실바나스는 모두 투구나 검, 혹은 그 뒤에 도사린 의지가 남긴 상처를 안고 있었다. 그들의 기억이 해답의 일부가 되었다. 승천의 보루에서 실바나스는 자신이 저지른 일의 상처를 마주하고 진실을 있는 그대로 말했다. 기억의 파편 속에서 기다리는 용서란 없으며, 오직 계속 저항하겠다는 선택만이 남아 있다고. 시초자는 지배의 투구를 의지의 왕관으로 다시 벼려 냈다. 그것은 지배가 아닌 저항의 상징이었다. 그 힘으로 마침내 조발과 맞설 수 있게 되었다."
L["A Gathering of Covenants"] = "성약의 단의 회합"
L["Anduin steals the Archon's sigil, and Sylvanas moves on Ardenweald. Tyrande finally catches her in the Heart of the Forest."] = "안두인이 집정관의 인장을 훔치고, 실바나스는 몽환숲으로 향합니다. 티란데는 마침내 숲의 심장부에서 그녀를 따라잡습니다."
L["Before the assault on the Sanctum, Bolvar saw fragments of what was happening inside Torghast. The Jailer forged Kingsmourne, a mourneblade shaped around Anduin's own weapon and a soul crystal. Sylvanas brought the blade to Anduin and demanded he join their cause willingly or be made to serve. Anduin saw the wound she was trying to hide: she kept offering him the choice Arthas had stolen from her. Blizzard later removed or auto-completed much of this Torghast questline for catch-up characters, but the vision is the emotional bridge into Chains of Domination."] = "성소 공격에 앞서, 볼바르는 토르가스트 안에서 벌어지는 일의 단편을 보았다. 간수는 안두인의 무기와 영혼 수정을 바탕으로 또 하나의 룬검, 왕의한을 벼려 냈다. 실바나스는 그 검을 안두인에게 가져가, 스스로 대의에 동참하든지 아니면 강제로 섬기게 되든지 택하라고 요구했다. 안두인은 그녀가 감추려는 상처를 꿰뚫어 보았다. 그녀는 아서스가 자신에게서 앗아 간 선택권을 계속 그에게 내밀고 있었다. 블리자드는 이후 따라잡기 캐릭터를 위해 이 토르가스트 퀘스트 라인의 상당 부분을 삭제하거나 자동 완료 처리했지만, 이 환영은 여전히 지배의 사슬로 이어지는 감정의 다리 역할을 한다."
L["Begins after your covenant campaign reaches The Search for Baine. Later characters may be offered a skip to Korthia; skipping completes this chapter."] = "성약의 단 캠페인이 '바인을 찾아서'에 도달한 뒤 시작됩니다. 이후 캐릭터에게는 코르시아로 건너뛰는 선택지가 제공될 수 있으며, 건너뛰면 이 장이 완료됩니다."
L["Bolvar's visions reveal the Jailer's next weapon: Anduin, bound to a mourneblade. Sylvanas still tries to call it a choice."] = "볼바르의 환영이 간수의 다음 무기를 드러냅니다. 바로 룬검에 묶인 안두인입니다. 실바나스는 여전히 그것을 선택이라 부르려 합니다."
L["Can't Turn Our Backs"] = "배수의 진"
L["Chains of Domination"] = "지배의 사슬"
