L["The assault on the Sanctum of Domination carried the covenants into the Jailer's seat of power. Sylvanas waited at the top of Torghast, fighting across shattered chains and the edge of the Maw while the Jailer dragged Oribos toward his prison. When Zovaal spoke of remaking reality so all would serve, Sylvanas finally heard Arthas in his words. She turned on him. The Jailer answered by returning the soul fragment Frostmourne had torn from her at Silvermoon, then left her unconscious at the mercy of those she had betrayed. She was defeated, but not judged. Not yet."] = "지배의 성소 공격으로 성약의 단들은 간수의 권좌 깊숙이 들어섰다. 실바나스는 토르가스트 정상에서 기다리고 있었고, 간수가 오리보스를 자신의 감옥으로 끌어당기는 동안 부서진 사슬과 나락의 끝자락을 넘나들며 싸웠다. 조발이 모두가 섬기도록 현실을 다시 빚겠다고 말하자, 실바나스는 마침내 그의 말에서 아서스의 목소리를 들었다. 그녀는 그에게 등을 돌렸다. 간수는 서리한이 실버문에서 그녀에게서 찢어 낸 영혼 조각을 되돌려 주는 것으로 응수하고는, 의식을 잃은 그녀를 그녀가 배신한 이들의 손에 남겨 두고 떠났다. 그녀는 패배했지만, 심판받지는 않았다. 아직은."
L["The covenants assault the Jailer's fortress in Torghast. At the summit waits Sylvanas, and the battle ends with the choice that makes News from Oribos possible."] = "성약의 단들이 토르가스트에 있는 간수의 요새를 공격합니다. 정상에서는 실바나스가 기다리고 있으며, 전투는 '오리보스에서 날아든 소식'으로 이어지는 선택으로 끝을 맺습니다."
L["The path through the Sepulcher reaches Anduin at last. Freeing him from Kingsmourne sets the stage for the Crown of Wills."] = "매장터를 지나는 길 끝에서 마침내 안두인에게 닿습니다. 그를 왕의한에서 해방하면 의지의 왕관을 위한 무대가 마련됩니다."
L["Within the Sepulcher, the heroes found Anduin still bound to the Jailer's will. The fight was not only to defeat him, but to reach the part of him still resisting. In the end, Anduin found the strength to help shatter Kingsmourne from within. Sylvanas's warning had been true: saving Anduin was the key to opposing Zovaal's design."] = "매장터 안에서 영웅들은 여전히 간수의 의지에 묶인 안두인을 발견했다. 싸움의 목적은 그를 쓰러뜨리는 데 그치지 않고, 아직 저항하고 있는 그의 일부에 닿는 것이었다. 결국 안두인은 내면에서 왕의한을 부수는 데 힘을 보탤 힘을 찾아냈다. 실바나스의 경고는 사실이었다. 안두인을 구하는 것이야말로 조발의 계획에 맞서는 열쇠였다."
L["Take Charge"] = "막중한 책무"
L["Testing One Two"] = "시험 중, 하나 둘"
L["The Broken Crown"] = "부서진 왕관"
L["The Battle of Ardenweald"] = "몽환숲 전투"
L["The Crown of Wills"] = "의지의 투구"
L["The First Move"] = "첫 수"
L["The Heart of Ardenweald"] = "몽환숲의 심장"
L["The Jailer's next move began in Bastion. Anduin, dominated through Kingsmourne, struck down the Archon and took her sigil while Sylvanas watched the plan unfold. Bolvar gathered the covenants in Oribos, and the war rushed to Ardenweald before the Winter Queen's sigil could be taken next. There, beneath the Heart of the Forest, Tyrande Whisperwind caught Sylvanas at last. Elune's wrath burned through her, but the Night Warrior's power faded before the killing blow. Sylvanas escaped, and the covenants turned toward Korthia and the Sanctum of Domination."] = "간수의 다음 수는 승천의 보루에서 시작되었다. 왕의한을 통해 지배당한 안두인은 집정관을 쓰러뜨리고 그녀의 인장을 빼앗았으며, 실바나스는 계획이 펼쳐지는 모습을 지켜보았다. 볼바르는 오리보스에 성약의 단들을 불러 모았고, 겨울 여왕의 인장마저 빼앗기기 전에 전쟁은 몽환숲으로 번졌다. 그곳 숲의 심장부 아래에서 티란데 위스퍼윈드는 마침내 실바나스를 붙잡았다. 엘룬의 분노가 실바나스를 불살랐지만, 결정타를 날리기 전에 밤의 전사의 힘이 사그라들었다. 실바나스는 달아났고, 성약의 단들은 코르시아와 지배의 성소로 눈을 돌렸다."
L["The Not-Scientific Method"] = "비과학적 방법"
L["The Pilgrim's Journey"] = "순례자의 여정"
L["The Pilgrimage Ends"] = "순례의 끝"
L["The Primus"] = "시초자"
L["Torghast Visions"] = "토르가스트의 환영"
L["Two Paths to Tread"] = "두 개의 길"
L["Unchecked Growth"] = "급성장 식물"
L["Uther appears in Haven with news from Oribos. Sylvanas has awakened, but reaching the Sepulcher means earning the Enlightened's help first."] = "우서가 오리보스의 소식을 들고 안식처에 나타납니다. 실바나스가 깨어났지만, 매장터에 닿으려면 먼저 깨우친 자들의 도움을 얻어야 합니다."
L["What Makes Us Strong"] = "우리를 강하게 만드는 것"
L["What We Overcome"] = "우리가 극복한 것들"
L["What We Wish to Forget"] = "우리가 잊고 싶은 것"
L["Where the Memory Resides"] = "기억이 머무르는 곳"
L["Where There's a Pilgrim, There's a Way"] = "순례자가 가는 곳에 길이 있다"
L["Voices of the Eternal"] = "영원의 목소리"
L["overlook behind Pilgrim's Grace"] = "순례자의 은총 뒤편 전망대"
L["A Cage for Alleria"] = "알레리아의 우리"
L["A vision of Quel'Thalas in shadow sends Arator looking for the Windrunners. His search reaches the Maw, where Sylvanas is still freeing the souls she condemned."] = "그림자에 잠긴 쿠엘탈라스의 환영을 본 아라토르는 윈드러너 가문을 찾아 나섭니다. 그의 여정은 나락에 이르고, 그곳에서 실바나스는 여전히 자신이 단죄한 영혼들을 풀어 주고 있습니다."
L["A Void Test of Wills"] = "의지를 시험하는 공허"
L["Alleria Windrunner"] = "알레리아 윈드러너"
L["Arator"] = "아라토르"
L["Be careful with the Threads of Fate choice from Fatescribe Roh-Tahl in Oribos. Choosing Threads of Fate skips the Shadowlands leveling campaign and marks Revendreth's main story quests complete, so use the replay storyline option if you want to play this chapter."] = "오리보스에서 운명필경사 로탈이 제안하는 '운명의 실' 선택에 주의하십시오. 운명의 실을 선택하면 어둠땅 레벨업 캠페인을 건너뛰고 레벤드레스의 주요 이야기 퀘스트가 완료 처리되므로, 이 장을 플레이하려면 이야기 다시 진행하기를 선택하십시오."
L["Blessings Be Upon You"] = "그대에게 축복을"
L["Bringer of the Void"] = "공허의 인도자"
L["Chaos Control"] = "혼돈 제어"
L["Determination"] = "결단"
L["Distant Echoes"] = "아득한 메아리"
L["Do You Have a Spare?"] = "잉여품 증여"
L["Excising the Incursion"] = "침입 저지"
L["Here Goes Something"] = "밑져야 본전"
L["In Her Shadow"] = "그림자 속에서"
L["Mad Space"] = "광기의 공간"
L["Meet Arator"] = "아라토르와의 만남"
L["Off to Tazavesh"] = "타자베쉬로"
L["Off to Tazavesh, Again"] = "다시 한번 타자베쉬로"
L["outside the Dornogal bank"] = "도르노갈 은행 앞"
L["Preludes and Preparations"] = "서곡과 준비"
L["Repent of the Highborne"] = "명가의 참회"
L["Repossession is Nine-Tenths of the Law"] = "압류의 법칙"
L["Returning to Life"] = "생으로 돌아가기"
L["Silver Hand Squire"] = "은빛 성기사단 종자"
L["Tag, You're It"] = "잡았다! 네가 술래야"
L["The Eleventh Hour"] = "마감 임박"
L["The Final Hazard"] = "마지막 위험 요소"
L["The Long Vigil"] = "기나긴 감시"
L["The Parent Trap"] = "부모의 함정"
L["The Warning"] = "경고"
L["Those As Well"] = "예외는 없다"
L["To Cleanse Shadow's Stain"] = "어둠의 얼룩 정화"
L["Ve'nari"] = "베나리"
L["Vereesa Windrunner"] = "베리사 윈드러너"
L["Vereesa's Tale"] = "베리사의 이야기"
L["What Might Come"] = "다가오는 전개"
L["Where in K'aresh is Alleria Windrunner?"] = "알레리아 윈드러너는 크아레쉬 어디에 있나?"
L["Your trainer sends you to Moonglade for lessons that cannot be taught in a city. The Cenarion Circle has work for young druids who are ready to listen to spirits, heal sick beasts, and follow the call of distant waters."] = "도시에서는 배울 수 없는 가르침이 있습니다. 직업 전문가는 젊은 드루이드를 달의 숲으로 보냅니다. 세나리온 의회에는 정령의 목소리에 귀 기울이고, 병든 짐승을 치유하며, 먼 물가의 부름을 따를 준비가 된 젊은 드루이드에게 맡길 일이 있습니다."
L["Speak with Duthorian Rall and take up the Tome of Valor. A paladin's lessons are not only prayers; they ask for aid given, judgment shown, and materials gathered with care.\n\nFollow the order's tests from early duty to the rites reserved for those who have carried the Light long enough to be trusted with more."] = "두소리안 랄과 대화하고 용맹의 고서를 받으십시오. 성기사의 가르침은 기도만이 아닙니다. 도움을 베풀고, 공정한 심판을 보이며, 정성껏 재료를 모으기를 요구합니다.\n\n초기 임무부터, 오랫동안 빛을 지녀 더 큰 일을 맡길 만하다고 인정받은 자에게만 허락된 의식까지, 기사단의 시험을 차례로 따라가십시오."
L["Master Mathias Shaw and Shenthul do not teach by lecture. They send rogues into guarded places, locked boxes, and situations where an antidote matters as much as a blade.\n\nBegin with your faction's poison work, then follow the hints that lead beyond city trainers into a wider trade of signals and reputation."] = "단장 마티아스 쇼와 셴툴은 말로 가르치지 않습니다. 그들은 도적을 경비가 삼엄한 곳으로, 잠긴 상자 앞으로, 해독제가 칼날만큼 중요한 상황 속으로 보냅니다.\n\n자기 진영의 독 다루기 임무로 시작해, 도시의 전문가를 넘어 신호와 평판이 오가는 더 넓은 세계로 이끄는 단서를 따라가십시오."
L["Your first totem begins with a call, not a command. The elements answer through trials, offerings, and long walks between trainers, spirits, and hidden shrines.\n\nFollow earth, fire, water, and air as each power is earned in turn. Later, the same lessons point toward a deeper test of balance."] = "첫 토템은 명령이 아닌 부름에서 시작됩니다. 정령은 시험과 공물, 그리고 전문가와 영혼, 숨겨진 제단 사이를 오가는 긴 여정을 통해 응답합니다.\n\n대지, 불, 물, 바람의 힘을 차례로 얻으며 그 길을 따라가십시오. 훗날 같은 가르침은 더 깊은 균형의 시험으로 이어집니다."
L["Warlock trainers do not offer power freely. They give names, errands, and circles, then ask whether you can bind what answers.\n\nBegin with the first summons and follow the darker lessons through demons, tomes, mounts, and bargains that always ask for more than coin."] = "흑마법사 전문가들은 힘을 거저 내주지 않습니다. 그들은 이름과 심부름, 마법진을 건넨 뒤, 부름에 응한 것을 속박할 수 있는지 묻습니다.\n\n첫 소환부터 시작해 악마, 마법서, 탈것, 그리고 언제나 돈 이상의 대가를 요구하는 거래로 이어지는 더 어두운 가르침을 따라가십시오."
L["Your warrior trainer has a practical lesson first: learn to stand, endure, and fight with discipline. After that, older tests wait beyond the starting grounds.\n\nSeek the instructors who send warriors to brawls, islands, charms, and a windwatcher's summons. The reward is a weapon, but the road is the real trial."] = "전사 전문가가 먼저 가르치는 것은 실전입니다. 버티고, 견디고, 규율 있게 싸우는 법을 익히십시오. 그 후에는 시작 지역 너머에서 더 오래된 시험이 기다립니다.\n\n전사들을 난투와 섬, 부적, 그리고 바람감시자의 소환으로 이끄는 교관들을 찾으십시오. 보상은 무기이지만, 진정한 시험은 그 여정 자체입니다."
L["Apothecary Johaan has work in Brill, and it is not the sort of work the living would approve of. The Forsaken need samples, records, and willing hands if they are to learn what can still kill the dead.\n\nBegin with the Royal Apothecary Society's errands in Tirisfal and follow the plague work into Silverpine and Hillsbrad. Each vial answers one question and raises another."] = "연금술사 요한에게는 브릴에서 맡길 일이 있지만, 산 자들이 반길 만한 일은 아닙니다. 포세이큰이 죽은 자마저 죽일 수 있는 것이 무엇인지 알아내려면 표본과 기록, 그리고 기꺼이 나설 일손이 필요합니다.\n\n티리스팔에서 왕립 연금술 학회의 심부름으로 시작해, 역병 연구를 따라 은빛소나무 숲과 언덕마루로 향하십시오. 약병 하나가 한 가지 질문에 답하면, 또 다른 질문이 생겨납니다."
L["North of Brill, the Agamand Mills still carry the family name. Coleman Farthing wants proof of what happened there, Deathguard Dillinger wants the dead cleared out, and Magistrate Sevren has heard enough about the family crypt to be concerned.\n\nSearch the old estate, bring back what the Forsaken ask for, and see why Tirisfal's dead rarely stay where they are put."] = "브릴 북쪽의 아가만드 밀농장에는 여전히 그 가문의 이름이 남아 있습니다. 콜만 파딩은 그곳에서 무슨 일이 있었는지 증거를 원하고, 죽음의경비병 딜링거는 망자들을 쓸어버리길 원하며, 집정관 세브렌은 가문의 납골당에 관해 들은 이야기만으로도 걱정이 큽니다.\n\n옛 영지를 뒤져 포세이큰이 요구하는 것을 가져오고, 티리스팔의 망자들이 왜 좀처럼 묻힌 자리에 머물지 않는지 알아보십시오."
L["Auberdine's watchers have seen trouble near the Tower of Althalaxx. Speak with Balthule Shadowstrike and learn what the Cult of the Dark Strand is doing on the northern coast.\n\nWhat begins as a report from Darkshore pulls you toward Ashenvale, where parchments, gems, and old corruption point to a threat still gathering strength."] = "아우버다인의 감시병들이 알살락스의 탑 근처에서 수상한 움직임을 목격했습니다. 발툴 섀도스트라이크와 대화하고 어둠의 끈 교단이 북쪽 해안에서 무슨 일을 꾸미는지 알아보십시오.\n\n어둠해안의 보고로 시작된 일은 잿빛 골짜기로 이어지고, 그곳에서 양피지와 보석, 오래된 타락은 여전히 힘을 모으고 있는 위협을 가리킵니다."
L["The Sepulcher needs help holding Silverpine Forest. Worgen stalk the roads, Dalaran mages keep their own counsel at Ambermill, and rumors from Shadowfang Keep have not grown quieter.\n\nTake the Forsaken orders one by one and learn why the forest still refuses to be claimed."] = "공동묘지는 은빛소나무 숲을 지킬 도움이 필요합니다. 늑대인간이 길을 배회하고, 달라란 마법사들은 호박색 농장에서 속내를 드러내지 않으며, 그림자송곳니 성채에서 들려오는 소문은 잦아들 기미가 없습니다.\n\n포세이큰의 명령을 하나씩 수행하며, 이 숲이 왜 여전히 누구의 손에도 넘어가지 않는지 알아보십시오."
L["High Executor Darthalia has work for anyone willing to serve Tarren Mill. The humans of Hillsbrad still farm, trade, and guard the roads as if the Forsaken claim means nothing.\n\nReport for orders and carry the campaign from the fields to the mines and beyond. Darthalia will tell you who must fall next."] = "고위집행관 다살리아는 타렌 제분소를 위해 일할 각오가 있는 이라면 누구에게나 일을 맡깁니다. 언덕마루의 인간들은 포세이큰의 영유권 주장 따위는 아랑곳없다는 듯 여전히 농사를 짓고, 장사를 하며, 길을 지키고 있습니다.\n\n명령을 받아 들판에서 광산으로, 그리고 그 너머까지 작전을 이어 가십시오. 다음에 누가 쓰러져야 하는지는 다살리아가 알려 줄 것입니다."
L["Marlene Redpath asks you to find her niece Pamela in Darrowshire. In the ruins, a lonely child is still waiting for family and trying to remember where her doll has gone.\n\nBegin with Pamela's small request and follow the Redpath family through old grief, missing records, and the question of what really happened on Darrowshire's last night."] = "말레네 레드패스가 다로우골에서 조카 파멜라를 찾아 달라고 부탁합니다. 폐허 속에서 외로운 아이가 여전히 가족을 기다리며 인형이 어디로 갔는지 기억해 내려 애쓰고 있습니다.\n\n파멜라의 작은 부탁으로 시작해 오래된 슬픔과 사라진 기록, 그리고 다로우골의 마지막 밤에 실제로 무슨 일이 있었는지에 대한 의문을 따라 레드패스 가족의 이야기를 좇으십시오."
L["Deputy Willem has a simple problem near Northshire: thieves in red masks have stolen from the abbey's vineyards. In Elwynn and Westfall, the same masks keep turning up in places they should not.\n\nHelp the local marshals and the People's Militia follow the Defias trail. What begins as bandit work soon asks who is organizing it, and why."] = "부관 윌렘에게 북녘골 근처에서 단순한 문제가 생겼습니다. 붉은 복면을 쓴 도둑들이 수도원의 포도밭을 털어 간 것입니다. 엘윈과 서부 몰락지대에서도 같은 복면이 있어서는 안 될 곳에 자꾸만 나타납니다.\n\n지역 치안대와 민병대를 도와 데피아즈의 흔적을 쫓으십시오. 도적 소탕으로 시작된 일은 곧 누가 이들을 조직하고 있는지, 그리고 그 이유가 무엇인지를 묻게 됩니다."
L["Darkshire keeps its lanterns lit because the woods do not. Commander Althea Ebonlocke needs help with the Night Watch, and every road out of town seems to carry another rumor, corpse, or warning.\n\nTake up the town's work and follow Duskwood's troubles as the locals give them to you: graves, worgen, missing people, and names spoken carefully after dark."] = "숲에는 빛이 없기에, 어둠골은 등불을 꺼뜨리지 않습니다. 사령관 알시아 에본로크는 밤경비대를 도와줄 이가 필요하며, 마을 밖으로 이어진 길마다 또 다른 소문이나 시체, 경고가 실려 오는 듯합니다.\n\n마을의 일을 맡아 주민들이 전하는 대로 그늘숲의 골칫거리를 따라가십시오. 무덤, 늑대인간, 실종자, 그리고 해가 진 뒤에는 조심스럽게만 입에 올리는 이름들이 기다립니다."
L["At the edge of the Blasted Lands, a fallen hero still waits for orders that never came. His regiment is gone, and the demons beyond Nethergarde have had years to make use of what was left behind.\n\nListen to the dead man's account and follow the scattered trail of soldiers, relics, and old command. The road is long because the failure was not simple."] = "저주받은 땅의 가장자리에서, 쓰러진 영웅이 끝내 오지 않은 명령을 여전히 기다리고 있습니다. 그의 연대는 사라졌고, 네더가드 너머의 악마들은 남겨진 것들을 이용할 시간이 수년이나 있었습니다.\n\n죽은 자의 이야기를 듣고 흩어진 병사들과 유물, 옛 지휘 체계의 흔적을 따라가십시오. 길이 먼 것은 그 실패가 결코 단순하지 않았기 때문입니다."
L["Marshal Dughan has posted a bounty at Westbrook Garrison. A Riverpaw brute named Hogger is prowling the woods, and Stormwind wants proof that the roads are safer.\n\nTake the warrant, follow the ridge southwest, and see why the locals speak his name with more concern than a single gnoll should earn."] = "치안대장 더그한이 서쪽시내 주둔지에 현상금을 걸었습니다. 들창코라는 강발톱 놀 무뢰배가 숲을 배회하고 있으며, 스톰윈드는 길이 더 안전해졌다는 증거를 원합니다.\n\n수배서를 받아 남서쪽 산등성이를 따라가며, 주민들이 왜 놀 한 마리에게 어울리지 않을 만큼 걱정스러운 얼굴로 그의 이름을 입에 올리는지 알아보십시오."
L["Under the broken Thandol Span, a dwarf's remains lie where few travelers think to look. Among them is a letter that never reached the woman waiting in Ironforge.\n\nCarry Sully Balloo's words home and let Sara Balloo decide what should be done with them. Some duties begin after the battle is already over."] = "무너진 탄돌 교각 아래, 여행자들이 좀처럼 살피지 않는 곳에 한 드워프의 유해가 놓여 있습니다. 그 곁에는 아이언포지에서 기다리는 여인에게 끝내 전해지지 못한 편지가 있습니다.\n\n설리 발루의 말을 고향으로 가져가, 그것을 어떻게 할지 사라 발루가 결정하게 하십시오. 어떤 의무는 전투가 이미 끝난 뒤에야 시작됩니다."
L["At the Crossroads, Mankrik is looking for his wife. He last saw her on the Gold Road, and the Barrens offers little comfort to anyone searching through quillboar territory.\n\nTake his question with you into the heat and dust. What you find, if you find anything, belongs first to the husband still waiting."] = "크로스로드에서 만크릭이 아내를 찾고 있습니다. 그는 황금길에서 아내를 마지막으로 보았고, 가시멧돼지의 영역을 뒤지는 이에게 불모의 땅은 위안을 거의 주지 않습니다.\n\n그의 물음을 안고 열기와 먼지 속으로 들어가십시오. 무엇을 찾게 되든, 찾을 수 있다면, 그것은 먼저 여전히 기다리는 남편의 몫입니다."
L["Feathermoon Stronghold expected a courier from Thalanaar. He never arrived, and the coast of Feralas has a way of swallowing small boats and easy answers.\n\nSearch the wreckage, carry back what proof you can, and follow the signs inland if the sea is not the whole story."] = "페더문 요새는 탈라나르에서 올 전령을 기다리고 있었습니다. 그는 끝내 도착하지 않았고, 페랄라스 해안은 작은 배도, 손쉬운 답도 곧잘 삼켜 버립니다.\n\n잔해를 수색해 찾을 수 있는 증거를 가져오고, 바다가 이야기의 전부가 아니라면 내륙의 흔적을 따라가십시오."
L["Thomas has been asked to find an adventurer for Bishop DeLavey in Stormwind Keep. The bishop will not speak of the matter openly, only that discretion matters and the kingdom may have need of you.\n\nBegin in Stormwind and follow a quiet trail of favors, contacts, and rumors. What starts as a missing man soon points beyond a simple disappearance."] = "토마스는 스톰윈드 왕궁의 주교 드라베이를 위해 모험가를 찾아 달라는 부탁을 받았습니다. 주교는 이 일을 드러내 놓고 말하지 않고, 신중해야 하며 왕국에 도움이 필요할지도 모른다고만 합니다.\n\n스톰윈드에서 시작해 호의와 연줄, 소문으로 이어진 조용한 흔적을 따라가십시오. 한 남자의 실종으로 시작된 일은 곧 단순한 실종 이상의 무언가를 가리킵니다."
L["In the Burning Steppes, Helendis Riverhorn has orders for the Alliance against black dragonkin gathering near Morgan's Vigil. In Kargath, Warlord Goretooth has a command for the Horde that points into Blackrock Spire.\n\nTake the first report and follow your faction's chain of summons, proofs, and dangerous names. The amulet at the end of the road is not given to anyone who has only heard rumors of dragons."] = "불타는 평원에서 헬렌디스 리버혼은 모건의 망루 근처에 모여드는 검은용족에 맞서 얼라이언스에 명령을 내립니다. 카르가스에서는 장군 고어투스가 검은바위 첨탑을 가리키는 호드의 명령을 준비해 두었습니다.\n\n첫 보고를 받고, 자기 진영의 소환과 증명, 위험한 이름들로 이어지는 연쇄를 따라가십시오. 길 끝에 있는 아뮬렛은 용에 관한 소문만 들어 본 자에게는 주어지지 않습니다."
L["In Blackrock Depths, rumors about Princess Moira Bronzebeard have become too serious for Ironforge to ignore. The Dark Irons say one thing, the kingdom fears another, and no one outside the mountain has the full truth.\n\nEnter the depths on your faction's orders and find out what became of the princess. Rescue may not be as simple as it sounds."] = "검은바위 나락에서 들려오는 공주 모이라 브론즈비어드에 관한 소문이 아이언포지가 외면하기엔 너무 심각해졌습니다. 검은무쇠 드워프는 이렇게 말하고 왕국은 또 다른 것을 두려워하지만, 산 밖에서 온전한 진실을 아는 이는 아무도 없습니다.\n\n자기 진영의 명령에 따라 나락으로 들어가 공주가 어떻게 되었는지 알아내십시오. 구출은 생각만큼 간단하지 않을지도 모릅니다."
L["Raene Wolfrunner sends you west from Astranaar to look for Teronis, who went searching for answers to the furbolg attacks and did not return.\n\nFollow his trail through Ashenvale's moonwells, ruins, and old magic. If the forest is being changed, Raene wants to know how, and who is helping it spread."] = "레이네 울프러너는 펄볼그의 공격에 대한 답을 찾으러 갔다가 돌아오지 않은 테로니스를 찾으라며 아스트라나르 서쪽으로 보냅니다.\n\n잿빛 골짜기의 달샘과 폐허, 오래된 마법을 지나 그의 흔적을 따라가십시오. 숲이 변하고 있다면, 레이네는 그 방식과 확산을 돕는 자가 누구인지 알고 싶어 합니다."
L["At Grom'gol, Nimboya asks after Yenniku, youngest son of the Darkspear chief. The Bloodscalp trolls may know where he was taken, but Stranglethorn rarely gives up a captive cleanly.\n\nPress the jungle tribes for answers, listen when older spirits are called, and keep following the trail even when it turns toward magic no troll should take lightly."] = "그롬골에서 님보야가 검은창 부족장의 막내아들 옌니쿠의 행방을 묻습니다. 붉은머리 트롤들이 그가 어디로 끌려갔는지 알지도 모르지만, 가시덤불 골짜기는 포로를 순순히 내주는 법이 없습니다.\n\n정글 부족들을 압박해 답을 얻어 내고, 오래된 영혼들이 불려 올 때 귀를 기울이며, 어떤 트롤도 가볍게 여겨서는 안 될 마법으로 흔적이 이어지더라도 끝까지 따라가십시오."
L["The Scarlet Crusade claims to defend Lordaeron from the undead, but its soldiers do not always wait to ask who is innocent. In Tirisfal, Southshore, and the Plaguelands, people have reasons to send you against the red tabard.\n\nFollow the Crusade's trail through farms, prisons, monasteries, and northern keeps. Each order you uncover makes their righteousness harder to trust."] = "붉은십자군은 언데드로부터 로데론을 지킨다고 주장하지만, 그 병사들은 누가 무고한지 묻기도 전에 칼을 휘두르기 일쑤입니다. 티리스팔과 남녘해안, 역병지대에는 붉은 휘장에 맞서 달라고 부탁할 이유가 있는 이들이 있습니다.\n\n농장과 감옥, 수도원, 북쪽 성채를 지나 십자군의 흔적을 따라가십시오. 밝혀내는 명령 하나하나가 그들의 정의를 더욱 믿기 어렵게 만듭니다."
L["A battered raft in Un'Goro holds a few odd belongings: a compass, a map, a key, and a photograph. No one stands nearby to explain them. Only the crater, the wreckage, and the sense that someone lost more than supplies.\n\nFollow the clues from Marshal's Refuge and help piece together what happened to their owner. The trail is strange, old-fashioned, and not eager to explain itself."] = "운고로의 낡은 뗏목에는 나침반, 지도, 열쇠, 사진 같은 기묘한 소지품 몇 가지가 남아 있습니다. 그것들을 설명해 줄 사람은 근처에 아무도 없습니다. 분화구와 잔해, 그리고 누군가 보급품보다 더 많은 것을 잃었다는 느낌만이 남아 있을 뿐입니다.\n\n마샬의 야영지에서부터 단서를 따라 그 주인에게 무슨 일이 있었는지 짜 맞춰 보십시오. 그 흔적은 기묘하고, 고풍스러우며, 쉽게 정체를 드러내지 않습니다."
L["A small scroll waits aboard a Bloodsail ship south of Booty Bay. It bears no proper patron, only a riddle and enough direction to make you wonder what was hidden.\n\nTake Cortello's words seriously and follow the clues wherever they send you. The treasure is not marked for anyone who wants a straight road."] = "무법항 남쪽의 붉은해적단 배 위에 작은 두루마리 하나가 놓여 있습니다. 제대로 된 의뢰인의 이름도 없이, 수수께끼 하나와 무엇이 숨겨져 있는지 궁금해질 만큼의 방향만 적혀 있습니다.\n\n코르텔로의 말을 진지하게 받아들이고, 단서가 이끄는 곳이라면 어디든 따라가십시오. 이 보물은 곧은길만 원하는 이를 위해 표시된 것이 아닙니다."
L["Abercrombie's requests sounded lonely before they sounded dangerous. Hair, juice, blossoms, ribs, and a stolen crate became Stitches on the road, and Darkshire learned what the hermit had been making."] = "애버크롬비의 부탁은 위험하게 들리기 전에 먼저 외롭게 들렸다. 머리카락, 즙, 꽃, 갈비뼈, 그리고 도둑맞은 상자는 결국 길 위의 누더기가 되었고, 어둠골은 그 은둔자가 무엇을 만들고 있었는지 알게 되었다."
L["Aid Gryan Stoutmantle in Westfall and seek Wiley the Black's note in Lakeshire."] = "서부 몰락지대의 그라이언 스타우트맨틀을 돕고, 호숫골에서 악당 와일리의 쪽지를 찾으십시오."
L["Alliance priests carry word of Scarlet activity from Stormwind to Desolace, Southshore, and finally the Monastery."] = "얼라이언스 사제들이 붉은십자군의 움직임에 관한 소식을 스톰윈드에서 잊혀진 땅과 남녘해안으로, 그리고 마침내 수도원까지 전합니다."
L["Answer Archmage Xylem's request in Azshara and study the magic left by Warlord Krellian."] = "아즈샤라에서 대마법사 실렘의 요청에 응하고 크렐리안 장군이 남긴 마법을 연구하십시오."
L["Answer your trainer's summons, draw a voidwalker into the circle, and bind it to your will."] = "직업 전문가의 부름에 응해 보이드워커를 마법진으로 끌어들이고 의지로 속박하십시오."
L["Apothecary Johaan began with blood, scales, and venom gathered from the creatures near Brill. In the tavern cellar, a captured mountaineer became the first proof that the new plague could be more than theory."] = "연금술사 요한은 브릴 인근의 짐승들에게서 모은 피와 비늘, 독으로 연구를 시작했다. 여관 지하실에서는 붙잡힌 산악대원 하나가 새로운 역병이 이론에 그치지 않을 수 있다는 첫 증거가 되었다."
L["At Fire Plume Ridge, the strange tools finally proved their worth. The Silver Totem stripped Blazerunner's shield, the sword found its purpose, and the Golden Flame was carried back to Marshal's Refuge. Linken's memory was still imperfect, but the road had given him a shape to follow: hero, blade, flame, and a companion brave enough to see it done."] = "불기둥 마루에서 기묘한 도구들은 마침내 제 몫을 해냈다. 은빛 토템이 블레이즈러너의 보호막을 벗겨 냈고, 검은 제 쓰임새를 찾았으며, 황금 불꽃은 마샬의 야영지로 옮겨졌다. 링쿠의 기억은 여전히 온전하지 않았지만, 여정은 그가 따라갈 하나의 윤곽을 남겨 주었다. 영웅, 검, 불꽃, 그리고 끝까지 함께할 만큼 용감한 동료."
L["At the Deepwater Tavern, follow the man who listens too closely and make Tapoke Jahn tell what he knows."] = "깊은바다 선술집에서 지나치게 귀를 기울이는 남자를 미행하고, 타포케 잔이 아는 것을 털어놓게 하십시오."
L["At the Scarab Wall, Anachronos shows the old war and names the broken road a scepter bearer must follow."] = "스카라베 성벽에서 아나크로노스는 옛 전쟁을 보여 주고, 홀을 지닌 자가 따라야 할 부서진 길을 일러 줍니다."
L["Azuregos sends you to Narain Soothfancy, whose ledger runs through goggles, chops, ransom notes, Draconic pages, and the sea."] = "아주어고스의 안내로 나라인 수스팬시를 찾아갑니다. 그의 장부에는 고글과 고기, 몸값 요구서, 용언 문서, 그리고 바다가 줄줄이 이어집니다."
L["Baristolth sends you to Anachronos and then to Blackwing Lair. Broodlord Lashlayer's head begins the work of earning Nozdormu's trust."] = "바리스톨스는 아나크로노스에게, 그리고 검은날개 둥지로 길을 안내합니다. 무리군주 래쉬레이어의 머리는 노즈도르무의 신뢰를 얻는 첫걸음입니다."
L["Before Tirion Fordring's search for his son, Hearthglen already stood as a military problem. Kirsta Deepshadow wanted the Scarlet Crusade measured in practical terms: medics, hunters, magi, knights, named officers, and the strength of the town itself. The reconnaissance made one thing clear. Hearthglen was not a remnant. It was an army still drilling under red banners."] = "티리온 폴드링이 아들을 찾아 나서기 전부터 하스글렌은 이미 군사적 골칫거리였다. 키르스타 딥섀도는 붉은십자군을 실질적인 기준으로 가늠하고자 했다. 의무병, 사냥꾼, 마법사, 기사, 이름난 장교들, 그리고 마을 자체의 힘까지. 정찰 끝에 한 가지가 분명해졌다. 하스글렌은 잔당이 아니었다. 여전히 붉은 깃발 아래 훈련을 이어 가는 군대였다."
L["Begin in the Burning Steppes with Helendis Riverhorn and carry the black dragon reports between Lakeshire, Stormwind, and Morgan's Vigil."] = "불타는 평원의 헬렌디스 리버혼에게서 시작해, 검은용에 관한 보고를 호숫골, 스톰윈드, 모건의 망루 사이로 전하십시오."
L["Begin Lord Grayson Shadowbreaker's rite and prepare yourself for the charger's judgment."] = "그레이슨 섀도브레이커 경의 의식을 시작하고 군마의 심판에 대비하십시오."
L["Begin Mor'zul Bloodbringer's work, gather the ritual tools, and prepare the road to Xoroth."] = "모르줄 블러드브링어의 과업을 시작해 의식 도구를 모으고 조로스로 가는 길을 준비하십시오."
L["Begin Nimboya's search by pressing the Bloodscalp trolls for any sign of Yenniku."] = "붉은머리 트롤들을 몰아붙여 옌니쿠의 흔적을 찾으며 님보야의 수색을 시작하십시오."
L["Begin with the red masks near Northshire and follow the same bandit sign through Elwynn."] = "북녘골 근처의 붉은 복면들로 시작해, 같은 도적 무리의 표식을 따라 엘윈 곳곳을 추적하십시오."
L["Bodley was frightened, talkative, and deeply entangled in Lord Valthalak's fate. Through him, the armor work became a matter of flame, reputation, and a shattered amulet."] = "보들리는 겁에 질려 있었고, 말이 많았으며, 군주 발타라크의 운명과 깊이 얽혀 있었다. 그를 통해 방어구 작업은 불꽃과 평판, 그리고 부서진 아뮬렛의 문제가 되었다."
L["Break the Stones of Binding and seek the last names left to the Fallen Hero: Corporal Thund Splithoof and Lieutenant Kirith."] = "속박의 돌을 부수고, 쓰러진 영웅에게 남은 마지막 이름들인 하사관 선드 스플릿후프와 부관 키리스를 찾으십시오."
L["Bring a Dungeon Set 1 bracer to Deliana or Mokvar and accept the first upgrade work."] = "던전 1 세트 손목 방어구를 델리아나 또는 모크바르에게 가져가 첫 강화 작업을 맡으십시오."
L["Bring General Drakkisath's blood to Rexxar and complete the Drakefire Amulet."] = "사령관 드라키사스의 피를 렉사르에게 가져가 비룡불꽃 아뮬렛을 완성하십시오."
L["Bring proof of the elements to the temple trial and show that the four powers can be held together."] = "정령의 증표를 사원의 시험장으로 가져가, 네 가지 힘을 하나로 아우를 수 있음을 보이십시오."
L["Bring Raschal's knife to Quintis Jonespyre and let the blade show what ordinary searching could not."] = "라샬의 칼을 퀸티스 존스파이어에게 가져가, 평범한 수색으로는 알 수 없던 것을 칼날이 보여 주게 하십시오."
L["Bring the Ancient Petrified Leaf to Felwood and hear what the ancients require of a hunter."] = "고대의 석화된 잎을 악령의 숲으로 가져가, 고대정령들이 사냥꾼에게 무엇을 요구하는지 들으십시오."
L["Bring the dead leaders to the cauldron and answer the price they demand before they speak."] = "죽은 족장들을 가마솥으로 데려가, 그들이 입을 열기 전에 요구하는 대가를 치르십시오."
L["By the time you reached Brill, the Scarlet Crusade was no rumor. Deathguard Simmer's stolen pumpkins became Apothecary Johaan's experiment, and a captured Scarlet Zealot learned how the Royal Apothecary Society meant to answer holy certainty. Outside town, Executor Zygand sent you into the Scarlet camps again and again until their officers broke. Brill's campaign was not only defense. It was the Forsaken answer taking shape."] = "브릴에 이르렀을 무렵, 붉은십자군은 더 이상 소문이 아니었다. 죽음경비병 시머의 도둑맞은 호박은 연금술사 요한의 실험 재료가 되었고, 붙잡힌 붉은십자군 광신도는 왕립 연금술 학회가 성스러운 확신에 어떻게 답하려 하는지 몸소 겪게 되었다. 마을 밖에서는 집행관 자이건드가 장교들이 무너질 때까지 붉은십자군 야영지로 몇 번이고 다시 보냈다. 브릴의 작전은 방어에 그치지 않았다. 그것은 포세이큰의 대답이 모습을 갖추어 가는 과정이었다."
L["Carlin and Chromie needed names made into relics: Horgus, Marduk, Davil, Joseph, and the marauders who joined the slaughter. Each recovered piece brought the last battle closer to being answered."] = "칼린과 크로미는 이름들을 유물로 바꿔 줄 이가 필요했다. 호르구스, 마르둑, 다빌, 조셉, 그리고 학살에 가담한 약탈자들까지. 되찾은 조각 하나하나가 마지막 전투의 답에 한 걸음씩 다가가게 했다."
L["Carry Balthule's warning to Delgren and follow the Dark Strand's trail through Ashenvale."] = "발툴의 경고를 델그렌에게 전하고, 잿빛 골짜기를 가로지르는 어둠의 끈 교단의 흔적을 따라가십시오."
L["Carry Duthorian Rall's lesson to Westfall and prove that valor protects those who cannot stand alone."] = "두소리안 랄의 가르침을 서부 몰락지대로 가져가, 용맹이란 홀로 설 수 없는 이들을 지키는 것임을 증명하십시오."
L["Carry the Azsharite to Galvan the Ancient so Felbane can be forged for the Blasted Lands."] = "아즈샤리트를 전설의 대장장이 갈반에게 가져가, 저주받은 땅에서 쓸 지옥파멸을 벼려 내게 하십시오."
L["Carry the Silver Totem into Linken's final trial and see whether the old adventure can be finished."] = "은빛 토템을 들고 링쿠의 마지막 시험에 나서, 오래된 모험을 끝맺을 수 있을지 확인하십시오."
L["Carry VanCleef's letter to Baros Alexston and follow the matter into the Stockade."] = "밴클리프의 편지를 바로스 알렉스턴에게 전하고, 지하감옥까지 그 일을 쫓으십시오."
L["Carry waters between distant places and learn why this totem asks for patience."] = "먼 곳 사이를 오가며 물을 나르고, 이 토템이 왜 인내를 요구하는지 깨달으십시오."
L["Commander Gor'shak's message pulls the Horde into Blackrock Depths, where Moira's captivity may shape more than one kingdom."] = "사령관 고르샤크의 전갈은 호드를 검은바위 나락으로 이끕니다. 그곳에 사로잡힌 모이라의 운명은 한 왕국 이상의 앞날을 바꿀지도 모릅니다."
L["Complete your first warrior trial and learn the stance that keeps you standing when blows fall."] = "첫 번째 전사 시험을 완수하고, 공격이 쏟아질 때도 버틸 수 있게 해 주는 태세를 익히십시오."
L["Dalar Dawnweaver asks you to thin the Moonrage worgen and recover signs of Arugal's magic."] = "달라 돈위버가 달빛분노 늑대인간의 수를 줄이고 아루갈의 마법 흔적을 찾아 달라고 부탁합니다."
L["Dalar Dawnweaver wanted proof that Arugal's curse still stained Silverpine. You hunted Moonrage worgen, recovered the Remedy of Arugal, and struck down those most touched by the mage's work."] = "달라 돈위버는 아루갈의 저주가 여전히 은빛소나무 숲을 더럽히고 있다는 증거를 원했다. 달빛분노 늑대인간을 사냥하고, 아루갈의 치료약을 되찾고, 그 마법사의 손길이 가장 깊이 닿은 자들을 쓰러뜨렸다."
L["Darkshire's first need was simple: more blades for the Night Watch. You answered Althea's call at Raven Hill and helped hold a town Stormwind could not easily protect."] = "어둠골에 가장 먼저 필요한 것은 단순했다. 밤경비대에 칼 한 자루라도 더 보태는 것. 까마귀 언덕에서 알시아의 부름에 응했고, 스톰윈드조차 쉽게 지켜 주지 못하는 마을을 지키는 데 힘을 보탰다."
L["Darthalia's first orders were plain: strike the farms, kill those who worked them, and leave the town afraid. Tarren Mill's campaign had begun."] = "다살리아의 첫 명령은 분명했다. 농장을 습격하고, 그곳에서 일하는 자들을 죽이고, 마을을 공포에 빠뜨리라는 것. 타렌 제분소의 작전이 시작되었다."
L["Deathknell's newly risen are not alone. Strike the Scarlet converts and take the courier's message before it leaves the valley."] = "죽음의 종소리 마을에 새로 깨어난 이들만 있는 것은 아닙니다. 붉은십자군 개종자들을 처치하고, 전령의 전갈이 골짜기를 벗어나기 전에 빼앗으십시오."
L["Delgren sent you after the cult's soul gems and writings from Ordil'Aran to Fire Scar Shrine and Satyrnaar. Each recovered piece loosened the hold of the power behind Althalaxx."] = "델그렌은 오딜아란에서 불타버린 신전과 사티르나르에 이르기까지 교단의 영혼석과 문서를 찾아오게 했다. 되찾은 조각 하나하나가 알살락스 배후에 있는 힘의 손아귀를 느슨하게 만들었다."
L["Dun Garok stood as the last hard point in Darthalia's campaign. When its mountaineers, priests, riflemen, and Captain Ironhill were dead, her commendation could be carried to Varimathras."] = "던 가록은 다살리아의 작전에서 마지막 남은 거점이었다. 그곳의 산악대원, 사제, 소총병, 그리고 부대장 아이언힐까지 모두 쓰러지자, 그녀의 추천장을 바리마트라스에게 전할 수 있게 되었다."
L["Emberstrife demands the skulls of four dragons: Scryer, Somnus, Chronalis, and Axtroz."] = "엠버스트라이프는 네 용의 두개골을 요구합니다. 스크라이어, 솜누스, 크로날리스, 악트로즈입니다."
L["Emberstrife's tests scattered the Horde across Azeroth. Scryer waited in Winterspring, Somnus haunted Swamp of Sorrows, Chronalis guarded the Caverns of Time, and Axtroz patrolled the road to Grim Batol. Each skull was trophy, key, and proof of strength. By the time the fourth dragon fell, Emberstrife's amulet was ready for the last transformation."] = "엠버스트라이프의 시험은 호드를 아제로스 곳곳으로 흩어지게 했다. 스크라이어는 여명의 설원에서 기다렸고, 솜누스는 슬픔의 늪을 떠돌았으며, 크로날리스는 시간의 동굴을 지켰고, 악트로즈는 그림 바톨로 가는 길을 순찰했다. 두개골 하나하나가 전리품이자 열쇠였고, 힘의 증거였다. 네 번째 용이 쓰러졌을 때, 엠버스트라이프의 아뮬렛은 마지막 변화를 맞을 준비가 되어 있었다."
L["Enter Dire Maul and recover the knowledge Lorekeeper Lydros keeps in the Athenaeum."] = "혈투의 전장에 들어가 현자 리드로스가 학술원에 간직한 지식을 되찾으십시오."
L["Enter Shadowfang Keep for the missing deathstalkers, the Book of Ur, and the mage who rules above the forest."] = "실종된 죽음추적자들과 우르의 책, 그리고 숲 위에 군림하는 마법사를 찾아 그림자송곳니 성채로 들어가십시오."
L["Enter the Deadmines beneath Moonbrook and confront the Brotherhood at the heart of its hideout."] = "달빛시내 마을 아래 죽음의 폐광으로 들어가, 은신처 한복판에서 형제단과 맞서십시오."
L["Enter the Monastery's graveyard and library for prisoners, forbidden books, and the records the Crusade keeps locked away."] = "수도원의 묘지와 도서관으로 들어가 포로들과 금서, 그리고 십자군이 깊이 숨겨 둔 기록을 찾으십시오."
L["Follow the last sign into the hive and learn whether Raschal's errand can still be answered."] = "마지막 흔적을 따라 벌집으로 들어가, 라샬의 임무를 아직 마무리할 수 있는지 알아보십시오."
L["Eris Havenfire's trial tested mercy under pressure. You kept the fallen moving, held shadow at bay, and earned Benediction through discipline and compassion."] = "에리스 헤븐파이어의 시험은 압박 속에서도 자비를 지킬 수 있는지 시험했다. 쓰러져 가는 이들을 계속 걷게 하고, 어둠을 막아 내며, 규율과 연민으로 축복을 얻어 냈다."
L["Escort Marshal Windsor back to Stormwind and stand with him when his proof is finally heard."] = "치안대장 윈저를 스톰윈드까지 호위하고, 마침내 그의 증거가 받아들여질 때 곁을 지키십시오."
L["Falrin Treeshaper's vendetta turned Dire Maul's library into your next post. The creatures he named were hunted, the enchantment was made, and a challenge was prepared for Blackrock Depths."] = "팔린 트리셰이퍼의 복수심은 혈투의 전장 도서관을 다음 임무지로 만들었다. 그가 지목한 괴물들을 사냥하고 마법부여를 마쳤으며, 검은바위 나락에서 치를 도전이 준비되었다."
L["Felwood gave the search older magic. Eridan Bluewind understood the silver heart Linken had been trying to make and sent you into Winterspring's old forests before Aquementas rose in Un'Goro. The elemental's power became a silver totem, the key to stripping away the final guardian's protection. The errand had strange humor about it, but the ritual was real."] = "악령숲은 수색에 더 오래된 마법을 더했다. 에리단 블루윈드는 링쿠가 만들려던 은빛 심장을 알아보았고, 운고로에서 아쿠에멘타스가 일어서기 전에 여명의 설원의 오래된 숲으로 보냈다. 그 정령의 힘은 은빛 토템이 되었고, 마지막 수호자의 보호막을 벗겨 낼 열쇠가 되었다. 심부름에는 묘한 유머가 깃들어 있었지만, 의식만큼은 진짜였다."
L["Find Balthule Shadowstrike near the Tower of Althalaxx and learn what gathers on Darkshore's northern coast."] = "알살락스의 탑 근처에서 발툴 섀도스트라이크를 찾아, 어둠해안 북쪽 해안에 무엇이 모여들고 있는지 알아보십시오."
L["Find Bodley near Blackrock Spire and learn why Lord Valthalak's amulet matters."] = "검은바위 첨탑 근처에서 보들리를 찾아, 군주 발타라크의 아뮬렛이 왜 중요한지 알아보십시오."
L["Find Pamela Redpath in Darrowshire and help gather the pieces of the doll she has lost."] = "다로우골에서 파멜라 레드패스를 찾아, 잃어버린 인형 조각을 모으는 일을 도우십시오."
L["Find Ravenholdt Manor and present yourself to the rogues who keep their own company in the hills."] = "라벤홀트 장원을 찾아, 언덕에 은거하는 도적들 앞에 모습을 드러내십시오."
L["Find Rexxar and follow the trials he sets before the amulet can be completed."] = "렉사르를 찾아, 아뮬렛을 완성하기 전에 그가 내리는 시험을 따르십시오."
L["Fire asked for risk, offering, and obedience to the rite. When the brazier answered, the flame became a servant at your side."] = "불은 위험과 공물, 그리고 의식에 대한 복종을 요구했다. 화로가 응답하자, 불꽃은 곁을 지키는 하수인이 되었다."
L["Follow Madame Eva's cards through old records, locked chests, and the trail of Stalvan Mistmantle."] = "에바 부인의 카드를 따라 오래된 기록과 잠긴 상자, 그리고 스탈반 미스트맨틀의 흔적을 좇으십시오."
L["Follow Pamela's family trail to Marlene, Carlin, and Chromie, who seeks the Annals of Darrowshire."] = "파멜라의 가족을 따라 말레네와 칼린, 그리고 다로우골 연대기를 찾는 크로미에게로 가십시오."
L["Follow Shael'dryn's guidance through old Ashenvale magic and the work left unfinished by Teronis."] = "셸드린의 인도를 따라 잿빛 골짜기의 오래된 마법과 테로니스가 끝내지 못한 일을 좇으십시오."
L["Follow Sven's grief, Jitters' journal, and the shadow that hangs over Raven Hill."] = "스벤의 슬픔과 지터스의 일지, 그리고 까마귀 언덕에 드리운 그림자를 따라가십시오."
L["Follow the call of fire through offerings, reagents, and the flame that waits in Durotar."] = "공물과 재료, 그리고 듀로타에서 기다리는 불꽃을 통해 불의 부름을 따르십시오."
L["Follow the Circle's instructions, gather what is needed for a cure, and cleanse the sick beasts you find."] = "의회의 지시에 따라 치료에 필요한 것을 모으고, 발견한 병든 짐승들을 정화하십시오."
L["Follow the Devourer of Souls chain and prepare the binding of a subtler demon."] = "'영혼에 굶주린 자' 연계 퀘스트를 따라, 더 교묘한 악마를 속박할 준비를 하십시오."
L["Trust the musty scroll's final verse and search where Cortello chose to hide his prize."] = "곰팡내 나는 두루마리의 마지막 구절을 믿고, 코르텔로가 보물을 숨긴 곳을 찾으십시오."
L["Follow Thelwater, Baros, Shaw, and Trias as the Defias trail returns to Stormwind."] = "데피아즈의 흔적이 스톰윈드로 되돌아가는 동안 델워터, 바로스, 쇼, 트리아스를 따라가십시오."
L["Follow Watcher Backus to Addle's Stead and bring the Defias docket back to Trias."] = "순찰대원 바커스를 따라 애들 농장으로 가서, 데피아즈 문서를 트리아스에게 가져가십시오."
L["Follow your faction's rogue trainer into guarded ground, locked boxes, and the antidote work needed for poisons."] = "자기 진영의 도적 전문가를 따라 경비가 삼엄한 곳과 잠긴 상자, 그리고 독을 다루는 데 필요한 해독제 연구로 나아가십시오."
L["From Stonard or Nethergarde, the road ended at the same ghost. The Fallen Hero told what waited beyond the swamp: Razelikh's servants took his fallen regiment, denied them rest, and bound them to stones of demonic power. His regret became an order of its own. If his soldiers could not live, they could still be set free."] = "스토나드에서든 네더가드에서든, 길은 같은 유령 앞에서 끝났다. 쓰러진 영웅은 늪 너머에 무엇이 기다리는지 들려주었다. 라젤리크의 하수인들이 쓰러진 그의 연대를 끌고 가 안식을 빼앗고, 악마의 힘이 깃든 돌에 묶어 두었다는 것이었다. 그의 회한은 그 자체로 하나의 명령이 되었다. 병사들을 살릴 수는 없어도, 풀어 줄 수는 있었다."
L["Gather ectoplasm, a power source, and goblin parts so Mux can finish his device."] = "먹스가 장치를 완성할 수 있도록 원형질과 동력원, 고블린 부품을 모으십시오."
L["Gather Johaan's ingredients around Brill and bring the mixture to the prisoner in the Gallows' End Tavern."] = "브릴 주변에서 요한의 재료를 모아, 교수대끝 선술집에 갇힌 포로에게 혼합물을 가져가십시오."
L["Gather Jordan Stilwell's materials from distant dangers and help forge Verigan's Fist."] = "위험한 먼 땅에서 조던 스틸웰의 재료를 모아 베리건의 주먹을 벼려 내는 일을 도우십시오."
L["Gather singing crystals and the Mind's Eye so Kin'weelay can make a Soul Gem for Yenniku."] = "노래하는 수정과 정신의 눈을 모아, 킨윌레이가 옌니쿠를 위한 영혼석을 만들 수 있게 하십시오."
L["Gather the final materials and ready the Brazier of Invocation for Upper Blackrock Spire."] = "마지막 재료를 모아, 검은바위 첨탑 상층에서 쓸 기원의 화로를 준비하십시오."
L["Go north of Brill to the Agamand Mills, clear the dead, and recover what remains of the family."] = "브릴 북쪽의 아가만드 밀농장으로 가서 망자들을 처치하고, 가문에 남은 것을 되찾으십시오."
L["Go to Tabetha in Dustwallow Marsh, recover the knowledge she needs, and prepare a wand of your chosen school."] = "먼지진흙 습지대의 타베사를 찾아가 그녀에게 필요한 지식을 구하고, 원하는 계열의 마법봉을 준비하십시오."
L["Gryan Stoutmantle suspected that Westfall's troubles reached beyond scattered bandits. Wiley's note confirmed allies, machinery, hidden routes, and the old grievance of the Stonemasons."] = "그라이언 스타우트맨틀은 서부 몰락지대의 혼란이 흩어진 도적 떼 이상의 문제라고 의심했다. 와일리의 쪽지는 협력자, 기계, 숨겨진 경로, 그리고 석공 조합의 오랜 원한을 확인해 주었다."
L["Hear Ragged John's tale, find Marshal Windsor in Blackrock Depths, and recover the proof taken from him."] = "털보 존의 이야기를 듣고, 검은바위 나락에서 치안대장 윈저를 찾아 그에게서 빼앗긴 증거를 되찾으십시오."
L["Hear the old tale of Thaurissan, then enter Blackrock Depths to learn what the mountain is hiding."] = "타우릿산에 관한 옛이야기를 들은 뒤 검은바위 나락에 들어가, 산이 무엇을 숨기고 있는지 알아보십시오."
L["Help Calor and Carevin hunt the worgen moving through Brightwood Grove and the Rotting Orchard."] = "칼로와 캐레빈을 도와 밝은나무 숲과 썩어가는 과수원을 누비는 늑대인간을 사냥하십시오."
L["Help Lydon finish the Elixir of Agony and find a way to deliver it to the captured farmers upstairs."] = "라이던이 죽음의 비약을 완성하도록 돕고, 위층에 붙잡힌 농부들에게 그것을 먹일 방법을 찾으십시오."
L["Help Tyrion prepare the spybot and learn what quiet meeting it was built to uncover."] = "티리온이 첩보로봇을 준비하도록 돕고, 그것이 어떤 은밀한 회합을 밝혀내려고 만들어졌는지 알아보십시오."
L["High Executor Hadrec's missing deathstalkers, Bel'dugur's forbidden book, and Dalar's demand all led into Shadowfang Keep. Arugal fell there, and the Sepulcher received the proof it required."] = "고위집행관 하드렉의 실종된 죽음추적자들, 벨두구르의 금서, 그리고 달라의 요구가 모두 그림자송곳니 성채로 이어졌다. 아루갈은 그곳에서 쓰러졌고, 공동묘지는 필요한 증거를 손에 넣었다."
L["Hillsbrad's strength lay in its smithy, leaders, registry, and mine. Darthalia sent you against each in turn, breaking the town by removing the people and records that held it together."] = "언덕마루의 힘은 대장간과 지도자들, 주민 명부, 그리고 광산에 있었다. 다살리아는 그 하나하나를 차례로 노리게 했고, 마을을 지탱하던 사람들과 기록을 없애 마을을 무너뜨렸다."
L["If the Eye of Divinity comes into your possession, seek Eris Havenfire in the Eastern Plaguelands. She has a trial that asks for more than quick hands and bright prayers.\n\nStand between panic and shadow, save who you can, and learn whether your faith holds when every mistake has a cost."] = "신성의 눈을 손에 넣었다면 동부 역병지대의 에리스 헤븐파이어를 찾아가십시오. 그녀의 시험은 재빠른 손놀림과 눈부신 기도 이상을 요구합니다.\n\n공포와 어둠 사이에 서서 구할 수 있는 이들을 구하고, 모든 실수에 대가가 따를 때도 신앙이 흔들리지 않는지 확인하십시오."
L["In Brill, the Forsaken answer the Crusade with prisoners, poison, and attacks against the camps west of town."] = "브릴에서 포세이큰은 포로와 독, 그리고 마을 서쪽 야영지에 대한 공격으로 십자군에 맞섭니다."
L["In Kargath, take Warlord Goretooth's orders into Blackrock Spire and bring Rend Blackhand's command to Thrall."] = "카르가스에서 장군 고어투스의 명령을 받아 검은바위 첨탑으로 들어가고, 렌드 블랙핸드의 명령서를 스랄에게 가져가십시오."
L["In Silithus, the Bronze Dragonflight does not hand trust to strangers. Before anyone can challenge what waits behind Ahn'Qiraj's gates, someone must prove they are more than another mortal asking for legends.\n\nBegin with the Brood of Nozdormu and follow the old scepter's trail through dragonflights, hidden lairs, bargains, and errands that sound impossible until someone does them."] = "실리더스에서 청동용군단은 낯선 이에게 쉽게 신뢰를 내주지 않습니다. 안퀴라즈의 관문 너머에 도사린 것에 도전하려면, 먼저 전설을 좇는 또 한 명의 필멸자 이상임을 증명해야 합니다.\n\n노즈도르무 혈족에서 시작해 여러 용군단과 숨겨진 둥지, 거래, 그리고 누군가 해내기 전까지는 불가능해 보이는 심부름으로 이어진 옛 홀의 흔적을 따라가십시오."
L["In Stratholme, search the Scarlet Bastion for the archive and the truth hidden behind its holy face."] = "스트라솔름의 붉은십자군 성채를 수색해, 기록 보관소와 성스러운 겉모습 뒤에 숨겨진 진실을 찾으십시오."
L["In Theramore, find Private Hendel near Sentry Point and bring him in alive if you can."] = "테라모어에서 감시초소 근처의 병사 헨델을 찾아, 가능하다면 산 채로 데려오십시오."
L["Join Commander Althea's Night Watch and begin clearing the dead around Raven Hill."] = "사령관 알시아의 밤경비대에 합류해 까마귀 언덕 주변의 망자들을 처치하기 시작하십시오."
L["King Magni sends the letter on to Grand Mason Marblesten, who needs Alterac Granite before Sully's memorial can stand."] = "마그니 왕은 편지를 대석공 마블스텐에게 보냅니다. 설리의 추모비를 세우려면 알터랙 화강암이 필요합니다."
L["Kirsta Deepshadow sends you into the Scarlet lines around Hearthglen to kill their specialists and scout the fortress."] = "키르스타 딥섀도는 하스글렌 주변의 붉은십자군 전선으로 보내 그들의 전문 병력을 처치하고 요새를 정찰하게 합니다."
L["Krellian's magic broke apart in curious ways, and Xylem knew what to make of it. The result was odd, useful, and unmistakably a mage's lesson."] = "크렐리안의 마법은 기묘한 방식으로 흩어졌고, 실렘은 그것으로 무엇을 만들어야 할지 알고 있었다. 그 결과물은 별나고 쓸모 있었으며, 틀림없는 마법사의 가르침이었다."
L["Latronicus sends you to Ginro Hearthkindle, who needs the Feralas coast searched for Raschal's missing boat."] = "라트로니쿠스는 긴로 하트킨들에게 보냅니다. 그는 라샬의 사라진 배를 찾아 페랄라스 해안을 수색해 줄 이가 필요합니다."
L["Linken's memory did not return like a clean answer. It came through strange errands, ghostly meetings, and a sword that changed in flashes of light. Donova, Gaeriyan, and the grave outside Gadgetzan turned the lost gnome's fragments into a rite of recovery. By the time the sword was reforged, Linken still did not fully understand himself, but the road was opening before him again."] = "링쿠의 기억은 명쾌한 답처럼 돌아오지 않았다. 기묘한 심부름과 유령과의 만남, 섬광 속에서 모습을 바꾸는 검을 통해 조금씩 돌아왔다. 도노바와 개리얀, 그리고 가젯잔 외곽의 무덤은 길 잃은 노움의 기억 조각들을 되찾는 의식이 되었다. 검이 다시 벼려졌을 때도 링쿠는 여전히 자신을 온전히 이해하지 못했지만, 그의 앞에는 다시 길이 열리고 있었다."
L["Lorekeeper Lydros entrusted you with a spell every company of adventurers comes to value. Power is not always flame and frost; sometimes it is preparation."] = "현자 리드로스는 어떤 모험가 일행이든 결국 소중히 여기게 되는 주문을 맡겼다. 힘이 언제나 화염과 냉기인 것은 아니다. 때로는 준비가 곧 힘이다."
L["Lydon's work in Tarren Mill turned research into local experiment. Tongues, ichor, and mountain lion blood became elixirs, and the tests on Umpi and Stanley showed how cruelly effective they could be."] = "타렌 제분소에서 라이던의 작업은 연구를 현장 실험으로 바꾸어 놓았다. 혀와 체액, 산사자의 피는 비약이 되었고, 움피와 스탠리를 대상으로 한 실험은 그것이 얼마나 잔인할 만큼 효과적인지 보여 주었다."
L["Magistrate Sevren knew the trouble went below the mills. In the family crypt you found older dead, wailing ancestors, and Captain Dargol's skull, ending the matter one grave at a time."] = "집정관 세브렌은 문제가 제분소 아래까지 뻗어 있다는 것을 알고 있었다. 가문의 납골당에서는 더 오래된 망자들과 울부짖는 조상들, 그리고 대장 다르골의 두개골이 나왔고, 무덤을 하나씩 정리하며 사건은 끝을 맺었다."
L["Mankrik survived a quillboar attack on the Gold Road, but Olgra did not return. Search the road south of the Crossroads for his wife."] = "만크릭은 황금길에서 가시멧돼지의 습격을 받고도 살아남았지만, 올그라는 돌아오지 않았습니다. 크로스로드 남쪽 길을 수색해 그의 아내를 찾으십시오."
L["Mankrik's request was painfully plain: find his wife. The Barrens offered little direction and less mercy, only a long road south of the Crossroads and quillboar waiting in the dust. When Olgra was found, the search became grief. Mankrik had asked for hope and received a body. What followed was the only answer his pain could bear: Bristleback tusks, brought back one by one."] = "만크릭의 부탁은 고통스러울 만큼 단순했다. 아내를 찾아 달라는 것. 불모의 땅은 방향도, 자비도 거의 내주지 않았다. 크로스로드 남쪽으로 뻗은 긴 길과 먼지 속에서 기다리는 가시멧돼지뿐이었다. 올그라를 찾았을 때 수색은 슬픔으로 바뀌었다. 만크릭은 희망을 구했지만 돌아온 것은 시신이었다. 그 뒤에 이어진 것은 그의 고통이 감당할 수 있는 유일한 답이었다. 하나씩 거둬 온 뻣뻣털 가시멧돼지의 엄니."
L["March on Dun Garok and bring Darthalia the victory she needs for her sealed commendation."] = "던 가록으로 진군해, 다살리아가 봉인된 추천장을 받는 데 필요한 승리를 안겨 주십시오."
L["Marlene's request led you to Pamela Redpath, alone among the ruins and still asking after her doll. Returning the pieces brought comfort, and also the first hard truth of Darrowshire."] = "말레네의 부탁을 따라가자 파멜라 레드패스가 있었다. 아이는 폐허 속에 홀로 남아 여전히 인형을 찾고 있었다. 조각을 돌려주자 위안이 찾아왔지만, 다로우골의 첫 번째 가혹한 진실도 함께 드러났다."
L["Meet Falrin Treeshaper in Dire Maul and gather what he needs for the next challenge."] = "혈투의 전장에서 팔린 트리셰이퍼를 만나, 다음 도전에 필요한 것을 모으십시오."
L["Menethil Harbor made the conspiracy plain. Mikhail noticed a listener by the tavern door, and Tapoke \"Slim\" Jahn tried to run before the questions reached him. When he broke, the case changed completely. The Defias had not taken a mere diplomat. They had taken Stormwind's king, and Slim had helped place Hendel aboard the king's ship. Mikhail could only send you to Theramore before the trail disappeared into military silence."] = "메네실 항구에서 음모의 실체가 드러났다. 미크헤일은 선술집 문가에서 엿듣는 자를 눈치챘고, \"홀쭉이\" 타포케 잔은 추궁이 닥치기 전에 달아나려 했다. 그가 입을 열자 사건의 양상은 완전히 바뀌었다. 데피아즈가 납치한 것은 한낱 외교관이 아니었다. 그들은 스톰윈드의 국왕을 데려갔고, 홀쭉이는 헨델을 왕의 배에 태우는 데 손을 보탰다. 미크헤일이 할 수 있는 일은 흔적이 군의 침묵 속으로 사라지기 전에 테라모어로 보내는 것뿐이었다."
L["Moira's disappearance led backward to old Thaurissan and the War of the Three Hammers. Ironforge's old wound led straight into Blackrock Depths, where Kharan Mighthammer's prison cell held the news Magni did not want to hear. Moira was in the heart of the Dark Iron kingdom, and the rescue he wanted was already tangled in questions of love, control, succession, and inherited hatred."] = "모이라의 실종은 과거로 거슬러 올라가 옛 타우릿산과 세 망치의 전쟁으로 이어졌다. 아이언포지의 오래된 상처는 곧장 검은바위 나락으로 이어졌고, 그곳 카란 마이트해머의 감방에는 마그니가 듣고 싶지 않았던 소식이 기다리고 있었다. 모이라는 검은무쇠 왕국의 심장부에 있었고, 그가 바란 구출은 이미 사랑과 지배, 왕위 계승, 그리고 대물림된 증오의 문제와 얽혀 있었다."
L["Mor'zul and Gorzeeki sent you through blood, stardust, Jaedenar, and Scholomance. In Dire Maul the rite opened, and the dreadsteed came through bound to your command."] = "모르줄과 고르지키는 피와 별가루, 자에데나르, 스칼로맨스를 거치는 길로 보냈다. 혈투의 전장에서 의식이 열렸고, 공포의 군마가 명령에 묶인 채 모습을 드러냈다."
L["Morgan Ladimore's grave led to a sorrow Darkshire had tried to bury. You ended Mor'Ladim's wandering and brought Sarah Ladimore the truth of her father."] = "모건 래디모어의 무덤은 어둠골이 묻어 두려 했던 슬픔으로 이어졌다. 모르라딤의 방황을 끝내고, 사라 래디모어에게 아버지에 관한 진실을 전했다."
L["Move from fields to town records, workers, leaders, and the mine that keeps Hillsbrad supplied."] = "들판에서 마을의 기록과 일꾼, 지도자들, 그리고 언덕마루에 물자를 대는 광산으로 공격을 넓히십시오."
L["Mux Manascrambler's device required ghostly residue, strange power, and parts only a goblin would trust. Once complete, it pointed the armor work toward matters no smith could see unaided."] = "먹스 마나스크램블러의 장치에는 유령의 잔여물과 기묘한 동력, 그리고 고블린만 믿을 법한 부품이 필요했다. 완성된 장치는 어떤 대장장이도 맨눈으로는 볼 수 없는 문제로 방어구 작업의 방향을 돌려놓았다."
L["Pamela's family was scattered by grief: Marlene near Andorhal, Jessica far away, and Carlin at Light's Hope. Chromie gave their sorrow a shape by asking for the Annals of Darrowshire."] = "파멜라의 가족은 슬픔으로 뿔뿔이 흩어져 있었다. 말레네는 안돌할 근처에, 제시카는 먼 곳에, 칼린은 빛의 희망 예배당에 있었다. 크로미는 다로우골 연대기를 찾아 달라고 부탁하며 그들의 슬픔에 형태를 부여했다."
L["Push into the Armory and Cathedral, where the Crusade's champions guard the heart of the Monastery."] = "십자군의 용사들이 수도원의 심장부를 지키는 무기고와 대성당으로 밀고 들어가십시오."
L["Ravenholdt opened a door beyond ordinary city training. There were signals to learn, reputations to mind, and thieves who knew the craft by its older rules."] = "라벤홀트 암살단은 평범한 도시 수련 너머로 향하는 문을 열어 주었다. 익혀야 할 신호와 신경 써야 할 평판, 그리고 더 오래된 규칙으로 기술을 익힌 도둑들이 그곳에 있었다."
L["Read the scroll found aboard the Bloodsail ship and follow only the clue Cortello left behind."] = "붉은해적단 배에서 발견한 두루마리를 읽고, 오직 코르텔로가 남긴 단서만을 따라가십시오."
L["Read the wanted poster outside Westbrook Garrison and hunt Hogger, the Riverpaw gnoll terrorizing southwestern Elwynn."] = "서쪽시내 주둔지 밖의 현상수배 전단을 읽고, 엘윈 남서부를 공포에 떨게 하는 강발톱 놀 들창코를 사냥하십시오."
L["Read the weathered grave north of Raven Hill and learn why Mor'Ladim still walks."] = "까마귀 언덕 북쪽의 비바람에 닳은 무덤을 살펴보고, 모르라딤이 왜 아직도 떠도는지 알아보십시오."
L["Recover the amulet pieces and components Bodley names from the old dungeons of Azeroth."] = "보들리가 말한 아뮬렛 조각과 재료를 아제로스의 오래된 던전들에서 되찾으십시오."
L["Recover the relics and skulls tied to Darrowshire's old defenders, villains, and marauders."] = "다로우골의 옛 수호자와 악당, 약탈자들과 얽힌 유물과 두개골을 되찾으십시오."
L["Recover the waterlogged letter beneath the Thandol Span and carry its last words home."] = "탄돌 교각 아래에서 물에 젖은 편지를 찾아, 그 마지막 말을 고향으로 전하십시오."
L["Renferrel and Faranell carried the work beyond Brill. Berard's journal, Pyrewood's danger, and the samples from Lake Lordamere gave the apothecaries older knowledge to add to their new recipe."] = "렌페렐과 파라넬은 연구를 브릴 너머로 넓혔다. 베라드의 일지, 송진나무 마을의 위험, 로다미어 호수에서 채취한 표본은 연금술사들이 새 제조법에 더할 오래된 지식을 안겨 주었다."
L["Report to Apothecary Lydon in Hillsbrad and gather what he needs for his next field trials."] = "언덕마루의 연금술사 라이던에게 보고하고, 다음 현장 실험에 필요한 것을 모으십시오."
L["Report to High Executor Darthalia and carry her first orders against the farms of Hillsbrad."] = "고위집행관 다살리아에게 보고하고, 언덕마루의 농장을 상대로 그녀의 첫 명령을 수행하십시오."
L["Return to Darrowshire with Chromie's relic bundle and stand with the town in its final battle."] = "크로미의 유물 꾸러미를 들고 다로우골로 돌아가, 마지막 전투에서 마을과 함께 싸우십시오."
L["Return to Deliana or Mokvar for the final exchange and complete the armor upgrade."] = "델리아나 또는 모크바르에게 돌아가 마지막 교환을 마치고 방어구 강화를 완료하십시오."
L["Return to the tower with Balthule's command and face Athrikus Narassin at the summit."] = "발툴의 명을 받들어 탑으로 돌아가, 정상에서 애스리쿠스 나라신과 맞서십시오."
L["Return to Westfall, watch the Brotherhood's movements, and let the trail show where it leads."] = "서부 몰락지대로 돌아가 형제단의 움직임을 지켜보고, 흔적이 어디로 이어지는지 확인하십시오."
L["Return to your trainer and receive the last totem needed to complete the circle of elements."] = "직업 전문가에게 돌아가 정령의 원을 완성할 마지막 토템을 받으십시오."
L["Return with the lost command, or answer Nethergarde's summons, and hear what Razelikh did to the soldiers who crossed into the Blasted Lands."] = "잃어버린 명령서를 들고 돌아가거나 네더가드의 부름에 응해, 저주받은 땅에 발을 들인 병사들에게 라젤리크가 무슨 짓을 했는지 들으십시오."
L["Run Abercrombie's errands near Raven Hill and learn what the old hermit means to build."] = "까마귀 언덕 근처에서 애버크롬비의 심부름을 하며, 그 늙은 은둔자가 무엇을 만들려 하는지 알아보십시오."
L["Search for Teronis near Lake Falathim and return with whatever remains of his work."] = "팔라딤 호수 근처에서 테로니스를 찾고, 그가 남긴 연구의 흔적을 무엇이든 가져오십시오."
L["Search the Woodpaw camps for Raschal's missing packs and any sign of where his errand went next."] = "나무발톱 놀 야영지를 뒤져 라샬의 잃어버린 짐 꾸러미와, 그의 임무가 어디로 이어졌는지 알려 줄 흔적을 찾으십시오."
L["Search the wrecked raft in Un'Goro and bring the small pack to Linken at Marshal's Refuge."] = "운고로의 부서진 뗏목을 뒤져 작은 꾸러미를 찾아, 마샬의 야영지에 있는 링쿠에게 가져가십시오."
L["Follow the next names in Linken's tale and prepare the totem he will need."] = "링쿠의 이야기에 나오는 다음 이름들을 따라가며 그에게 필요한 토템을 준비하십시오."
L["Seek Haleh in Winterspring and bring her General Drakkisath's blood to make the Drakefire Amulet."] = "여명의 설원에서 헬레를 찾아 사령관 드라키사스의 피를 건네고 비룡불꽃 아뮬렛을 만드십시오."
L["Seek Loramus Thalipedes in Azshara. The demon hunter knows how Razelikh is warded, but he needs a name torn from the deep."] = "아즈샤라에서 로라무스 탈리페데스를 찾으십시오. 그 악마사냥꾼은 라젤리크를 지키는 결계에 대해 알고 있지만, 심연에서 뜯어낸 이름 하나가 필요합니다."
L["Seek Strahad Farsan, assemble the Tome of the Cabal, and prepare the felhunter binding."] = "스트라드 파선을 찾아 비밀의 고서를 완성하고 지옥사냥개 속박을 준비하십시오."
L["Seek the earth's sapta, speak with its manifestation, and return with your first totem."] = "대지의 삽타를 찾아 그 현신과 대화하고, 첫 토템을 받아 돌아오십시오."
L["Seek the halves of the pendant across lake and sea so the form of the sea lion may be taught."] = "바다사자 변신을 배울 수 있도록, 호수와 바다에 흩어진 펜던트의 두 조각을 찾으십시오."
L["Seek the Islander, gather the charms, and answer Bath'rah's summons for the whirlwind weapon."] = "섬 사람을 찾아 부적을 모으고, 회오리바람 무기를 얻기 위해 바스라의 소환에 응하십시오."
L["Sentinel Elissa's missing scout was alive, but Balthule's report was grave. Warlocks held the tower, their parchments spoke of the Dark Strand, and the warning had to reach Ashenvale."] = "파수병 엘리사의 실종된 정찰병은 살아 있었지만, 발툴의 보고는 심각했다. 흑마법사들이 탑을 장악하고 있었고, 그들의 양피지에는 어둠의 끈 교단이 언급되어 있었으며, 이 경고는 반드시 잿빛 골짜기에 전해져야 했다."
L["Shaw's report gave Gryan a name, but the messenger gave him movement. The Defias Traitor then led you through Moonbrook to the hidden entrance beneath the ruined town."] = "쇼의 보고로 그라이언은 이름을 알게 되었고, 전령을 통해 그들의 움직임을 파악했다. 이어 데피아즈단 변절자의 안내를 받아 달빛시내 마을을 지나, 폐허가 된 마을 아래 숨겨진 입구에 이르렀다."
L["Speak with the proper trainer and bind the felsteed that will carry you on darker roads."] = "알맞은 전문가와 대화하고, 더 어두운 길을 함께 달릴 지옥마를 속박하십시오."
L["Sven's murdered family and Jitters' fear showed that Raven Hill was being worked by a darker hand. With Morbent's Bane prepared, you ended the necromancer beyond the graves."] = "살해당한 스벤의 가족과 지터스의 두려움은 까마귀 언덕 뒤에서 더 어두운 손길이 움직이고 있음을 보여 주었다. 모벤트의 파멸을 준비한 뒤, 무덤 너머의 강령술사를 끝장냈다."
L["Tabetha's work asked for texts, materials, and a measure of field sense. When the ritual was complete, your studies had a proper focus in hand."] = "타베사의 일에는 문헌과 재료, 그리고 어느 정도의 현장 감각이 필요했다. 의식이 끝났을 때, 그동안의 연구는 손에 쥔 제대로 된 마법봉 하나로 결실을 맺었다."
L["Take Coleman's concern to Magistrate Sevren and descend into the crypt beneath the mills."] = "콜만의 걱정을 집정관 세브렌에게 전하고, 제분소 아래의 납골당으로 내려가십시오."
L["Take Johaan's work to Silverpine, recover Berard's research, and bring Faranell the samples he requires."] = "요한의 연구를 은빛소나무 숲으로 가져가 베라드의 연구 자료를 되찾고, 파라넬에게 필요한 표본을 가져다주십시오."
L["Take the soggy clue at its word and look for the next scrap where the riddle says it waits."] = "물에 젖은 단서를 곧이곧대로 믿고, 수수께끼가 가리키는 곳에서 다음 쪽지를 찾으십시오."
L["The Agamand Mills still bore the family name, though the family itself had joined Tirisfal's dead. You brought Coleman Farthing the remains he asked for and helped clear the grounds for Brill."] = "아가만드 밀농장은 여전히 그 가문의 이름을 품고 있었지만, 가문 사람들은 이미 티리스팔의 망자가 되어 있었다. 콜만 파딩이 원하던 유해를 가져다주고, 브릴을 위해 그 땅을 정리하는 일을 도왔다."
L["The amulet hunt sent you after pieces, components, and summoned echoes in dangerous places. Each recovery brought Lord Valthalak's broken pride closer to being called forth."] = "아뮬렛을 찾는 여정은 위험한 곳곳에서 조각과 재료, 그리고 소환된 메아리를 쫓게 했다. 하나씩 되찾을 때마다 군주 발타라크의 부서진 자존심을 불러낼 때가 가까워졌다."
L["The Ancient Petrified Leaf proved to be a summons. The ancients named the demons, and by hunting them alone you earned the right to carry Rhok'delar."] = "고대의 석화된 잎은 하나의 소환장이었다. 고대정령들이 악마들의 이름을 알려 주었고, 홀로 그들을 사냥한 끝에 록델라를 지닐 자격을 얻었다."
L["The Armory and Cathedral were the Crusade's creed made flesh. Houndmaster Loksey guarded the Library with trained violence. Herod turned recruits into zealots through spectacle and blood. In the Cathedral, Scarlet Commander Mograine and High Inquisitor Whitemane embodied the order's shining lie: holy words wrapped around endless war. Whether sent by Varimathras or Raleigh, you cut through the Monastery's saints and executioners alike."] = "무기고와 대성당은 십자군의 신조가 육신을 얻은 곳이었다. 사냥개조련사 록시는 훈련된 폭력으로 도서관을 지켰다. 헤로드는 구경거리와 피로 신병들을 광신도로 만들었다. 대성당에서는 붉은십자군 사령관 모그레인과 종교재판관 화이트메인이 기사단의 빛나는 거짓을 몸소 보여 주었다. 끝없는 전쟁을 감싼 성스러운 말들. 바리마트라스의 명을 받았든 랄레이의 명을 받았든, 수도원의 성자와 처형자를 가리지 않고 베어 나갔다."
L["The Azsharite was raw possibility: crystal from a dangerous coast, named by a demon hunter, and meant for a foe normal steel could not touch. Galvan the Ancient gave that possibility form. Felbane was not an heirloom or a trophy. It was a blade for one brutal task: wound Razelikh's protected servants, gather the shattered amulet, and open the way to the demon himself."] = "아즈샤리트는 날것의 가능성이었다. 위험한 해안에서 얻은 수정이자, 악마사냥꾼이 이름 붙인 것이며, 평범한 강철로는 건드릴 수 없는 적을 위한 것이었다. 전설의 대장장이 갈반은 그 가능성에 형태를 부여했다. 지옥파멸은 가보도 전리품도 아니었다. 단 하나의 잔혹한 임무를 위한 칼날이었다. 라젤리크의 보호를 받는 하수인들에게 상처를 입히고, 부서진 아뮬렛을 모아, 악마 본인에게 이르는 길을 여는 것."
L["The blue shard hid grave purpose beneath impossible errands. Azuregos sent you to Narain, and Narain's ledger demanded Molten Core goggles, a great chimaerok meal, a stolen book, a ransom drop, pages from dragons, the fires of Onyxia and Ragnaros, and Neptulon's wrath off Azshara's coast. Strange as it was, each step pulled the shard closer to the scepter."] = "푸른 조각은 터무니없어 보이는 심부름 아래 엄중한 목적을 숨기고 있었다. 아주어고스는 나라인에게 보냈고, 나라인의 장부는 화산 심장부의 고글, 거대한 키메로크 요리, 도둑맞은 책, 몸값 전달, 용들의 문서, 오닉시아와 라그나로스의 불꽃, 그리고 아즈샤라 해안의 넵튤론의 분노를 요구했다. 기묘하기 그지없었지만, 한 걸음 한 걸음이 조각을 홀에 더 가까이 이끌었다."
L["The call of air was brief, but it completed what the earlier trials began. Earth, fire, water, and air now stood with you."] = "바람의 부름은 짧았지만, 앞선 시험들이 시작한 일을 완성했다. 이제 대지와 불, 물, 바람이 함께했다."
L["The call of water sent you farther than the earlier trials. Through Barrens dust and distant roads, you learned the patience the element required."] = "물의 부름은 앞선 시험들보다 더 먼 곳으로 이끌었다. 불모의 땅의 먼지와 먼 길을 지나며, 그 정령이 요구하는 인내를 배웠다."
L["The charger's trial demanded sacrifice, craft, and courage in haunted places. At the end, the spirit answered the Light and came to your side."] = "군마의 시험은 망령이 깃든 곳에서의 희생과 기술, 그리고 용기를 요구했다. 마침내 그 영혼은 빛에 응답해 곁으로 다가왔다."
L["The Circle sent you from lesson to remedy. You found the source of the sickness, gathered the cure, and restored creatures that had been left to suffer."] = "의회는 가르침에서 치료로 이끌었다. 병의 근원을 찾아내고, 치료제를 모으고, 고통 속에 버려졌던 짐승들을 되살렸다."
L["The Dalaran wizards at Ambermill were moving supplies and waking old ley-work beneath Silverpine. Shadow Priest Allister and Dalar Dawnweaver followed the evidence until Archmage Ataeric stood exposed."] = "호박색 농장의 달라란 마법사들은 물자를 옮기며 은빛소나무 숲 아래 잠든 오래된 지맥 술식을 깨우고 있었다. 어둠의 사제 알리스터와 달라 돈위버는 증거를 따라간 끝에 대마법사 아타에릭의 정체를 드러냈다."
L["The dead of Darrowshire rose to fight again. You held the line, faced the corrupted Joseph Redpath, and gave Pamela the peace of knowing her father had come home."] = "다로우골의 망자들이 다시 싸우기 위해 일어섰다. 전선을 지키고, 타락한 조셉 레드패스와 맞서, 파멜라에게 아버지가 집으로 돌아왔다는 안식을 안겨 주었다."
L["The Deadmines were mine, factory, shipyard, and fortress. At the heart of it all stood Edwin VanCleef, whose death ended Westfall's immediate crisis and left one final letter behind."] = "죽음의 폐광은 광산이자 공장이었고, 조선소이자 요새였다. 그 모든 것의 중심에는 에드윈 밴클리프가 있었다. 그의 죽음으로 서부 몰락지대의 당면한 위기는 끝났지만, 마지막 편지 한 통이 남았다."
L["The device revealed Anthion Harmon, a ghost bound by his sister's danger. You entered Stratholme, reached Ysida in time, and returned to the brother who had waited outside its gates."] = "장치는 누이의 위험에 묶인 유령, 안시온 하몬의 모습을 드러냈다. 스트라솔름에 들어가 늦지 않게 이시다에게 닿았고, 성문 밖에서 기다리던 오라비에게 돌아갔다."
L["The Elixir of Agony passed from blossom to composite, from Faranell's decay to Lydon's final activation. With Dun Garok stout as the vessel, the inn itself became the last test."] = "죽음의 비약은 꽃에서 혼합물로, 파라넬의 부패를 거쳐 라이던의 최종 활성화로 완성되었다. 던 가록 흑맥주를 그릇 삼아, 여관 자체가 마지막 시험장이 되었다."
L["The Fallen Hero speaks of a regiment lost waiting for orders. Begin in Stonard and search the southern swamps for the command that never reached him."] = "쓰러진 영웅은 명령을 기다리다 사라진 연대에 대해 이야기합니다. 스토나드에서 시작해, 그에게 끝내 닿지 못한 명령을 찾아 남쪽 늪지대를 수색하십시오."
L["The Fallen Hero's grief began with obedience. He led his soldiers toward the Blasted Lands and waited for orders that never came. Dispatch Commander Ruag remembered the lost message, Bengor remembered the ambush, and the Swamp Talker still held the Warchief's command. The truth was bitter: the regiment had been told to withdraw. The order never reached them."] = "쓰러진 영웅의 슬픔은 복종에서 시작되었다. 그는 병사들을 이끌고 저주받은 땅으로 향했고, 끝내 오지 않은 명령을 기다렸다. 파견사령관 루아그는 사라진 전갈을 기억했고, 벤고르는 매복을 기억했으며, 늪의 대변자는 여전히 대족장의 명령을 지니고 있었다. 진실은 쓰라렸다. 연대에는 퇴각 명령이 내려졌지만, 그 명령은 끝내 그들에게 닿지 못했다."
L["The felsteed was not purchased like an ordinary mount. It was called, bound, and made to bear the one who mastered the ritual."] = "지옥마는 평범한 탈것처럼 돈으로 살 수 있는 것이 아니었다. 부름을 받고, 속박되어, 의식을 지배한 자를 태우도록 길들여졌다."
L["The fight moved from ghostly remorse to demon-hunter craft. Loramus Thalipedes understood Razelikh's ward, but knowledge had to be earned. Lord Arkkoroc gave up the beast's name only after Hetaera's heads were brought from the Bay of Storms, and Loramus used the blood to name the enemy properly. The demon's protections were no longer a mystery. Felbane had to be made."] = "싸움은 유령의 회한에서 악마사냥꾼의 기술로 옮겨 갔다. 로라무스 탈리페데스는 라젤리크의 결계를 알고 있었지만, 그 지식은 대가를 치러야 얻을 수 있었다. 제왕 아크코로크는 폭풍의 만에서 헤타에라의 머리를 가져온 뒤에야 그 짐승의 이름을 내주었고, 로라무스는 그 피로 적의 이름을 제대로 밝혀냈다. 악마의 보호막은 더 이상 수수께끼가 아니었다. 이제 지옥파멸을 만들어야 했다."
L["The final clue led to the great falls on the Hinterlands coast. Under the water, after pirates, mud, and raptors, Cortello's chest waited with a reward fit for a traveler."] = "마지막 단서는 동부 내륙지 해안의 거대한 폭포로 이어졌다. 해적과 진흙, 랩터를 지나 들어간 물속에서, 코르텔로의 상자가 여행자에게 걸맞은 보상을 품고 기다리고 있었다."
L["The final proof came from General Drakkisath himself. His blood completed the amulet's power, and Rexxar turned the long road of commands, disguises, skulls, and trials into a single key. The Horde had its answer to Onyxia: strength tested across the world and deep inside Blackrock Spire."] = "마지막 증거는 사령관 드라키사스 그 자신에게서 나왔다. 그의 피가 아뮬렛의 힘을 완성했고, 렉사르는 명령과 변장, 두개골과 시험으로 이어진 긴 여정을 하나의 열쇠로 바꾸어 놓았다. 호드는 오닉시아에 맞설 답을 손에 넣었다. 세상 곳곳에서, 그리고 검은바위 첨탑 깊은 곳에서 시험받은 힘이었다."
L["The first binding taught the warlock's bargain clearly. A creature of the void answered, resisted, and was made to serve."] = "첫 속박은 흑마법사의 거래가 무엇인지 분명히 가르쳐 주었다. 공허의 존재가 응답했고, 저항했으며, 결국 굴복해 섬기게 되었다."
L["The first Defias were thieves in the vineyards and bandits on the roads. By the time Morgan the Collector's ring reached Marshal Dughan, the red masks looked less like chance and more like organization."] = "처음의 데피아즈는 포도밭의 도둑이자 길 위의 산적이었다. 징세관 모건의 반지가 치안대장 더그한에게 전해졌을 무렵, 붉은 복면은 우연이라기보다 조직처럼 보이기 시작했다."
L["The first exchange began with a worn class bracer and a simple test of readiness. Deliana or Mokvar made the first improvement and sent you onward to Gadgetzan."] = "첫 교환은 낡은 직업 손목 방어구와 준비가 되었는지 확인하는 간단한 시험으로 시작되었다. 델리아나 또는 모크바르가 첫 강화를 해 주고 가젯잔으로 보냈다."
L["The first scroll waited in the hold of a Bloodsail ship with no one to explain it. Its verse led you beneath a bridge in the Swamp of Sorrows, where the next clue lay in the mud."] = "첫 번째 두루마리는 설명해 줄 이 하나 없이 붉은해적단 배의 선창에 놓여 있었다. 그 구절은 슬픔의 늪의 한 다리 아래로 이끌었고, 그곳 진흙 속에 다음 단서가 묻혀 있었다."
L["The first signs of Onyxia's reach came from the Burning Steppes, where Helendis Riverhorn watched black dragonkin gathering strength. Magistrate Solomon treated the threat as a kingdom matter, Bolvar Fordragon weighed it from Stormwind Keep, and Marshal Maxwell became the Alliance's field anchor. The question was no longer whether dragons were moving. It was who in Stormwind had allowed the threat to spread."] = "오닉시아의 손길이 처음 드러난 곳은 불타는 평원이었다. 그곳에서 헬렌디스 리버혼은 검은용족이 힘을 모으는 것을 지켜보고 있었다. 집정관 솔로몬은 이 위협을 왕국의 문제로 다루었고, 볼바르 폴드라곤은 스톰윈드 왕궁에서 사태를 저울질했으며, 치안대장 맥스웰은 얼라이언스의 현장 거점이 되었다. 문제는 더 이상 용들이 움직이고 있는가가 아니었다. 스톰윈드의 누가 그 위협이 퍼지도록 내버려 두었는가였다."
L["The Graveyard and Library showed the Crusade's order from the inside. Vorrel Sengutz lay tortured by Interrogator Vishas. Scholars wanted books the Crusade had locked away. Horde agents wanted the Compendium of the Fallen, and Parqual Fintallas wanted the book the Crusade used to teach itself how to fight the dead. Alliance scholars wanted the Mythology of the Titans. Every shelf and cell told the same truth: the Scarlet Crusade did not only kill enemies. It controlled what its followers were allowed to know."] = "묘지와 도서관은 십자군의 질서를 안에서부터 보여 주었다. 보렐 센구츠는 심문관 비샤스에게 고문당하고 있었다. 학자들은 십자군이 감춰 둔 책을 원했다. 호드 요원들은 타락의 개요를, 파쿠알 핀탈라스는 십자군이 망자와 싸우는 법을 스스로 익히는 데 쓴 책을 원했다. 얼라이언스 학자들은 티탄 신화를 원했다. 모든 서가와 감방이 같은 진실을 말했다. 붉은십자군은 적을 죽이는 데 그치지 않았다. 추종자들이 무엇을 알아도 되는지까지 통제했다."
L["The green shard was not won by simple killing. Eranikus had fallen into nightmare, and Remulos needed the corruption named before it could be answered. The defense of Moonglade became a rite before all who came to stand there: shades pouring from the Dream, Remulos holding the line, and Tyrande's grace turning a dragon's rage toward redemption."] = "초록 조각은 단순히 적을 쓰러뜨리는 것만으로 얻을 수 있는 것이 아니었다. 에라니쿠스는 악몽에 빠져 있었고, 레물로스는 그 타락에 맞서기 전에 먼저 그 정체를 밝혀야 했다. 달의 숲 방어전은 그곳에 모인 모두 앞에서 펼쳐진 의식이 되었다. 꿈에서 쏟아져 나오는 그림자들, 전선을 지키는 레물로스, 그리고 용의 분노를 구원으로 돌려놓은 티란데의 은총."
L["The Horde's road to Onyxia began with Blackrock command papers and the old wound of the Blackhand name. Warlord Goretooth demanded proof from Lower Blackrock Spire, Eitrigg weighed the report in Orgrimmar, and Thrall sent you to kill Warchief Rend Blackhand. Rend's death was a declaration that the Horde would not bow to a false warchief propped up by dragons."] = "오닉시아를 향한 호드의 여정은 검은바위 부족의 명령서와 블랙핸드라는 이름에 얽힌 오랜 상처에서 시작되었다. 장군 고어투스는 검은바위 첨탑 하층에서 증거를 가져오라 요구했고, 아이트리그는 오그리마에서 그 보고를 검토했으며, 스랄은 대족장 렌드 블랙핸드를 처치하라고 보냈다. 렌드의 죽음은 용들이 떠받친 거짓 대족장에게 호드가 결코 굴복하지 않겠다는 선언이었다."
L["The Islander tested your mettle, Bath'rah named the charms, and Cyclonian answered the call. When the storm was defeated, the weapon was yours."] = "섬 사람은 기개를 시험했고, 바스라는 부적의 이름을 알려 주었으며, 사이클로니안이 부름에 응했다. 폭풍을 물리치자 그 무기는 마침내 손에 들어왔다."
L["The last climb belonged to the dead as much as the living. Grol the Destroyer, Archmage Allistarj, and Lady Sevine each held a piece of Razelikh's power, and Felbane made them mortal enough to fall. The united ward opened the Rise of the Defiler. There, above the ruined land that had swallowed a Horde regiment, Razelikh finally answered for the souls he chained. The Fallen Hero could not undo his failure, but he saw the demon broken and his soldiers released."] = "마지막 오르막은 산 자만큼이나 망자의 몫이었다. 파괴자 그롤, 대마법사 알리스타르지, 그리고 세빈 부인은 각자 라젤리크의 힘 한 조각을 지니고 있었고, 지옥파멸은 그들을 쓰러뜨릴 수 있을 만큼 유한한 존재로 만들었다. 하나로 합쳐진 결계가 파멸자의 봉우리를 열었다. 호드의 연대를 삼킨 폐허의 땅 위, 그곳에서 라젤리크는 마침내 자신이 사슬로 묶은 영혼들의 대가를 치렀다. 쓰러진 영웅은 자신의 실패를 되돌릴 수는 없었지만, 악마가 무너지고 병사들이 풀려나는 것을 지켜보았다."
L["The last preparations made the brazier ready. After ghosts, goblins, gladiators, and dungeon shades, the path narrowed to the chamber where Valthalak could answer."] = "마지막 준비로 화로가 갖추어졌다. 유령과 고블린, 검투사, 던전의 망령을 지나, 길은 발타라크가 응답할 수 있는 방으로 좁혀졌다."
L["The last step was not to kill Yenniku, but to reach him. At the Ruins of Aboraz, beside Zanzil's servants and the haunted Crystal Shore, the Soul Gem turned violence into rescue. Yenniku's soul was pulled free of Zanzil's control and carried back to Nimboya. The work that had begun with trophies and cauldron smoke ended as a Darkspear promise: the tribe would remember the one who brought the chief's son home."] = "마지막 단계는 옌니쿠를 죽이는 것이 아니라 그에게 닿는 것이었다. 잔질의 하수인들과 유령이 출몰하는 수정 해안 곁, 아보라즈의 폐허에서 영혼석은 폭력을 구출로 바꾸었다. 옌니쿠의 영혼은 잔질의 지배에서 벗어나 님보야에게 돌아갔다. 전리품과 가마솥 연기로 시작된 일은 검은창 부족의 약속으로 끝을 맺었다. 부족장의 아들을 집으로 데려온 이를 부족은 기억할 것이다."
L["The notice at Westbrook Garrison named a gnoll and a claw. Forest's Edge taught the rest. Hogger stood among the Riverpaw with enough strength to make a simple bounty feel like a hard lesson in the wilds beyond Elwynn's roads. When Marshal Dughan received the claw, the border toward Westfall felt less like open countryside and more like a warning."] = "서쪽시내 주둔지의 게시문에는 놀 한 마리와 발톱 하나가 적혀 있었다. 나머지는 숲 가장자리에서 배웠다. 강발톱 놀들 사이에 버티고 선 들창코는 단순한 현상금 사냥을 엘윈의 길 너머 야생에서 겪는 혹독한 교훈으로 바꿀 만큼 강했다. 치안대장 더그한이 발톱을 받았을 때, 서부 몰락지대로 향하는 경계는 탁 트인 시골이라기보다 하나의 경고처럼 느껴졌다."
L["The Plaguelands proved the Crusade had become more than a monastery. Scarlet banners flew over towers and towns, Stratholme's living quarter hid the Fordring family painting, and Hearthglen stood as a fortress of certainty. Tirion Fordring, exiled and alone, still believed his son could be saved from it. Forgotten memories, lost honor, and the painting became weapons against fanatic teaching. Disguised as Scarlet, you reached Taelan and watched him remember who he was before the Crusade taught him whom to hate."] = "역병지대는 십자군이 이미 수도원 이상의 존재가 되었음을 증명했다. 붉은십자군의 깃발이 탑과 마을 위로 휘날렸고, 스트라솔름의 생존자 구역에는 폴드링 가문의 초상화가 숨겨져 있었으며, 하스글렌은 확신의 요새로 버티고 있었다. 추방당해 홀로 남은 티리온 폴드링은 여전히 아들을 그곳에서 구할 수 있다고 믿었다. 잊힌 기억과 잃어버린 명예, 그리고 초상화는 광신적인 가르침에 맞서는 무기가 되었다. 붉은십자군으로 변장해 탤런에게 닿았고, 십자군이 누구를 증오해야 하는지 가르치기 전 그가 어떤 사람이었는지 기억해 내는 모습을 지켜보았다."
L["The raft in Un'Goro held a compass, a curled map, a lion-headed key, and a photograph of a gnome in green. Linken knew the belongings, but memory would not come with them. The crater had left him with fragments of an errand, a blade without its tale, and the sense that someone had once entrusted him with more than he could remember."] = "운고로의 뗏목에는 나침반, 둘둘 말린 지도, 사자 머리 열쇠, 그리고 초록 옷을 입은 노움의 사진이 있었다. 링쿠는 그 물건들을 알아보았지만, 기억은 함께 돌아오지 않았다. 분화구는 그에게 심부름의 단편과 사연을 잃은 검, 그리고 한때 누군가 그가 기억하는 것보다 더 많은 것을 맡겼다는 느낌만을 남겼다."
L["The records, letters, and keepsakes led from Duskwood to Stormwind, Elwynn, Westfall, and back again. At Mistmantle Manor, Stalvan's legend ended with his ring in Madame Eva's hands."] = "기록과 편지, 유품은 그늘숲에서 스톰윈드, 엘윈, 서부 몰락지대로 이어졌다가 다시 돌아왔다. 미스트맨틀 저택에서 스탈반의 전설은 그의 반지가 에바 부인의 손에 들어가며 끝을 맺었다."
L["The red shard was the bluntest path and perhaps the cruelest. Vaelastrasz, already broken by Nefarian, could only point toward the master of Blackwing Lair and set a clock running. The shard was taken from Nefarian under pressure, a raid victory folded into the long duty of the scepter."] = "붉은 조각은 가장 직설적인, 그리고 어쩌면 가장 잔혹한 길이었다. 이미 네파리안에게 망가진 밸라스트라즈가 할 수 있는 일은 검은날개 둥지의 주인을 가리키고 시간과의 싸움을 시작하게 하는 것뿐이었다. 조각은 쫓기듯 네파리안에게서 빼앗아 왔고, 공격대의 승리는 홀을 위한 긴 의무의 일부가 되었다."
L["The red tear outside Ahn'Qiraj was memory made visible. Anachronos let the past speak: the night elves, dragons, and qiraji locked in a war old enough to feel mythic. The scepter had broken across dragonflights and tragedies. To open the gates, the champion would have to follow those wounds into the Emerald Dream, Blackwing Lair, and Azshara's blue-dragon riddles."] = "안퀴라즈 밖의 붉은 균열은 눈에 보이는 기억이었다. 아나크로노스는 과거가 직접 말하게 했다. 나이트 엘프와 용, 퀴라지가 신화처럼 느껴질 만큼 오래된 전쟁에 얽혀 있었다. 홀은 여러 용군단과 비극에 걸쳐 산산이 부서졌다. 관문을 열려면, 용사는 그 상처를 따라 에메랄드의 꿈과 검은날개 둥지, 그리고 아즈샤라의 푸른용 수수께끼로 가야 했다."
L["The second clue turned the riddle into a journey across the sea. In Dustwallow, among Bloodfen raptors, another scrap waited for anyone stubborn enough to keep reading."] = "두 번째 단서로 수수께끼는 바다 건너의 여정이 되었다. 먼지진흙 습지대의 피늪 랩터들 사이에서, 끈질기게 읽어 나갈 이를 위한 또 다른 쪽지가 기다리고 있었다."
L["The Stockade did not end the matter. Thelwater's visitor, Baros' warning, Shaw's caution, and Trias' quiet knowledge all pointed toward a dangerous friend of the Brotherhood inside Stormwind."] = "스톰윈드 지하감옥에서 일이 끝난 것은 아니었다. 델워터를 찾아온 방문객, 바로스의 경고, 쇼의 신중함, 그리고 트리아스가 조용히 알고 있던 사실은 모두 스톰윈드 안에 있는 형제단의 위험한 동조자를 가리켰다."
L["The succubus trial warned that not every danger arrives with brute force. You gathered what was required and bound temptation to command."] = "서큐버스의 시험은 모든 위험이 완력과 함께 오지는 않는다는 것을 일깨웠다. 필요한 것을 모아, 유혹을 명령에 묶어 두었다."
L["The Sunken Temple trial asked you to carry the elements as one calling. When the proofs were gathered, your mastery had been tested in full."] = "가라앉은 사원의 시험은 정령들을 하나의 소명으로 품으라고 요구했다. 증표를 모두 모았을 때, 그 숙련은 온전히 시험을 통과했다."
L["The Tome of the Cabal led through old contacts and dangerous errands. When the binding was done, the felhunter's hunger became your weapon against magic."] = "비밀의 고서는 오래된 연줄과 위험한 심부름으로 이어졌다. 속박을 마치자, 지옥사냥개의 굶주림은 마법에 맞서는 무기가 되었다."
L["The Tome of Valor led you to Daphne Stilwell and a hard lesson in service. Valor was not spoken over you; it was proven on a dangerous road."] = "용맹의 고서는 대프니 스틸웰과 봉사의 혹독한 가르침으로 이끌었다. 용맹은 누군가 말로 내려 주는 것이 아니었다. 위험한 길 위에서 증명해야 하는 것이었다."
L["The trail began beneath the broken Thandol Span, beside a dwarf pinned in the riverbed. Sully Balloo's letter was not a weapon, a map, or a royal order. It was a husband's goodbye, written before war turned private love into public loss. Sara Balloo received the letter in Ironforge and asked for only one thing more: that her king know what had been given in his name."] = "흔적은 무너진 탄돌 교각 아래, 강바닥에 깔린 드워프 곁에서 시작되었다. 설리 발루의 편지는 무기도, 지도도, 왕명도 아니었다. 전쟁이 사적인 사랑을 공적인 상실로 바꾸기 전에 쓴 한 남편의 작별 인사였다. 아이언포지에서 편지를 받은 사라 발루는 단 한 가지만 더 부탁했다. 그녀의 왕이 그의 이름으로 무엇이 바쳐졌는지 알아 주기를."
L["The water trial carried you beyond the safety of your trainer. When the pendant was made whole, the sea lion form answered, and deeper waters opened to you."] = "물의 시험은 전문가의 보호를 벗어난 곳으로 이끌었다. 펜던트가 온전해지자 바다사자 변신이 응답했고, 더 깊은 물길이 열렸다."
L["The Woodpaw trail looked at first like scavenging. Then you found Raschal's backpacks pinned to a tree, still bearing Feathermoon insignia. One parcel could be delivered to Thalanaar, a small duty completed in the middle of the search. The other evidence mattered more: a note about strange insect creatures south of the gnoll camps. Raschal had not merely been attacked. He had chosen to investigate a threat under Feralas."] = "나무발톱 놀의 흔적은 처음엔 단순한 약탈처럼 보였다. 그러다 나무에 박힌 라샬의 배낭이 발견되었다. 여전히 페더문의 문장이 달려 있었다. 꾸러미 하나는 탈라나르로 전할 수 있었다. 수색 도중에 마친 작은 임무였다. 더 중요한 것은 다른 증거였다. 놀 야영지 남쪽의 기묘한 곤충 생물에 관한 쪽지였다. 라샬은 단순히 습격당한 것이 아니었다. 그는 페랄라스 아래의 위협을 조사하기로 스스로 택했던 것이다."
L["The worgen were another fear in the dark, hunting through grove and orchard. Calor tested you against them until Master Carevin accepted that you could help keep their teeth from Darkshire."] = "늑대인간은 숲과 과수원을 누비며 사냥하는, 어둠 속의 또 다른 공포였다. 칼로는 늑대인간을 상대로 시험을 거듭했고, 마침내 캐레빈은 어둠골을 그들의 이빨로부터 지키는 데 힘이 될 수 있음을 인정했다."
L["The Writhing Deep made the whole case larger. Raschal was alive, sealed inside an alien pod by the Zukk'ash, and his report confirmed that Feralas was facing something more dangerous than a local hive. Shandris Feathermoon sent the warning to Darnassus, where Gracina Spiritmight named the threat: silithid. What began as a missing courier ended as an early warning about the insect menace waiting beneath Azeroth's southern deserts."] = "고통의 구덩이는 사건의 규모를 훨씬 키웠다. 라샬은 살아 있었지만 주크애쉬에 의해 기이한 고치 속에 봉인되어 있었고, 그의 보고는 페랄라스가 단순한 벌집보다 훨씬 위험한 무언가와 마주하고 있음을 확인해 주었다. 샨드리스 페더문은 다르나서스로 경고를 보냈고, 그곳에서 그라시나 스피릿마이트가 위협의 정체를 밝혔다. 실리시드였다. 실종된 전령으로 시작된 일은 아제로스 남쪽 사막 아래 도사린 곤충 위협에 대한 이른 경고로 끝을 맺었다."
L["Theldren's challengers waited in the Ring of Law, where words meant little. You survived the arena, and Anthion had what he needed for the next pieces."] = "델드렌의 도전자들은 말이 거의 통하지 않는 법의 투기장에서 기다리고 있었다. 투기장에서 살아남자, 안시온은 다음 조각을 위해 필요한 것을 손에 넣었다."
L["Theramore brought the mystery into the open without solving it. Commander Samaul sent you to Sentry Point, Archmage Tervosh guided you to Private Hendel, and Hendel's guard post became the last fight of the trail. When Hendel yielded, Jaina Proudmoore appeared to take charge of the prisoner and thank you quietly for services that could not be publicly named. You had exposed the kidnapping of King Varian Wrynn, but the larger wound remained open: the king was still missing, and someone powerful enough to use the Defias had not yet shown their face."] = "테라모어는 수수께끼를 풀지는 못했지만 수면 위로 끌어올렸다. 사령관 사마울은 감시초소로 보냈고, 대마법사 테르보쉬는 병사 헨델에게 안내했으며, 헨델의 초소는 이 추적의 마지막 전장이 되었다. 헨델이 굴복하자 제이나 프라우드무어가 나타나 포로를 넘겨받고, 공개적으로는 밝힐 수 없는 공로에 조용히 감사를 전했다. 국왕 바리안 린의 납치를 밝혀냈지만, 더 큰 상처는 여전히 아물지 않았다. 국왕은 아직 행방불명이었고, 데피아즈를 이용할 만큼 강력한 누군가는 아직 얼굴을 드러내지 않았다."
L["Thomas sends you quietly to Bishop DeLavey in Stormwind Keep, where a missing envoy has become a private matter."] = "토마스는 스톰윈드 왕궁의 주교 드라베이에게 조용히 보냅니다. 그곳에서 실종된 사절의 일은 은밀한 문제가 되었습니다."
L["Tirion Fordring asks for aid in a personal matter that leads through Stratholme and Scarlet-held country."] = "티리온 폴드링이 개인적인 일로 도움을 청합니다. 그 일은 스트라솔름과 붉은십자군이 장악한 땅으로 이어집니다."
L["Travel to Moonglade, hear the Great Bear Spirit, and return ready for the trial of body and heart."] = "달의 숲으로 가서 거대한 곰의 혼의 말을 듣고, 몸과 마음의 시험에 나설 준비를 갖춰 돌아오십시오."
L["Trias sends you into Old Town after Dashel Stonefist, whose answers pull the matter beyond Stormwind."] = "트리아스는 다셸 스톤피스트를 찾아 구 시가지로 보냅니다. 그의 대답은 사건을 스톰윈드 너머로 끌고 갑니다."
L["Turn from worgen to Dalaran, gathering crates, pendants, and rune-work around Ambermill."] = "늑대인간에서 달라란으로 눈을 돌려, 호박색 농장 주변에서 상자와 펜던트, 룬 장치를 모으십시오."
L["Turn stolen Scarlet orders against Tyr's Hand and use Nathanos' disguise to walk inside their ranks."] = "훔친 붉은십자군 명령서를 티르의 손 수도원에 역이용하고, 나타노스의 변장술로 그들의 대열 속을 누비십시오."
L["Tyrion's disguise and spybot drew Lord Gregor Lescovar and Marzon the Silent Blade into the open. Their deaths carried the truth back through Trias, Baros, and the king's court."] = "티리온의 변장과 첩보로봇은 그레골 라스코발 경과 소리없는검객 마르존을 끌어냈다. 그들의 죽음으로 진실은 트리아스와 바로스를 거쳐 왕궁까지 전해졌다."
L["Use Dartol's Rod to reach Krolg and turn against Ran Bloodtooth's corrupted furbolg."] = "다톨의 마법봉으로 크롤그에게 다가가, 랜 블러드투스의 타락한 펄볼그에 맞서십시오."
L["Use Mux's device near Stratholme, then race the city to save Ysida Harmon from the baron."] = "스트라솔름 근처에서 먹스의 장치를 사용한 뒤, 시간과 싸우며 도시를 가로질러 남작에게서 이시다 하몬을 구하십시오."
L["Carry Kin'weelay's Soul Gem into the jungle and look for the moment to free Yenniku."] = "킨윌레이의 영혼석을 들고 정글로 가서, 옌니쿠를 풀어 줄 순간을 노리십시오."
L["Use the taming rod on the beasts your trainer names, then return to learn how to keep a companion."] = "직업 전문가가 지정한 짐승들에게 길들이기 막대를 사용한 뒤, 돌아가서 동료를 곁에 두는 법을 배우십시오."
L["Follow Linken's memory through strange visions and help his sword remember what he cannot."] = "기묘한 환영 속에서 링쿠의 기억을 따라가며, 그가 떠올리지 못하는 것을 그의 검이 기억해 내도록 도우십시오."
L["Vaelastrasz gives little time for ceremony. The red shard must be claimed before the chance is lost."] = "밸라스트라즈에게는 격식을 차릴 시간이 없습니다. 기회가 사라지기 전에 붉은 조각을 손에 넣어야 합니다."
L["VanCleef's letter reached Baros Alexston, who remembered the Stonemasons better than most. His concern led to Warden Thelwater, Bazil Thredd, and the riot within the Stockade."] = "밴클리프의 편지는 누구보다 석공 조합을 잘 기억하는 바로스 알렉스턴에게 전해졌다. 그의 우려는 교도소장 델워터와 바질 스레드, 그리고 지하감옥의 폭동으로 이어졌다."
L["When the shards were whole, the matter no longer belonged to one champion. The Might of Kalimdor waited on the war effort, the armies at the wall, and all who had prepared for the gates to open. The gong turned a repaired scepter into history: Ahn'Qiraj opened, and the war beyond the Scarab Wall began."] = "조각들이 온전해지자, 이 일은 더 이상 한 용사의 몫이 아니었다. 칼림도어 연합군의 출정은 전쟁 지원과 성벽 앞의 군대, 그리고 관문이 열릴 날을 대비해 온 모든 이들에게 달려 있었다. 징은 복원된 홀을 역사로 바꾸었다. 안퀴라즈가 열렸고, 스카라베 성벽 너머의 전쟁이 시작되었다."
L["When your hunter trainer turns from weapons to trust, learn how to tame and train a beast. Later, if an ancient leaf ever finds its way into your hands, answer the stranger calling from Felwood."] = "사냥꾼 전문가가 무기에서 신뢰로 가르침을 옮겨 가면, 야수를 길들이고 훈련하는 법을 배우십시오. 훗날 고대의 잎이 손에 들어온다면, 악령의 숲에서 부르는 낯선 이에게 응답하십시오."
L["When your old dungeon armor has seen enough battle, Deliana or Mokvar will offer work that sounds simple enough: bring the right pieces, prove you are ready, and keep following instructions.\n\nThe errands soon reach far beyond a single set of bracers. Expect old dungeons, stranger patrons, expensive favors, and a brazier whose purpose is not explained all at once."] = "오래된 던전 방어구가 충분히 전투를 겪었다면, 델리아나 또는 모크바르가 꽤 단순해 보이는 일을 제안할 것입니다. 알맞은 방어구를 가져오고, 준비가 되었음을 증명하고, 지시를 계속 따르는 것입니다.\n\n심부름은 곧 손목 방어구 한 벌을 훨씬 넘어서게 됩니다. 오래된 던전과 더 기묘한 의뢰인, 값비싼 부탁, 그리고 그 목적이 한 번에 밝혀지지 않는 화로가 기다리고 있습니다."
L["Win Theldren's challenge in Blackrock Depths so Anthion can continue the armor work."] = "검은바위 나락에서 델드렌의 도전에 승리해, 안시온이 방어구 작업을 이어 갈 수 있게 하십시오."
L["With Athrikus Narassin weakened, Balthule sent you back into Althalaxx. You climbed past the warlocks of the Dark Strand and ended their master where he had gathered them."] = "애스리쿠스 나라신이 약해지자 발툴은 다시 알살락스로 보냈다. 어둠의 끈 교단의 흑마법사들을 지나 탑을 오르고, 그들을 불러 모은 바로 그곳에서 그들의 주인을 끝장냈다."
L["With Felbane in hand, follow the last names the Fallen Hero gives you and prepare for the demon's reckoning."] = "지옥파멸을 손에 들고, 쓰러진 영웅이 알려 주는 마지막 이름들을 따라 악마와의 결판을 준비하십시오."
L["With Onyxia exposed, the Alliance still needed a way into her lair. Bolvar sent you to Haleh, hidden in Winterspring, and Haleh named the final price: the blood of General Drakkisath from Upper Blackrock Spire. The black dragonflight's own champion became the material for the Drakefire Amulet. The court conspiracy was over. The assault on Onyxia could begin."] = "오닉시아의 정체가 드러났지만, 얼라이언스에게는 여전히 그 둥지에 들어갈 방법이 필요했다. 볼바르는 여명의 설원에 숨어 지내는 헬레에게 보냈고, 헬레는 마지막 대가를 밝혔다. 검은바위 첨탑 상층에 있는 사령관 드라키사스의 피였다. 검은용군단의 용사 그 자신이 비룡불꽃 아뮬렛의 재료가 되었다. 궁정의 음모는 끝났다. 이제 오닉시아에 대한 공격을 시작할 수 있었다."
L["With the Eye of Divinity in hand, seek Eris Havenfire and protect the spirits entrusted to you."] = "신성의 눈을 손에 넣었다면, 에리스 헤븐파이어를 찾아가 맡겨진 영혼들을 지키십시오."
L["With the three shards restored, take up the Scepter of the Shifting Sands and return to the Scarab Gong."] = "세 조각을 모두 복원했다면, 흐르는 모래의 홀을 들고 스카라베 징으로 돌아가십시오."
L["You answered the call to Moonglade and learned from the Great Bear Spirit. When the final trial was done, the strength of the bear was yours to call upon in battle."] = "달의 숲의 부름에 응해 거대한 곰의 혼에게서 가르침을 얻었다. 마지막 시험을 마치자, 전투에서 곰의 힘을 불러낼 수 있게 되었다."
L["You approached the wild as a hunter must: with patience, caution, and respect. When the final beast yielded, you were no longer meant to travel alone."] = "사냥꾼이라면 마땅히 그래야 하듯, 인내와 신중함, 존중으로 야생에 다가갔다. 마지막 야수가 마음을 열었을 때, 더는 홀로 여행할 운명이 아니었다."
L["You carried ore, gems, and other hard-won materials back to Jordan Stilwell. Verigan's Fist was not granted by ceremony alone; it was made through effort."] = "광석과 보석, 그 밖에 어렵게 얻은 재료를 조던 스틸웰에게 가져갔다. 베리건의 주먹은 의식만으로 주어지지 않았다. 노력으로 만들어 낸 것이었다."
L["You carried the sapta, listened to the earth, and proved steady enough to bear its totem. The first element had answered."] = "삽타를 지니고 대지의 목소리에 귀 기울였으며, 그 토템을 지닐 만큼 굳건함을 증명했다. 첫 번째 정령이 응답했다."
L["You returned to the one who started the work with a full trail behind you: rescues, bargains, spirits, and old dungeons. The final pieces made the upgraded set a record of where you had been."] = "구출과 거래, 영혼, 오래된 던전으로 이어진 긴 여정을 뒤로하고 처음 일을 맡긴 이에게 돌아갔다. 마지막 조각으로 강화된 방어구는 그동안 지나온 길의 기록이 되었다."
L["Your first warrior lesson was not about striking harder. You learned to take the blow, hold your ground, and live long enough to answer."] = "첫 전사 수업은 더 세게 치는 법에 관한 것이 아니었다. 공격을 받아 내고, 자리를 지키고, 반격할 때까지 살아남는 법을 배웠다."
L["Your mage trainer sends you to Tabetha in Dustwallow Marsh, where practical magic begins with travel, errands, and materials that will not gather themselves.\n\nFollow the lessons that turn study into tools: a wand, a strange polymorph, and food enough for hungry companions."] = "마법사 상급자는 먼지진흙 습지대의 타베사에게 가 보라고 합니다. 실전 마법은 먼 여정과 잔심부름, 그리고 저절로 모이지 않는 재료에서 시작됩니다.\n\n배움을 도구로 바꾸는 수업을 따라가십시오. 마법봉과 기묘한 변이 주문, 그리고 배고픈 동료들을 넉넉히 먹일 음식이 기다리고 있습니다."
L["Your poison training taught the trade plainly: enter unseen, open what is locked, and survive the danger you mean to wield."] = "독 수련은 이 일의 본질을 숨김없이 가르쳐 주었습니다. 들키지 않고 잠입하고, 잠긴 것을 열고, 직접 다루려는 위험 속에서 살아남는 것입니다."
