L["Breaking the Stones of Binding turned battle into mercy. One by one, the servants of Razelikh, Grol, Allistarj, and Sevine lost their anchors, and the dead soldiers were released from a fate worse than death. Corporal Thund Splithoof appeared long enough to honor the work and leave a token behind. Then one name remained: Lieutenant Kirith. Finding him in the Serpent's Coil revealed the next truth. Razelikh could not be reached until his protections were understood."] = "속박의 돌을 부수자 전투는 자비가 되었다. 라젤리크의 하수인인 그롤, 알리스타르지, 세빈이 하나씩 이 세상에 묶인 닻을 잃었고, 죽은 병사들은 죽음보다 더한 운명에서 풀려났다. 하사관 선드 스플릿후프가 잠시 모습을 드러내 그 일을 기리고 징표 하나를 남겼다. 이제 남은 이름은 하나, 부관 키리스뿐이었다. 뱀의 보금자리에서 그를 찾아내자 다음 진실이 드러났다. 라젤리크의 보호막을 파악하기 전에는 그에게 손이 닿지 않았다."
