L["Castle Nathria fell, but Revendreth was not finished with its former ruler. In the Sanguine Depths, General Draven found Z'rali, the naaru whose Light had wounded the realm and whose mercy might yet help contain its sins. Then Remornia, Denathrius's living blade, became the prison that would hold him. The rebellion did not simply execute its master. It chose the harsher, stranger work Revendreth was built for: to bind arrogance, preserve what could still be redeemed, and let time do what vengeance could not."] = "나스리아 성채는 무너졌지만, 레벤드레스와 옛 지배자 사이의 일은 아직 끝나지 않았다. 장군 드레이븐은 핏빛 심연에서 나루 즈랄리를 찾아냈다. 그 빛은 이 영역에 상처를 남겼지만, 그 자비는 어쩌면 이 땅의 죄악을 가두는 데 힘이 될지도 몰랐다. 그리고 드나트리우스의 살아 있는 검 레모르니아가 그를 붙잡아 둘 감옥이 되었다. 반란군은 주인을 그저 처형하지 않았다. 대신 레벤드레스가 애초에 존재하는 이유인, 더 가혹하고 기이한 일을 택했다. 오만을 속박하고, 아직 구원할 수 있는 것을 지키며, 복수로는 이룰 수 없는 일을 시간에 맡기는 것이었다."
L["Castle Nathria's Aftermath"] = "나스리아 성채의 여파"
