L["Dashel Stonefist was exactly the sort of contact Trias expected: violent, useful, and unwilling to talk until persuaded. Once subdued, he admitted that his part had ended when the first plan failed. The backup plan involved someone from Menethil Harbor, a man called Slim. Trias knew enough to send you across the sea before the trail went cold."] = "다셸 스톤피스트는 트리아스가 예상한 그대로의 인물이었다. 거칠고, 쓸모 있고, 힘으로 설득하기 전에는 입을 열지 않았다. 제압당한 뒤에야 그는 첫 번째 계획이 실패하면서 자기 역할도 끝났다고 털어놓았다. 대비책에는 메네실 항구의 누군가, 슬림이라는 사내가 얽혀 있었다. 트리아스는 흔적이 끊기기 전에 서둘러 바다를 건너가게 했다."
L["Dashel's Lead"] = "다셸의 단서"
L["Dawn's Blossom, The Jade Forest"] = "새벽의 꽃, 비취 숲"
