L["Dazar'alor, Zuldazar"] = "다자알로, 줄다자르"
L["Dead Man's Plea"] = "죽은 자의 부탁"
L["Death did not make the Bloodscalp leaders cooperative. Nezzliok wanted trophy skulls stolen from the Skullsplitters. Gan'zulah wanted Ana'thek's broken armor and a tally of Skullsplitter hunters, headhunters, and berserkers. The spirits were not redeemed by the cauldron. They were bribed, threatened, and indulged until they finally gave up the truth: Yenniku had not died with the Bloodscalps. Zanzil the Outcast had taken him."] = "죽었다고 해서 붉은머리 부족의 지도자들이 협조적으로 변하지는 않았다. 네즐리오크는 해골쪼개기 부족에게서 빼앗은 전리품 해골을 원했다. 간줄라는 아나테크의 부서진 갑옷과 함께 해골쪼개기 부족의 사냥꾼, 머리사냥꾼, 광전사를 처치한 증거를 요구했다. 가마솥이 영혼들을 구원한 것은 아니었다. 뇌물과 협박과 비위 맞추기가 이어진 끝에야 그들은 마침내 진실을 털어놓았다. 옌니쿠는 붉은머리 부족과 함께 죽지 않았다. 추방자 잔질이 그를 데려간 것이었다."
L["Deathguard Burgess"] = "죽음경비병 버제스"
L["Deathguard Dillinger"] = "죽음의경비병 딜링거"
L["Deathguard Dillinger, Tirisfal Glades"] = "죽음의경비병 딜링거, 티리스팔 숲"
L["Deathguard Samsa"] = "죽음경비병 삼사"
L["Deathknell taught the Forsaken their first lesson about Lordaeron's living survivors: the Scarlet Crusade did not see people, only infection. Executor Arren sent you against Scarlet converts and their courier, then read the stolen intelligence and understood the warning. The Crusade was watching Deathknell, counting the dead, and preparing for war."] = "죽음의 종소리 마을은 포세이큰에게 로데론의 살아남은 자들에 관한 첫 교훈을 주었다. 붉은십자군의 눈에는 사람이 아니라 감염만 보였다. 집행관 아렌은 붉은십자군 개종자들과 그들의 전령을 처치하게 한 뒤, 빼앗아 온 정보를 읽고 그 경고의 의미를 깨달았다. 붉은십자군은 죽음의 종소리 마을을 지켜보며 죽은 자의 수를 세고, 전쟁을 준비하고 있었다."
