L["Duskwood supplied the first hard evidence. Watcher Backus remembered Defias agents gathering around Addle's Stead, and the small farmhouse held the proof: a docket official enough to worry even a veteran watchman. Backus sent it back to Trias, and Trias saw the shape of the next lead in one familiar word: Fist."] = "그늘숲에서 첫 번째 확실한 증거가 나왔다. 순찰대원 바커스는 데피아즈단 요원들이 애들 농장 주변에 모이던 것을 기억했고, 그 작은 농가에 증거가 있었다. 노련한 순찰대원조차 불안해할 만큼 공식적인 문서였다. 바커스가 그것을 트리아스에게 보냈고, 트리아스는 익숙한 한 단어에서 다음 단서의 윤곽을 알아보았다. 바로 '피스트'였다."
