L["Ginro's next idea was strange even by night elf standards: give the knife to Quintis Jonespyre and let psychometry do what ordinary tracking could not. Quintis saw Raschal taking two large leather backpacks inland, worrying over Woodpaw gnolls, and failing to notice water elementals forming behind him. The knife did not solve the mystery, but it gave the search a direction and a new fear: Raschal had found something worse than gnolls."] = "긴로의 다음 착상은 나이트 엘프의 기준으로도 기묘했다. 칼을 퀸티스 존스파이어에게 건네, 평범한 추적으로는 할 수 없는 일을 사물의 기억을 읽는 능력으로 해내자는 것이었다. 퀸티스는 라샬이 커다란 가죽 배낭 두 개를 들고 내륙으로 향하며 나무발톱 놀을 걱정하는 모습을 보았다. 등 뒤에서 물의 정령이 형체를 갖추는 것은 알아차리지 못한 채였다. 칼이 수수께끼를 풀어 주지는 않았지만, 수색에 방향을 주었고 새로운 두려움도 안겨 주었다. 라샬은 놀보다 더 끔찍한 무언가와 맞닥뜨린 것이다."
