L["Jaina and Anduin brought the Alliance's hammer down on Lordaeron. The Horde fought from the walls, but the siege was overwhelming. When the gates could no longer hold, Sylvanas triggered the plague systems beneath the city — releasing the Blight on her own capital rather than let the Alliance take it. Soldiers on both sides choked and died. The Undercity was lost, left poisoned and empty behind her. The Forsaken had no home left. Again."] = "제이나와 안두인은 얼라이언스의 철퇴를 로데론에 내리쳤다. 호드는 성벽 위에서 맞섰지만, 포위 공격은 압도적이었다. 성문이 더는 버틸 수 없게 되자 실바나스는 도시 아래의 역병 장치를 가동했다. 얼라이언스에게 넘겨주느니 자신의 수도에 역병을 퍼뜨리는 쪽을 택한 것이다. 양 진영의 병사들이 숨이 막혀 죽어 갔다. 언더시티는 독에 물든 채 텅 빈 곳으로 버려졌다. 포세이큰에게는 돌아갈 집이 남지 않았다. 또다시."
