L["Magni could not answer Sara's grief with victory, so he answered with remembrance. Grand Mason Marblesten took the commission seriously, sending you into the Darrow Hill cave for Alterac Granite worthy of the memorial. When the stone was cut and the work was done, the tribute no longer belonged only to Sully Balloo. It stood for every soldier whose death had been reduced to orders, borders, and reports until someone stopped long enough to read the letter."] = "마그니는 사라의 슬픔에 승리로 답할 수 없었기에 추모로 답했다. 대석공 마블스텐은 그 의뢰를 무겁게 받아들여, 기념비에 걸맞은 알터랙 화강암을 구해 오도록 다로우 언덕 동굴로 보냈다. 돌을 깎아 작업을 마쳤을 때, 그 추모비는 더 이상 설리 발루만의 것이 아니었다. 누군가 걸음을 멈추고 편지를 읽어 주기 전까지 명령과 국경과 보고서 속 숫자로만 남았던, 모든 병사의 죽음을 기리는 것이 되었다."
L["Magni orders a rescue, but Blackrock Depths may make it more complicated than an ordinary fight."] = "마그니가 구출을 명령하지만, 검은바위 나락에서는 평범한 전투보다 일이 훨씬 복잡해질지도 모릅니다."
