L["Marshal Windsor's return turned suspicion into spectacle. At the gates of Stormwind, he gathered himself for one last duty and marched through the city toward the keep. The guards, nobles, and courtiers saw what the dragon had hidden from them: Lady Katrana Prestor was no noble advisor. She was Onyxia, broodmother of the black dragonflight. Windsor died exposing her, but his sacrifice broke the illusion around Bolvar and gave the Alliance a clear enemy at last."] = "치안대장 윈저의 귀환으로 의혹은 모두가 지켜보는 광경이 되었다. 스톰윈드 성문 앞에서 그는 마지막 임무를 위해 마음을 다잡고, 도시를 가로질러 왕궁으로 행진했다. 경비병과 귀족, 신하들은 용이 감춰 왔던 것을 두 눈으로 보았다. 여군주 카트라나 프레스톨은 고귀한 조언자가 아니었다. 그녀는 검은용군단의 어미용 오닉시아였다. 윈저는 그녀의 정체를 밝히다 목숨을 잃었지만, 그 희생으로 볼바르를 감싼 환영이 깨졌고 얼라이언스는 마침내 분명한 적을 마주하게 되었다."
