L["Nathanos Blightcaller understood the Scarlet Crusade as an enemy of logistics as much as faith. The Crimson Courier carried command papers through the Plaguelands. Varimathras wanted them read. Nathanos wanted them used. With a rotten apple and a Scarlet disguise, you walked into Tyr's Hand as if you belonged there, then returned with enough truth to send Demetria and her escort to their deaths on the road."] = "나타노스 블라이트콜러가 보기에 붉은십자군은 신앙의 군대인 동시에 보급으로 움직이는 군대였다. 진홍십자군 급사가 역병지대를 오가며 지휘 문서를 나르고 있었다. 바리마트라스는 그 문서를 읽고 싶어 했고, 나타노스는 그것을 이용하고 싶어 했다. 썩은 사과 하나와 붉은십자군 변장을 갖추고 티르의 손 수도원에 마치 그곳 사람인 양 걸어 들어갔다가, 데메트리아와 호위대를 길 위에서 죽음으로 몰아넣기에 충분한 진실을 들고 돌아왔다."
L["Nathanos' Ruse"] = "나타노스의 책략"
