L["Nezzliok's answer made the rescue feel almost impossible. Zanzil controlled Yenniku body and soul, and ordinary weapons could not solve that. Kin'weelay found one thin chance in the legends of Stranglethorn: the Mind's Eye. Pulsing blue shards from Crystalvein Mine prepared the ritual, and Mai'Zoth's ogres guarded the Eye itself inside the Mosh'Ogg mound. With both in hand, Kin'weelay could reshape the magic into a Soul Gem."] = "네즐리오크의 대답을 듣자 구출은 거의 불가능해 보였다. 잔질은 옌니쿠의 몸과 영혼을 모두 지배하고 있었고, 평범한 무기로는 어찌할 도리가 없었다. 킨윌레이는 가시덤불 골짜기의 전설에서 실낱같은 가능성 하나를 찾아냈다. 바로 정신의 눈이었다. 수정 광산에서 캐낸 고동치는 푸른 조각으로 의식을 준비했고, 눈 자체는 모쉬오그 소굴 안에서 마이조스의 오우거들이 지키고 있었다. 두 가지를 모두 손에 넣자, 킨윌레이는 그 마법을 영혼석으로 빚어낼 수 있었다."
L["Night Run, Ashenvale"] = "어둠의 터, 잿빛 골짜기"
L["Night Web Venom"] = "밤그물 거미 독"
L["Nighthaven, Moonglade"] = "밤의 안식처, 달숲"
L["Nimboya"] = "님보야"
L["Nimboya's search began with a fear no Darkspear wanted confirmed. Yenniku, the chief's youngest son, had vanished after being given to the Gurubashi, and the Bloodscalp tribe looked like the only trail left. Tusks proved you could hunt them. Shrunken heads proved Yenniku was not among their trophies. Finally, Gan'zulah and Nezzliok had to die so their heads could be forced to answer from the cauldron at Grom'gol."] = "님보야의 수색은 검은창 부족 누구도 사실로 확인되길 바라지 않던 두려움에서 시작되었다. 족장의 막내아들 옌니쿠가 구루바시에게 넘겨진 뒤 행방불명되었고, 남은 단서는 붉은머리 부족뿐인 듯했다. 엄니는 그들을 사냥할 수 있다는 증거였다. 쪼그라든 머리는 옌니쿠가 그들의 전리품 속에 없다는 증거였다. 마지막으로 간줄라와 네즐리오크를 죽여야 했다. 그래야만 그들의 머리를 그롬골의 가마솥에 넣어 억지로라도 대답하게 만들 수 있었다."
