L["Raene Wolfrunner feared for Teronis, and Ashenvale answered with a corpse. The murlocs near Lake Falathim had killed him, but his journal survived, along with the trail to a glowing gem. Returning both to Astranaar changed the task. Teronis had died looking for a way to slow the furbolg attacks, and Raene asked you to carry that hope forward."] = "레이네 울프러너는 테로니스를 걱정했고, 잿빛 골짜기는 시체 하나로 답했다. 팔라딤 호수 근처의 멀록들이 그를 죽였지만, 그의 일지는 남아 있었고 빛나는 보석으로 이어지는 흔적도 함께였다. 그 둘을 아스트라나르로 가져가자 임무가 달라졌다. 테로니스는 퍼볼그의 공격을 늦출 방법을 찾다가 죽었고, 레이네는 그 희망을 이어 가 달라고 부탁했다."
