L["Ragged John gave the conspiracy a name and a survivor: Marshal Reginald Windsor. Finding Windsor in Blackrock Depths did not bring immediate victory. He had lost hope, and the proof had been torn away from him. A crumpled note and a shred of evidence changed that. Windsor remembered his duty, gathered the missing information, and prepared for the impossible part: walking out of Blackrock Depths alive."] = "털보 존은 음모에 이름과 생존자를 붙여 주었다. 바로 치안대장 레지널드 윈저였다. 검은바위 나락에서 윈저를 찾아냈다고 곧바로 승리가 찾아온 것은 아니었다. 그는 희망을 잃었고, 증거마저 빼앗긴 뒤였다. 구겨진 쪽지 한 장과 증거 한 조각이 그를 바꾸어 놓았다. 윈저는 자신의 의무를 떠올리고 빠진 정보를 모은 뒤, 불가능해 보이는 일을 준비했다. 검은바위 나락에서 살아서 걸어 나가는 것이었다."
