L["Shael'dryn knew what Teronis had been chasing: Dartol's Rod, broken into pieces and hidden across Ashenvale's corrupted places. The iron shaft lay behind a key carried by twisted treants near Felwood. The iron pommel had passed through Dor'danil's dead and into the slime. When the rod was remade, a hidden shrine gave it power again. By then, Teronis' errand had become something stranger: not a weapon, but a way to speak across the line between the uncorrupted and the lost."] = "셸드린은 테로니스가 무엇을 쫓고 있었는지 알고 있었다. 바로 다톨의 막대였다. 막대는 여러 조각으로 부서져 잿빛 골짜기의 타락한 곳곳에 숨겨져 있었다. 무쇠 자루는 악령숲 근처의 뒤틀린 나무정령들이 지닌 열쇠 너머에 있었다. 무쇠 머리장식은 도르다닐의 망자들을 거쳐 진흙괴물 속으로 들어가 있었다. 막대를 다시 맞추자 숨겨진 제단이 다시 힘을 불어넣었다. 그 무렵 테로니스의 임무는 더 기묘한 것으로 바뀌어 있었다. 무기가 아니라, 타락하지 않은 자와 길을 잃은 자 사이의 경계 너머로 말을 건넬 방법이었다."
