L["Sylvanas Windrunner was a Ranger-General, then a corpse, then a queen the Horde was never fully prepared for. Slain by Arthas at the gates of Silvermoon and raised as the first of his banshees, she clawed her way back to herself and built an undead kingdom from the ruins of Lordaeron.\n\nFollow her from Icecrown and Silverpine into wars that test leadership, vengeance, survival, freedom, and the question of what remains when a Windrunner can no longer run from what she has done."] = "실바나스 윈드러너는 순찰대장군이었고, 시체가 되었으며, 이윽고 호드가 끝내 온전히 감당할 준비가 되지 않았던 여왕이 되었습니다. 실버문의 성문 앞에서 아서스에게 살해당하고 그의 첫 번째 밴시로 되살아난 그녀는, 사투 끝에 자신을 되찾고 로데론의 폐허 위에 언데드 왕국을 세웠습니다.\n\n얼음왕관과 은빛소나무 숲에서부터 그녀의 발자취를 따라가십시오. 지도력과 복수, 생존과 자유를 시험하는 전쟁, 그리고 윈드러너가 더는 자신이 저지른 일에서 달아날 수 없게 되었을 때 무엇이 남는가라는 질문이 기다리고 있습니다."
