L["The bronze dragonflight did not greet mortals as allies. Baristolth's trial led to Anachronos, then back through Blackwing Lair and into the Silithus hives. The Head of Broodlord Lashlayer proved strength; the carapace fragments proved endurance. Before the scepter could be repaired, a champion first had to become someone the Brood of Nozdormu would even address."] = "청동용군단은 필멸자를 동맹으로 맞이하지 않았다. 바리스톨스의 시험은 아나크로노스에게로 이어졌고, 다시 검은날개 둥지를 거쳐 실리더스의 벌집으로 향했다. 용기대장 래쉬레이어의 머리는 힘을, 껍질 조각은 인내를 증명했다. 홀을 복원하기 전에, 용사는 먼저 노즈도르무 혈족이 말이라도 걸어 줄 만한 존재가 되어야 했다."
