L["The Horde path entered the same crisis through a different door: a commander in chains, a prisoner with information, and Thrall reading the politics beneath the dungeon walls. Freeing Moira was not mercy alone. It was strategy. If a Dark Iron child could inherit Ironforge, then Blackrock Depths was not only a prison. It was a future capital waiting in the dark."] = "호드의 길은 다른 문을 통해 같은 위기로 들어섰다. 사슬에 묶인 지휘관, 정보를 쥔 포로, 그리고 던전 벽 아래에 감춰진 정치를 읽어 낸 스랄이 있었다. 모이라를 풀어 주는 것은 자비만이 아니었다. 그것은 전략이었다. 검은무쇠 드워프의 아이가 아이언포지를 물려받을 수 있다면, 검은바위 나락은 단순한 감옥이 아니었다. 어둠 속에서 때를 기다리는 미래의 수도였다."
L["the house north of Raven Hill Cemetery"] = "까마귀 언덕 묘지 북쪽의 집"
L["The Hunter's Path"] = "사냥꾼의 길"
L["the Imperial Seat, Blackrock Depths"] = "황제의 옥좌, 검은바위 나락"
L["The Instigator's Enchantment"] = "주동자의 마법"
L["The investigation began with resignation. Latronicus had already declared Raschal missing in action, and Ginro Hearthkindle had spent a week searching Feralas for nothing but gnoll teeth and disappointment. The wrecked row boat on the Forgotten Coast changed that. It was shredded almost in two, marked with Feathermoon's crest, and hiding one small clue in the mud: Raschal's knife."] = "조사는 체념에서 시작되었다. 라트로니쿠스는 이미 라샬을 작전 중 실종자로 처리했고, 긴로 하트킨들은 일주일 동안 페랄라스를 뒤졌지만 얻은 것은 놀의 이빨과 실망뿐이었다. 잊혀진 해안에 난파한 조각배가 그 흐름을 바꾸었다. 배는 거의 두 동강이 나 있었고, 페더문의 문장이 새겨져 있었으며, 진흙 속에 작은 단서 하나를 숨기고 있었다. 라샬의 칼이었다."
L["The investigation began with secrecy, not ceremony. Thomas found you near the Cathedral and sent you to Bishop DeLavey, who admitted that a diplomat sent to meet Jaina Proudmoore had disappeared. DeLavey suspected the Defias but could not prove it, so he pulled in people outside the usual channels: Jorgen by the Valley of Heroes, then Elling Trias above the cheese shop. The case had already moved from church business to spy work."] = "조사는 격식이 아니라 은밀함 속에서 시작되었다. 대성당 근처에서 다가온 토마스는 주교 드라베이를 찾아가라고 했고, 드라베이는 제이나 프라우드무어를 만나러 보낸 외교관이 사라졌다고 털어놓았다. 드라베이는 데피아즈단을 의심했지만 증명할 수 없었기에, 평소의 경로 밖에 있는 사람들을 끌어들였다. 영웅의 계곡 옆의 요르겐, 그리고 치즈 가게 위층의 엘링 트리아스였다. 사건은 이미 교회의 일에서 첩보 활동으로 넘어가 있었다."
