L["The order sounded simple because grief needed it to be simple: kill Thaurissan, spare Moira, bring the princess home. Blackrock Depths answered with something crueler. When the emperor fell, Moira did not thank her rescuers. She mourned her husband, named her unborn child heir to Ironforge, and sent Magni a future he could not command away."] = "명령은 단순하게 들렸다. 슬픔이 그것을 단순하게 만들어야 했기 때문이다. 타우릿산을 죽이고, 모이라는 살려서, 공주를 집으로 데려오라. 검은바위 나락은 더 잔인한 답을 내놓았다. 제왕이 쓰러졌을 때 모이라는 구해 준 이들에게 고마워하지 않았다. 그녀는 남편을 애도하고, 뱃속의 아이를 아이언포지의 후계자로 선포했으며, 마그니에게 명령으로는 물리칠 수 없는 미래를 보냈다."
