L["The rod transformed more than your shape. It let you approach Krolg, an uncorrupted furbolg who still carried grief and anger for what had happened to his people. Krolg blamed the night elves, but he also knew Ran Bloodtooth had become a threat no one could ignore. Killing Ran and his guards did not cleanse Ashenvale, but it proved Teronis had not died for nothing. Raene kept the skull and the rod as proof that the forest could still be defended."] = "막대가 바꾼 것은 겉모습만이 아니었다. 그 덕분에 타락하지 않은 퍼볼그 크롤그에게 다가갈 수 있었다. 그는 동족에게 닥친 일로 여전히 슬픔과 분노를 품고 있었다. 크롤그는 나이트 엘프를 탓했지만, 랜 블러드투스가 누구도 외면할 수 없는 위협이 되었다는 것도 알고 있었다. 랜과 그의 호위병들을 처치했다고 잿빛 골짜기가 정화된 것은 아니었지만, 테로니스의 죽음이 헛되지 않았다는 것은 증명되었다. 레이네는 숲을 아직 지킬 수 있다는 증거로 그 해골과 막대를 간직했다."
L["The Royal Rescue"] = "공주 구출"
L["the ruined inn of Andorhal, Western Plaguelands"] = "안돌할의 폐허가 된 여관, 서부 역병지대"
L["the Ruins of Aboraz, along the Crystal Shore"] = "수정 해안을 따라 자리한 아보라즈 폐허"
L["the Scarab Wall, Silithus"] = "스카라베 성벽, 실리더스"
L["The Scarlet Bastion in Stratholme did not only guard soldiers and sermons. Its archive held the evidence Duke Nicholas Zverenhoff wanted burned, and Balnazzar's fall showed the deeper rot under the Crusade's purity. The order's zeal was not merely human cruelty. Something worse had been wearing it like a vestment."] = "스트라솔름의 붉은십자군 요새가 지키던 것은 병사와 설교만이 아니었다. 그곳의 기록 보관소에는 공작 니콜라스 즈바른호프가 불태우고 싶어 한 증거가 있었고, 발나자르의 몰락은 붉은십자군의 순결함 아래 깊이 자리한 부패를 드러냈다. 그 교단의 광신은 단순한 인간의 잔혹함이 아니었다. 더 끔찍한 무언가가 그것을 제의처럼 걸치고 있었던 것이다."
