L["The trail through Midnight returned to Windrunner Spire, the family home that still held the sisters' wounds in its stone. The halls were not only abandoned; they were haunted by memory, loyalty, resentment, and grief. For Sylvanas's story, the dungeon is context rather than command: a place where the Windrunner name still aches, and where the past keeps answering long after everyone tried to leave it behind."] = "한밤의 여정은 윈드러너 첨탑으로 되돌아갔다. 자매들의 상처가 아직 돌 속에 남아 있는 가문의 옛집이었다. 그 전당은 그저 버려진 곳이 아니었다. 기억과 충성, 원한과 슬픔이 유령처럼 떠돌고 있었다. 실바나스의 이야기에서 이 던전은 반드시 거쳐야 할 길이라기보다 배경에 가깝다. 윈드러너라는 이름이 여전히 아픔으로 남은 곳, 모두가 떠나려 한 지 오래인데도 과거가 계속 대답하는 곳이다."
