L["The way into the Sepulcher opened, and the covenants carried the fight into the machinery of creation. With the Crown of Wills reforged and Anduin freed, the final battle moved deeper into the Sepulcher, where Zovaal tried to remake reality through the First Ones' design. He failed. The Jailer fell, and the Shadowlands war finally ended. Only then could Sylvanas be brought before those she had wronged."] = "매장지로 들어가는 길이 열리자, 성약의 단은 창조의 기계 장치 속으로 싸움을 이어 갔다. 의지의 투구가 다시 벼려지고 안두인이 풀려나자, 최후의 전투는 태초의 존재의 매장지 더 깊은 곳으로 향했다. 조바알은 그곳에서 태초의 존재의 설계를 이용해 현실을 다시 만들려 했다. 그는 실패했다. 간수가 쓰러지고, 어둠땅의 전쟁은 마침내 끝났다. 그제야 실바나스는 자신이 해를 끼친 이들 앞에 설 수 있었다."
