L["Thrall knew Onyxia's threat reached beyond Blackrock Mountain, so he sent you to Rexxar. The champion of the Horde carried old knowledge and a hard road: find Myranda, wear an illusion, gather dragon eyes in Upper Blackrock Spire, and use that disguise to reach Emberstrife. Where the Alliance exposed a dragon in court, the Horde had to deceive a dragon servant into opening the next gate."] = "스랄은 오닉시아의 위협이 검은바위 산 너머까지 뻗어 있음을 알았기에 렉사르에게 보냈다. 호드의 용사는 오래된 지식과 함께 험난한 길을 일러 주었다. 마이랜다를 찾아 환영을 두르고, 검은바위 첨탑 상층에서 용의 눈을 모은 뒤, 그 변장으로 엠버스트라이프에게 다가가는 것이었다. 얼라이언스가 궁정에서 용의 정체를 폭로했다면, 호드는 용의 하수인을 속여 다음 관문을 열게 해야 했다."
