L["Vereesa's visions showed Silvermoon under a shadowed sun, and Arator went looking for the family legacy that might answer it. Alleria was still hunting Xal'atath, and Sylvanas remained in the Maw, freeing the souls she had condemned. So Arator followed the trail no one else wanted to walk: through Ve'nari's gate and into the realm of the damned. The Devouring Host followed him there, and together he and Sylvanas cut them out of the Tremaculum. Arator asked her to come home. Sylvanas refused. Her duty was still among the dead, but she gave him the answer he needed: Silvermoon did need a Windrunner, and he could be one."] = "베리사의 환영에는 그림자 진 태양 아래의 실버문이 비쳤고, 아라토르는 그 답이 될지도 모를 가문의 유산을 찾아 나섰다. 알레리아는 여전히 잘라타스를 쫓고 있었고, 실바나스는 나락에 남아 자신이 저주했던 영혼들을 풀어 주고 있었다. 그래서 아라토르는 누구도 걷고 싶어 하지 않는 길을 따라갔다. 베나리의 관문을 지나 저주받은 자들의 영역으로 들어간 것이다. 포식의 무리가 그곳까지 그를 쫓아왔고, 아라토르와 실바나스는 함께 그들을 나락의 구렁에서 베어 냈다. 아라토르는 그녀에게 집으로 돌아오자고 청했다. 실바나스는 거절했다. 그녀의 의무는 여전히 망자들 곁에 있었다. 하지만 그녀는 아라토르에게 필요한 답을 주었다. 실버문에는 윈드러너가 필요하며, 그가 바로 그 윈드러너가 될 수 있다고."
