L["Windrunner Spire opens its haunted halls in Midnight. This is not required for Sylvanas's penance, but it is a sharp look back at the Windrunner family home and the grief left behind by Alleria, Sylvanas, and Vereesa."] = "한밤에서 윈드러너 첨탑이 유령 깃든 전당의 문을 엽니다. 실바나스의 속죄에 꼭 필요한 과정은 아니지만, 윈드러너 가문의 옛집과 알레리아, 실바나스, 베리사가 남긴 슬픔을 날카롭게 되돌아보게 합니다."
