L["You fought through the Ruins of Gilneas — sabotage, ambushes, a cat-and-mouse hunt through a shattered city — and cornered Godfrey, the man who had betrayed everyone at least once. Sylvanas raised him without ceremony. Then came the final push: Lorna Crowley was captured and brought before her. Sylvanas offered terms. The Gilneas Liberation Front could keep fighting and watch everything turn to dust, or stand aside. It was not a bluff. It was cold, precise, and entirely in character."] = "길니아스 폐허를 뚫고 싸워 나갔다. 파괴 공작과 매복, 무너진 도시 곳곳에서 벌어진 쫓고 쫓기는 사냥 끝에, 모두를 적어도 한 번씩은 배신한 사내 갓프리를 궁지로 몰아넣었다. 실바나스는 아무런 격식도 없이 그를 되살렸다. 이어 마지막 공세가 시작되었다. 로르나 크롤리가 사로잡혀 실바나스 앞에 끌려왔다. 실바나스는 조건을 내걸었다. 길니아스 해방전선은 계속 싸우다 모든 것이 잿더미가 되는 꼴을 지켜보거나, 물러서야 했다. 허세가 아니었다. 냉정하고 정확하며, 더없이 실바나스다운 방식이었다."
L["Ysida Harmon"] = "이시다 하몬"
L["Yvette Farthing"] = "이베트 파딩"
L["Zanzil's Hold"] = "잔질의 속박"
L["Zekhan"] = "제칸"
L["Zombie Juice"] = "좀비 독주"
L["Zukk'ash Pod"] = "주크애쉬 고치"
L["A Few Handfuls of Oats"] = "귀리 몇 줌"
L["Gather oats from the farms of Westfall and bring them back to Verna Furlbrow for Old Blanchy."] = "서부 몰락지대의 농장에서 귀리를 모아, 늙은말 블랑쉬를 위해 베르나 펄브로우에게 가져가십시오."
L["Jansen Stead, Westfall"] = "얀센 농장, 서부 몰락지대"
L["Old Blanchy"] = "늙은말 블랑쉬"
L["Poor Old Blanchy"] = "늙은말 블랑쉬"
L["The Furlbrows had fled their farm with little more than a broken wagon and a hungry old horse. Eight handfuls of oats were not much against the trouble in Westfall, but for Blanchy and the people still trying to leave, it was enough to make the road feel possible again."] = "펄브로우 부부는 부서진 마차와 배고픈 늙은 말 한 마리만 겨우 챙겨 농장을 떠났다. 귀리 여덟 줌은 서부 몰락지대의 혼란 앞에서 대단한 것이 아니었지만, 블랑쉬와 아직 떠나려 애쓰는 사람들에게는 다시 길을 나설 수 있겠다는 마음을 품게 하기에 충분했다."
L["Verna Furlbrow"] = "베르나 펄브로우"
L["Verna Furlbrow and her husband left their farm in a hurry, only for their wagon to break near the road into Westfall. Their old horse, Blanchy, has carried more than her share already.\n\nGather what oats you can from the nearby farms. It is a small kindness, but on a hard road even that can matter."] = "베르나 펄브로우와 남편은 서둘러 농장을 떠났지만, 서부 몰락지대로 들어가는 길목에서 마차가 부서지고 말았습니다. 늙은 말 블랑쉬는 이미 제 몫 이상의 짐을 짊어졌습니다.\n\n근처 농장에서 귀리를 최대한 모아 오십시오. 작은 친절이지만, 험한 길에서는 그것조차 큰 힘이 될 수 있습니다."
L["Defias camps around Elwynn Forest"] = "엘윈 숲 곳곳의 데피아즈단 야영지"
L["Farmer Furlbrow"] = "농부 펄브로우"
L["Furlbrow's Deed"] = "펄브로우의 땅문서"
L["Recover the Furlbrows' watch from the pumpkin farm, return any stolen deed you find, and gather oats for Old Blanchy."] = "호박 농장에서 펄브로우 부부의 시계를 되찾고, 도둑맞은 증서를 발견하면 돌려준 뒤, 늙은말 블랑쉬를 위해 귀리를 모으십시오."
L["The Forgotten Heirloom"] = "두고 온 회중시계"
L["The Furlbrows had fled their farm with a broken wagon, a hungry old horse, and too little room for memory. The pocket watch was only a small thing, but it carried a wedding day and a home they might never see again. The oats were just as small, yet for Old Blanchy and the people still trying to leave Westfall, they made the road feel possible again."] = "펄브로우 부부는 부서진 마차와 배고픈 늙은 말을 이끌고 농장을 떠났고, 추억을 챙길 자리는 거의 없었다. 회중시계는 작은 물건에 불과했지만, 그 안에는 결혼식 날과 다시는 보지 못할지도 모르는 집이 담겨 있었다. 귀리 역시 보잘것없었지만, 늙은말 블랑쉬와 아직 서부 몰락지대를 떠나려 애쓰는 사람들에게는 다시 길을 나설 수 있겠다는 희망이 되었다."
L["Verna Furlbrow and her husband left their farm in a hurry, only for their wagon to break near the road into Westfall. Behind them are thieves in the fields, a farmhouse they may never see again, and a few keepsakes left in the rush.\n\nRecover what the Furlbrows could not carry, then gather oats for Blanchy. It is a small kindness on the edge of a larger ruin."] = "베르나 펄브로우와 남편은 서둘러 농장을 떠났지만, 서부 몰락지대로 들어가는 길목에서 마차가 부서지고 말았습니다. 그들 뒤에는 들판을 누비는 도둑들과 다시는 보지 못할지도 모르는 농가, 그리고 황급히 떠나느라 남겨 둔 몇 가지 추억의 물건이 있습니다.\n\n펄브로우 부부가 챙기지 못한 물건을 되찾은 뒤, 블랑쉬를 위해 귀리를 모으십시오. 더 큰 몰락의 가장자리에서 베푸는 작은 친절입니다."
L["What They Left Behind"] = "남겨 두고 온 것들"
L["Westfall"] = "서부 몰락지대"
L["Apothecary Faustin"] = "연금술사 파우스틴"
L["Beggar's Haunt"] = "부랑자 소굴"
L["Beggar's Haunt, Duskwood"] = "부랑자 소굴, 그늘숲"
L["Deathstalker Zraedus"] = "죽음추적자 즈레더스"
L["Deepstrider Giants"] = "심해걸음 거인"
L["Duskwood / Swamp of Sorrows / Desolace"] = "그늘숲 / 슬픔의 늪 / 잊혀진 땅"
L["eastern Swamp of Sorrows"] = "슬픔의 늪 동부"
L["Faustin's Serum"] = "파우스틴의 혈청"
L["Infiltrator Marksen"] = "침투요원 마크슨"
L["Meet the Forsaken agents hidden in Duskwood and help prepare a truth serum for Stonard's prisoner."] = "그늘숲에 숨어 있는 포세이큰 요원들을 만나, 스토나드의 포로에게 쓸 자백제 준비를 도우십시오."
L["Mire Lord"] = "우두머리 늪괴물"
L["Misty Valley, Swamp of Sorrows"] = "안개 골짜기, 슬픔의 늪"
L["North of the road into Deadwind Pass, two Forsaken agents keep a quiet post at Beggar's Haunt. A human infiltrator has seen too much, and Stonard's orcs have taken him alive before the matter could be settled.\n\nWork with Deathstalker Zraedus and Apothecary Faustin on a serum meant to draw out the truth. They are very particular about whose truth reaches the Horde."] = "저승바람 고개로 들어가는 길 북쪽, 부랑자 소굴에서 포세이큰 요원 두 명이 조용히 자리를 지키고 있습니다. 한 인간 첩자가 너무 많은 것을 보았고, 일이 마무리되기 전에 스토나드의 오크들이 그를 산 채로 붙잡아 갔습니다.\n\n죽음추적자 즈레더스, 연금술사 파우스틴과 함께 진실을 끌어낼 혈청을 만드십시오. 두 사람은 누구의 진실이 호드에 전해질지를 두고 몹시 까다롭게 굽니다."
L["Nothing But The Truth"] = "진실의 물약"
L["Shadow Panthers"] = "그림자 표범"
L["Stonard's Prisoner"] = "스토나드의 포로"
L["The Truth Serum"] = "자백제"
L["the coast near Ethel Rethor, Desolace"] = "에텔 레소르 근처 해안, 잊혀진 땅"
L["Zraedus and Faustin called it help for their orcish allies, but every errand served the same purpose: keep the captive in Stonard from saying too much. The serum needed panther hearts, rare fungus, and a giant's tumor before Faustin could finish it. By the time Marksen drank the disguised brew, the truth was already losing its chance to be heard."] = "즈레더스와 파우스틴은 오크 동맹을 돕는 일이라고 했지만, 모든 심부름은 같은 목적을 위한 것이었다. 스토나드에 붙잡힌 포로가 너무 많은 말을 하지 못하게 막는 것이었다. 파우스틴이 혈청을 완성하려면 표범의 심장과 희귀한 버섯, 그리고 거인의 종양이 필요했다. 마크센이 정체를 감춘 그 약을 마셨을 때, 진실은 이미 세상에 알려질 기회를 잃어 가고 있었다."
L["Zraedus's Request"] = "즈레더스의 부탁"
L["The Shady Rest Inn"] = "그늘 쉼터 여관"
L["On the road between Dustwallow Marsh and the Barrens, the Shady Rest Inn is nothing but ash, hoofprints, a scorched shield, and a guard badge that should not be there.\n\nFollow the clues before faction blame buries the truth. What begins as a burned waystation becomes an investigation through evidence that may have been left to tell too simple a story."] = "먼지진흙 습지대와 불모의 땅 사이의 길목, 그늘 쉼터 여관에 남은 것은 재와 발굽 자국, 그을린 방패, 그리고 그곳에 있어서는 안 될 경비병 휘장뿐입니다.\n\n진영 간의 비난이 진실을 덮어 버리기 전에 단서를 쫓으십시오. 불타 버린 쉼터에서 시작된 일은, 지나치게 단순한 이야기를 들려주도록 일부러 남겨졌을지도 모를 증거를 파헤치는 조사로 이어집니다."
L["Dustwallow Marsh"] = "먼지진흙 습지대"
L["World of Warcraft"] = "World of Warcraft"
L["Suspicious Hoofprints"] = "수상한 발굽 자국"
L["Hoofprints"] = "발굽 자국"
L["the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "그늘 쉼터 여관 폐허, 먼지진흙 습지대"
L["Foothold Citadel, Theramore Isle"] = "거점 요새, 테라모어 섬"
L["Lost Point, Dustwallow Marsh"] = "버려진 경비탑, 먼지진흙 습지대"
L["North Point Tower, Dustwallow Marsh"] = "북부 경비탑, 먼지진흙 습지대"
L["the Theramore blacksmith, Dustwallow Marsh"] = "테라모어의 대장장이, 먼지진흙 습지대"
L["Brackenwall Village, Dustwallow Marsh"] = "담쟁이 마을, 먼지진흙 습지대"
L["Theramore Isle, Dustwallow Marsh"] = "테라모어 섬, 먼지진흙 습지대"
L["outside the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "그늘 쉼터 여관 폐허 바깥, 먼지진흙 습지대"
L["Tabetha's Farm, Dustwallow Marsh"] = "타베사의 농장, 먼지진흙 습지대"
L["inside the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "그늘 쉼터 여관 폐허 안, 먼지진흙 습지대"
L["The Ruins"] = "폐허"
L["Captain Garran Vimes sends you to the burned inn, where the first clues point in several uncomfortable directions."] = "사령관 개런 바임스의 지시로 불타 버린 여관을 찾아가면, 첫 단서들이 여러 불편한 방향을 가리킵니다."
L["The ruins did not offer a clean answer. Hoofprints marked the ash outside the inn, a blackened shield suggested a tauren hand, and a Theramore badge tied the scene to Lieutenant Paval Reethe. Even Smiling Jim's grief only sharpened the question: who wanted everyone looking at the wrong enemy?"] = "폐허는 명쾌한 답을 주지 않았다. 여관 밖의 잿더미에는 발굽 자국이 찍혀 있었고, 시커멓게 그을린 방패는 타우렌의 솜씨를 암시했으며, 테라모어의 휘장은 현장을 부관 파발 리테와 엮었다. 웃는 짐의 슬픔조차 질문을 더 날카롭게 만들 뿐이었다. 대체 누가 모두의 눈을 엉뚱한 적에게 돌리려 한 것일까?"
L["Inspecting the Ruins"] = "폐허 조사"
L["Captain Garran Vimes"] = "사령관 개런 바임스"
L["They Call Him Smiling Jim"] = "유쾌한 짐이라 불리는 사나이"
L["Guard Byron"] = "경비병 바이론"
L["The Black Shield"] = "검은 방패"
L["Follow the scorched shield from the ruined fireplace back through Theramore's smiths."] = "무너진 벽난로에서 나온 그을린 방패를 들고 테라모어의 대장장이들을 찾아가십시오."
L["The black shield looked like the simplest clue, and so it became the most dangerous one. Caz Twosprocket could tell it was not made in Theramore, and the size suggested a tauren bearer, but certainty stayed out of reach. The clue was real, yet it still felt planted to push anger toward the Horde."] = "검은 방패는 가장 단순한 단서처럼 보였고, 그래서 가장 위험한 단서가 되었다. 카즈 투스프로켓은 그것이 테라모어에서 만든 물건이 아니라는 것을 알아보았고, 크기로 보아 타우렌이 들던 것 같았지만 확신에는 이르지 못했다. 단서는 진짜였지만, 여전히 호드에게 분노를 돌리려고 일부러 남겨 둔 것처럼 느껴졌다."
L["Black Shield"] = "검은 방패"
L["The Black Shield: Caz Twosprocket"] = "검은 방패: 카즈 투스프로켓"
L["The Black Shield: Vimes' Report"] = "검은 방패: 바임스의 보고"
L["Caz Twosprocket"] = "카즈 투스프로켓"
L["Paval Reethe"] = "파발 리테"
L["Trace the Theramore Guard badge to Paval Reethe and the deserters at Lost Point."] = "테라모어 경비병 휘장을 단서로 파발 리테와 버려진 경비탑의 탈영병들을 추적하십시오."
L["The guard badge led away from the inn and into Theramore's own troubles. Paval Reethe had deserted, and Balos Jacken's men at Lost Point had little love left for their old command. Reethe looked guilty enough to be useful, but not guilty enough to be the answer."] = "경비병 휘장은 여관을 벗어나 테라모어 내부의 문제로 이어졌다. 파발 리테는 탈영했고, 버려진 경비탑에 있는 밸로스 제킨의 부하들은 옛 지휘부에 대한 애정이 거의 남아 있지 않았다. 리테는 쓸모 있을 만큼은 수상해 보였지만, 해답이 될 만큼 수상하지는 않았다."
L["Lieutenant Paval Reethe"] = "부관 파발 리테"
L["Theramore Guard Badge"] = "테라모어 경비병 휘장"
L["Lieutenant Paval Reethe: Records"] = "부관 파발 리테: 기록"
L["Daelin's Men"] = "대린의 부하"
L["Adjutant Tesoran"] = "부관 테소렌"
L["The Deserters"] = "탈영병"
L["The Deserters: Lost Point"] = "탈영병: 버려진 경비탑"
L["The Deserters: Balos' Account"] = "탈영병: 밸로스의 진술"
L["Balos Jacken"] = "밸로스 제킨"
L["The Hidden Hand"] = "숨은 손"
L["The evidence carries you north to one more camp, then south to Tabetha for a clearer look at the hand behind the fire."] = "증거를 따라 북쪽의 야영지 한 곳을 더 거친 뒤, 남쪽의 타베사에게 가서 화재 뒤에 숨은 손의 정체를 더 분명히 확인합니다."
L["The missing piece was not a deserter or a city guard, but a Grimtotem move meant to poison Theramore and the Horde against each other. Captain Darill's evidence exposed Blackhoof Village as part of the plot, while Tabetha pointed to Direhorn Post as the real source of the attack. When the camp burned, the Shady Rest finally had an answer."] = "빠진 조각은 탈영병도, 도시 경비병도 아니었다. 테라모어와 호드를 서로 반목하게 만들려는 그림토템 부족의 술책이었다. 대장 다릴의 증거는 검은발굽 마을이 음모에 가담했음을 드러냈고, 타베사는 공포뿔 거점이 공격의 진짜 근원이라고 지목했다. 그 야영지가 불타오르자, 그늘 쉼터 여관의 비극은 마침내 답을 얻었다."
L["A Grim Connection"] = "불길한 관계"
L["Confirming the Suspicion"] = "의혹 확인"
L["Captain Darill"] = "대장 다릴"
L["Arms of the Grimtotems"] = "그림토템 부족의 무기"
L["Tabetha's Assistance"] = "타베사의 도움"
L["Raze Direhorn Post!"] = "공포뿔 거점을 파괴하라!"
L["Justice for the Hyals"] = "하이알 가족을 위한 정의"
L["Peace at Last"] = "마침내 찾은 평화"
L["Krog has orders to investigate the burned inn, but the real clues are waiting in the ash."] = "크로그는 불타 버린 여관을 조사하라는 명령을 받았지만, 진짜 단서는 잿더미 속에서 기다리고 있습니다."
L["The ruins were not merely Alliance grief. Hoofprints, a scorched shield, and a Theramore badge could all be read as accusations, and Krog wanted the Horde's answers before Theramore wrote the story for everyone. The evidence pointed at tauren ironwork and Paval Reethe, but neither trail felt complete."] = "폐허는 얼라이언스만의 슬픔이 아니었다. 발굽 자국과 그을린 방패, 테라모어의 휘장은 모두 고발로 읽힐 수 있었고, 크로그는 테라모어가 멋대로 이야기를 정해 버리기 전에 호드의 답을 얻고 싶어 했다. 증거는 타우렌의 철제품과 파발 리테를 가리켰지만, 어느 쪽 흔적도 완전하지 않았다."
L["Krog"] = "크로그"
L["Carry the blackened shield through Brackenwall and Thunder Bluff until Mosarn can place the craft."] = "그을린 방패를 들고 고사리장벽 마을과 썬더 블러프를 거쳐, 모사른이 그 솜씨의 출처를 알아낼 때까지 조사하십시오."
L["The shield should have settled the matter, but it only made the case stranger. Krog, Do'gol, and Mosarn could follow the iron's story, yet the shield alone did not prove who set the fire. It was a clue with enough truth to be useful and enough ambiguity to start a war."] = "방패로 사건이 매듭지어져야 했지만, 오히려 일은 더 기묘해졌다. 크로그와 도골, 모사른은 그 쇠붙이의 내력을 짚어 낼 수 있었지만, 방패만으로는 누가 불을 질렀는지 증명할 수 없었다. 쓸모 있을 만큼의 진실과 전쟁을 일으킬 만큼의 모호함을 함께 지닌 단서였다."
L["The Black Shield: Do'gol"] = "검은 방패: 도골"
L["The Black Shield: Do'gol's Findings"] = "검은 방패: 도골의 조사 결과"
L["Do'gol"] = "도골"
L["The Black Shield: Return to Krog"] = "검은 방패: 크로그에게 돌아가기"
L["The Black Shield: Mosarn"] = "검은 방패: 모사른"
L["Track Paval Reethe with Ogron's help and see why the badge was left behind."] = "오그론의 도움을 받아 파발 리테를 추적하고, 휘장이 왜 남겨졌는지 알아보십시오."
L["Paval Reethe was real, cornered, and dangerous, but the speed of his death made him look less like the murderer and more like a man someone needed silenced. The badge at the inn had not solved the case. It had revealed how badly someone wanted a convenient suspect."] = "파발 리테는 실존했고, 궁지에 몰려 있었으며, 위험했다. 하지만 너무나 빨리 죽은 탓에, 그는 살인자라기보다 누군가 입을 막아야 했던 사람처럼 보였다. 여관에 남은 휘장은 사건을 해결하지 못했다. 오히려 누군가가 편리한 용의자를 얼마나 간절히 원했는지를 드러냈을 뿐이었다."
L["Questioning Reethe"] = "리테 심문"
L["Ogron"] = "오그론"
L["Mosarn's new lead brings the investigation back to Krog, then south to Tabetha for a clearer look at the hand behind the fire."] = "모사른의 새로운 단서로 조사는 다시 크로그에게 돌아가고, 이어 남쪽의 타베사에게 이어져 화재 뒤에 숨은 손의 정체를 더 분명히 드러냅니다."
L["Mosarn's memory reopened the case and pulled the scattered clues into one line: the Grimtotem had used the inn to inflame Theramore and the Horde. Krog's evidence and Tabetha's certainty led to Direhorn Post. Burning it down did not restore the Shady Rest, but it stopped the lie from doing more work."] = "모사른의 기억이 사건을 다시 열었고, 흩어진 단서들을 하나로 꿰었다. 그림토템 부족이 여관을 이용해 테라모어와 호드 사이에 불을 지핀 것이었다. 크로그의 증거와 타베사의 확신은 공포뿔 거점으로 이어졌다. 그곳을 불태운다고 그늘 쉼터가 되살아나지는 않았지만, 거짓이 더 큰 해를 끼치는 것은 막을 수 있었다."
L["Return to Krog"] = "크로그에게 돌아가기"
L["Mosarn"] = "모사른"
L["More than Coincidence"] = "우연 이상의 것"
L["The Grimtotem Plot"] = "그림토템의 음모"
L["Seek Out Tabetha"] = "타베사를 찾아서"
L["Justice Dispensed"] = "정의의 심판"
L["The Hakkari Trail"] = "학카리의 흔적"
L["At Steamwheedle Port, Yeh'kinya asks for help with old troll spirits and older tablets. The work sounds archaeological at first, but the names on the tablets are not harmless history.\n\nFollow the trail from Feralas and Zul'Farrak to Jintha'Alor, the Temple of Atal'Hakkar, Blackrock Spire, and finally Yojamba Isle. What begins as a favor for a lone troll becomes a warning about the Soulflayer's return."] = "스팀휘들 항구의 예킨야가 오래된 트롤 영혼과 그보다 더 오래된 석판에 관한 도움을 청합니다. 처음에는 고고학 조사처럼 들리지만, 석판에 새겨진 이름들은 결코 무해한 역사가 아닙니다.\n\n페랄라스와 줄파락에서 시작해 진타알로, 아탈학카르 신전, 검은바위 첨탑을 거쳐 마침내 요잠바 섬까지 흔적을 따라가십시오. 외로운 트롤을 위한 부탁으로 시작된 일은 영혼의 학살자의 귀환을 알리는 경고가 됩니다."
L["Tanaris / Feralas / Zul'Farrak / The Hinterlands / Sunken Temple / Blackrock Spire / Stranglethorn Vale"] = "타나리스 / 페랄라스 / 줄파락 / 동부 내륙지 / 가라앉은 사원 / 검은바위 첨탑 / 가시덤불 골짜기"
L["Zul'Farrak"] = "줄파락"
L["Screecher Spirits"] = "계곡천둥매의 영혼"
L["Yeh'kinya"] = "예킨야"
L["Steamwheedle Port, Tanaris"] = "스팀휘들 항구, 타나리스"
L["Zul'Farrak, near Gahz'rilla's pool"] = "줄파락, 가즈릴라의 연못 근처"
L["the summit cave at Jintha'Alor, The Hinterlands"] = "진타알로 정상의 동굴, 동부 내륙지"
L["the Sanctum of the Fallen God, Temple of Atal'Hakkar"] = "몰락한 신의 성소, 아탈학카르 신전"
L["Zul'Mashar, Eastern Plaguelands"] = "줄마샤르, 동부 역병지대"
L["Lower Blackrock Spire"] = "검은바위 첨탑 하층"
L["Yojamba Isle, Stranglethorn Vale"] = "요잠바 섬, 가시덤불 골짜기"
L["Yeh'kinya sends you into Feralas to question the spirits of Vale Screechers."] = "예킨야의 부탁을 받아 페랄라스로 가서 골짜기 비명새의 영혼들에게 물어보십시오."
L["The first clue was not written on stone. Yeh'kinya's bramble drew memories from dead screechers in Feralas, and those spirits pointed toward an old troll prophecy. The errand had opened a door into Hakkari history."] = "첫 번째 단서는 돌에 새겨져 있지 않았다. 예킨야의 가시나무는 페랄라스에서 죽은 비명새들의 기억을 끌어냈고, 그 영혼들은 오래된 트롤 예언을 가리켰다. 그 심부름은 학카리의 역사로 들어가는 문을 연 셈이었다."
L["The Prophecy of Mosh'aru"] = "모쉬아루의 예언"
L["Recover the first two Mosh'aru tablets from Zul'Farrak, then seek the ancient egg hidden in Jintha'Alor."] = "줄파락에서 첫 두 개의 모샤루 석판을 되찾은 뒤, 진타알로에 숨겨진 고대의 알을 찾으십시오."
L["Zul'Farrak held the first tablets: one with Theka the Martyr, one near Hydromancer Velratha and the sacred pool. Their prophecy named an ancient egg, a relic from the age of troll empires. At Jintha'Alor, the egg waited behind the amphitheater at the top of the city, guarded by the kind of history that still had teeth."] = "줄파락에는 첫 석판들이 있었다. 하나는 순교자 테카가, 다른 하나는 물술사 벨라타와 신성한 연못 근처에 있었다. 석판의 예언은 트롤 제국 시대의 유물인 고대의 알을 지목했다. 진타알로에서 그 알은 도시 꼭대기의 원형 경기장 뒤편에서 기다리고 있었고, 여전히 이빨을 드러낸 역사가 그것을 지키고 있었다."
L["The Ancient Egg"] = "고대의 알"
L["The God Hakkar"] = "학카르의 화신"
L["Carry the egg into the Temple of Atal'Hakkar and bind the avatar's essence inside it."] = "알을 아탈학카르 신전으로 가져가 화신의 정수를 그 안에 봉인하십시오."
L["The temple in the Swamp of Sorrows gave the prophecy its true weight. The egg was not merely a container for old magic; it was a vessel for Hakkar's essence. In the Sanctum of the Fallen God, the avatar rose, fell, and left behind power Yeh'kinya had asked you to gather."] = "슬픔의 늪에 있는 신전에서 예언은 비로소 진짜 무게를 드러냈다. 알은 단순히 오래된 마법을 담는 그릇이 아니라, 학카르의 정수를 담을 용기였다. 몰락한 신의 성소에서 화신은 일어섰다가 쓰러졌고, 예킨야가 모아 오라고 했던 힘을 남겼다."
L["The Final Tablets"] = "마지막 서판"
L["Prospector Ironboot reveals the missing tablets and sends you to Eastern Plaguelands and Lower Blackrock Spire."] = "발굴조사단장 아이언부트가 빠진 석판의 존재를 밝히고, 동부 역병지대와 검은바위 첨탑 하층으로 보냅니다."
L["Prospector Ironboot saw the lie in the work Yeh'kinya had given you. There were six tablets, not two, and the rest changed the meaning of the prophecy. Zul'Mashar held the third and fourth; Lower Blackrock Spire held the final pair. Piece by piece, the tablets stopped sounding like a way to contain Hakkar and started sounding like a way to bring him back."] = "발굴조사단장 아이언부트는 예킨야가 맡긴 일 속에 숨은 거짓을 꿰뚫어 보았다. 석판은 두 개가 아니라 여섯 개였고, 나머지 석판들이 예언의 의미를 바꾸어 놓았다. 세 번째와 네 번째 석판은 줄마샤르에, 마지막 두 개는 검은바위 첨탑 하층에 있었다. 하나씩 맞춰 갈수록 석판은 학카르를 가두는 방법이 아니라 그를 되살리는 방법처럼 읽히기 시작했다."
L["The Lost Tablets of Mosh'aru"] = "모쉬아루의 잃어버린 서판"
L["Prospector Ironboot"] = "발굴조사단장 아이언부트"
L["The Hand of Rastakhan"] = "라스타칸의 대리인"
L["Confront Yeh'kinya, then carry Ironboot's warning to Molthor on Yojamba Isle."] = "예킨야와의 대면을 마친 뒤, 아이언부트의 경고를 요잠바 섬의 몰토르에게 전하십시오."
L["Yeh'kinya had not been preserving the world from Hakkar. He had sped the Soulflayer's return. The truth turned a long dungeon trail into a Zandalar summons, and Molthor received the warning on Yojamba Isle. The fight had moved beyond tablets and temples. Zul'Gurub was waiting."] = "예킨야는 학카르로부터 세상을 지키고 있던 것이 아니었다. 오히려 영혼의 학살자의 귀환을 앞당기고 있었다. 이 진실로 긴 던전 여정은 잔달라의 소환으로 바뀌었고, 요잠바 섬의 몰토르가 그 경고를 받았다. 싸움은 이제 석판과 신전을 넘어섰다. 줄구룹이 기다리고 있었다."
L["Confront Yeh'kinya"] = "예킨야와의 대면"
L["Maraudon"] = "마라우돈"
L["The crystal caverns beneath Desolace are holy ground, burial ground, and wound all at once. Satyrs, centaur spirits, corrupted plants, and an earth princess all pull at the same buried story.\n\nEnter Maraudon from the orange and purple passages, recover the Scepter of Celebras, and follow the descent to Princess Theradras and the remains of Zaetar."] = "잊혀진 땅 아래의 수정 동굴은 성지이자 묘지이며, 동시에 상처입니다. 사티로스와 켄타우로스의 영혼, 타락한 식물, 그리고 대지의 공주가 모두 같은 묻힌 이야기를 붙잡고 있습니다.\n\n주황색 통로와 보라색 통로를 통해 마라우돈에 들어가 켈레브라스의 홀을 되찾고, 공주 테라드라스와 재타르의 유해가 있는 깊은 곳까지 내려가십시오."
L["Desolace / Maraudon / Moonglade"] = "잊혀진 땅 / 마라우돈 / 달의 숲"
L["The Pariah's Instructions"] = "추방자의 지시서"
L["Centaur Pariah"] = "켄타우로스 추방자"
L["southern Desolace"] = "잊혀진 땅 남부"
L["southern Desolace, near the Valley of Spears"] = "잊혀진 땅 남부, 창의 골짜기 근처"
L["Kormek's Hut, Desolace"] = "코르메크의 오두막, 잊혀진 땅"
L["Shadowprey Village, Desolace"] = "그늘수렵 마을, 잊혀진 땅"
L["the orange crystal passage, Maraudon"] = "주황색 수정 통로, 마라우돈"
L["south of Shadowprey Village, Desolace"] = "그늘수렵 마을 남쪽, 잊혀진 땅"
L["Earth Song Falls, Maraudon"] = "대지노래 폭포, 마라우돈"
L["The Pariah and the Prophet"] = "추방자와 예언자"
L["Follow the Centaur Pariah's instructions and heed Willow's request for Maraudon's carved crystals."] = "켄타우로스 추방자의 지시를 따르고, 마라우돈의 조각된 수정을 구해 달라는 윌로우의 부탁에 귀 기울이십시오."
L["Before the inner caverns, Maraudon offered two warnings. The Centaur Pariah named the khans and the Nameless Prophet, a path through the centaur dead. Willow, far less trustworthy, wanted Theradric carvings from the same twisted place. Both errands made the caverns feel older than Desolace's current wars."] = "안쪽 동굴에 이르기 전, 마라우돈은 두 가지 경고를 건넸다. 켄타우로스 추방자는 칸들과 이름 없는 예언자를 언급하며 켄타우로스 망자들 사이로 난 길을 일러 주었다. 그보다 훨씬 미덥지 못한 윌로우는 같은 뒤틀린 장소에서 테라드릭 조각품을 원했다. 두 심부름 모두 이 동굴이 잊혀진 땅의 지금 전쟁들보다 훨씬 오래되었음을 느끼게 했다."
L["Twisted Evils"] = "뒤틀린 악마"
L["Willow"] = "윌로우"
L["Vyle Corruption"] = "사악한 타락"
L["Cleanse Vylestem vines in the orange caverns and gather shadowshards from the purple side."] = "주황색 동굴의 바일스템 덩굴을 정화하고, 보라색 쪽에서 그림자 조각을 모으십시오."
L["Vyletongue's corruption was not only demonic; it had soaked into Maraudon's plants and crystals. Talendria or Vark sent you to fill a vial at the orange pool and draw the poison out plant by plant. The shadowshards outside the purple passage told the same story in stone: the caverns were sick, and the sickness had useful fragments for people outside."] = "바일텅의 타락은 악마의 것만이 아니었다. 그것은 마라우돈의 식물과 수정에까지 스며들어 있었다. 탈렌드리아나 바르크는 주황색 연못에서 약병을 채워, 식물 하나하나에서 독을 뽑아내라고 했다. 보라색 통로 밖의 그림자 조각들도 돌로써 같은 이야기를 들려주었다. 동굴은 병들어 있었고, 그 병에는 바깥사람들이 쓸 만한 조각들이 있었다."
L["Vyletongue Corruption"] = "바일텅의 타락"
L["Talendria"] = "탈렌드리아"
L["Vark Battlescar"] = "바르크 배틀스카"
L["Shadowshard Fragments"] = "음영석 조각"
L["Theramore, Dustwallow Marsh"] = "테라모어, 먼지진흙 습지대"
L["Uthel'nay"] = "우텔나이"
L["The Scepter of Celebras"] = "셀레브라스의 홀"
L["Recover the Celebrian rod and diamond, free Celebras, and restore the scepter."] = "켈레브리안 막대와 다이아몬드를 되찾고, 켈레브라스를 해방한 뒤 홀을 복원하십시오."
L["Cavindra's plea gave the dungeon its heart. Noxxion held the rod, Lord Vyletongue held the diamond, and Celebras himself wandered under corruption. Once the keeper was defeated and redeemed, the two pieces could become a scepter again, not only a shortcut through Maraudon but a sign that some part of the place could still be restored."] = "카빈드라의 간청은 이 던전에 심장을 불어넣었다. 녹시온은 막대를, 군주 바일텅은 다이아몬드를 지니고 있었고, 켈레브라스는 타락에 휩싸인 채 떠돌고 있었다. 수호자를 쓰러뜨리고 구원하자 두 조각은 다시 홀이 될 수 있었다. 그것은 마라우돈을 가로지르는 지름길일 뿐 아니라, 이곳의 일부는 아직 되살릴 수 있다는 징표였다."
L["Legends of Maraudon"] = "마라우돈의 전설"
L["Cavindra"] = "카빈드라"
L["Celebras the Redeemed"] = "회복된 셀레브라스"
L["Corruption of Earth and Seed"] = "대지와 씨앗의 오염"
L["Slay Princess Theradras, learn what became of Zaetar, and carry the Seed of Life to Remulos."] = "공주 테라드라스를 처치하고, 재타르가 어떻게 되었는지 알아낸 뒤, 생명의 씨앗을 레물로스에게 가져가십시오."
L["At the bottom of Maraudon, Princess Theradras guarded both destruction and grief. Zaetar's remains had fed the place into strange life, and his spirit asked for something gentler than vengeance: a seed carried to his brother in Moonglade. The dungeon ended not with a clean victory over the centaur's origin, but with proof that Zaetar had become part of the land."] = "마라우돈의 밑바닥에서 공주 테라드라스는 파멸과 슬픔을 함께 지키고 있었다. 재타르의 유해는 이곳에 기묘한 생명을 불어넣었고, 그의 영혼은 복수보다 온화한 것을 청했다. 달의 숲에 있는 형제에게 씨앗 하나를 전해 달라는 것이었다. 던전의 끝은 켄타우로스의 기원에 대한 깔끔한 승리가 아니라, 재타르가 이 땅의 일부가 되었다는 증거였다."
L["Keeper Marandis"] = "수호자 마란디스"
L["Selendra"] = "셀렌드라"
L["Seed of Life"] = "생명의 씨앗"
L["Zaetar's Spirit"] = "재타르의 영혼"
L["Scarlet Monastery Library, Tirisfal Glades"] = "붉은십자군 수도원 도서관, 티리스팔 숲"
L["Retrieve %s from %s and return to %s in %s."] = "%2$s에서 %1$s 회수 후 %4$s에 있는 %3$s에게 돌아가십시오."
L["the Monastery in Tirisfal Glades"] = "티리스팔 숲의 수도원"
L["Going, Going, Guano!"] = "조분석을 나에게!"
L["Caer Darrow's ruined school is locked behind more than a door. The Scourge has made Scholomance a place of experiments, ghosts, noble inheritance, and old betrayals that refuse to stay buried.\n\nForge the Skeleton Key, then follow the stories waiting inside: Eva Sarkhoff's revenge, Kirtonos, Ras Frostwhisper's lost humanity, and the Barov family's poisoned fortune."] = "카엘 다로우의 폐허가 된 학교를 막고 있는 것은 문 하나만이 아닙니다. 스컬지는 스칼로맨스를 실험과 유령, 귀족의 유산, 그리고 묻히기를 거부하는 오랜 배신의 장소로 만들었습니다.\n\n해골 열쇠를 만든 뒤, 그 안에서 기다리는 이야기들을 따라가십시오. 에바 사크호프의 복수, 키르토노스, 라스 프로스트위스퍼가 잃어버린 인간성, 그리고 바로브 가문의 독이 든 재산이 기다리고 있습니다."
L["Western Plaguelands / Tanaris / Un'Goro Crater / Scholomance"] = "서부 역병지대 / 타나리스 / 운고로 분화구 / 스칼로맨스"
L["the ruins of Andorhal, Western Plaguelands"] = "안돌할 폐허, 서부 역병지대"
L["Doctor Theolen Krastinov's room, Scholomance"] = "의사 테올렌 크라스티노브의 방, 스칼로맨스"
L["the Chamber of Summoning, Scholomance"] = "소환의 방, 스칼로맨스"
L["near the Bulwark, Tirisfal Glades"] = "보루 근처, 티리스팔 숲"
L["The Skeleton Key"] = "해골 열쇠"
L["After proving yourself in the Plaguelands, forge the Skeleton Key that opens Scholomance."] = "역병지대에서 실력을 증명한 뒤, 스칼로맨스의 문을 여는 해골 열쇠를 만드십시오."
L["Scholomance was not simply entered. Arbington or Dithers sent you through bones from Andorhal, a costly goblin mold in Gadgetzan, a forging at Fire Plume Ridge, and Araj's scarab in the ruined city. The finished Skeleton Key turned Caer Darrow's locked academy from a rumor into a place you could finally confront."] = "스칼로맨스는 그냥 들어갈 수 있는 곳이 아니었다. 아빙턴이나 디더스는 안돌할의 뼈, 가젯잔에서 구한 값비싼 고블린 주형, 불기둥 마루에서의 단조, 그리고 폐허 도시에 있는 아라즈의 스카라베를 차례로 구해 오게 했다. 완성된 해골 열쇠 덕분에, 굳게 잠긴 카엘 다로우의 학원은 소문 속의 장소에서 마침내 맞설 수 있는 곳이 되었다."
L["Skeletal Fragments"] = "뼈조각"
L["Alchemist Arbington"] = "연금술사 알빙턴"
L["Apothecary Dithers"] = "연금술사 디더스"
L["Mold Rhymes With..."] = "거푸집과 뼈조각"
L["Fire Plume Forged"] = "불기둥 용광로"
L["Krinkle Goodsteel"] = "크린클 굿스틸"
L["Araj's Scarab"] = "아라즈의 스카라베"
L["The Key to Scholomance"] = "스칼로맨스로 가는 열쇠"
L["The Sarkhoffs"] = "사크호프 가족"
L["Eva Sarkhoff asks you to punish Krastinov, recover his bag, and summon Kirtonos."] = "에바 사크호프는 크라스티노브를 응징하고, 그의 가방을 되찾고, 키르토노스를 소환해 달라고 부탁합니다."
L["Eva Sarkhoff's grief had been waiting outside the school. Doctor Theolen Krastinov had butchered her family, and Jandice Barov guarded the next proof. When the Blood of Innocents called Kirtonos to the balcony, Scholomance answered with one of its own monsters, and Eva's vengeance finally had form."] = "에바 사크호프의 슬픔은 학교 밖에서 기다리고 있었다. 의사 테올렌 크라스티노브가 그녀의 가족을 도륙했고, 잔다이스 바로브가 다음 증거를 지키고 있었다. 무고한 자의 피가 키르토노스를 발코니로 불러내자, 스칼로맨스는 자신이 품은 괴물 하나로 응답했고, 에바의 복수는 마침내 형체를 얻었다."
L["Doctor Theolen Krastinov, the Butcher"] = "도살자, 테올렌 크라스티노브"
L["Eva Sarkhoff"] = "에바 사크호프"
L["Krastinov's Bag of Horrors"] = "소름끼치는 크라스티노브의 가방"
L["Kirtonos the Herald"] = "사자 키르토노스"
L["Ras Frostwhisper"] = "라스 프로스트위스퍼"
L["Learn who Ras Frostwhisper was, restore the memory of his death, and face the lich in Scholomance."] = "라스 프로스트위스퍼가 어떤 사람이었는지 알아내고, 그의 죽음에 관한 기억을 되살린 뒤, 스칼로맨스에서 리치와 맞서십시오."
L["Ras Frostwhisper was not born a lich. Magistrate Marduke and Artist Renfray helped recover the human truth beneath the monster: a keepsake, a memory at Menethil's Gift, and a ritual strong enough to pull Ras back toward mortality. In Scholomance, the keepsake made him vulnerable. Killing him ended a lich and returned a human head to Caer Darrow."] = "라스 프로스트위스퍼는 처음부터 리치로 태어난 것이 아니었다. 집정관 마르듀크와 화가 렌프레이는 괴물 아래에 숨은 인간의 진실을 되찾도록 도왔다. 기념품 하나, 메네실의 선물에 남은 기억, 그리고 라스를 필멸의 존재 쪽으로 끌어당길 만큼 강력한 의식이었다. 스칼로맨스에서 그 기념품은 그를 약하게 만들었다. 그를 처치하자 리치는 최후를 맞았고, 카엘 다로우에는 인간의 머리가 돌아왔다."
L["The Human, Ras Frostwhisper"] = "라스 프로스트위스퍼"
L["Magistrate Marduke"] = "집정관 마르듀크"
L["The Dying, Ras Frostwhisper"] = "망자, 라스 프로스트위스퍼"
L["Menethil's Gift"] = "메네실의 선물"
L["Soulbound Keepsake"] = "영혼이 씌인 유품"
L["The Lich, Ras Frostwhisper"] = "리치, 라스 프로스트위스퍼"
L["Barov Family Fortune"] = "바로브 가의 유산"
L["Recover the Barov deeds from Scholomance, then choose which heir becomes the last Barov."] = "스칼로맨스에서 바로브 가문의 증서를 되찾은 뒤, 어느 상속자를 마지막 바로브로 만들지 선택하십시오."
L["The Barov fortune was scattered through Scholomance in deeds to Brill, Tarren Mill, Southshore, and Caer Darrow. Alexi and Weldon each claimed the inheritance and each wanted the other dead. When the papers were recovered, the family matter became murder by proxy, and one brother's claim ended at the other's feet."] = "바로브 가문의 재산은 브릴, 타렌 밀농장, 사우스쇼어, 카엘 다로우의 증서가 되어 스칼로맨스 곳곳에 흩어져 있었다. 알렉시와 웰던은 저마다 유산을 주장하며 서로가 죽기를 바랐다. 증서를 되찾자 집안 문제는 대리 살인이 되었고, 한 형제의 주장은 다른 형제의 발치에서 끝을 맺었다."
L["Weldon Barov"] = "웰던 바로브"
L["Alexi Barov"] = "알렉시 바로브"
L["The Last Barov"] = "최후의 바로브"
L["Near Ashenvale's northern border, the Howling Vale is full of wolf-men that should not be there. Sentinel Melyria Frostshadow believes the Tome of Mel'Thandris may explain why.\n\nFollow Velinde Starsong's trail from Ashenvale to Darnassus, Ratchet, Booty Bay, and Duskwood. The scythe's story is not tidy, but it is one of Classic's clearest windows into the first mysteries of the worgen."] = "잿빛 골짜기의 북쪽 경계 근처, 울부짖는 골짜기에는 있어서는 안 될 늑대인간들이 들끓고 있습니다. 파수꾼 멜리리아 프로스트섀도는 멜탄드리스의 고서가 그 이유를 밝혀 줄지도 모른다고 생각합니다.\n\n벨린데 스타송의 발자취를 따라 잿빛 골짜기에서 다르나서스, 톱니항, 무법항, 그늘숲까지 가 보십시오. 낫의 이야기는 깔끔하게 정리되지 않지만, 늑대인간에 얽힌 최초의 수수께끼를 가장 선명하게 엿볼 수 있는 클래식의 이야기 중 하나입니다."
L["Ashenvale / Darnassus / The Barrens / Stranglethorn Vale / Duskwood"] = "잿빛 골짜기 / 다르나서스 / 불모의 땅 / 가시덤불 골짜기 / 그늘숲"
L["The Howling Vale"] = "울부짖는 골짜기"
L["Sentinel Melyria Frostshadow"] = "파수꾼 멜리리아 프로스트섀도"
L["Forest Song, Ashenvale"] = "숲의 노래, 잿빛 골짜기"
L["the Howling Vale, Ashenvale"] = "울부짖는 골짜기, 잿빛 골짜기"
L["the Warrior's Terrace, Darnassus"] = "전사의 테라스, 다르나서스"
L["the Sentinels' bunkhouse, Darnassus"] = "파수꾼 숙소, 다르나서스"
L["Ratchet, The Barrens"] = "톱니항, 불모의 땅"
L["Booty Bay, Stranglethorn Vale"] = "무법항, 가시덤불 골짜기"
L["Darkshire Town Hall, Duskwood"] = "어둠골 마을회관, 그늘숲"
L["Roland's Doom, Duskwood"] = "롤랜드 광산, 그늘숲"
L["Study the Tome of Mel'Thandris and learn why worgen have appeared near the Felwood border."] = "멜탄드리스의 고서를 살펴보고, 악령의 숲 경계 근처에 늑대인간이 나타난 이유를 알아내십시오."
L["The Tome of Mel'Thandris did not give a plain report. It showed Velinde Starsong praying for help against demons and receiving the Scythe of Elune in answer. The worgen in the Howling Vale were no local accident. They were tied to a night elf priestess, a weapon, and a call that had gone wrong."] = "멜탄드리스의 고서는 평범한 보고서가 아니었다. 그 안에는 벨린데 스타송이 악마에 맞설 도움을 청하며 기도하고, 그 응답으로 엘룬의 낫을 받는 모습이 담겨 있었다. 울부짖는 골짜기의 늑대인간은 우연히 생겨난 것이 아니었다. 그들은 나이트 엘프 여사제와 무기 하나, 그리고 잘못되어 버린 부름과 얽혀 있었다."
L["Velinde Starsong"] = "벨린데 스타송"
L["Carry Melyria's concern to Darnassus and search Velinde's stored effects."] = "멜리리아의 우려를 다르나서스에 전하고, 보관된 벨린데의 유품을 살펴보십시오."
L["Darnassus remembered Velinde as a trusted priestess, not a villain. Thyn'tel Bladeweaver opened her stored belongings, and the journal inside changed the search from a military report into a missing-person trail. Velinde had used the scythe, lost control of the worgen, and disappeared while seeking help far from Ashenvale."] = "다르나서스는 벨린데를 악당이 아니라 신망받는 여사제로 기억했다. 신텔 블레이드위버가 보관된 그녀의 소지품을 열었고, 그 안의 일지는 수색을 군사 보고에서 실종자 추적으로 바꾸어 놓았다. 벨린데는 낫을 사용했다가 늑대인간을 통제하지 못하게 되었고, 잿빛 골짜기에서 멀리 떨어진 곳으로 도움을 구하러 갔다가 자취를 감추었다."
L["Velinde's Effects"] = "벨린데의 영향"
L["Thyn'tel Bladeweaver"] = "신텔 블레이드위버"
L["Across the Sea"] = "바다 건너"
L["Follow Velinde's travel records from Ratchet to Booty Bay and onto the roads north."] = "벨린데의 여행 기록을 따라 톱니항에서 무법항으로, 그리고 북쪽으로 난 길까지 가십시오."
L["Velinde's journal sent the trail across the world instead of deeper into Ashenvale. Ratchet remembered her passage to Booty Bay, and Booty Bay's caravan records pointed north toward Duskwood. The scythe had crossed continents, leaving only ship ledgers, goblin memory, and a road through dangerous country."] = "벨린데의 일지는 흔적을 잿빛 골짜기 깊숙한 곳이 아니라 세상 건너편으로 이끌었다. 톱니항은 그녀가 무법항으로 가는 배에 올랐던 것을 기억했고, 무법항의 수송대 기록은 북쪽의 그늘숲을 가리켰다. 낫은 대륙을 건넜고, 남은 것은 선박 장부와 고블린의 기억, 그리고 위험한 땅을 가로지르는 길뿐이었다."
L["The Barrens Port"] = "불모의 땅 항구"
L["Passage to Booty Bay"] = "무법항으로의 여정"
L["Wharfmaster Dizzywig"] = "부두주임 디지위그"
L["The Caravan Road"] = "행상길"
L["Caravaneer Ruzzgot"] = "행상 러즈고트"
L["The Carevin Family"] = "카레빈 일가"
L["Ask Darkshire's records and the Carevin family what they know about worgen in Duskwood."] = "다크샤이어의 기록과 카레빈 가문을 통해 그늘숲의 늑대인간에 관해 알려진 것을 알아보십시오."
L["Darkshire had no clean record of Velinde, but it had worgen. Clerk Daltry pointed to Jonathan Carevin, whose family made a business of hunting the forest's monsters. Carevin's suspicion gave way to a practical bargain: if the trail led into Roland's Doom, then any answer found there should be shared with Darkshire."] = "다크샤이어에는 벨린데에 관한 깔끔한 기록이 없었지만, 늑대인간은 있었다. 서기관 달트리는 숲의 괴물 사냥을 가업으로 삼은 조나단 카레빈을 가리켰다. 카레빈의 의심은 현실적인 거래로 바뀌었다. 흔적이 롤랜드 광산으로 이어진다면, 그곳에서 찾은 답은 다크샤이어와 나누어야 한다는 것이었다."
L["Jonathan Carevin"] = "조나단 카레빈"
L["Answered Questions"] = "해결된 의문"
L["Return to Darnassus with what the Duskwood cave revealed about Velinde and the scythe."] = "그늘숲 동굴에서 밝혀진 벨린데와 낫에 관한 사실을 가지고 다르나서스로 돌아가십시오."
L["Roland's Doom gave no triumphant recovery, only signs of what the scythe had unleashed and where Velinde's trail had broken. Thyn'tel accepted the report with gratitude and unease. The worgen could be contained for now, but the Scythe of Elune remained out of night elf hands, waiting for another chapter."] = "롤랜드 광산에서 낫을 의기양양하게 되찾는 일은 없었다. 낫이 무엇을 풀어놓았는지, 벨린데의 흔적이 어디서 끊겼는지를 보여 주는 징후만 있었을 뿐이다. 신텔은 감사와 불안이 뒤섞인 채 보고를 받아들였다. 당분간은 늑대인간을 막아 낼 수 있었지만, 엘룬의 낫은 여전히 나이트 엘프의 손을 벗어난 채 다음 이야기를 기다리고 있었다."
L["Travel to Darkshore and speak with Zidormi outside Lor'danel to view the time before the burning of Teldrassil."] = "어둠해안으로 가서 로르다넬 외곽의 지도르미와 대화하면 텔드랏실이 불타기 전의 시간대를 볼 수 있습니다."
L["Play or replay this scenario from Archivist Sylvia in Orgrimmar's Valley of Wisdom. If you still have the original quest, begin with High Overlord Saurfang in Grommash Hold."] = "오그리마 지혜의 골짜기에 있는 기록관 실비아에게서 이 시나리오를 진행하거나 다시 진행할 수 있습니다. 원래 퀘스트를 아직 가지고 있다면 그롬마쉬 요새의 대군주 사울팽에게서 시작하십시오."
L["Complete Stay of Execution, then follow the path you chose: loyalists continue with Nathanos Blightcaller in Grommash Hold, while rebels continue with Lor'themar Theron at the Dranosh'ar Blockade outside Orgrimmar."] = "'집행 유예' 퀘스트를 완료한 뒤, 선택한 길을 따르십시오. 충성파는 그롬마쉬 요새의 나타노스 블라이트콜러에게서, 반란군은 오그리마 외곽 드라노쉬아르 봉쇄선의 로르테마르 테론에게서 이야기가 이어집니다."
L["Speak with Highlord Bolvar Fordragon in the Ring of Fates, Oribos, and follow the Torghast campaign until the Anduin and Kingsmourne vision. If Bolvar no longer offers the chain, the game has already moved this character past it."] = "대영주 볼바르 폴드라곤(운명의 고리, 오리보스)과 대화한 뒤, 안두인과 킹스모른의 환영이 나올 때까지 토르가스트 캠페인을 진행하십시오. 볼바르가 더 이상 이 연계 퀘스트를 제공하지 않는다면, 이 캐릭터는 이미 해당 단계를 지난 것입니다."
L["Secrets of Uldaman"] = "울다만의 비밀"
L["The Badlands dig site is more than a ruin full of troggs and Dark Iron dwarves. Uldaman holds titan records, old dwarven fears, and relics that both factions are willing to chase through the dust.\n\nFollow Hammertoe's warning, the Shattered Necklace, and the Platinum Discs to uncover what the Titans left beneath the stone."] = "황야의 땅의 발굴 현장은 트로그와 검은무쇠 드워프가 들끓는 폐허 그 이상입니다. 울다만에는 티탄의 기록과 드워프들의 오랜 두려움, 그리고 두 진영 모두 먼지를 뒤집어쓰면서까지 쫓는 유물이 잠들어 있습니다.\n\n해머토의 경고와 부서진 목걸이, 백금 원반을 따라가 티탄이 바위 아래에 남긴 것을 밝혀내십시오."
L["Badlands / Ironforge / Orgrimmar / Thunder Bluff / Uldaman"] = "황야의 땅 / 아이언포지 / 오그리마 / 썬더 블러프 / 울다만"
L["A Sign of Hope"] = "희망의 전조"
L["Crumpled Map"] = "구겨진 지도"
L["Hammertoe's Digsite, Badlands"] = "해머토의 발굴현장, 황야의 땅"
L["the outer Uldaman caves, Badlands"] = "울다만 바깥 동굴, 황야의 땅"
L["Angor Fortress, Badlands"] = "고통의 요새, 황야의 땅"
L["Galgann Firehammer's chamber, Uldaman"] = "갈간 파이어해머의 방, 울다만"
L["the Mystic Ward, Ironforge"] = "마법 지구, 아이언포지"
L["Droffers and Son Salvage, Orgrimmar"] = "드로퍼 부자 고물상, 오그리마"
L["near Revelosh's chamber, Uldaman"] = "레벨로쉬의 방 근처, 울다만"
L["the treasure chamber beyond Archaedas, Uldaman"] = "아카에다스 너머의 보물 방, 울다만"
L["the Vault, Ironforge"] = "금고, 아이언포지"
L["Hammertoe's Warning"] = "해머토의 경고"
L["Find Hammertoe Grez, stop the Shadowforge search, and recover the titan-inscribed Tablet of Will."] = "해머토 그레즈를 찾고, 그림자용광로 일족의 수색을 저지한 뒤, 티탄의 글이 새겨진 의지의 석판을 되찾으십시오."
L["A crumpled map turned a dig-site rumor into a rescue. Hammertoe Grez had been taken into Uldaman because he knew too much about titan relics and Dark Iron plans. His amulet reached Ironforge, Belgrum sent you against Ambassador Infernus, and the Tablet of Will was recovered before the Shadowforge could turn titan knowledge into stronger golems."] = "구겨진 지도 한 장이 발굴 현장의 소문을 구출 작전으로 바꾸었다. 해머토 그레즈는 티탄의 유물과 검은무쇠 드워프의 계획에 대해 너무 많이 알았기에 울다만으로 끌려갔다. 그의 목걸이가 아이언포지에 닿자 벨그럼은 사절 인페르누스를 처치하라고 보냈고, 그림자용광로 일족이 티탄의 지식으로 더 강력한 골렘을 만들기 전에 의지의 석판을 되찾았다."
L["Prospector Ryedol"] = "발굴조사단장 라이돌"
L["Amulet of Secrets"] = "비밀의 아뮬렛"
L["Hammertoe Grez"] = "해머토 그레즈"
L["Prospect of Faith"] = "돈독한 믿음"
L["Passing Word of a Threat"] = "위협의 경고"
L["Historian Karnik"] = "역사학자 카르닉"
L["An Ambassador of Evil"] = "악의 사자"
L["The Lost Tablets of Will"] = "잃어버린 결의의 서판"
L["The Shattered Necklace"] = "부서진 목걸이"
L["Trace the broken necklace through Uldaman's gems, journals, and power source."] = "울다만의 보석과 일지, 동력원을 통해 부서진 목걸이의 행방을 추적하십시오."
L["The shattered necklace made Uldaman personal in two different ways. Alliance characters traced Talvash's old work and restored the piece through gems and Archaedas' power source. Horde characters followed Droffers and Son Salvage into a bargain with Jarkal Mossmeld. Either way, the dungeon became a puzzle of ruby, sapphire, topaz, and a construct's heart."] = "부서진 목걸이는 서로 다른 두 방식으로 울다만을 개인적인 이야기로 만들었다. 얼라이언스는 탈바쉬의 옛 작업을 추적해, 보석과 아카에다스의 동력원으로 목걸이를 복원했다. 호드는 드로퍼 부자 고물상을 따라가 자칼 모스멜드와 거래를 맺었다. 어느 쪽이든 던전은 루비와 사파이어, 황옥, 그리고 피조물의 심장으로 이루어진 수수께끼가 되었다."
L["Shattered Necklace"] = "부서진 목걸이"
L["Lore for a Price"] = "정보의 대가"
L["Talvash del Kissel"] = "탈바쉬 델 키젤"
L["Back to Uldaman"] = "울다만으로 돌아가기"
L["Find the Gems"] = "보석 찾기"
L["Restoring the Necklace"] = "목걸이 복원"
L["Necklace Recovery"] = "목걸이 회수"
L["Dran Droffers"] = "드란 드로퍼스"
L["Necklace Recovery, Take 2"] = "목걸이 회수 - 2차 시도"
L["Translating the Journal"] = "일지 번역"
L["Remains of a Paladin"] = "성기사의 유해"
L["Jarkal Mossmeld"] = "자칼 모스멜드"
L["Find the Gems and Power Source"] = "보석과 마력원천 찾기"
L["Deliver the Gems"] = "보석 전달"
L["Necklace Recovery, Take 3"] = "목걸이 회수 - 3차 시도"
L["The Platinum Discs"] = "백금 원반"
L["Defeat Archaedas, consult the stone watcher, and carry the miniature discs to your faction's scholar."] = "아카에다스를 쓰러뜨리고, 바위 감시자에게 조언을 구한 뒤, 축소판 원반을 소속 진영의 학자에게 가져가십시오."
L["Behind Archaedas, the Discs of Norgannon spoke with the calm weight of titan memory. They named the Creators, the Earthen, and the deep history beneath dwarven stone. The portable discs went from Uldaman to Ironforge or Thunder Bluff, where scholars understood that the find was not only treasure. It was origin."] = "아카에다스 너머에서 노르간논의 원반은 티탄의 기억이 지닌 차분한 무게로 말을 건넸다. 원반은 창조주와 토석인, 그리고 드워프의 바위 아래 잠든 깊은 역사를 일러 주었다. 휴대용 원반은 울다만에서 아이언포지나 썬더 블러프로 옮겨졌고, 그곳의 학자들은 이 발견이 단순한 보물이 아님을 깨달았다. 그것은 기원이었다."
L["Discs of Norgannon"] = "노르간논의 원반"
L["High Explorer Magellas"] = "선임탐험가 마겔라스"
L["Mourning Rise"] = "애도의 오름길"
L["The Stonevault"] = "바위금고"
L["Korgran has cared for Mourning Rise longer than his failing memory can reliably hold. The memorial grounds still need tending, kobolds have begun looting the dead, and Urtago is trying to help him hand over a duty he is not ready to lose.\n\nFollow Korgran through the last traditions of his post: honoring the fallen, forging a lantern, and choosing how an earthen says farewell."] = "코그란은 흐려져 가는 기억으로는 다 담아 둘 수 없을 만큼 오랫동안 애도의 오름길을 돌보아 왔습니다. 추모지는 여전히 손길이 필요하고, 코볼트들은 망자의 물건을 약탈하기 시작했으며, 우르타고는 그가 아직 놓아 버릴 준비가 되지 않은 임무를 넘겨줄 수 있도록 돕고 있습니다.\n\n쓰러진 이들을 기리고, 등불을 벼리고, 토석인이 작별을 고하는 방식을 선택하는 일까지, 코그란이 맡은 직무의 마지막 전통을 함께하십시오."
L["Isle of Dorn"] = "도른의 섬"
L["Before I Depart"] = "내가 떠나기 전에"
L["Korgran"] = "코그란"
L["Mourning Rise, Isle of Dorn"] = "애도의 오름길, 도른의 섬"
L["Optional breadcrumb: To Mourning Rise may point you here first. The story itself begins with Korgran at Mourning Rise."] = "선택적 안내 퀘스트: '애도의 오름길로' 퀘스트가 먼저 이곳으로 안내할 수 있습니다. 이야기 자체는 애도의 오름길의 코그란에게서 시작됩니다."
L["Korgran knows his mind is fading, but the Rise still needs a caretaker. Help him and Urtago drive out the kobolds, honor the fallen, and prepare the lantern that will carry his final choice."] = "코그란은 자신의 정신이 흐려져 가고 있음을 알지만, 오름길에는 여전히 관리인이 필요합니다. 코그란, 우르타고와 함께 코볼트를 몰아내고, 쓰러진 이들을 기리고, 그의 마지막 선택을 담을 등불을 준비하십시오."
L["Korgran still called himself caretaker of Mourning Rise, even as Urtago quietly did more and more of the work. Together you cleared kobolds from the memorial, recovered what they had stolen, and saw how often Korgran lost the thread of the present. The duties that defined him were slipping away.\n\nWhen the time came, Korgran chose one more tradition. He forged a lantern, searched for a lost earthen, cleaned ashes from the memorial, and walked toward the coast with Urtago beside him. His farewell was not treated as defeat. It was a final act of care, made in the place he had guarded for so long."] = "우르타고가 조용히 점점 더 많은 일을 떠맡는 동안에도, 코그란은 여전히 자신을 애도의 오름길의 관리인이라 불렀다. 함께 추모지에서 코볼트를 몰아내고 빼앗긴 물건을 되찾는 사이, 코그란이 얼마나 자주 현재의 실마리를 놓치는지 알 수 있었다. 그를 그답게 만들던 임무들이 손가락 사이로 빠져나가고 있었다.\n\n때가 오자 코그란은 전통 하나를 더 택했다. 그는 등불을 벼리고, 길 잃은 토석인을 찾고, 추모지의 재를 닦아 낸 뒤, 우르타고와 나란히 해안을 향해 걸어갔다. 그의 작별은 패배로 여겨지지 않았다. 그것은 그토록 오래 지켜 온 곳에서 행한 마지막 돌봄이었다."
L["Honor Their Memories"] = "추억을 기리며"
L["Urtago"] = "우르타고"
L["You No Take Plunder!"] = "너 약탈물 못 가져간다!"
L["Laws Apply to All"] = "법은 만인에게 평등하다"
L["The Great Collapse"] = "대붕괴"
L["Cutting the Wick"] = "심지 자르기"
L["Who Runs This Fine Establishment?"] = "주인장 나오라 그래"
L["One More Tradition"] = "또 하나의 전통"
L["The Forging of Memories"] = "기억을 벼리다"
L["The Last Journey"] = "마지막 여정"
L["The Lost Earthen"] = "잊힌 토석인"
L["A Change of Tradition"] = "전통의 변화"
L["Tools of Declaration"] = "선언 도구"
L["Cleansing Ashes"] = "정화의 재"
L["As He Departs"] = "떠나는 길에"
L["The Weight of Duty"] = "책무의 무게"
L["Stay a While"] = "잠깐 내 이야기를 들어보겠나"
L["Ruby Life Pools"] = "루비 생명의 웅덩이"
L["At the Ruby Lifeshrine, Veritistrasz asks for something rare in an adventurer's life: time. No army waits, no world-ending machine is counting down, and no one needs a hundred trophies from the local wildlife.\n\nSit with an old red dragon in dwarf form, listen to what he remembers, and help him face the name he has spent ages trying not to say."] = "루비 생명의 제단에서 베리티스트라즈는 모험가의 삶에서 좀처럼 얻기 힘든 것을 청합니다. 바로 시간입니다. 기다리는 군대도, 세상의 종말을 향해 초읽기를 하는 기계도 없고, 주변 야생 동물의 전리품 백 개를 원하는 사람도 없습니다.\n\n드워프의 모습을 한 늙은 붉은용 곁에 앉아 그가 기억하는 이야기에 귀 기울이고, 그가 오랜 세월 입에 올리지 않으려 애써 온 이름과 마주하도록 도우십시오."
L["The Waking Shores"] = "깨어나는 해안"
L["Veritistrasz"] = "베리티스트라즈"
L["Ruby Lifeshrine, The Waking Shores"] = "루비 생명의 제단, 깨어나는 해안"
L["Obsidian Citadel, The Waking Shores"] = "흑요석 성채, 깨어나는 해안"
L["Veritistrasz only asks you to sit, listen, and look out over the Waking Shores. What begins as memory becomes grief, and a hidden diary gives him one last truth to carry."] = "베리티스트라즈의 부탁은 그저 함께 앉아 이야기를 들으며 깨어나는 해안을 바라봐 달라는 것뿐입니다. 추억으로 시작된 이야기는 슬픔이 되고, 숨겨진 일기는 그에게 간직할 마지막 진실 하나를 건넵니다."
L["Veritistrasz sat at the Ruby Lifeshrine and asked you to stay. His stories moved gently at first: old homes, old meals, the strange way places change when you are gone too long. Then the memories turned toward the black dragonflight, toward the friend he loved, and toward the betrayal that broke both his family and his certainty.\n\nLater, a damaged diary from the Obsidian Citadel brought the name he could not reach: Distyia. It did not undo what happened, but it gave his grief shape. Veritistrasz remembered the person beneath the corruption, and for a moment the old wound was not quite so alone."] = "베리티스트라즈는 루비 생명의 제단에 앉아 곁에 머물러 달라고 청했다. 그의 이야기는 처음에는 잔잔하게 흘렀다. 옛집과 옛 식사, 그리고 너무 오래 떠나 있으면 장소가 낯설게 변해 버리는 기묘함에 관한 이야기였다. 그러다 기억은 검은용군단으로, 그가 사랑했던 친구에게로, 그리고 그의 가족과 확신을 모두 무너뜨린 배신으로 향했다.\n\n훗날 흑요석 성채에서 나온 훼손된 일기가 그가 떠올리지 못하던 이름을 가져왔다. 디스티아였다. 그 이름이 지난 일을 되돌리지는 못했지만, 그의 슬픔에 형체를 주었다. 베리티스트라즈는 타락 아래에 있던 그 사람을 기억해 냈고, 잠시나마 오래된 상처는 그리 외롭지 않았다."
L["Memories"] = "추억"
L["Memories Revived"] = "되살아난 기억"
L["Partially Destroyed Diary"] = "일부 훼손된 일기"
L["Runas the Shamed"] = "수치스러운 루나스"
L["Azurewing Repose is under pressure from withered nightborne, hungry leyline abuse, and a prince who sees dragons as a resource to drain. In the middle of it all is Runas, a withered exile who still has just enough wit, shame, and courage left to choose who he wants to be.\n\nBegin with Stellagosa's search for the missing whelpling and follow Runas through one last useful, heartbreaking day."] = "하늘빛나래 안식처는 몰락자가 된 나이트본과 탐욕스러운 지맥 남용, 그리고 용을 고갈시킬 자원으로만 여기는 왕자에게 압박받고 있습니다. 그 한가운데에 루나스가 있습니다. 몰락자가 되어 추방당했지만, 자신이 어떤 존재가 될지 선택할 만큼의 재치와 수치심, 용기가 아직 남아 있는 자입니다.\n\n사라진 새끼용을 찾는 스텔라고사의 부탁에서 시작해, 쓸모 있으면서도 가슴 아픈 루나스의 마지막 하루를 함께하십시오."
L["Azsuna"] = "아즈스나"
L["Eye of Azshara"] = "아즈샤라의 눈"
L["Azurewing Repose, Azsuna"] = "하늘빛나래 안식처, 아즈스나"
L["Stellagosa sends you after a missing whelpling and you meet Runas, a withered exile who knows the Repose's enemies better than anyone wants to admit."] = "스텔라고사의 부탁으로 사라진 새끼용을 찾아 나섰다가, 안식처의 적들을 누구도 인정하고 싶지 않을 만큼 잘 아는 몰락자 추방자 루나스를 만납니다."
L["Stellagosa's missing whelpling led you to Runas the Shamed, a withered nightborne with a sharp tongue and a hunger he could barely hold back. He had been cast out, diminished, and written off, but he still understood the leylines, the withered, and the danger gathering around Azurewing Repose.\n\nRunas helped you recover the whelpling and find Stellagosa, even as his own cravings returned. He was not safe. He knew it. Still, he kept choosing to help."] = "스텔라고사의 사라진 새끼용을 찾다가 수치스러운 루나스를 만났다. 독설가인 그는 간신히 억누르고 있는 굶주림을 품은 몰락자 나이트본이었다. 그는 쫓겨나고 쇠약해졌으며 버림받았지만, 여전히 지맥과 몰락자, 그리고 하늘빛나래 안식처 주변에 모여드는 위험을 이해하고 있었다.\n\n루나스는 자신의 갈망이 되살아나는 와중에도 새끼용을 되찾고 스텔라고사를 찾도록 도왔다. 그는 안전한 존재가 아니었다. 그도 그 사실을 알았다. 그럼에도 그는 계속 돕는 쪽을 택했다."
L["The Consumed"] = "새끼용 구출"
L["Mana-Drained Whelpling"] = "마나가 고갈된 새끼용"
L["Projection of Senegos"] = "세네고스의 투영체"
L["Runas Knows the Way"] = "루나스는 알아요"
L["The Hunger Returns"] = "굶주림이 돌아오다"
L["Leyline Abuse"] = "지맥 착취"
L["The Nightborne Prince"] = "나이트본 왕자"
L["Runas guides you into the prince's territory, bargains with his own hunger, and helps expose what the nightborne are doing to the dragons."] = "루나스는 왕자의 영역으로 길을 안내하고, 자신의 굶주림과 타협하며, 나이트본이 용들에게 저지르는 짓을 폭로하도록 돕습니다."
L["Runas knew the prince's camp from the inside: the habits, the arrogance, and the weak points. With his guidance, you sabotaged the nightborne, stole what you needed, and found Stellagosa alive but endangered. Runas kept laughing, kept deflecting, and kept moving because stopping would mean feeling the pull of the hunger too clearly.\n\nBy the time you returned to Azurewing Repose, Runas had given the dragons what they needed most: a path to strike back before the prince could feast on them."] = "루나스는 왕자의 야영지를 속속들이 알고 있었다. 그들의 습관과 오만함, 그리고 약점까지. 그의 안내를 받아 나이트본의 계획을 방해하고 필요한 것을 훔쳐 냈으며, 살아 있지만 위험에 처한 스텔라고사를 찾아냈다. 루나스는 계속 웃고, 계속 말을 돌리며, 계속 움직였다. 멈추는 순간 굶주림이 끌어당기는 힘을 너무 선명하게 느끼게 될 것이기 때문이었다.\n\n하늘빛나래 안식처로 돌아왔을 무렵, 루나스는 용들에게 가장 필요한 것을 건넨 뒤였다. 왕자가 그들을 집어삼키기 전에 반격할 길이었다."
L["You Scratch My Back..."] = "상부상조"
L["Still Alive"] = "다시 찾은 힘"
L["Hunger's End"] = "굶주림의 끝"
L["Khadgar and Stellagosa rally the defense. Runas spends his last strength making sure his final hours matter."] = "카드가와 스텔라고사가 방어 태세를 갖춥니다. 루나스는 남은 힘을 모두 쏟아 자신의 마지막 시간이 의미 있도록 합니다."
L["The nightborne assault reached Azurewing Repose. Khadgar, Stellagosa, and the blue dragons fought to protect Senegos while the withered closed in. Runas was almost out of time. He knew what was coming, and he chose to spend his last clear moments helping instead of hiding.\n\nAt the end, he thanked you for letting his final hours mean something. Then the hunger took him. The victory at Azurewing Repose came with a quiet loss, and Runas the Shamed earned a better name than the one he had carried."] = "나이트본의 공격이 하늘빛나래 안식처에 이르렀다. 몰락자들이 조여 오는 가운데 카드가와 스텔라고사, 푸른용들은 세네고스를 지키기 위해 싸웠다. 루나스에게는 남은 시간이 거의 없었다. 그는 무엇이 다가오는지 알았고, 정신이 맑은 마지막 순간들을 숨는 대신 돕는 데 쓰기로 했다.\n\n마지막에 그는 자신의 마지막 시간이 의미를 갖게 해 주어 고맙다고 말했다. 그리고 굶주림이 그를 삼켰다. 하늘빛나래 안식처의 승리에는 조용한 상실이 뒤따랐고, 수치스러운 루나스는 지금까지 짊어져 온 이름보다 더 나은 이름을 얻었다."
L["Feasting on the Dragon"] = "용 잡아먹기"
L["On the Brink"] = "위기의 순간"
L["Cursed to Wither"] = "메마름의 저주"
L["Rhea's Last Egg"] = "레아의 마지막 알"
L["Blackrock Caverns"] = "검은바위 동굴"
L["In the Badlands, a red dragon hides behind a simple name and a very dangerous plan. Rhea wants to save the future of the black dragonflight from Deathwing's madness, and she needs samples, secrecy, and one gnome scientist who is just strange enough to help.\n\nFollow Rhea's work from Lethlor Ravine to the Hidden Clutch, then stay for the Badlands locals arguing over what really happened when Deathwing came."] = "황야의 땅에서 한 붉은용이 평범한 이름과 몹시 위험한 계획 뒤에 몸을 숨기고 있습니다. 레아는 데스윙의 광기로부터 검은용군단의 미래를 구하고자 하며, 그러려면 표본과 비밀 유지, 그리고 도움이 될 만큼 적당히 괴짜인 노움 과학자 한 명이 필요합니다.\n\n레슬로 협곡에서 숨겨진 둥지까지 레아의 작업을 따라간 뒤, 데스윙이 왔을 때 정말로 무슨 일이 있었는지를 두고 티격태격하는 황야의 땅 주민들의 이야기도 들어 보십시오."
L["Badlands"] = "황야의 땅"
L["Cataclysm"] = "대격변"
L["First Sample: Wild Eggs"] = "첫 번째 표본: 야생 검은용 알"
L["Rhea"] = "레아"
L["Lethlor Ravine, Badlands"] = "레슬로 협곡, 황야의 땅"
L["Easily Swayed"] = "풍전등화"
L["Dolph Blastus"] = "돌프 브라스투스"
L["A Strange Request"] = "이상한 부탁"
L["Fuselight, Badlands"] = "점화등 마을, 황야의 땅"
L["Agmond's End, Badlands"] = "아그몬드의 최후, 황야의 땅"
L["Dustwind Dig, Badlands"] = "먼지바람 발굴지, 황야의 땅"
L["Bloodwatcher Point, Badlands"] = "피감시자 거점, 황야의 땅"
L["Scar of the Worldbreaker, Badlands"] = "세계파괴자의 흉터, 황야의 땅"
L["The Maker's Terrace, Badlands"] = "창조주의 정원, 황야의 땅"
L["New Kargath, Badlands"] = "신 카르가스, 황야의 땅"
L["Rhea's Work"] = "레아의 작업"
L["If Rhea does not offer these quests yet, complete the Fuselight intro through A Strange Request first."] = "레아가 아직 이 퀘스트들을 주지 않는다면, 먼저 점화등 마을의 도입 퀘스트를 '이상한 부탁'까지 완료하십시오."
L["Rhea asks for black dragon samples and slowly reveals why she is risking everything in the Badlands."] = "레아는 검은용의 표본을 부탁하며, 자신이 왜 황야의 땅에서 모든 것을 걸고 있는지 조금씩 밝힙니다."
L["Rhea's errands looked like field work at first: wild eggs, whelps, implanted eggs, and a strange fog that hid more than geography. Then she revealed the truth. She was Rheastrasza, a red dragon trying to rescue the future of the black dragonflight before Deathwing's corruption consumed it forever.\n\nThe samples were not trophies. They were the last chance to create an uncorrupted black dragon egg."] = "레아의 심부름은 처음에는 현장 조사처럼 보였다. 야생의 알과 새끼용, 무언가가 심어진 알, 그리고 지형 이상의 것을 감춘 기묘한 안개까지. 그러다 그녀는 진실을 밝혔다. 그녀는 붉은용 레아스트라자였고, 데스윙의 타락이 검은용군단의 미래를 영원히 집어삼키기 전에 그것을 구하려 하고 있었다.\n\n표본은 전리품이 아니었다. 타락하지 않은 검은용의 알을 만들어 낼 마지막 기회였다."
L["Second Sample: Whelps"] = "두 번째 표본: 새끼비룡"
L["Lifting the Veil"] = "베일을 벗는 용군단"
L["Third Sample: Implanted Eggs"] = "세 번째 표본: 닉손드라의 알"
L["Rhea Revealed"] = "레아의 정체"
L["The Venerable Doctor Blam"] = "존경스러운 블램 박사"
L["The Hidden Clutch"] = "숨겨진 손아귀"
L["Dr. Blam takes over the science. Alliance and Horde routes split through rival dig sites before converging on the clutch Rhea is trying to protect."] = "박사 블램이 과학 연구를 넘겨받습니다. 얼라이언스와 호드의 여정은 서로 경쟁하는 발굴지로 갈라졌다가, 레아가 지키려는 둥지에서 다시 합쳐집니다."
L["Dr. Hieronymus Blam was exactly the kind of scientist Rhea needed: brilliant, excitable, and only partly reassuring. His work sent you through trogg trouble, dusty titan ruins, and faction rivalries at Dustwind Dig or Bloodwatcher Point. Stone watchers, ancient games, and old machinery all became part of the same desperate experiment.\n\nEverything pointed back to one thing: a hidden clutch that Deathwing could not be allowed to find."] = "박사 히에로니무스 블램은 레아에게 꼭 필요한 과학자였다. 명석하고, 쉽게 흥분하며, 믿음직함은 절반쯤에 그쳤다. 그의 연구를 따라 트로그 소동과 먼지 쌓인 티탄 유적, 그리고 먼지바람 발굴지나 피감시자 거점에서 벌어지는 진영 간의 경쟁을 헤쳐 나갔다. 바위 감시자와 고대의 놀이, 낡은 기계 장치가 모두 같은 절박한 실험의 일부가 되었다.\n\n모든 것은 한 가지로 이어졌다. 데스윙이 결코 찾아내서는 안 될 숨겨진 둥지였다."
L["Troggish Troubles"] = "트로그 문제"
L["Dr. Hieronymus Blam"] = "박사 히에로니무스 블램"
L["Dustwind Dig"] = "먼지바람 발굴지"
L["Bloodwatcher Point"] = "피감시자 거점"
L["All's Fair in Love, War, and Archaeology"] = "사랑과 전쟁과 고고학에는 수단과 방법을 가리지 말라"
L["Lead Prospector Durdin"] = "선임 발굴조사단장 더딘"
L["It's Not About History, It's About Power"] = "역사가 아닌 힘에 대한 문제"
L["High Examiner Tae'thelan Bloodwatcher"] = "고위 검사관 태더란 블러드워처"
L["The Warden's Pawn"] = "감독관의 졸"
L["The Sentinel's Pawn"] = "파수꾼의 졸"
L["The Warden's Game"] = "감독관의 게임"
L["Stone Slab"] = "돌판"
L["The Sentinel's Game"] = "파수꾼의 게임"
L["Marble Slab"] = "대리석판"
L["Ancient Protectors"] = "고대 수호자"
L["The Titans' Trove"] = "티탄의 귀중품"
L["Return to Blam"] = "블램에게 돌아가기"
L["Trove of the Watchers"] = "감시자의 보고"
L["Into the Dragon's Mouth"] = "용의 입으로"
L["New Kargath"] = "신 카르가스"
L["Rheastrasza's Gift"] = "레아스트라자의 선물"
L["Rhea gathers unlikely guards for the clutch, but Deathwing's shadow falls over the plan before the egg can be safe."] = "레아는 뜻밖의 수호자들을 모아 둥지를 지키려 하지만, 알이 안전해지기도 전에 데스윙의 그림자가 계획을 덮칩니다."
L["Rhea's defense force was improvised in true Badlands fashion. Alliance adventurers recruited Eric, Baelog, and Olaf. Horde adventurers recruited Amakkar, Jurrix, and Gargal. The work was strange, dangerous, and somehow hopeful.\n\nThen Deathwing came. The clutch was exposed, Rhea's plan became a sacrifice, and the last egg had to survive without the dragon who had made it possible."] = "레아의 방어대는 그야말로 황야의 땅다운 방식으로 급조되었다. 얼라이언스 모험가들은 에릭, 밸로그, 올라프를, 호드 모험가들은 아마카르, 주릭스, 가르갈을 끌어들였다. 일은 기묘하고 위험했지만, 어쩐지 희망적이었다.\n\n그때 데스윙이 나타났다. 둥지는 드러났고, 레아의 계획은 희생이 되었으며, 마지막 알은 자신을 있게 한 용 없이 살아남아야 했다."
L["The Swift, the Fierce, and the Stout"] = "날쌘돌이, 험악꾼, 뚱뚱보"
L["Eric, the Utility Dwarf"] = "만능 드워프 에릭"
L["Eric \"The Swift\""] = "\"날쌘돌이\" 에릭"
L["Baelog, the Glass Cannon"] = "유리대포 밸로그"
L["Baelog"] = "밸로그"
L["Olaf, the Big Fella'"] = "거구 올라프"
L["Olaf"] = "올라프"
L["The Wrath of a Dragonflight"] = "용군단의 분노"
L["Their Hunt Continues"] = "끈질긴 추적"
L["The Sorrow and the Fury"] = "슬픔과 분노"
L["The Bad Dogs"] = "나쁜 녀석들"
L["Amakkar, Jack of All Trades"] = "팔방미인 아마카르"
L["Amakkar"] = "아마카르"
L["Jurrix the Striker"] = "공격대장 주릭스"
L["Jurrix Whitemane"] = "주릭스 화이트메인"
L["Gargal, the Behemoth"] = "거인 가르갈"
L["Gargal"] = "가르갈"
L["The Egg Lives On"] = "알은 영원하다"
L["Dr. Blam reveals Rhea's final deception and the secret she preserved: one uncorrupted black dragon egg."] = "박사 블램은 레아의 마지막 속임수와 그녀가 지켜 낸 비밀을 밝힙니다. 바로 타락하지 않은 검은용의 알 하나입니다."
L["Deathwing believed he had destroyed Rhea's work. Dr. Blam revealed the truth: Rhea had hidden the real egg and left a false trail behind. Her last act was not only sacrifice, but misdirection.\n\nThe egg lived. Somewhere beyond Deathwing's reach, the future black dragon Wrathion had a chance to exist."] = "데스윙은 레아의 작업을 파괴했다고 믿었다. 박사 블램이 진실을 밝혔다. 레아는 진짜 알을 숨기고 거짓 흔적을 남겨 두었던 것이다. 그녀의 마지막 행동은 희생인 동시에 교묘한 눈속임이었다.\n\n알은 살아남았다. 데스윙의 손이 닿지 않는 어딘가에서, 훗날의 검은용 래시온이 태어날 기회를 얻었다."
L["Devastation"] = "유린"
L["The Day that Deathwing Came"] = "데스윙이 온 날"
L["Theldurin, Lucien, and Martek each explain how they personally survived Deathwing. The stories get less reliable and much funnier as they go."] = "텔두린과 루시앙, 마르텍이 저마다 데스윙에게서 어떻게 살아남았는지 이야기합니다. 이야기는 갈수록 믿기 어려워지고, 훨씬 더 웃겨집니다."
L["After the tragedy of Rhea's story, the Badlands gave you its strangest form of grief relief: three locals trying to outdo each other with increasingly impossible versions of the day Deathwing came. Theldurin punched the Destroyer. Lucien improved the story. Martek improved it even more.\n\nNone of it was reliable history. All of it was Badlands truth: when the world breaks, sometimes people survive by turning terror into a story they can laugh at."] = "레아의 비극적인 이야기가 끝난 뒤, 황야의 땅은 가장 기묘한 방식으로 슬픔을 달래 주었다. 데스윙이 왔던 날을 두고, 주민 세 명이 점점 더 말도 안 되는 이야기로 서로를 이기려 든 것이다. 텔두린은 파괴자에게 주먹을 날렸다. 루시앙은 거기에 살을 붙였다. 마르텍은 거기서 한술 더 떴다.\n\n어느 것도 믿을 만한 역사는 아니었다. 하지만 모두 황야의 땅다운 진실이었다. 세상이 부서질 때, 사람들은 때로 공포를 웃어넘길 수 있는 이야기로 바꾸며 살아남는다."
L["Theldurin the Lost"] = "실성한 텔두린"
L["The Day that Deathwing Came: The Real Story"] = "데스윙이 온 날: 진짜 이야기"
L["Lucien Tosselwrench"] = "루시앙 토슬렌치"
L["The Day that Deathwing Came: What Really Happened"] = "데스윙이 온 날: 진짜 있었던 일"
L["Martek the Exiled"] = "망명자 마르텍"
L["A Blue Dawn"] = "푸른 여명"
L["The Azure Vault"] = "하늘빛 보관소"
L["The blue dragonflight survived Malygos, the Nexus War, and years of grief by scattering across Azeroth. Kalecgos can lead an Aspect's flight again, but only if the blues choose to become a family instead of a memory.\n\nAnswer Kalecgos's call, search for the lost blue dragons, and help each branch decide whether there is still a home worth returning to."] = "푸른용군단은 아제로스 곳곳으로 흩어짐으로써 말리고스와 마력의 탑 전쟁, 그리고 오랜 슬픔의 세월을 견뎌 냈습니다. 칼렉고스는 다시 위상으로서 용군단을 이끌 수 있지만, 그러려면 푸른용들이 기억이 아닌 가족이 되기를 스스로 선택해야 합니다.\n\n칼렉고스의 부름에 응해 흩어진 푸른용들을 찾고, 각 갈래가 아직 돌아갈 가치가 있는 집이 남아 있는지 결정하도록 도우십시오."
L["The Azure Span / Thaldraszus / Azeroth"] = "하늘빛 평원 / 탈드라서스 / 아제로스"
L["Keeper of the Ossuary"] = "납골당의 수호자"
L["The Azure Archives, The Azure Span"] = "하늘빛 기록보관소, 하늘빛 평원"
L["Algeth'ar Academy, Thaldraszus"] = "알게타르 대학, 탈드라서스"
L["Borean Tundra"] = "북풍의 땅"
L["Crystalsong Forest"] = "수정노래 숲"
L["Booty Bay, The Cape of Stranglethorn"] = "무법항, 가시덤불 곶"
L["Kalecgos begins at the Veiled Ossuary, where memories of Sindragosa, Malygos, Azuregos, and Senegos show how much the blue dragonflight has lost."] = "칼렉고스의 여정은 장막의 납골당에서 시작됩니다. 그곳에 깃든 신드라고사와 말리고스, 아주어고스, 세네고스의 기억은 푸른용군단이 얼마나 많은 것을 잃었는지 보여 줍니다."
L["Kalecgos called you to the Veiled Ossuary to help tend the memories of the blue dragonflight. With Senegos and Azuregos drawn into the work, the archives became more than a vault. They became a place to face what the blues had survived: Malygos, Sindragosa, exile, war, and the long habit of grieving separately.\n\nBy the time the first memories returned, Kalecgos understood the real task. The flight could not be restored by duty alone. The missing blues had to be found, heard, and invited home."] = "칼렉고스는 푸른용군단의 기억을 돌보는 일을 도와 달라며 장막의 납골당으로 불렀다. 세네고스와 아주어고스까지 이 일에 함께하면서, 기록보관소는 단순한 금고 이상이 되었다. 푸른용들이 견뎌 온 것들과 마주하는 곳이 된 것이다. 말리고스, 신드라고사, 망명, 전쟁, 그리고 저마다 따로 슬퍼해 온 오랜 습관까지.\n\n첫 기억들이 돌아올 무렵, 칼렉고스는 진짜 과제를 깨달았다. 용군단은 의무만으로는 되살아날 수 없었다. 사라진 푸른용들을 찾아내고, 그들의 이야기를 듣고, 집으로 초대해야 했다."
L["On the Trail Again"] = "다시 여로에 나서다"
L["Senegos"] = "세네고스"
L["Rolling Out"] = "공 굴리기"
L["Lest We Forget"] = "잊기 전에 할 일"
L["Archives Return"] = "기록 보관소로 돌아가기"
L["Azuregos's Support"] = "아주어고스의 지원"
L["Unusual Disruptions"] = "기이한 분열 현상"
L["Archival Arrival"] = "기록 보관소 도착"
L["Where in the World is a Lost Blue Dragon?"] = "실종된 푸른용은 도대체 어디에?"
L["Sindragosa and Malygos's Rest"] = "신드라고사와 말리고스의 안식"
L["Memories of Sindragosa and Malygos"] = "신드라고사와 말리고스의 기억"
L["The Search for Blue Dragons"] = "푸른용을 찾아서"
L["Kalecgos begins the search in earnest, naming the scattered blues and sending you across Azeroth to bring their stories back together."] = "칼렉고스는 본격적으로 수색을 시작하며 흩어진 푸른용들의 이름을 하나하나 꼽고, 그들의 이야기를 다시 하나로 모으기 위해 아제로스 곳곳으로 보냅니다."
L["The archives gave Kalecgos names, but names were not enough. The missing blues had built separate lives, separate loyalties, and separate ways of surviving. Some were hiding from pain. Some were trapped in old debts. Some had made peace with never returning.\n\nKalecgos chose to ask rather than command. The blue dragonflight's renewal would be a gathering, not a summons."] = "기록보관소는 칼렉고스에게 이름들을 알려 주었지만, 이름만으로는 충분하지 않았다. 사라진 푸른용들은 저마다의 삶과 충성, 그리고 살아남는 방식을 따로 일구어 왔다. 어떤 이는 고통을 피해 숨어 있었다. 어떤 이는 묵은 빚에 묶여 있었다. 또 어떤 이는 다시는 돌아가지 않으리라는 사실을 받아들인 채였다.\n\n칼렉고스는 명령 대신 부탁을 택했다. 푸른용군단의 재건은 소집이 아니라 모임이 될 것이었다."
L["Lost Blue Dragons"] = "실종된 푸른용"
L["A Pair of Blue Dragons"] = "한 쌍의 푸른용"
L["The Last Missing Blue Dragon"] = "마지막 푸른용 실종자"
L["Those We Left Behind"] = "남겨진 이들"
L["Lanigosa and Surigosa carry the cost of the Nexus War. Help them face a legacy that was never only history."] = "라니고사와 수리고사는 마력의 탑 전쟁의 대가를 짊어지고 있습니다. 결코 지나간 역사만이 아니었던 유산과 마주하도록 그들을 도우십시오."
L["Lanigosa's branch of the search led to Crystalsong Forest and Dustwallow Marsh, where grief had hardened around the Nexus War. The losses were personal, not abstract: shattered legacy, arcane echoes, old banners, and survivors who had learned to keep moving because stopping hurt too much.\n\nWith Surigosa and Kalecgos, you helped turn remembrance into release. The past was not erased, but it no longer had to be a prison."] = "라니고사를 찾는 갈래는 수정노래 숲과 먼지진흙 습지대로 이어졌다. 그곳에서는 마력의 탑 전쟁을 둘러싼 슬픔이 단단히 굳어 있었다. 상실은 추상적인 것이 아니라 개인적인 것이었다. 산산조각 난 유산, 비전의 메아리, 낡은 깃발, 그리고 멈추면 너무 아프기에 계속 움직이는 법을 배운 생존자들이 있었다.\n\n수리고사, 칼렉고스와 함께 추모를 해방으로 바꾸어 냈다. 과거는 지워지지 않았지만, 더 이상 감옥일 필요는 없었다."
L["Lanigosa"] = "라니고사"
L["A Shattered Legacy"] = "부서진 유산"
L["An Arcane Requiem"] = "비전의 진혼곡"
L["Creative Solutions"] = "창의적인 해결 방안"
L["Aftershocks"] = "강한 여파"
L["Surigosa"] = "수리고사"
L["The Sound of Silence"] = "침묵의 소리"
L["Regrets in Crystal"] = "수정 속 회한"
L["The Sullied Banner"] = "더럽혀진 깃발"
L["A Moment of Reflection"] = "성찰의 순간"
L["No Such Thing as Bad Luck"] = "불행은 없다"
L["Zeros has a debt problem in Booty Bay, which means the blue dragonflight's reunion briefly becomes paperwork, bribery, and goblin accounting."] = "제로스는 무법항에서 빚 문제를 안고 있습니다. 덕분에 푸른용군단의 재회는 잠시 서류 작업과 뇌물, 고블린식 회계 업무가 되어 버립니다."
L["Zeros did not need a grand speech. He needed out of debt. Booty Bay wrapped the search in ledgers, bribes, crystals, and the kind of bargaining that makes dragons wonder why mortals invented money.\n\nSenegos treated the mess with surprising patience, and Zeros eventually found a path back that did not involve running forever. Even the ridiculous errands served the larger truth: every scattered blue had a different reason to stay away."] = "제로스에게 필요한 것은 거창한 연설이 아니었다. 빚에서 벗어나는 것이었다. 무법항에서 수색은 장부와 뇌물, 수정, 그리고 필멸자들이 왜 돈을 발명했는지 용들이 의아해할 만한 흥정에 휩싸였다.\n\n세네고스는 이 난장판을 놀라울 만큼 참을성 있게 다루었고, 제로스는 결국 영원히 도망치지 않고도 돌아올 길을 찾았다. 우스꽝스러운 심부름조차 더 큰 진실을 보여 주었다. 흩어진 푸른용들에게는 저마다 멀리 떨어져 있을 이유가 있었다."
L["Zeros"] = "제로스"
L["Information is King"] = "정보는 곧 왕이다"
L["Blixrez Goodstitch"] = "블릭스레즈 굿스티치"
L["Anyway, I Started Bribing"] = "매수 시작"
L["Zeroing Debt"] = "빚이 제로"
L["Money, Money, Money!"] = "돈, 돈, 돈!"
L["Crystals Shmystals"] = "수정 소동"
L["Settled with the Baron"] = "남작과의 협상"
L["The Booty Bay Journal"] = "무법항 일보"
L["Booty Bay"] = "무법항"
L["Warm Winds and Water"] = "따뜻한 바람과 물"
L["Kalecgos visits Kirygosa in the Jade Forest, where care, quiet work, and old friendship matter more than speeches."] = "칼렉고스는 비취 숲의 키리고사를 찾아갑니다. 그곳에서는 연설보다 보살핌과 묵묵한 일, 그리고 오랜 우정이 더 중요합니다."
L["Kirygosa's life in the Jade Forest was not a problem to solve. It was a life she had made. Kalecgos helped with carp, deliveries, and simple comforts because asking someone to come home means respecting the home they already have.\n\nThe visit became a gentle reminder that the blue dragonflight could be wider than one place. Returning did not have to mean abandoning what had healed them."] = "비취 숲에서 키리고사가 꾸린 삶은 해결해야 할 문제가 아니었다. 그것은 그녀가 스스로 일군 삶이었다. 칼렉고스는 잉어를 잡고 물건을 배달하며 소소한 위안을 건넸다. 누군가에게 집으로 돌아오라고 청하려면, 그가 이미 가진 집을 존중해야 하기 때문이다.\n\n이 방문은 푸른용군단이 한 장소보다 더 넓을 수 있다는 사실을 부드럽게 일깨워 주었다. 돌아온다고 해서 자신들을 치유해 준 것을 버려야 하는 것은 아니었다."
L["Carp Care"] = "잉어 돌보기"
L["Kirygosa"] = "키리고사"
L["Self Care"] = "스스로를 돌보기"
L["Local Deliveries"] = "지역 배달"
L["Up, Up, and Home"] = "저 높은 곳의 보금자리"
L["A Drink with Kalecgos"] = "칼렉고스와 한잔을"
L["A Protector of Magic"] = "마법의 수호자"
L["Sindragosa's simulacrum sends you to Winterspring, where Haleh and old arcane tests reconnect another piece of blue dragon history."] = "신드라고사의 모사체의 안내로 여명의 설원에 가면, 헬레와 오래된 비전 시험이 푸른용 역사의 또 다른 조각을 다시 이어 줍니다."
L["The Winterspring branch carried a colder kind of memory. Sindragosa's simulacrum guided the search, Haleh guarded her own piece of the flight's story, and the work moved through tests, artifacts, and old magic rather than open confession.\n\nStill, the pattern held. The scattered blues were not being collected. They were being remembered, respected, and invited to stand together again."] = "여명의 설원 갈래에는 더 차가운 기억이 깃들어 있었다. 신드라고사의 모사체가 수색을 이끌었고, 헬레는 용군단 이야기의 한 조각을 홀로 지키고 있었으며, 일은 솔직한 고백보다는 시험과 유물, 오래된 마법을 통해 진행되었다.\n\n그래도 흐름은 같았다. 흩어진 푸른용들은 수집되는 것이 아니었다. 기억되고, 존중받으며, 다시 함께 서자는 초대를 받고 있었다."
L["Winterspring"] = "여명의 설원"
L["Sindragosa"] = "신드라고사"
L["Test Subject"] = "시험용 물체"
L["Owl of a Sudden"] = "갑작스러운 반전"
L["A Wyrm Rest"] = "고룡의 휴식"
L["Jade Forest"] = "비취 숲"
L["Blue is My Favorite Color"] = "푸른색이 제일 좋아"
L["Artifacts Abound"] = "넘치는 유물"
L["Back with the Blues"] = "푸른용과 함께 돌아오다"
L["Reunited Again"] = "재상봉"
L["The final trouble at the Veiled Ossuary brings the blues home, not as Malygos left them, but as a flight ready to choose its own future."] = "장막의 납골당에서 벌어진 마지막 사건이 푸른용들을 집으로 불러들입니다. 말리고스가 남기고 간 모습이 아니라, 스스로 미래를 선택할 준비가 된 용군단으로서 말입니다."
L["The Veiled Ossuary's final crisis forced the reunited blues to act together. Azuregos, Senegos, Sindragosa's memory, Kalecgos, and the scattered branches all carried different hurts, but they were no longer isolated by them.\n\nWhen the last conflict ended, the farewell was peaceful. The blue dragonflight did not return to the past. It stepped into a new dawn with grief acknowledged, bonds restored, and Kalecgos no longer trying to hold the flight together alone."] = "장막의 납골당에 닥친 마지막 위기는 다시 모인 푸른용들이 함께 움직이도록 만들었다. 아주어고스와 세네고스, 신드라고사의 기억, 칼렉고스, 그리고 흩어졌던 갈래들은 저마다 다른 상처를 안고 있었지만, 더는 그 상처 때문에 고립되지 않았다.\n\n마지막 싸움이 끝나자 작별은 평화로웠다. 푸른용군단은 과거로 돌아가지 않았다. 슬픔을 인정하고 유대를 되찾은 채 새로운 여명으로 나아갔고, 칼렉고스는 더 이상 홀로 용군단을 붙들려 애쓰지 않아도 되었다."
L["Veiled Trouble"] = "장막에 가려진 문제"
L["Veiled Ossuary Chaos"] = "혼돈에 빠진 장막의 납골당"
L["Memories of Old"] = "과거의 기억"
L["What Still Remains"] = "아직 남아 있는 것"
L["Swiftly to the Archives"] = "기록 보관소 긴급 귀환"
L["The Last Conflict"] = "마지막 갈등"
L["A Peaceful Farewell"] = "평온한 작별 인사"
